# Define the function to find anagrams of a string in a given list of strings
def anagram_lambda(strings, target):
    # Create a lookup table to store the frequency of each character in the target string
    char_count = {}

    # Count the frequency of each character in the target string
    for char in target:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Initialize an empty list to store the anagrams
    anagrams = []

    # Iterate through each string in the input list
    for string in strings:
        # Create a copy of the string to compare against
        current_string = string.lower()

        # Count the frequency of each character in the current string
        current_char_count = {}
        for char in current_string:
            if char in current_char_count:
                current_char_count[char] += 1
            else:
                current_char_count[char] = 1

        # Check if the current string has the same frequency as the target string
        if char_count == current_char_count:
            anagrams.append(string)

    return anagrams

