def count_Fac(n):
    # Initialize a dictionary to store prime factors and their counts
    prime_factors = {}

    # Check for number of 2s that divide n
    while n % 2 == 0:
        if 2 in prime_factors:
            prime_factors[2] += 1
        else:
            prime_factors[2] = 1
        n //= 2

    # n must be odd at this point, so a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            if i in prime_factors:
                prime_factors[i] += 1
            else:
                prime_factors[i] = 1
            n //= i

    # This condition is to handle the case when n is a prime number greater than 2
    if n > 2:
        if n in prime_factors:
            prime_factors[n] += 1
        else:
            prime_factors[n] = 1

    # Return the total count of distinct prime factors
    return len(prime_factors)

