def normalize_license_plate(text):
    if not isinstance(text, str):
        return None
    cleaned = []
    for ch in text.strip():
        if ch in ' -_':
            continue
        if ch.isalpha():
            up = ch.upper()
            if not ('A' <= up <= 'Z'):
                return None
            cleaned.append(up)
        elif ch.isdigit():
            cleaned.append(ch)
        else:
            return None
    if not (2 <= len(cleaned) <= 8):
        return None
    has_letter = any('A' <= ch <= 'Z' for ch in ''.join(cleaned))
    has_digit = any(ch.isdigit() for ch in cleaned)
    if not has_letter or not has_digit:
        return None
    return ''.join(cleaned)

def normalize_inventory(items):
    try:
        iterator = iter(items)
    except TypeError:
        raise TypeError("items must be iterable")

    totals = {}
    for record in iterator:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError("each record must be a 3-element sequence")
        category, name, quantity = record
        if not isinstance(category, str) or not isinstance(name, str):
            raise TypeError("category and name must be strings")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an integer")
        if quantity < 0:
            raise ValueError("quantity must not be negative")
        key = (category, name)
        totals[key] = totals.get(key, 0) + quantity

    result = []
    for category, name in sorted(totals.keys()):
        result.append({"category": category, "name": name, "quantity": totals[(category, name)]})
    return result

def encode_interval_runs(intervals):
    normalized = []
    seen = set()

    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a length-2 list or tuple of integers")
        a, b = item
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        start, end = (a, b) if a <= b else (b, a)
        key = (start, end)
        if key not in seen:
            seen.add(key)
            normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]

    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

def normalize_event_title(title: str) -> str:
    words = title.split()
    normalized = []

    for word in words:
        start = 0
        end = len(word)
        while start < end and not word[start].isalnum():
            start += 1
        while end > start and not word[end - 1].isalnum():
            end -= 1
        core = word[start:end]
        if not core:
            continue

        first = core[0]
        if first.isalpha():
            first = first.upper()
        rest = []
        for ch in core[1:]:
            rest.append(ch.lower() if ch.isalpha() else ch)
        normalized.append(first + ''.join(rest))

    return ' '.join(normalized)

def summarize_runs(seq):
    if not isinstance(seq, list):
        raise TypeError("seq must be a list")
    for x in seq:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers")
    if not seq:
        return (0, None, 0)
    run_count = 1
    longest_run_length = 1
    longest_run_value = seq[0]
    current_value = seq[0]
    current_length = 1
    for x in seq[1:]:
        if x == current_value:
            current_length += 1
        else:
            run_count += 1
            if current_length > longest_run_length:
                longest_run_length = current_length
                longest_run_value = current_value
            current_value = x
            current_length = 1
    if current_length > longest_run_length:
        longest_run_length = current_length
        longest_run_value = current_value
    return (longest_run_length, longest_run_value, run_count)

def schedule_batches(items, capacity):
    if capacity < 0:
        raise ValueError('capacity must be nonnegative')
    batches = []
    current = []
    current_sum = 0
    for item in items:
        if item < 0:
            raise ValueError('items must be nonnegative')
        if item > capacity:
            raise ValueError('item exceeds capacity')
        if current_sum + item <= capacity:
            current.append(item)
            current_sum += item
        else:
            if current:
                batches.append(current)
            current = [item]
            current_sum = item
    if current:
        batches.append(current)
    return batches

def render_ascii_barcode(bits, width=1, separator='|'):
    if not isinstance(bits, str) or bits == '':
        raise ValueError('bits must be a non-empty string')
    if any(ch not in '01' for ch in bits):
        raise ValueError('bits must contain only 0 and 1')
    if not isinstance(width, int) or width < 1:
        raise ValueError('width must be a positive integer')
    if not isinstance(separator, str):
        raise ValueError('separator must be a string')

    groups = [ch * width for ch in bits]
    return separator.join(groups)

def parse_timeline_spec(spec: str) -> list[tuple[int, str]]:
    if spec.strip() == "":
        return []

    result = []
    segments = spec.strip().split(';')
    for raw_segment in segments:
        segment = raw_segment.strip()
        if segment == "":
            raise ValueError("empty segment")
        if ':' not in segment:
            raise ValueError("missing colon")
        left, label = segment.split(':', 1)
        label = label.strip()
        if label == "":
            raise ValueError("empty label")
        if '-' not in left:
            raise ValueError("missing hyphen")
        start_str, end_str = left.split('-', 1)
        start_str = start_str.strip()
        end_str = end_str.strip()
        if start_str == "" or end_str == "":
            raise ValueError("missing bound")
        if not start_str.isdigit() or not end_str.isdigit():
            raise ValueError("non-integer bound")
        start = int(start_str)
        end = int(end_str)
        if start > end:
            raise ValueError("start greater than end")
        for t in range(start, end + 1):
            result.append((t, label))
    return result

