def normalize_csv_row(row, headers):
    if not isinstance(headers, (list, tuple)):
        headers = list(headers)
    if any((not isinstance(h, str)) or h == '' for h in headers):
        raise ValueError('headers must be unique non-empty strings')
    if len(set(headers)) != len(headers):
        raise ValueError('headers must be unique non-empty strings')
    if len(headers) == 0:
        if row == {} or row == [] or row == ():
            return {}
        raise ValueError('row must be empty when headers are empty')

    result = {h: None for h in headers}

    if isinstance(row, dict):
        for k in row:
            if k not in result:
                raise KeyError(k)
        for h in headers:
            if h in row:
                result[h] = row[h]
        return result

    if isinstance(row, (str, bytes, bytearray)):
        raise TypeError('row must be a dictionary or a non-string sequence')

    try:
        seq = list(row)
    except TypeError:
        raise TypeError('row must be a dictionary or a non-string sequence')

    if len(seq) > len(headers):
        raise ValueError('row has more values than headers')

    for i, value in enumerate(seq):
        result[headers[i]] = value
    return result

def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    validated = []
    for rec in events:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            raise ValueError('each event must be a 3-element sequence')
        start, end, label = rec
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('start and end must be integers')
        if not isinstance(label, str) or label == '':
            raise ValueError('label must be a non-empty string')
        if start > end:
            raise ValueError('start must be <= end')
        validated.append((start, end, label))

    by_label = {}
    for start, end, label in validated:
        by_label.setdefault(label, []).append((start, end))

    merged = []
    for label, intervals in by_label.items():
        intervals.sort(key=lambda x: (x[0], x[1]))
        cur_start, cur_end = intervals[0]
        for s, e in intervals[1:]:
            if s <= cur_end + 1:
                if e > cur_end:
                    cur_end = e
            else:
                merged.append((cur_start, cur_end, label))
                cur_start, cur_end = s, e
        merged.append((cur_start, cur_end, label))

    merged.sort(key=lambda x: (x[0], x[1], x[2]))
    return merged

def segment_holiday_messages(text: str) -> list[str]:
    messages = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '#' and i + 1 < n and (text[i + 1].isupper() or text[i + 1].isdigit() or text[i + 1] == '_'):
            j = i + 1
            while j < n and (text[j].isupper() or text[j].isdigit() or text[j] == '_'):
                j += 1
            messages.append(text[i:j])
            i = j
        else:
            i += 1
    return messages

def normalize_key_value_text(text):
    result = {}
    if text == "":
        return result
    for raw_line in text.split("\n"):
        stripped_line = raw_line.strip()
        if stripped_line == "":
            continue
        if stripped_line.startswith("#"):
            continue
        if raw_line.count("=") != 1:
            raise ValueError("Each data line must contain exactly one =")
        key_part, value_part = raw_line.split("=", 1)
        key = key_part.strip()
        value = value_part.strip()
        if key == "":
            raise ValueError("Key must be non-empty")
        for ch in key:
            if not (ch.isascii() and (ch.isalnum() or ch in "_-")):
                raise ValueError("Invalid key")
        canon_key = key.lower()
        lower_value = value.lower()
        if lower_value == "true":
            canon_value = True
        elif lower_value == "false":
            canon_value = False
        elif lower_value in ("null", "none"):
            canon_value = None
        elif value == "-" or value == "":
            canon_value = value
        else:
            num_text = value[1:] if value.startswith("-") else value
            if num_text.isdigit() and (value[0].isdigit() or value.startswith("-")):
                canon_value = int(value)
            else:
                canon_value = value
        result[canon_key] = canon_value
    return result

import re

def normalize_key_value_text(text):
    """
    Parses a small configuration-like text into a canonical dictionary.

    Parameters:
    text (str): A string containing zero or more lines separated by \n.

    Returns:
    dict: A canonical dictionary with keys converted to lowercase and values normalized.
    """
    # Split the text into lines
    lines = text.split('\n')

    # Initialize an empty dictionary to store the result
    result = {}

    # Iterate over each line
    for line in lines:
        # Strip leading and trailing whitespace
        line = line.strip()

        # Check if the line starts with '#'
        if line.startswith('#'):
            continue

        # Split the line into key and value
        parts = line.split('=')

        # Check if there are exactly two parts
        if len(parts) != 2:
            raise ValueError("Invalid line format")

        # Extract key and value
        key = parts[0].strip()
        value = parts[1].strip()

        # Validate key
        if not key:
            raise ValueError("Key cannot be empty")

        # Convert key to lowercase
        key = key.lower()

        # Normalize value
        if value == 'null':
            value = None
        elif value == 'none':
            value = None
        elif value == '-':
            value = int(value[1:])
        else:
            try:
                value = bool(value)
            except ValueError:
                raise ValueError(f"Invalid value: {value}")

        # Store the result
        result[key] = value

    return result

