def summarize_deltas(nums):
    """
    Analyzes a sequence of integers and returns a dictionary with four keys:
    count, total, sign_changes, and prefix_max.

    Parameters:
    nums (list or tuple): A list or tuple of integers.

    Returns:
    dict: A dictionary with the specified keys.
    """
    if not isinstance(nums, (list, tuple)):
        raise TypeError("Input must be a list or tuple of integers.")

    count = len(nums)
    total = sum(nums)
    sign_changes = 0
    prefix_max = []

    for i in range(1, count):
        if nums[i] * nums[i - 1] < 0:
            sign_changes += 1
        prefix_max.append(max(prefix_max[-1], nums[i]))

    return {
        'count': count,
        'total': total,
        'sign_changes': sign_changes,
        'prefix_max': prefix_max
    }

