            value = value.strip()
            if ',' in value:
                parts = [p.strip() for p in value.split(',')]
                cleaned = []
                seen = set()
                for part in parts:
                    if part == '':
                        continue
                    if part not in seen:
                        seen.add(part)
                        cleaned.append(part)
                cleaned.sort()
                return ','.join(cleaned)
            return value
        return str(value)

    result = []
    for item in headers:
        if isinstance(item, str):
            s = item.strip()
            sep_count = s.count('=') + s.count(':')
            if sep_count != 1:
                raise ValueError('string header must contain exactly one separator')
            if '=' in s:
                name, value = s.split('=', 1)
            else:
                name, value = s.split(':', 1)
            name = name.strip().lower()
            value = normalize_value(value.strip())
            result.append(f'{name}={value}')
        elif isinstance(item, (list, tuple)):
            if len(item) != 2:
                raise ValueError('tuple/list header must have length 2')
            name, value = item
            if not isinstance(name, str):
                name = str(name)
            name = name.strip().lower()
            value = normalize_value(value)
            result.append(f'{name}={value}')
        else:
            raise TypeError('unsupported header descriptor')
    return result

def normalize_inventory_changes(changes):
    if not isinstance(changes, list):
        raise TypeError('changes must be a list')
    totals = {}
    order = []
    for entry in changes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError('each change must be a 2-tuple')
        item, delta = entry
        if not isinstance(item, str) or not isinstance(delta, int):
            raise TypeError('item must be str and delta must be int')
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += delta
    parts = []
    for item in order:
        total = totals[item]
        if total != 0:
            parts.append(f'{item}:{total}')
    return ' | '.join(parts)

def normalize_menu_orders(orders):
    try:
        iterator = iter(orders)
    except TypeError:
        raise TypeError("orders must be iterable")

    customer_items = {}
    customer_order = []

    for record in iterator:
        try:
            pair = tuple(record)
        except TypeError:
            raise TypeError("each order record must be a 2-item iterable")
        if len(pair) != 2:
            raise TypeError("each order record must be a 2-item iterable")

        customer_id, items = pair
        if not isinstance(customer_id, str) or customer_id == "":
            raise ValueError("customer_id must be a non-empty string")

        try:
            items_iter = iter(items)
        except TypeError:
            raise TypeError("items must be iterable")

        if customer_id not in customer_items:
            customer_items[customer_id] = []
            customer_order.append(customer_id)

        seen = set(customer_items[customer_id])
        for item in items_iter:
            if not isinstance(item, str) or item == "":
                raise ValueError("item names must be non-empty strings")
            if item not in seen:
                customer_items[customer_id].append(item)
                seen.add(item)

    return [(cid, tuple(customer_items[cid])) for cid in sorted(customer_order)]

def flatten_runs(items):
    result = []
    iterator = iter(items)
    try:
        current = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_path_tokens(path: str) -> str:
    if path == "":
        return "."

    parts = []
    for segment in path.split("/"):
        if segment == "" or segment == ".":
            continue
        if segment == "..":
            if parts:
                parts.pop()
            continue
        parts.append(segment)

    return "/".join(parts) if parts else "."

def normalize_log_entries(entries):
    result = []
    for entry in entries:
        trimmed = entry.strip()
        if not trimmed:
            continue
        parts = trimmed.split('|', 2)
        while len(parts) < 3:
            parts.append('')
        timestamp, level, message = (p.strip() for p in parts[:3])
        if timestamp:
            timestamp = timestamp.replace(' ', '_')
        level = level.upper()
        if message.endswith('.'):
            message = message[:-1]
        result.append(f'{timestamp}|{level}|{message}')
    return result

def normalize_scoring_events(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    totals = {}
    order = []
    net_points = 0
    event_count = 0

    for event in events:
        if not isinstance(event, (list, tuple)) or len(event) != 2:
            raise ValueError("each event must be a 2-item list or tuple")
        player, points = event
        if not isinstance(player, str):
            raise TypeError("player must be a string")
        if not isinstance(points, int):
            raise TypeError("points must be an integer")
        if points == 0:
            continue

        if player not in totals:
            totals[player] = 0
            order.append(player)
        totals[player] += points
        net_points += points
        event_count += 1

    leaders = []
    if totals:
        max_total = max(totals.values())
        leaders = [player for player in order if totals[player] == max_total]

    return {
        "totals": totals,
        "leaders": leaders,
        "net_points": net_points,
        "event_count": event_count,
    }

def normalize_scoring_events(events):
    """
    Normalize the scoring events by summing up points of each player,
    ignoring zero-point events and returning a dictionary with the required keys.

    :param events: List of tuples (player, points)
    :return: A dictionary with keys 'totals', 'leaders', 'net_points', and 'event_count'
    """
    if not isinstance(events, list) or not all(isinstance(event, tuple) for event in events):
        raise TypeError("Input must be a list of tuples.")
    if not all(isinstance(player, str) for player in event[0]):
        raise TypeError("First item of each event must be a string.")
    if not all(isinstance(points, int) for points in event[1]):
        raise TypeError("Second item of each event must be an integer.")
    if len(events) == 0:
        return {'totals': {}, 'leaders': [], 'net_points': 0, 'event_count': 0}

    # Initialize totals, leaders, net_points, and event_count
    totals = {}
    leaders = []
    net_points = 0
    event_count = 0

    # Process each event
    for player, points in events:
        if points == 0:
            continue
        if player not in totals:
            totals[player] = 0
        totals[player] += points
        if points > net_points:
            net_points = points
        if points > 0:
            leaders.append(player)

    # Calculate net_points
    net_points = sum(totals.values())

    # Return the normalized summary
    return {
        "totals": totals,
        "leaders": leaders,
        "net_points": net_points,
        "event_count": event_count
    }

