def compress_spans(points):
    if not isinstance(points, (list, tuple)):
        raise ValueError('points must be a sequence of integers')
    if len(points) == 0:
        return []
    for x in points:
        if not isinstance(x, int):
            raise ValueError('points must be a sequence of integers')
    spans = []
    start = prev = points[0]
    for x in points[1:]:
        if x < prev:
            raise ValueError('points must be sorted in nondecreasing order')
        if x == prev:
            continue
        if x == prev + 1:
            prev = x
        else:
            spans.append((start, prev))
            start = prev = x
    spans.append((start, prev))
    return spans

def normalize_inventory(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')

    totals = {}
    for rec in records:
        if not isinstance(rec, dict):
            raise TypeError('each record must be a dict')
        if set(rec.keys()) != {'sku', 'warehouse', 'qty'}:
            raise ValueError('each record must have exactly sku, warehouse, qty')
        sku = rec['sku']
        warehouse = rec['warehouse']
        qty = rec['qty']
        if not isinstance(sku, str) or sku == '':
            raise ValueError('sku must be a non-empty string')
        if not isinstance(warehouse, str) or warehouse == '':
            raise ValueError('warehouse must be a non-empty string')
        if not isinstance(qty, int):
            raise ValueError('qty must be an int')
        key = (sku, warehouse)
        totals[key] = totals.get(key, 0) + qty

    result = []
    for (sku, warehouse), qty in sorted(totals.items(), key=lambda item: (item[0][0], item[0][1])):
        if qty != 0:
            result.append({'sku': sku, 'warehouse': warehouse, 'qty': qty})
    return result

def render_calendar_grid(events, start_day=1, end_day=31):
    if not isinstance(start_day, int) or not isinstance(end_day, int):
        raise ValueError("start_day and end_day must be integers")
    if start_day > end_day:
        raise ValueError("start_day must be <= end_day")
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    day_to_labels = {}
    for ev in events:
        if not isinstance(ev, tuple) or len(ev) != 2:
            raise ValueError("each event must be a 2-tuple")
        day, label = ev
        if not isinstance(day, int):
            raise ValueError("event day must be an integer")
        if not isinstance(label, str):
            raise ValueError("event label must be a string")
        day_to_labels.setdefault(day, []).append(label)

    lines = []
    for day in range(start_day, end_day + 1):
        labels = sorted(day_to_labels.get(day, []), key=lambda s: (len(s), s))
        if labels:
            lines.append(f"{day:02d}: {', '.join(labels)}")
        else:
            lines.append(f"{day:02d}:")
    return "\n".join(lines)

def normalize_breadcrumbs(path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    if path == '/':
        return '/'

    parts = []
    for chunk in path.split('/'):
        if chunk == '' or chunk == '.':
            continue
        if chunk == '..':
            if parts:
                parts.pop()
            continue
        parts.append(chunk)

    return '/'.join(parts)

def best_signal_window(signals, window):
    if not isinstance(window, int):
        raise ValueError("window must be an integer")
    if window < 0:
        raise ValueError("window must not be negative")

    vals = list(signals)
    for x in vals:
        if not isinstance(x, int):
            raise TypeError("all signal values must be integers")

    n = len(vals)
    if window == 0:
        return (0, 0, -1)
    if window > n:
        return None

    current = sum(vals[:window])
    best_sum = current
    best_start = 0

    for start in range(1, n - window + 1):
        current += vals[start + window - 1] - vals[start - 1]
        if current > best_sum:
            best_sum = current
            best_start = start

    return (best_sum, best_start, best_start + window - 1)

def encode_runlength_grid(grid):
    if not isinstance(grid, list):
        raise TypeError("grid must be a list")
    if grid == []:
        return []
    if any(not isinstance(row, list) for row in grid):
        raise TypeError("each row must be a list")
    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("all rows must have the same length")
        for x in row:
            if not isinstance(x, int):
                raise TypeError("all grid elements must be integers")
    flat = [x for row in grid for x in row]
    if not flat:
        return []
    out = []
    current = flat[0]
    count = 1
    for x in flat[1:]:
        if x == current:
            count += 1
        else:
            out.append((current, count))
            current = x
            count = 1
    out.append((current, count))
    return out

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    if not events:
        return ''

    normalized = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError('each event must be a tuple of length 3')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('start and end must be integers')
        if not isinstance(label, str):
            raise TypeError('label must be a string')
        if start > end:
            raise ValueError('start must be less than or equal to end')
        start_h, start_m = divmod(start, 60)
        end_h, end_m = divmod(end, 60)
        start_str = f'{start_h:02d}:{start_m:02d}'
        end_str = f'{end_h:02d}:{end_m:02d}'
        normalized.append((start, end, label, f'{start_str}-{end_str}|{label}'))

    normalized.sort(key=lambda x: (x[0], x[1], x[2]))
    return ';'.join(item[3] for item in normalized)

def parse_ledger(lines):
    result = {}
    for raw in lines:
        line = raw.strip()
        if not line:
            raise ValueError('Invalid line')
        parts = line.split(' ')
        if len(parts) != 3 or any(p == '' for p in parts):
            raise ValueError('Invalid line')
        op, category, amount_text = parts
        if op not in ('ADD', 'SUB'):
            raise ValueError('Invalid operation')
        if any(ch.isspace() for ch in category) or category == '':
            raise ValueError('Invalid category')
        try:
            amount = int(amount_text, 10)
        except Exception:
            raise ValueError('Invalid amount')
        if category not in result:
            result[category] = {'total_in': 0, 'total_out': 0, 'balance': 0}
        entry = result[category]
        contribution = amount if op == 'ADD' else -amount
        if contribution >= 0:
            entry['total_in'] += contribution
        else:
            entry['total_out'] += -contribution
        entry['balance'] += contribution
    return result

def parse_inventory_updates(records):
    inventory = {}
    for record in records:
        if not isinstance(record, str):
            raise ValueError('Each record must be a string')
        parts = record.split(':')
        if len(parts) != 3:
            raise ValueError('Malformed record')
        action, sku, qty_str = parts
        if action not in {'ADD', 'REMOVE', 'SET'}:
            raise ValueError('Unknown action')
        if not sku or ':' in sku:
            raise ValueError('Invalid SKU')
        if qty_str == '' or qty_str.startswith('-'):
            raise ValueError('Invalid quantity')
        if not qty_str.isdigit():
            raise ValueError('Invalid quantity')
        qty = int(qty_str)
        current = inventory.get(sku, 0)
        if action == 'ADD':
            inventory[sku] = current + qty
        elif action == 'REMOVE':
            new_value = current - qty
            if new_value < 0:
                raise ValueError('Inventory cannot go below zero')
            inventory[sku] = new_value
        else:  # SET
            inventory[sku] = qty
    return inventory

def parse_inventory_updates(records):
    """
    Parses a sequence of update strings for a warehouse inventory system.

    Each update string is in the format:
    - "ADD:<sku>:<qty>"
    - "REMOVE:<sku>:<qty>"
    - "SET:<sku>:<qty>"

    Updates inventory for a SKU by adding or removing inventory based on the provided action.
    Returns a dictionary mapping each SKU to its final inventory.

    :param records: Iterable of update strings.
    :return: Dictionary mapping each SKU to its final inventory.
    """
    inventory = {}
    for record in records:
        try:
            action, sku, qty = record.split(':')
            if action == 'ADD':
                inventory[sku] += int(qty)
            elif action == 'REMOVE':
                inventory[sku] -= int(qty)
            elif action == 'SET':
                inventory[sku] = int(qty)
            else:
                raise ValueError(f"Unknown action: {action}")
        except ValueError as e:
            raise ValueError(f"Invalid update: {e}")
    return inventory

