def decode_sprite_grid(lines):
    if not isinstance(lines, list):
        raise TypeError("lines must be a list of strings")
    if not lines:
        return []
    first_width = len(lines[0])
    result = []
    for y, row in enumerate(lines):
        if not isinstance(row, str):
            raise TypeError("each row must be a string")
        if len(row) != first_width:
            raise ValueError("all rows must have the same length")
        for x, ch in enumerate(row):
            if ch == '#':
                result.append((x, y))
            elif ch != '.':
                raise ValueError("grid may contain only '#' and '.'")
    return result

def canonicalize_commands(commands):
    result = []
    seen = set()
    for cmd in commands:
        if not isinstance(cmd, str):
            raise ValueError("all commands must be strings")
        if '#' in cmd:
            cmd = cmd.split('#', 1)[0]
        cmd = cmd.strip()
        if not cmd:
            continue
        if not all(ch.isalnum() or ch in {'-', '_'} for ch in cmd):
            raise ValueError("invalid command")
        canon = cmd.upper()
        if canon not in seen:
            seen.add(canon)
            result.append(canon)
    return result

def merge_events(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    grouped = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('id', 'start', 'end', 'tags')
        for key in required:
            if key not in event:
                raise ValueError('missing required key')
        eid = event['id']
        start = event['start']
        end = event['end']
        tags = event['tags']
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('start and end must be integers')
        if start > end:
            raise ValueError('start cannot exceed end')
        if not isinstance(tags, list):
            raise ValueError('tags must be a list')
        if eid not in grouped:
            grouped[eid] = {'id': eid, 'start': start, 'end': end, 'tags': set(tags)}
        else:
            grouped[eid]['start'] = min(grouped[eid]['start'], start)
            grouped[eid]['end'] = max(grouped[eid]['end'], end)
            grouped[eid]['tags'].update(tags)
    result = []
    for eid in sorted(grouped):
        item = grouped[eid]
        result.append({'id': item['id'], 'start': item['start'], 'end': item['end'], 'tags': sorted(item['tags'])})
    return result

def summarize_runs(text: str) -> dict:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    if text == '':
        return {
            'total_length': 0,
            'symbol_lengths': {},
            'first_symbol': None,
            'last_symbol': None,
            'num_segments': 0,
        }

    segments = text.split(',')
    if any(seg == '' for seg in segments):
        raise ValueError('malformed run list')

    symbol_lengths = {}
    total_length = 0
    first_symbol = None
    last_symbol = None

    for seg in segments:
        if len(seg) < 2:
            raise ValueError('malformed segment')
        symbol = seg[0]
        count_part = seg[1:]
        if symbol.isdigit() or symbol == ',':
            raise ValueError('invalid symbol')
        if not count_part.isdigit():
            raise ValueError('invalid count')
        count = int(count_part)
        if count <= 0:
            raise ValueError('count must be positive')
        if first_symbol is None:
            first_symbol = symbol
        last_symbol = symbol
        total_length += count
        symbol_lengths[symbol] = symbol_lengths.get(symbol, 0) + count

    return {
        'total_length': total_length,
        'symbol_lengths': symbol_lengths,
        'first_symbol': first_symbol,
        'last_symbol': last_symbol,
        'num_segments': len(segments),
    }

def normalize_tagged_pairs(items):
    if items is None:
        raise TypeError('items must be an iterable of 2-tuples')
    result = []
    seen = set()
    for entry in items:
        if not isinstance(entry, tuple):
            raise TypeError('each item must be a tuple')
        if len(entry) != 2:
            raise TypeError('each tuple must have exactly 2 elements')
        tag, value = entry
        if not isinstance(tag, str):
            continue
        if tag in seen:
            continue
        seen.add(tag)
        result.append((tag, value))
    return result

def decode_run_metadata(text):
    if text is None:
        return {}
    s = text.strip()
    if not s:
        return {}

    result = {}
    allowed_statuses = {"ok", "fail", "skip"}

    def valid_run_id(run_id):
        if not run_id:
            return False
        for ch in run_id:
            if ch.isspace() or ch in ",;":
                return False
            if not (ch.isalnum() or ch in "_-"):
                return False
        return True

    for record in s.split(";"):
        rec = record.strip()
        if not rec:
            continue
        parts = [p.strip() for p in rec.split(",")]
        if len(parts) != 3:
            continue
        run_id, status, score_text = parts
        if not valid_run_id(run_id):
            continue
        if status not in allowed_statuses:
            continue
        try:
            score = int(score_text)
        except Exception:
            continue
        if str(score) != score_text and str(score) != score_text.lstrip("+"):
            # Reject formats like "01" or "+3" or embedded whitespace.
            # int() may accept them, but the task requires decimal integer notation.
            if score_text not in ("0", "-0"):
                if score_text != str(score):
                    continue
        result[run_id] = (status, score)
    return result

def decode_run_metadata(run_metadata):
    """
    Parses a compact run-metadata string into a dictionary of fields.

    :param run_metadata: A string containing zero or more records separated by semicolons.
    :return: A dictionary mapping each valid run_id to a tuple (status, score).
    """
    # Split the input string into records
    records = run_metadata.split(';')

    # Initialize an empty dictionary to store results
    result = {}

    # Iterate over each record
    for record in records:
        # Split the record into fields
        fields = record.split(',')

        # Check if there are exactly three fields
        if len(fields) != 3:
            continue

        # Extract run_id, status, and score
        run_id = fields[0]
        status = fields[1]
        score = float(fields[2])

        # Update the result dictionary with the valid run_id and its corresponding tuple
        result[run_id] = (status, score)

    return result

