def normalize_compound_key(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    stripped = text.strip()
    if not stripped:
        return ''

    parts = []
    current = []
    for ch in stripped:
        if ch in ' _-':
            if current:
                parts.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        parts.append(''.join(current))

    def normalize_segment(seg):
        if seg.isdigit():
            return seg
        chars = []
        first_done = False
        for c in seg:
            if not first_done and c.isalpha():
                chars.append(c.upper())
                first_done = True
            elif c.isalpha():
                chars.append(c.lower())
            else:
                chars.append(c)
                if not first_done and not c.isalpha():
                    pass
        return ''.join(chars)

    return '-'.join(normalize_segment(seg) for seg in parts)

def render_ascii_histogram(counts, width=10, fill_char='#', label_char='|'):
    counts_list = list(counts)
    if not isinstance(width, int) or width <= 0:
        raise ValueError("width must be a positive integer")
    if not isinstance(fill_char, str) or len(fill_char) != 1:
        raise ValueError("fill_char must be a single-character string")
    if not isinstance(label_char, str) or len(label_char) != 1:
        raise ValueError("label_char must be a single-character string")

    lines = []
    for index, c in enumerate(counts_list):
        if not isinstance(c, int) or isinstance(c, bool) or c < 0:
            raise ValueError("counts must be non-negative integers")
        bar = fill_char * min(c, width)
        lines.append(f"{index}{label_char}{bar}")
    return "\n".join(lines)

def render_ascii_histogram(counts, width=10, fill_char='#', label_char='|'):
    """
    Converts a sequence of non-negative integer counts into a multiline ASCII histogram string.

    :param counts: An iterable of integers.
    :param width: A positive integer representing the width of the histogram.
    :param fill_char: A single-character string representing the fill character for bars.
    :param label_char: A single-character string representing the label character for the histogram.
    :return: A multiline ASCII histogram string.
    """
    if not all(isinstance(count, int) and count >= 0 for count in counts):
        raise ValueError("All counts must be non-negative integers.")
    if not isinstance(width, int) or width <= 0:
        raise ValueError("Width must be a positive integer.")
    if not isinstance(fill_char, str) or len(fill_char) != 1:
        raise ValueError("Fill character must be a single-character string.")
    if not isinstance(label_char, str) or len(label_char) != 1:
        raise ValueError("Label character must be a single-character string.")

    histogram = []
    for index, count in enumerate(counts):
        if count == 0:
            histogram.append('')
        else:
            bar_length = min(count, width)
            bar = fill_char * bar_length
            histogram.append(f'{index}{label_char}{bar}')

    return '\n'.join(histogram)

