def compress_runs(items):
    try:
        iterator = iter(items)
    except TypeError:
        raise TypeError("items must be iterable")

    result = []
    try:
        current = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def decode_range_signature(signature):
    if not isinstance(signature, str):
        raise ValueError("signature must be a string")

    s = signature.strip()
    if s == "":
        return []

    intervals = []
    parts = s.split(",")
    for raw_part in parts:
        part = raw_part.strip()
        if part == "":
            raise ValueError("empty item")

        if ".." in part:
            pieces = part.split("..")
            if len(pieces) != 2:
                raise ValueError("invalid range")
            left, right = pieces[0].strip(), pieces[1].strip()
            if left == "" or right == "":
                raise ValueError("invalid range")
            try:
                start = int(left)
                end = int(right)
            except Exception:
                raise ValueError("invalid integer")
            if start > end:
                raise ValueError("reversed range")
            intervals.append((start, end))
        else:
            try:
                n = int(part)
            except Exception:
                raise ValueError("invalid integer")
            intervals.append((n, n))

    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = []
    for start, end in intervals:
        if not merged:
            merged.append([start, end])
            continue
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return [(a, b) for a, b in merged]

def segment_drift(sequence):
    it = iter(sequence)
    try:
        first = next(it)
    except StopIteration:
        raise ValueError('sequence must not be empty')

    result = []
    prev_segment_value = first
    prev_value = first

    for value in it:
        if value != prev_value:
            if value != prev_segment_value:
                result.append(value - prev_segment_value)
                prev_segment_value = value
            prev_value = value
    return result

def encode_runs(values):
