        return (isinstance(x, int) and not isinstance(x, bool)) or isinstance(x, str)

    first = values[0]
    if not valid_item(first):
        raise TypeError("all elements must be int or str, excluding bool")

    current = first
    count = 1

    for item in values[1:]:
        if not valid_item(item):
            raise TypeError("all elements must be int or str, excluding bool")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    result.append((current, count))
    return result

def encode_runs(values):
    """
    Encodes a list of values into run-length encoding with strict typing rules.

    Parameters:
    values (list): A list containing integers or strings.

    Returns:
    list: A list of tuples, where each tuple contains a value and its count.
    """
    if not isinstance(values, list):
        raise TypeError("Input must be a list.")

    encoded = []
    current_value = None
    count = 0

    for value in values:
        if isinstance(value, int):
            if current_value is None:
                current_value = value
                count = 1
            else:
                if current_value == value:
                    count += 1
                else:
                    encoded.append((current_value, count))
                    current_value = value
                    count = 1
        elif isinstance(value, str):
            if current_value is None:
                current_value = value
                count = 1
            else:
                if current_value == value:
                    count += 1
                else:
                    encoded.append((current_value, count))
                    current_value = value
                    count = 1
        else:
            raise TypeError(f"Unsupported type: {type(value)}")

    # Handle the last group
    if current_value is not None:
        encoded.append((current_value, count))

    return encoded

