def normalize_ragged_matrix(rows):
    try:
        outer = list(rows)
    except TypeError:
        raise TypeError("rows must be iterable")

    normalized = []
    max_len = 0

    for row in outer:
        try:
            items = list(row)
        except TypeError:
            raise TypeError("each row must be iterable")

        converted = []
        for item in items:
            if isinstance(item, bool):
                converted.append(int(item))
            elif isinstance(item, int):
                converted.append(item)
            else:
                raise TypeError("rows may contain only ints or bools")
        normalized.append(converted)
        if len(converted) > max_len:
            max_len = len(converted)

    result = []
    for row in normalized:
        if len(row) < max_len:
            row = row + [0] * (max_len - len(row))
        else:
            row = list(row)
        result.append(row)
    return result

def normalize_inventory_records(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    def normalize_active(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            lowered = value.strip().lower()
            if lowered in {"true", "yes", "1"}:
                return True
            if lowered in {"false", "no", "0"}:
                return False
        return bool(value)

    normalized = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError("each record must be a dict")
        if set(record.keys()) != {"sku", "count", "active"}:
            raise ValueError("each record must have exactly sku, count, active")

        sku = record["sku"]
        if not isinstance(sku, str):
            sku = str(sku)
        sku = sku.strip().upper()
        if not sku:
            raise ValueError("sku must not be empty")

        try:
            count = int(record["count"])
        except Exception as e:
            raise ValueError("count must be convertible to int") from e

        active = normalize_active(record["active"])
        normalized.append({"sku": sku, "count": count, "active": active})

    normalized.sort(key=lambda r: (r["sku"], -r["count"], not r["active"]))
    return normalized

