            if 'sources' not in entry:
                raise ValueError("Each entry in logs must include 'sources' key.")

    # Sort logs by day and version, preserving order for identical days and versions
    logs.sort(key=lambda x: (x[0], x[1][0]))

    # Initialize result list
    result = []

    # Iterate through each log entry
    for log in logs:
        stream_name, entries = log
        # Create a new dictionary with normalized changes
        normalized_changes = {entry['version']: entry['changes']}
        # Add sources to the result list
        for source in entries:
            normalized_changes[source] = source
        # Append the normalized changes to the result list
        result.append(normalized_changes)

    return result

