def decode_repeating_blocks(s: str) -> str:
    stack = []  # each item: (previous_string, repeat_count)
    current = []
    num = None

    for ch in s:
        if ch.isdigit():
            if num is None:
                num = ch
            else:
                num += ch
        elif ch == '[':
            if num is None:
                raise ValueError('missing repeat count before [')
            k = int(num)
            if k <= 0:
                raise ValueError('repeat count must be positive')
            stack.append((''.join(current), k))
            current = []
            num = None
        elif ch == ']':
            if num is not None:
                raise ValueError('digits must be followed by [')
            if not stack:
                raise ValueError('unmatched closing bracket')
            prev, k = stack.pop()
            segment = ''.join(current) * k
            current = [prev + segment]
        else:
            if num is not None:
                raise ValueError('digits must be followed by [')
            current.append(ch)

    if num is not None:
        raise ValueError('trailing repeat count')
    if stack:
        raise ValueError('unbalanced opening bracket')
    return ''.join(current)

def compress_runs(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if text == "":
        return ""

    result = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            result.append(f"{current}{count}")
            current = ch
            count = 1

    result.append(f"{current}{count}")
    return "".join(result)

def normalize_matrix_rows(matrix):
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list")

    result = []
    for row in matrix:
        if not isinstance(row, (list, tuple)):
            raise TypeError("each row must be a list or tuple")
        normalized_row = []
        if len(row) == 0:
            result.append(normalized_row)
            continue
        total = 0
        for x in row:
            if not isinstance(x, (int, float)):
                raise TypeError("matrix elements must be int or float")
            total += x
        if total == 0:
            result.append([0.0 for _ in row])
        else:
            result.append([x / total for x in row])
    return result

def compress_calendar_slots(slots):
    if not isinstance(slots, list):
        raise TypeError("slots must be a list")
    if not slots:
        return []

    normalized = []
    for item in slots:
        if not isinstance(item, (tuple, list)) or len(item) != 2:
            raise ValueError("each interval must be a 2-item tuple/list")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("interval endpoints must be integers")
        if start >= end:
            raise ValueError("interval must satisfy start < end")
        normalized.append((start, end))

    normalized.sort(key=lambda x: x[0])
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        elif start == last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def normalize_license_plate(text: str) -> str:
    cleaned = []
    for ch in text:
        if 'a' <= ch <= 'z' or 'A' <= ch <= 'Z' or '0' <= ch <= '9':
            cleaned.append(ch.upper())
    s = ''.join(cleaned)
    if not s:
        return ''

    first_digit = None
    for i, ch in enumerate(s):
        if '0' <= ch <= '9':
            first_digit = i
            break
    if first_digit is None:
        return s

    letters = s[:first_digit]
    j = first_digit
    while j < len(s) and '0' <= s[j] <= '9':
        j += 1
    digits = s[first_digit:j]
    tail = s[j:]

    parts = []
    if letters:
        parts.append(letters)
    if digits:
        parts.append(digits)
    if tail:
        parts.append(tail)
    return '-'.join(parts)

def summarize_ledger(entries):
    def is_valid_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    totals = {}
    count = 0
    grand_total = 0

    for entry in entries:
        category = amount = None

        if isinstance(entry, tuple) and len(entry) == 2:
            category, amount = entry
        elif isinstance(entry, dict) and 'category' in entry and 'amount' in entry:
            category, amount = entry['category'], entry['amount']
        elif isinstance(entry, list) and len(entry) == 2:
            category, amount = entry[0], entry[1]
        else:
            continue

        if not isinstance(category, str):
            continue
        category = category.strip()
        if not category:
            continue
        if not is_valid_int(amount):
            continue

        totals[category] = totals.get(category, 0) + amount
        grand_total += amount
        count += 1

    if not totals:
        return {'totals': {}, 'grand_total': 0, 'categories': [], 'count': 0}

    categories = sorted(totals)
    sorted_totals = {k: totals[k] for k in categories}
    return {'totals': sorted_totals, 'grand_total': grand_total, 'categories': categories, 'count': count}

def normalize_nested_menu(menu):
    if not isinstance(menu, list):
        raise TypeError('menu must be a list')

    result = []

    def walk(items, prefix):
        if not isinstance(items, list):
            raise ValueError('subitems must be a list')
        for item in items:
            if isinstance(item, str):
                if ':' not in item:
                    raise ValueError('invalid item format')
                name, price = item.split(':', 1)
                if not name or not price or ':' in price:
                    raise ValueError('invalid item format')
                if not price.isdigit():
                    raise ValueError('price must be an integer string')
                path = name if not prefix else prefix + '/' + name
                result.append((path, int(price)))
            elif isinstance(item, tuple):
                if len(item) != 2:
                    raise ValueError('invalid category tuple')
                category_name, subitems = item
                if not isinstance(category_name, str) or not category_name:
                    raise ValueError('invalid category name')
                new_prefix = category_name if not prefix else prefix + '/' + category_name
                walk(subitems, new_prefix)
            else:
                raise ValueError('invalid item type')

    walk(menu, '')
    return result

def normalize_nested_menu(menu):
    """
    Normalize a nested menu specification into a flattened summary.

    Args:
    - menu (list of items): A list of items, where each item can be:
      - A string of the form `'name:price'`, where `name` is non-empty and `price` is a decimal integer string.
      - A 2-tuple `(category_name, subitems)`, where `category_name` is a non-empty string and `subitems` is a list containing only items of the same two allowed forms recursively.

    Returns:
    - list of (path, total_price) tuples: A list of (path, total_price) tuples, one for each string item encountered in depth-first left-to-right order.
    """
    def flatten(item):
        if isinstance(item, str):
            return item.split(':')
        elif isinstance(item, tuple):
            return [flatten(subitem) for subitem in item[1]]
        else:
            raise ValueError(f"Invalid item type: {type(item)}")

    def dfs(node, path, total_price):
        nonlocal path, total_price
        if isinstance(node, str):
            path.append(node)
            total_price += int(node.split(':')[1])
        elif isinstance(node, tuple):
            for subitem in node[1]:
                dfs(subitem, path, total_price)
        else:
            raise ValueError(f"Invalid node type: {type(node)}")

    result = []
    for item in menu:
        try:
            path, total_price = dfs(item, [], 0)
            result.append((path, total_price))
        except ValueError as e:
            raise TypeError(f"Invalid menu: {e}")

    return result

