def decode_sparse_grid(records, default=0):
    if not records:
        return []

    max_row = -1
    max_col = -1
    validated = []

    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("Each record must be a 3-tuple")
        r, c, value = record
        if not isinstance(r, int) or not isinstance(c, int):
            raise ValueError("Row and column indices must be integers")
        if r < 0 or c < 0:
            raise ValueError("Row and column indices must be non-negative")
        if r > max_row:
            max_row = r
        if c > max_col:
            max_col = c
        validated.append((r, c, value))

    grid = [[default for _ in range(max_col + 1)] for _ in range(max_row + 1)]
    for r, c, value in validated:
        grid[r][c] = value
    return grid

