def merge_intervals(intervals):
    """Merge half-open integer intervals.

    Args:
        intervals: sequence of 2-item sequences [start, end) with integers.

    Returns:
        List of merged intervals as [start, end] lists, sorted by start.

    Raises:
        ValueError: if any interval is malformed, non-integer, or has start >= end.
    """
    validated = []
    for item in intervals:
        try:
            if len(item) != 2:
                raise ValueError
            start, end = item[0], item[1]
        except Exception:
            raise ValueError("each interval must be a 2-item sequence")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("interval endpoints must be integers")
        if start >= end:
            raise ValueError("interval start must be less than end")
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [[validated[0][0], validated[0][1]]]

    for start, end in validated[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

