def normalize_event_schedule(events):
    """
    Normalize an event schedule by merging duplicate events with the same title and start/end,
    keeping the first metadata seen for that exact duplicate and ignoring later duplicates.
    Sorts the remaining unique events by start ascending, then end ascending, and then title lexicographically.

    :param events: List of tuples (title, start, end) or (title, start, end, metadata)
    :return: List of dictionaries, each with keys 'title', 'start', 'end', and 'metadata'
    """
    # Helper function to check if a tuple is valid
    def is_valid_tuple(record):
        if not isinstance(record, tuple):
            raise ValueError("Invalid event record")
        if len(record) != 3:
            raise ValueError("Invalid event record format")
        if not all(isinstance(x, int) for x in record):
            raise ValueError("All elements in the event record must be integers")
        if not all(isinstance(x, str) for x in record):
            raise ValueError("All elements in the event record must be strings")
        if not all(isinstance(x, dict) for x in record[2]):
            raise ValueError("Metadata must be a dictionary")
        if record[0] == "":
            raise ValueError("Title cannot be empty")
        if record[1] < 0 or record[2].get('start', None) < 0 or record[2].get('end', None) < 0:
            raise ValueError("Start and end times must be non-negative integers")
        return True

    # Validate each record
    for record in events:
        if not is_valid_tuple(record):
            raise ValueError("Invalid event record")

    # Merge duplicate events
    merged_events = []
    for event in events:
        if event in merged_events:
            merged_events[-1]['metadata'] = event[2]
        else:
            merged_events.append(event)

    # Sort events
    merged_events.sort(key=lambda x: (x[0], x[1], x[2]))

    # Return the normalized schedule
    return [event for event in merged_events]

