        raise TypeError('records must be a list')

    def normalize(s):
        if not isinstance(s, str):
            raise TypeError('path values must be strings')
        parts = []
        for segment in s.split('/'):
            if segment == '' or segment == '.':
                continue
            if segment == '..':
                if parts and parts[-1] != '..':
                    parts.pop()
                else:
                    parts.append('..')
            else:
                parts.append(segment)
        return '/'.join(parts) if parts else '.'

    out = []
    for record in records:
        if 'name' not in record:
            raise KeyError('name')
        if 'path' not in record:
            raise KeyError('path')
        new_record = {}
        for key in record:
            if key == 'path':
                new_record[key] = normalize(record[key])
            elif key == 'alias':
                value = record[key]
                new_record[key] = None if value is None else normalize(value)
            elif key == 'metadata':
                value = record[key]
                new_record[key] = value.copy() if isinstance(value, dict) else value
            else:
                new_record[key] = record[key]
        out.append(new_record)
    return out

def normalize_record_paths(records):
    """
    Normalize record paths by splitting, resolving, and normalizing paths.

    Parameters:
    records (list of dict): A list of record dictionaries.

    Returns:
    list of dict: A new list of normalized record dictionaries.
    """
    def normalize_path(path):
        # Split the path on '/'
        parts = path.split('/')
        # Remove empty segments and '.' segments
        parts = [p for p in parts if p]
        # Resolve '..' by removing the previous kept segment if one exists
        while '..' in parts:
            parts.remove(parts[-2])
        # Join the remaining segments with '/'
        return '/' + '/'.join(parts)

    def normalize_alias(alias):
        # Normalize alias with the same rules as path
        return normalize_path(alias)

    def normalize_metadata(metadata):
        # Copy metadata by value only at the top level
        return metadata.copy()

    normalized_records = []
    for record in records:
        if 'name' not in record or 'path' not in record:
            raise KeyError("Missing required name or path key")
        if not isinstance(record['path'], str):
            raise TypeError("Path must be a string")

        normalized_record = {
            'name': record['name'],
            'path': normalize_path(record['path']),
            'alias': normalize_alias(record.get('alias', None)),
            'metadata': normalize_metadata(record.get('metadata', {}))
        }
        normalized_records.append(normalized_record)

    return normalized_records

