def summarize_plateau_runs(values):
    iterator = iter(values)
    try:
        first = next(iterator)
    except StopIteration:
        return {
            'run_count': 0,
            'longest_run_length': 0,
            'run_lengths_by_value': {},
            'plateau_starts': []
        }

    run_count = 1
    longest_run_length = 1
    run_lengths_by_value = {first: 1}
    plateau_starts = []

    current_value = first
    current_run_length = 1
    index = 0
    current_run_start = 0

    for index, item in enumerate(iterator, start=1):
        run_lengths_by_value[item] = run_lengths_by_value.get(item, 0) + 1
        if item == current_value:
            current_run_length += 1
        else:
            if current_run_length >= 2:
                plateau_starts.append(current_run_start)
            longest_run_length = max(longest_run_length, current_run_length)
            run_count += 1
            current_value = item
            current_run_length = 1
            current_run_start = index

    if current_run_length >= 2:
        plateau_starts.append(current_run_start)
    longest_run_length = max(longest_run_length, current_run_length)

    return {
        'run_count': run_count,
        'longest_run_length': longest_run_length,
        'run_lengths_by_value': run_lengths_by_value,
        'plateau_starts': plateau_starts,
    }

def summarize_plateau_runs(values):
    """
    Analyzes a sequence of integers and returns a dictionary with four keys:
    - run_count: the number of maximal contiguous runs of equal values.
    - longest_run_length: the length of the longest such run.
    - run_lengths_by_value: a dictionary mapping each distinct integer value to the total number of elements belonging to all of its runs combined.
    - plateau_starts: a list of zero-based indices where a run of length at least 2 begins.

    Parameters:
    values (iterable): A sequence of integers.

    Returns:
    dict: A dictionary with the specified keys.
    """
    if not values:
        return {'run_count': 0, 'longest_run_length': 0, 'run_lengths_by_value': {}, 'plateau_starts': []}

    run_counts = {}
    max_length = 0
    current_run = []

    for value in values:
        if value == current_run[-1]:
            current_run.append(value)
        else:
            if len(current_run) > max_length:
                max_length = len(current_run)
                run_counts[current_run[-1]] = len(current_run)
            current_run = [value]

    if len(current_run) > max_length:
        max_length = len(current_run)
        run_counts[current_run[-1]] = len(current_run)

    plateau_starts = []
    for i, value in enumerate(values):
        if i >= 2 and run_counts[value] >= 2:
            plateau_starts.append(i)

    return {
        'run_count': run_counts,
        'longest_run_length': max_length,
        'run_lengths_by_value': run_counts,
        'plateau_starts': plateau_starts
    }

