def render_number_grid(numbers: list[int], width: int) -> str:
    if width < 1:
        raise ValueError("width must be at least 1")
    if not numbers:
        return ""

    def fmt(n: int) -> str:
        if n < 0:
            return f"({abs(n)})"
        return str(n)

    rows = []
    for i in range(0, len(numbers), width):
        row_items = [fmt(n) for n in numbers[i:i + width]]
        rows.append(" ".join(row_items))
    return "\n".join(rows)

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    seen = set()
    grouped = {}

    for record in events:
        if not isinstance(record, tuple) or len(record) != 4:
            raise ValueError("each event must be a 4-tuple")
        day, start, end, label = record
        if not isinstance(day, int) or day < 0:
            raise ValueError("day must be a non-negative integer")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("start and end must be integers")
        if start < 0:
            raise ValueError("start must be non-negative")
        if end < start:
            raise ValueError("end must be >= start")
        if not isinstance(label, str):
            raise ValueError("label must be a string")

        key = (day, start, end, label)
        if key in seen:
            continue
        seen.add(key)
        grouped.setdefault(day, []).append((start, end, label))

    result = []
    for day in sorted(grouped):
        day_events = sorted(grouped[day], key=lambda x: (x[0], x[1], x[2]))
        result.append((day, day_events))
    return result

def normalize_event_schedule(events):
    """
    Normalize an event schedule by grouping events by day, ensuring each day has at most one event.

    Parameters:
    events (list of tuples): A list of event records, where each record is a tuple (day, start, end, label).

    Returns:
    list of tuples: A list of (day, events_for_day) tuples, where events_for_day is a list of (start, end, label) tuples.
    """
    def validate_record(record):
        if not isinstance(record, tuple) or len(record) != 4:
            raise ValueError("Invalid event record.")
        if record[0] < 0:
            raise ValueError("Day cannot be negative.")
        if not all(isinstance(x, int) for x in record[1:]):
            raise ValueError("Start and end must be integers.")
        if record[1] < record[0]:
            raise ValueError("Start cannot be less than end.")
        if not isinstance(record[2], int):
            raise ValueError("End must be an integer.")
        if not isinstance(record[3], str):
            raise ValueError("Label must be a string.")
        return True

    def merge_duplicate_events(events):
        seen = set()
        for record in events:
            if record in seen:
                continue
            seen.add(record)
            events.remove(record)
        return events

    def group_by_day(events):
        day_events = {}
        for record in events:
            if record[0] not in day_events:
                day_events[record[0]] = []
            day_events[record[0]].append(record)
        return day_events

    def sort_events(events):
        events.sort(key=lambda x: (x[0], x[1], x[2]))
        return events

    normalized_events = []
    for day, events in group_by_day(events):
        if not events:
            continue
        events = merge_duplicate_events(events)
        sorted_events = sort_events(events)
        normalized_events.append((day, sorted_events))

    return normalized_events

