def normalize_grid_path(grid, path):
    def invalid(reason):
        return {"valid": False, "normalized": [], "reason": reason}

    # Validate grid
    if not isinstance(grid, list) or len(grid) == 0:
        return invalid("invalid grid")
    first_row_len = None
    for row in grid:
        if not isinstance(row, list) or len(row) == 0:
            return invalid("invalid grid")
        if first_row_len is None:
            first_row_len = len(row)
        elif len(row) != first_row_len:
            return invalid("invalid grid")
        for cell in row:
            if not isinstance(cell, int):
                return invalid("invalid grid")

    # Validate path container
    if not isinstance(path, list):
        return invalid("invalid path")

    rows = len(grid)
    cols = first_row_len
    normalized = []
    seen = set()

    for item in path:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            return invalid("invalid coordinate")
        r, c = item
        if not isinstance(r, int) or not isinstance(c, int):
            return invalid("invalid coordinate")
        if not (0 <= r < rows and 0 <= c < cols):
            return invalid("out of bounds")
        coord = (r, c)
        if coord in seen:
            return invalid("repeated coordinate")
        if normalized:
            pr, pc = normalized[-1]
            if abs(pr - r) + abs(pc - c) != 1:
                return invalid("non-adjacent step")
        seen.add(coord)
        normalized.append(coord)

    return {"valid": True, "normalized": normalized, "reason": "ok"}

def normalize_grid_path(grid, path):
    """
    Validates and normalizes a path through a rectangular grid.

    Parameters:
    - grid: A non-empty list of non-empty lists of integers.
    - path: A list of coordinate pairs, where each pair is a 2-item sequence of integers [row, col].

    Returns:
    - A dictionary with exactly these keys:
      - `"valid"`: boolean
      - `"normalized"`: a list of coordinate tuples `(row, col)` if the path is valid, otherwise an empty list
      - `"reason"`: a string explaining the first validation failure, or `"ok"` if valid
    """
    # Check if the grid is a proper rectangle
    if len(grid) != len(grid[0]) or not all(len(row) == len(grid[0]) for row in grid):
        return {"valid": False, "reason": "invalid grid"}

    # Check if the path is a list
    if not isinstance(path, list):
        return {"valid": False, "reason": "invalid path"}

    # Check if every step in the path is a 2-item sequence of integers
    if not all(isinstance(coord, tuple) for coord in path):
        return {"valid": False, "reason": "invalid coordinate"}

    # Check if every coordinate lies inside the grid bounds
    for coord in path:
        if not (0 <= coord[0] < len(grid) and 0 <= coord[1] < len(grid[0])):
            return {"valid": False, "reason": "out of bounds"}

    # Check if consecutive coordinates are 4-neighbor adjacent
    for i in range(len(path) - 1):
        if abs(path[i][0] - path[i + 1][0]) != 1 or abs(path[i][1] - path[i + 1][1]) != 1:
            return {"valid": False, "reason": "non-adjacent step"}

    # If all checks pass, return valid
    return {"valid": True, "normalized": path, "reason": "ok"}

# Example usage:
print(normalize_grid_path([[1, 2], [3, 4]], [[0, 0], [1, 1]]))  # Output: {"valid": True, "normalized": [(0, 0), (1, 1)], "reason": "ok"}

def normalize_command_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if path == '':
        return ''

    sigil = ''
    if path.startswith('!'):
        sigil = '!'
        path = path[1:]

    segments = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if segments and segments[-1] != '..':
                segments.pop()
            else:
                segments.append('..')
        else:
            segments.append(part)

    if sigil and not segments:
        return '!'
    if sigil:
        return '!/' + '/'.join(segments)
    return '/'.join(segments)

def normalize_markdown_heading(levels):
    try:
        items = list(levels)
    except TypeError:
        raise TypeError("levels must be iterable")

    if not items:
        return {"min": None, "max": None, "normalized": []}

    for x in items:
        if type(x) is not int:
            raise TypeError("all levels must be integers")
        if x < 1:
            raise ValueError("heading levels must be positive integers")

    min_level = min(items)
    max_level = max(items)
    normalized = [x - min_level for x in items]
    return {"min": min_level, "max": max_level, "normalized": normalized}

def merge_intervals(intervals):
    try:
        items = list(intervals)
    except TypeError:
        raise TypeError('intervals must be iterable')

    validated = []
    for item in items:
        try:
            pair = list(item)
        except TypeError:
            raise TypeError('each interval must be an iterable of two integers')
        if len(pair) != 2:
            raise TypeError('each interval must contain exactly two integers')
        a, b = pair
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError('each interval must contain exactly two integers')
        if a > b:
            raise ValueError('interval start must not exceed end')
        validated.append((a, b))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [list(validated[0])]
    for start, end in validated[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def parse_ledger_balance(lines):
    balance = None
    saw_instruction = False
    for raw in lines:
        if raw is None:
            raise ValueError("invalid instruction")
        line = raw.strip()
        if not line:
            continue
        saw_instruction = True
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("invalid instruction")
        cmd, arg_text = parts
        try:
            value = int(arg_text)
        except Exception:
            raise ValueError("invalid integer")
        if cmd == "SET":
            balance = value
        elif cmd == "ADD":
            if balance is None:
                raise ValueError("missing initial SET")
            balance += value
        elif cmd == "SUB":
            if balance is None:
                raise ValueError("missing initial SET")
            balance -= value
        elif cmd == "MUL":
            if balance is None:
                raise ValueError("missing initial SET")
            balance *= value
        elif cmd == "DIV":
            if balance is None:
                raise ValueError("missing initial SET")
            if value == 0:
                raise ZeroDivisionError("division by zero")
            balance //= value
        else:
            raise ValueError("unknown command")
    if not saw_instruction:
        raise ValueError("no instructions")
    if balance is None:
        raise ValueError("missing initial SET")
    return balance

def parse_ledger_balance(lines):
    """
    Parses a simple text ledger and returns the final balance as an integer.

    Args:
    lines (iterable of str): A list of strings representing ledger instructions.

    Returns:
    int: The final balance after processing all instructions.

    Raises:
    ValueError: If the input is not a valid ledger format.
    ZeroDivisionError: If division by zero occurs.
    """
    balance = 0
    for line in lines:
        # Strip leading and trailing whitespace
        line = line.strip()

        # Check if the line is a valid command
        if line.startswith("SET"):
            try:
                balance = int(line.split()[1])
            except ValueError:
                raise ValueError(f"Invalid SET command: {line}")
        elif line.startswith("ADD"):
            try:
                balance += int(line.split()[1])
            except ValueError:
                raise ValueError(f"Invalid ADD command: {line}")
        elif line.startswith("SUB"):
            try:
                balance -= int(line.split()[1])
            except ValueError:
                raise ValueError(f"Invalid SUB command: {line}")
        elif line.startswith("MUL"):
            try:
                balance *= int(line.split()[1])
            except ValueError:
                raise ValueError(f"Invalid MUL command: {line}")
        elif line.startswith("DIV"):
            try:
                balance //= int(line.split()[1])
            except ZeroDivisionError:
                raise ZeroDivisionError(f"Division by zero error: {line}")
        else:
            raise ValueError(f"Unknown command: {line}")

    return balance

