def normalize_channel_name(name):
    if not isinstance(name, str):
        raise TypeError("name must be a str")

    s = name.strip().lower()

    # Replace runs of whitespace, underscores, and hyphens with a single hyphen.
    out = []
    in_sep = False
    for ch in s:
        if ch.isspace() or ch == '_' or ch == '-':
            if not in_sep:
                out.append('-')
                in_sep = True
        else:
            in_sep = False
            if 'a' <= ch <= 'z' or '0' <= ch <= '9':
                out.append(ch)
            # other characters are discarded

    result = ''.join(out)

    # Collapse any accidental repeated hyphens from adjacent separator groups.
    collapsed = []
    prev_hyphen = False
    for ch in result:
        if ch == '-':
            if not prev_hyphen:
                collapsed.append(ch)
            prev_hyphen = True
        else:
            collapsed.append(ch)
            prev_hyphen = False

    final = ''.join(collapsed).strip('-')
    if not final:
        raise ValueError("normalized name is empty")
    return final

def normalize_tags(text):
    if not isinstance(text, str):
        raise ValueError('text must be a string')

    entries = {}
    if text == '':
        return ''

    parts = text.split(';')
    for raw_part in parts:
        part = raw_part.strip()
        if part == '':
            continue

        if '=' in part:
            if part.count('=') != 1:
                raise ValueError('malformed entry')
            left, right = part.split('=')
            key = left.strip()
            value = right.strip()
            if key == '':
                raise ValueError('empty key')
            entries[key] = value
        else:
            key = part.strip()
            if key == '':
                raise ValueError('empty key')
            entries[key] = True

    items = []
    for key in sorted(entries):
        value = entries[key]
        if value is True:
            rendered = 'true'
        else:
            rendered = value
        items.append(f'{key}={rendered}')
    return ';'.join(items)

