def split_sql_statements(script: str) -> list[str]:
    statements = []
    current = []
    in_string = False
    i = 0
    n = len(script)

    while i < n:
        ch = script[i]
        if in_string:
            current.append(ch)
            if ch == "'":
                if i + 1 < n and script[i + 1] == "'":
                    current.append("'")
                    i += 1
                else:
                    in_string = False
        else:
            if ch == "'":
                in_string = True
                current.append(ch)
            elif ch == ";":
                stmt = "".join(current).strip()
                if stmt:
                    statements.append(stmt)
                current = []
            else:
                current.append(ch)
        i += 1

    if in_string:
        raise ValueError("unterminated single-quoted string")

    stmt = "".join(current).strip()
    if stmt:
        statements.append(stmt)
    return statements

def normalize_route(routes):
    def validate_segment(seg):
        if not isinstance(seg, str):
            raise TypeError("segment must be a string")
        if seg == "":
            raise ValueError("empty segment")
        if "/" in seg:
            raise ValueError("segment cannot contain '/'")

    def walk(items, prefix, depth, out):
        if not isinstance(items, list):
            raise TypeError("children must be a list")
        for item in items:
            if isinstance(item, str):
                validate_segment(item)
                path = item if not prefix else prefix + "/" + item
                out.append((path, depth))
            elif isinstance(item, tuple):
                if len(item) != 2:
                    raise TypeError("tuple must have exactly two items")
                name, children = item
                validate_segment(name)
                if not isinstance(children, list):
                    raise TypeError("children must be a list")
                new_prefix = name if not prefix else prefix + "/" + name
                walk(children, new_prefix, depth + 1, out)
            else:
                raise TypeError("invalid route item")

    result = []
    walk(routes, "", 0, result)
    return result

def normalize_route(routes):
    def dfs(route, depth=0):
        if isinstance(route, str):
            if '/' in route:
                raise ValueError("Segment names cannot contain '/'")
            return (route, depth)
        elif isinstance(route, tuple):
            name, children = route
            if not isinstance(name, str) or not isinstance(children, list):
                raise TypeError("Segment names and children must be strings and lists respectively.")
            if not all(isinstance(segment, str) for segment in children):
                raise TypeError("All children must be strings.")
            return (f"{name}/{', '.join(children)}", depth + 1)
        else:
            raise TypeError("Invalid route type")

    normalized_routes = []
    for route in routes:
        normalized_route.append(dfs(route))
    return normalized_routes

