        parts = segment.split("-")
        if len(parts) != 2:
            raise ValueError("malformed segment")
        start_s, end_s = parts
        if start_s == "" or end_s == "":
            raise ValueError("malformed segment")
        if not start_s.isdigit() or not end_s.isdigit():
            raise ValueError("malformed segment")
        start = int(start_s)
        end = int(end_s)
        if start > end:
            raise ValueError("start greater than end")
        total += end - start
    return total

def normalize_license_plate(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    s = text.strip()
    cleaned = []
    for ch in s:
        if 'a' <= ch <= 'z':
            cleaned.append(chr(ord(ch) - 32))
        elif 'A' <= ch <= 'Z' or '0' <= ch <= '9':
            cleaned.append(ch)
    result = ''.join(cleaned)
    if not result:
        raise ValueError('no ASCII alphanumeric characters found')
    return result

def normalize_event_log(events):
