def compress_spans(values):
    if not isinstance(values, list):
        raise TypeError('values must be a list')
    if not values:
        return []
    for x in values:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
    result = []
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.append((current, count))
            current = x
            count = 1
    result.append((current, count))
    return result

def compress_intervals(intervals):
    validated = []
    for item in intervals:
        if not hasattr(item, '__len__') or len(item) != 2:
            raise TypeError('each interval must have exactly two items')
        start, end = item[0], item[1]
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('interval bounds must be integers')
        if start > end:
            raise ValueError('interval start cannot exceed end')
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [[validated[0][0], validated[0][1]]]

    for start, end in validated[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

def normalize_event_tags(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    result = {}
    for event in events:
        if not isinstance(event, tuple) or len(event) != 2:
            raise TypeError('each event must be a tuple of length 2')
        day, tags = event
        if not isinstance(day, int):
            raise TypeError('day must be an integer')
        try:
            iterator = iter(tags)
        except TypeError:
            raise TypeError('tags must be iterable')

        day_tags = result.setdefault(day, set())
        for tag in iterator:
            if not isinstance(tag, str):
                raise TypeError('each tag must be a string')
            normalized = tag.strip().lower()
            if normalized:
                day_tags.add(normalized)

    return {day: sorted(tags) for day, tags in result.items()}

def normalize_event_tags(events):
    """
    Normalize event tags by converting them to lowercase, stripping whitespace,
    ignoring empty strings, and maintaining lexicographic order for each day.

    :param events: List of tuples (day, tags)
    :return: Dictionary mapping each day to a sorted list of unique normalized tags
    """
    if not isinstance(events, list):
        raise TypeError("events must be a list.")
    if not all(isinstance(event, tuple) for event in events):
        raise TypeError("All events must be tuples of length 2.")
    if not all(isinstance(day, int) for day in events):
        raise TypeError("All days must be integers.")
    if not all(isinstance(tag, str) for tag in events[0][1]):
        raise TypeError("All tags must be strings.")

    # Initialize the result dictionary
    result = {}

    # Iterate over each event
    for day, tags in events:
        # Convert tags to lowercase, strip whitespace, and filter out empty strings
        normalized_tags = [tag.lower().strip() for tag in tags if tag]

        # Sort the tags and add to the result dictionary
        sorted_tags = sorted(normalized_tags)
        result[day] = sorted_tags

    return result

