    else:
        parts.append(f"{start}-{prev}")

    return ",".join(parts)

def align_collections(items, defaults):
    if not hasattr(defaults, 'items'):
        raise TypeError('defaults must support items()')
    try:
        default_pairs = list(defaults.items())
    except Exception:
        raise TypeError('defaults must support items()')

    normalized = []
    seen_default_keys = set()
    item_list = []
    for pair in items:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError('each item must be a 2-tuple')
        item_list.append(pair)

    for key, default_value in default_pairs:
        seen_default_keys.add(key)
        found = False
        last_value = default_value
        for k, v in item_list:
            try:
                if k == key:
                    found = True
                    last_value = v
            except Exception:
                raise TypeError('unhashable or uncomparable key')
        normalized.append((key, last_value if found else default_value))

    for k, v in item_list:
        try:
            in_defaults = k in seen_default_keys
        except TypeError:
            raise TypeError('unhashable key')
        if not in_defaults:
            normalized.append((k, v))

    return normalized

def max_balanced_subarray_sum(nums):
    if not isinstance(nums, list):
        raise TypeError('nums must be a list of integers')
    for x in nums:
        if not isinstance(x, int):
            raise TypeError('nums must be a list of integers')

    prefix = 0
    seen = {0: -1}
    best = None
    for i, x in enumerate(nums):
        prefix += x
        if prefix in seen:
            # sum of subarray from seen[prefix]+1 to i is zero
            # Since only zero-sum subarrays are allowed, their sum is always 0.
            if best is None or 0 > best:
                best = 0
        else:
            seen[prefix] = i
    return 0 if best is None else best

def normalize_nested_counts(data):
    if isinstance(data, bool):
        return data
    if isinstance(data, int):
        return data // 2 if data % 2 == 0 else 3 * data + 1
    if isinstance(data, str):
        return data
    if isinstance(data, list):
        return [normalize_nested_counts(x) for x in data]
    if isinstance(data, tuple):
        return tuple(normalize_nested_counts(x) for x in data)
    if isinstance(data, dict):
        return {k: normalize_nested_counts(v) for k, v in data.items()}
    raise TypeError(f'Unsupported type: {type(data).__name__}')

def normalize_nested_counts(data):
    """
    Normalize the counts in a nested structure where even integers become n // 2,
    odd integers become 3 * n + 1, and boolean values remain unchanged.
    Strings are returned unchanged, and dictionaries are processed recursively.

    Parameters:
    data (dict or list): The nested structure to normalize.

    Returns:
    dict or list: A new structure with the normalized counts.
    """
    def normalize_value(value):
        if isinstance(value, int):
            return value // 2 if value % 2 == 0 else 3 * value + 1
        elif isinstance(value, bool):
            return value
        elif isinstance(value, str):
            return value
        elif isinstance(value, list):
            return [normalize_value(item) for item in value]
        elif isinstance(value, tuple):
            return tuple(normalize_value(item) for item in value)
        else:
            raise TypeError(f"Unsupported type: {type(value)}")

    return normalize_value(data)

