def normalize_sensor_readings(readings):
    retained = {}
    order = {}

    for idx, record in enumerate(readings):
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise TypeError("Each record must be a 3-item sequence")
        timestamp, sensor_id, value = record
        if not isinstance(timestamp, (int, float)) or isinstance(timestamp, bool):
            raise TypeError("timestamp must be int or float")
        if not isinstance(sensor_id, str):
            raise TypeError("sensor_id must be a string")
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("value must be int or float")
        if value < 0:
            continue
        if sensor_id not in retained or timestamp > retained[sensor_id][0] or timestamp == retained[sensor_id][0]:
            retained[sensor_id] = (timestamp, float(value), idx)

    if not retained:
        return []

    max_value = max(v for _, v, _ in retained.values())
    items = []
    for sensor_id in sorted(retained):
        _, value, _ = retained[sensor_id]
        if max_value == 0:
            norm = 0.0
        else:
            norm = float(value / max_value)
        items.append((sensor_id, norm))
    return items

def normalize_schedule(entries):
    try:
        iterator = iter(entries)
    except TypeError:
        raise TypeError("entries must be iterable of strings")

    result = []
    for item in iterator:
        if not isinstance(item, str):
            raise TypeError("all entries must be strings")
        s = item.strip()
        if not s:
            continue
        if ':' not in s:
            result.append(s)
            continue
        before, after = s.split(':', 1)
        before_stripped = before.strip()
        after_stripped = after.strip()
        if before_stripped.isalpha():
            before_norm = before_stripped.title()
        else:
            before_norm = before_stripped
        if '-' in after_stripped:
            left, right = after_stripped.split('-', 1)
            after_norm = left.strip() + '-' + right.strip()
        else:
            after_norm = after_stripped
        result.append(before_norm + ':' + after_norm)
    return result

def parse_status_table(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    lines = [line for line in text.split('\n') if line.strip() != '']
    if not lines:
        return []

    header_parts = [part.strip() for part in lines[0].split('|')]
    if any(part == '' for part in header_parts):
        raise ValueError('header names must be non-empty')
    if len(set(header_parts)) != len(header_parts):
        raise ValueError('duplicate header names')

    result = []
    width = len(header_parts)
    for line in lines[1:]:
        parts = [part.strip() for part in line.split('|')]
        if len(parts) != width:
            raise ValueError('row has wrong number of fields')
        result.append(dict(zip(header_parts, parts)))
    return result

def normalize_prerequisite_plan(plan):
    valid = {}
    order = []
    for item in plan:
        if not isinstance(item, tuple) or len(item) != 2:
            continue
        course, prereqs = item
        if not isinstance(course, str):
            continue
        if course not in valid:
            valid[course] = []
            order.append(course)
        seen = set(valid[course])
        try:
            iterator = iter(prereqs)
        except TypeError:
            continue
        for p in iterator:
            if isinstance(p, str) and p not in seen:
                valid[course].append(p)
                seen.add(p)
    if not order:
        return ((), ())
    sorted_courses = tuple(sorted(order))
    adjacency = tuple(tuple(valid[c]) for c in sorted_courses)
    return (sorted_courses, adjacency)

def normalize_event_schedule(events):
    valid = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 4:
            continue
        start, end, label, priority = item
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        if not isinstance(label, str) or not isinstance(priority, int):
            continue
        if start >= end:
            continue
        valid.append((start, end, label, priority))

    by_label = {}
    for start, end, label, priority in valid:
        by_label.setdefault(label, []).append((start, end, priority))

    merged = []
    for label, intervals in by_label.items():
        intervals.sort(key=lambda x: (x[0], x[1], -x[2]))
        cur_s, cur_e, cur_p = intervals[0]
        for s, e, p in intervals[1:]:
            if s <= cur_e:
                if e > cur_e:
                    cur_e = e
                if p > cur_p:
                    cur_p = p
                if s < cur_s:
                    cur_s = s
            else:
                merged.append((cur_s, cur_e, label, cur_p))
                cur_s, cur_e, cur_p = s, e, p
        merged.append((cur_s, cur_e, label, cur_p))

    merged.sort(key=lambda x: (x[0], x[1], x[2]))
    return merged

def compress_runs(sequence):
