    Normalize a sequence of sensor readings. Each reading is either a 3-tuple
    (timestamp, sensor_id, value) or the literal string 'gap'.

    :param data: List of tuples or strings representing sensor readings.
    :return: A list of tuples with normalized values.
    """
    def normalize_reading(reading):
        if not isinstance(reading, (tuple, str)):
            raise TypeError("Each element must be a tuple or a string.")
        if len(reading) != 3:
            raise ValueError("Each tuple must have exactly three elements.")

        timestamp, sensor_id, value = reading

        try:
            timestamp_as_float = float(timestamp)
            value_as_float = float(value)
