def normalize_interval(interval):
    def to_int(x):
        if isinstance(x, bool):
            raise ValueError('invalid integer')
        if not isinstance(x, int):
            raise ValueError('invalid integer')
        return x

    def normalize_pair(a, b):
        a = to_int(a)
        b = to_int(b)
        if a <= b:
            return (a, b + 1)
        return (b, a + 1)

    if isinstance(interval, (list, tuple)):
        if len(interval) != 2:
            raise TypeError('interval must have exactly two items')
        return normalize_pair(interval[0], interval[1])

    if isinstance(interval, str):
        s = interval.strip()
        sep = None
        if '..' in s:
            parts = s.split('..')
            sep = '..'
        elif ':' in s:
            parts = s.split(':')
            sep = ':'
        else:
            # dash parsing with support for negative numbers
            if s.count('-') < 1:
                raise ValueError('invalid interval string')
            # find separator dash: last dash that is not part of first number's sign
            idx = None
            for i in range(1, len(s)):
                if s[i] == '-':
                    idx = i
                    break
            if idx is None:
                raise ValueError('invalid interval string')
            parts = [s[:idx], s[idx+1:]]
            sep = '-'
        if len(parts) != 2:
            raise ValueError('invalid interval string')
        left = parts[0].strip()
        right = parts[1].strip()
        if left == '' or right == '':
            raise ValueError('invalid interval string')
        try:
            a = int(left)
            b = int(right)
        except Exception:
            raise ValueError('invalid interval string')
        return normalize_pair(a, b)

    raise TypeError('unsupported interval type')

def normalize_interval(interval):
    """
    Normalize an interval description into a canonical half-open interval representation.

    Parameters:
    interval (list or tuple): A 2-item tuple or list [start, end] or (start, end).

    Returns:
    tuple: A tuple (start, end + 1) representing the normalized interval.

    Raises:
    TypeError: If the input is not a list, tuple, or string.
    ValueError: If the string cannot be parsed as one of the supported interval formats.
    """
    if not isinstance(interval, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    if len(interval) != 2:
        raise ValueError("Input must contain exactly two items.")

    try:
        start, end = map(int, interval)
    except ValueError:
        raise ValueError(f"Invalid interval format: {interval}")

    if start <= end:
        return (start, end + 1)
    else:
        return (end, start + 1)

