def plan_ledger(payments, cap):
    if not isinstance(payments, (list, tuple)):
        raise TypeError("payments must be a list or tuple")
    if not isinstance(cap, int):
        raise TypeError("cap must be an integer")
    if cap < 0:
        raise ValueError("cap must be non-negative")

    total = 0
    clipped = []
    net_positive = 0
    first_over_cap = -1

    for i, p in enumerate(payments):
        total += p
        if p > cap:
            cp = cap
        elif p < -cap:
            cp = -cap
        else:
            cp = p
        clipped.append(cp)
        if cp > 0:
            net_positive += cp
        if first_over_cap == -1 and abs(p) > cap:
            first_over_cap = i

    return {
        "count": len(payments),
        "sum": total,
        "clipped": clipped,
        "net_positive": net_positive,
        "first_over_cap": first_over_cap,
    }

def normalize_channel_labels(labels):
    if not isinstance(labels, (list, tuple)):
        raise TypeError("labels must be a list or tuple")

    result = []
    for label in labels:
        if not isinstance(label, str):
            raise TypeError("each label must be a string")

        s = label.strip().upper()

        out = []
        prev_underscore = False
        for ch in s:
            if ch.isalnum() and ch.isascii():
                out.append(ch)
                prev_underscore = False
            elif ch in "-_" or ch.isspace():
                if not prev_underscore:
                    out.append("_")
                    prev_underscore = True
            else:
                pass
        normalized = "".join(out).strip("_")
        if not normalized:
            normalized = "UNKNOWN"
        if normalized == "LFE":
            normalized = "SUB"
        result.append(normalized)
    return result

def normalize_inventory(records):
    if records is None:
        raise TypeError("records must be a sequence of 3-item records")
    totals = {}
    for rec in records:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            raise TypeError("each record must be a 3-item tuple or list")
        sku, quantity, unit_price = rec
        if not isinstance(sku, str):
            raise TypeError("sku must be a string")
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError("quantity must be an integer")
        if not isinstance(unit_price, (int, float)) or isinstance(unit_price, bool):
            raise TypeError("unit_price must be numeric")
        if sku not in totals:
            totals[sku] = [0, 0.0]
        totals[sku][0] += quantity
        totals[sku][1] += quantity * float(unit_price)
    out = []
    for sku in sorted(totals):
        total_qty, weighted_sum = totals[sku]
        avg = 0.0 if total_qty == 0 else weighted_sum / total_qty
        out.append((sku, total_qty, float(avg)))
    return out

def summarize_transcript(lines):
    result = {}
    for line in lines:
        if line.count(':') != 1:
            raise ValueError('Each line must contain exactly one colon')
        speaker_raw, message = line.split(':', 1)
        speaker = speaker_raw.strip().lower()
        if not speaker:
            raise ValueError('Speaker name cannot be blank')
        if message.startswith(' '):
            message = message[1:]
        if speaker not in result:
            result[speaker] = {'turns': 0, 'chars': 0}
        result[speaker]['turns'] += 1
        result[speaker]['chars'] += len(message)
    return result

def balance_multiset_difference(a, b):
    try:
        iter_a = iter(a)
        iter_b = iter(b)
    except TypeError:
        raise TypeError("inputs must be iterable")

    counts = {}

    def add_items(it, delta):
        for item in it:
            try:
                counts[item] = counts.get(item, 0) + delta
            except TypeError:
                raise TypeError("items must be hashable")

    add_items(iter_a, 1)
    add_items(iter_b, -1)

    only_a = []
    only_b = []
    for item, diff in counts.items():
        if diff > 0:
            only_a.append((item, diff))
        elif diff < 0:
            only_b.append((item, -diff))

    only_a.sort(key=lambda p: repr(p[0]))
    only_b.sort(key=lambda p: repr(p[0]))
    return (tuple(only_a), tuple(only_b))

def merge_intervals_with_gaps(intervals, max_gap):
    if not isinstance(max_gap, (int, float)) or isinstance(max_gap, bool) or max_gap < 0:
        raise TypeError("max_gap must be a non-negative number")

    try:
        items = list(intervals)
    except TypeError:
        raise TypeError("intervals must be an iterable of intervals")

    normalized = []
    for interval in items:
        try:
            pair = list(interval)
        except TypeError:
            raise TypeError("each interval must be an iterable of two numeric values")
        if len(pair) != 2:
            raise TypeError("each interval must contain exactly two values")
        start, end = pair
        if isinstance(start, bool) or isinstance(end, bool) or not isinstance(start, (int, float)) or not isinstance(end, (int, float)):
            raise TypeError("interval endpoints must be numeric")
        if start > end:
            raise ValueError("interval start must not exceed end")
        normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]

    for start, end in normalized[1:]:
        cur_start, cur_end = merged[-1]
        gap = start - cur_end
        if gap <= max_gap:
            merged[-1] = (cur_start, end if end > cur_end else cur_end)
        else:
            merged.append((start, end))

    return merged

def normalize_schedule(entries):
    if not isinstance(entries, list):
        raise ValueError('entries must be a list')

    day_order = {'Mon': 0, 'Tue': 1, 'Wed': 2, 'Thu': 3, 'Fri': 4, 'Sat': 5, 'Sun': 6}
    seen = set()
    parsed = []

    def parse_time(s):
        if len(s) != 5 or s[2] != ':':
            raise ValueError('invalid time format')
        hh = s[:2]
        mm = s[3:]
        if not (hh.isdigit() and mm.isdigit()):
            raise ValueError('invalid time digits')
        h = int(hh)
        m = int(mm)
        if not (0 <= h <= 23 and 0 <= m <= 59):
            raise ValueError('invalid time value')
        return h * 60 + m

    for entry in entries:
        if not isinstance(entry, str):
            raise ValueError('each entry must be a string')
        if ':' not in entry:
            raise ValueError('malformed entry')
        day, rest = entry.split(':', 1)
        if day not in day_order:
            raise ValueError('invalid day')
        if '-' not in rest:
            raise ValueError('malformed entry')
        start_s, end_s = rest.split('-', 1)
        start = parse_time(start_s)
        end = parse_time(end_s)
        if start >= end:
            raise ValueError('start must be earlier than end')
        canonical = f"{day}:{start_s[:2]}:{start_s[3:]}"  # placeholder to be corrected
        # Build canonical directly from parsed times
        sh, sm = divmod(start, 60)
        eh, em = divmod(end, 60)
        canonical = f"{day}:{sh:02d}:{sm:02d}-{eh:02d}:{em:02d}".replace(':', ':', 1)
        # The above produces DAY:HH:MM-HH:MM already
        canonical = f"{day}:{sh:02d}:{sm:02d}-{eh:02d}:{em:02d}"
        key = (day_order[day], start, end)
        if key not in seen:
            seen.add(key)
            parsed.append((key, canonical))

    parsed.sort(key=lambda item: item[0])
    return [canonical for _, canonical in parsed]

