    return normalized

def normalize_schedule(entries):
    """
    Normalize a list of schedule entries into a new list of normalized, deduplicated entries.

    Each entry is a tuple or list of exactly 3 items: (start, end, label).
    - Validate every entry.
    - Require start <= end.
    - Normalize each entry by converting it to a tuple (start, end, label).
    - Remove duplicates while preserving only one copy of identical normalized entries.
    - Return the unique normalized entries sorted ascending by start, then end, then label.

    :param entries: List of schedule entries.
    :return: A new list of normalized, deduplicated entries.
    """
    def normalize_entry(entry):
        try:
            start, end, label = entry
            if not isinstance(start, int) or not isinstance(end, int) or not isinstance(label, str):
                raise TypeError("All entries must be tuples or lists of exactly 3 items.")
            if start > end:
                raise ValueError("Start time must be less than or equal to end time.")
            return (start, end, label)
        except TypeError as e:
            raise TypeError(e)
        except ValueError as e:
            raise ValueError(e)

    normalized_entries = []
    for entry in entries:
        normalized_entry = normalize_entry(entry)
        if normalized_entry not in normalized_entries:
            normalized_entries.append(normalized_entry)

    return sorted(normalized_entries, key=lambda x: (x[0], x[1], x[2]))

