def canonicalize_segments(paths):
    try:
        iterator = iter(paths)
    except TypeError:
        raise TypeError("paths must be iterable")

    result = []
    seen = set()

    for path in iterator:
        if not isinstance(path, str):
            raise TypeError("all elements must be strings")

        rooted = len(path) > 0 and path[0] in ('/', '\\')
        parts = []
        i = 0
        n = len(path)
        while i < n:
            if path[i] in ('/', '\\'):
                i += 1
                continue
            j = i
            while j < n and path[j] not in ('/', '\\'):
                j += 1
            seg = path[i:j]
            if seg == '.' or seg == '':
                pass
            elif seg == '..':
                if parts and parts[-1] != '..':
                    parts.pop()
                else:
                    if not rooted:
                        parts.append('..')
            else:
                parts.append(seg)
            i = j

        if rooted:
            if parts:
                normalized = '/' + '/'.join(parts)
            else:
                normalized = '/'
        else:
            normalized = '/'.join(parts) if parts else '.'

        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)

    return result

def normalize_record(record):
    if not isinstance(record, dict):
        raise TypeError('record must be a dict')
    if set(record.keys()) != {'id', 'tags', 'meta'}:
        raise ValueError('record must contain exactly id, tags, and meta')

    rid = record['id']
    if not isinstance(rid, int) or isinstance(rid, bool) or rid <= 0:
        raise ValueError('id must be a positive integer')

    tags = record['tags']
    if not isinstance(tags, list):
        raise TypeError('tags must be a list')
    seen = set()
    deduped = []
    for tag in tags:
        if not isinstance(tag, str):
            raise TypeError('each tag must be a string')
        if tag not in seen:
            seen.add(tag)
            deduped.append(tag)
    normalized_tags = tuple(sorted(deduped))

    meta = record['meta']
    if not isinstance(meta, dict):
        raise TypeError('meta must be a dict')
    normalized_meta = tuple(sorted(meta.items(), key=lambda kv: kv[0]))

    return (rid, normalized_tags, normalized_meta)

def normalize_tag_list(tags):
    if not isinstance(tags, list):
        raise TypeError("tags must be a list")

    seen = set()
    result = []
    for item in tags:
        if item is None:
            continue
        if not isinstance(item, str):
            raise TypeError("each tag must be a string or None")
        if item == "":
            continue
        normalized = item.strip().lower()
        if normalized == "":
            continue
        if "," in normalized:
            raise ValueError("tags may not contain commas")
        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return ",".join(result)

def parse_duration(expr):
    if not isinstance(expr, str) or expr == "":
        raise ValueError("invalid duration expression")

    multipliers = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    seen = set()
    total = 0
    i = 0
    n = len(expr)

    while i < n:
        if not expr[i].isdigit():
            raise ValueError("invalid duration expression")
        start = i
        while i < n and expr[i].isdigit():
            i += 1
        if i >= n:
            raise ValueError("invalid duration expression")
        unit = expr[i]
        if unit not in multipliers:
            raise ValueError("invalid duration expression")
        if unit in seen:
            raise ValueError("invalid duration expression")
        seen.add(unit)
        amount = int(expr[start:i])
        total += amount * multipliers[unit]
        i += 1

    return total

def sanitize_column_names(headers):
    try:
        iterator = iter(headers)
    except TypeError:
        raise TypeError('headers must be iterable of strings')

    result = []
    counts = {}

    for item in iterator:
        if not isinstance(item, str):
            raise TypeError('all headers must be strings')
        s = item.lower()
        out = []
        prev_underscore = False
        for ch in s:
            if ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch == '_':
                if ch == '_':
                    if not prev_underscore:
                        out.append(ch)
                    prev_underscore = True
                else:
                    out.append(ch)
                    prev_underscore = False
            else:
                if not prev_underscore:
                    out.append('_')
                    prev_underscore = True
        name = ''.join(out).strip('_')
        name = name if name else 'col'

        if name in counts:
            counts[name] += 1
            unique = f'{name}_{counts[name]}'
            while unique in counts:
                counts[name] += 1
                unique = f'{name}_{counts[name]}'
            counts[unique] = 0
            result.append(unique)
        else:
            counts[name] = 0
            result.append(name)
    return result

def top_k_frequent_ngrams(text, n, k):
    if n < 1:
        raise ValueError("n must be at least 1")
    if k == 0:
        return []
    words = text.split()
    if n > len(words):
        return []
    counts = {}
    for i in range(len(words) - n + 1):
        ng = tuple(words[i:i + n])
        counts[ng] = counts.get(ng, 0) + 1
    items = list(counts.items())
    items.sort(key=lambda pair: (-pair[1], pair[0]))
    return items[:k]

def parse_duration_to_seconds(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    if text == "":
        raise ValueError("empty string")

    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen = set()
    total = 0
    i = 0
    n = len(text)

    while i < n:
        if not text[i].isdigit():
            raise ValueError("expected digit")
        j = i
        while j < n and text[j].isdigit():
            j += 1
        if j == n:
            raise ValueError("missing unit")
        unit = text[j]
        if unit not in units:
            raise ValueError("unsupported unit")
        if unit in seen:
            raise ValueError("duplicate unit")
        value = int(text[i:j])
        total += value * units[unit]
        seen.add(unit)
        i = j + 1

    return total

def summarize_digit_runs(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    lengths = []
    values = []
    current = []

    def flush_run():
        if current:
            run = ''.join(current)
            lengths.append(len(run))
            values.append(int(run))
            current.clear()

    for ch in text:
        if '0' <= ch <= '9':
            current.append(ch)
        else:
            flush_run()
    flush_run()

    return {
        'count': len(lengths),
        'lengths': lengths,
        'values': values,
        'longest': max(lengths) if lengths else 0,
    }

def normalize_interval_list(intervals):
    if intervals is None:
        raise ValueError("intervals must be a list of intervals")
    normalized = []
    copied = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each interval must have exactly two elements")
        start, end = item[0], item[1]
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must be <= end")
        copied.append((start, end))
    if not copied:
        return []
    copied.sort(key=lambda x: (x[0], x[1]))
    cur_start, cur_end = copied[0]
    for start, end in copied[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            normalized.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    normalized.append([cur_start, cur_end])
    return normalized

def stable_partition_by_threshold(values, threshold):
    if not isinstance(threshold, int):
        raise TypeError("threshold must be an integer")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")
    lower = []
    upper = []
    for item in iterator:
        if item < threshold:
            lower.append(item)
        else:
            upper.append(item)
    return lower + upper

def normalize_interval_schedule(schedule):
    if schedule == []:
        return []

    validated = []
    for interval in schedule:
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise ValueError('Each interval must be a 2-item sequence')
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('Interval endpoints must be integers')
        if start >= end:
            raise ValueError('Interval start must be less than end')
        validated.append((start, end))

    validated.sort(key=lambda x: x[0])
    merged = [validated[0]]
    for start, end in validated[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def summarize_event_log(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    valid_actions = {'start', 'stop', 'pause'}
    counts = {'start': 0, 'stop': 0, 'pause': 0}

    for item in events:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each event must be a tuple of length 2')
        timestamp, action = item
        if not isinstance(timestamp, int):
            raise TypeError('timestamp must be an int')
        if not isinstance(action, str):
            raise TypeError('action must be a str')
        if action not in valid_actions:
            raise ValueError('invalid action')
        counts[action] += 1

    count = len(events)
    first_timestamp = events[0][0] if events else None
    last_timestamp = events[-1][0] if events else None

    transitions = 0
    has_gap = False
    for i in range(1, len(events)):
        prev_ts, prev_action = events[i - 1]
        ts, action = events[i]
        if action != prev_action:
            transitions += 1
        if ts - prev_ts > 10:
            has_gap = True

    return {
        'count': count,
        'first_timestamp': first_timestamp,
        'last_timestamp': last_timestamp,
        'actions': counts,
        'transitions': transitions,
        'has_gap': has_gap,
    }

def normalize_schedule(entries):
    if entries == []:
        return []

    expanded = []
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError('invalid entry')
        start, end, label = entry
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('invalid entry')
        if not (0 <= start <= 1439) or not (0 <= end <= 1439):
            raise ValueError('invalid entry')
        if not isinstance(label, str) or label == '':
            raise ValueError('invalid entry')

        if start <= end:
            expanded.append((start, end, label))
        else:
            expanded.append((start, 1439, label))
            expanded.append((0, end, label))

    by_label = {}
    for start, end, label in expanded:
        by_label.setdefault(label, []).append((start, end))

    result = []
    for label in sorted(by_label):
        intervals = sorted(by_label[label])
        merged = []
        for s, e in intervals:
            if not merged:
                merged.append([s, e])
            else:
                ps, pe = merged[-1]
                if s <= pe + 1:
                    merged[-1][1] = max(pe, e)
                else:
                    merged.append([s, e])
        for s, e in merged:
            result.append((s, e, label))

    result.sort(key=lambda x: (x[2], x[0]))
    return result

def normalize_inventory(records):
    summary = {}
    if not isinstance(records, list):
        return summary
    for rec in records:
        if not isinstance(rec, dict):
            continue
        required = ('product', 'quantity', 'unit', 'location')
        if any(k not in rec for k in required):
            continue
        product = rec['product']
        quantity = rec['quantity']
        unit = rec['unit']
        location = rec['location']
        if not isinstance(product, str) or not isinstance(unit, str) or not isinstance(location, str) or not isinstance(quantity, int):
            continue
        p = product.strip().lower()
        u = unit.strip()
        loc = location.strip().lower()
        if p not in summary:
            summary[p] = {'quantity': 0, 'locations': set(), 'units': set()}
        summary[p]['quantity'] += quantity
        summary[p]['locations'].add(loc)
        summary[p]['units'].add(u)
    result = {}
    for p in sorted(summary):
        result[p] = {
            'quantity': summary[p]['quantity'],
            'locations': sorted(summary[p]['locations']),
            'units': sorted(summary[p]['units'])
        }
    return result

def apply_piecewise_pricing(prices, discount_rules):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    if not isinstance(discount_rules, list):
        raise TypeError("discount_rules must be a list")

    for p in prices:
        if not isinstance(p, int):
            raise TypeError("each price must be an int")
        if p < 0:
            raise ValueError("prices must be non-negative")

    validated_rules = []
    for rule in discount_rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise TypeError("each rule must be a 2-tuple")
        min_price, discount_percent = rule
        if not isinstance(min_price, int) or not isinstance(discount_percent, int):
            raise TypeError("rule elements must be ints")
        if min_price < 0:
            raise ValueError("min_price must be non-negative")
        if discount_percent < 0 or discount_percent > 100:
            raise ValueError("discount_percent must be between 0 and 100")
        validated_rules.append((min_price, discount_percent))

    if not validated_rules:
        return prices.copy()

    result = []
    for price in prices:
        best_min = None
        best_discount = 0
        for min_price, discount_percent in validated_rules:
            if price >= min_price:
                if best_min is None or min_price > best_min or min_price == best_min:
                    best_min = min_price
                    best_discount = discount_percent
        final_price = price - (price * best_discount // 100)
        result.append(final_price)
    return result

def apply_piecewise_pricing(prices, discount_rules):
    """
    Apply piecewise discount rules to item prices.

    :param prices: List of non-negative integers representing item prices.
    :param discount_rules: List of tuples (min_price, discount_percent) where each tuple
                           applies only when the original price is greater than or equal to min_price.
    :return: A new list of final prices for the items.
    """
    if not isinstance(prices, list):
        raise TypeError("prices must be a list.")
    if not isinstance(discount_rules, list):
        raise TypeError("discount_rules must be a list.")
    if not all(isinstance(price, int) for price in prices):
        raise TypeError("All prices in prices must be integers.")
    if not all(isinstance(rule, tuple) for rule in discount_rules):
        raise TypeError("All rules in discount_rules must be tuples of integers.")
    if any(price < 0 for price in prices):
        raise ValueError("All prices in prices must be non-negative.")
    if any(min_price < 0 for min_price in rule[0] for rule in discount_rules):
        raise ValueError("All min_prices in discount_rules must be non-negative.")
    if not discount_rules:
        return prices.copy()

    final_prices = []
    for price in prices:
        for min_price, discount_percent in discount_rules:
            if price >= min_price:
                final_price = price - floor(price * discount_percent / 100)
                break
        final_prices.append(final_price)

    return final_prices

