def render_numeric_spiral(n: int) -> list[str]:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return []

    grid = [[0] * n for _ in range(n)]
    top, bottom, left, right = 0, n - 1, 0, n - 1
    value = 1

    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            grid[top][c] = value
            value += 1
        top += 1

        for r in range(top, bottom + 1):
            grid[r][right] = value
            value += 1
        right -= 1

        if top <= bottom:
            for c in range(right, left - 1, -1):
                grid[bottom][c] = value
                value += 1
            bottom -= 1

        if left <= right:
            for r in range(bottom, top - 1, -1):
                grid[r][left] = value
                value += 1
            left += 1

    width = len(str(n * n))
    return [" ".join(str(cell).rjust(width) for cell in row) for row in grid]

def summarize_revenue_queries(prices, queries):
    results = []
    for q in queries:
        if len(q) != 2:
            raise ValueError('Each query must be a pair (low, high)')
        low, high = q
        if low > high:
            raise ValueError('low must be <= high')
        best = 0
        current = 0
        for price in prices:
            if low <= price <= high:
                current += price
                if current > best:
                    best = current
            else:
                current = 0
        results.append(best)
    return results

def canonicalize_route(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if path == '':
        return '/'
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)
    return '/' + '/'.join(parts) if parts else '/'

def parse_timeline_entries(text: str) -> list[tuple[int, str]]:
    if text is None:
        raise TypeError("text must be a string")
    result = []
    stripped = text.strip()
    if not stripped:
        return result
    parts = stripped.split(';')
    for raw_entry in parts:
        entry = raw_entry.strip()
        if not entry:
            continue
        if ':' not in entry:
            raise ValueError(f"Malformed entry: {entry!r}")
        minute_str, label = entry.split(':', 1)
        minute_str = minute_str.strip()
        label = label.strip()
        if not minute_str or not label:
            raise ValueError(f"Malformed entry: {entry!r}")
        if minute_str[0] == '-':
            raise ValueError(f"Malformed entry: {entry!r}")
        if not minute_str.isdigit():
            raise ValueError(f"Malformed entry: {entry!r}")
        minute = int(minute_str)
        result.append((minute, label))
    return result

def parse_measurement(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    s = text.strip()
    if not s:
        raise ValueError('empty input')

    i = 0
    n = len(s)
    if s[i] in '+-':
        i += 1
        if i >= n:
            raise ValueError('missing number')

    start_num = i
    has_digit = False
    has_dot = False
    while i < n:
        ch = s[i]
        if ch.isdigit():
            has_digit = True
            i += 1
        elif ch == '.':
            if has_dot:
                raise ValueError('multiple dots')
            has_dot = True
            i += 1
        else:
            break

    if not has_digit:
        raise ValueError('missing digits')
    if i == n:
        raise ValueError('missing unit')

    unit = s[i:]
    if not unit.isalpha() or any(c.isspace() for c in unit):
        raise ValueError('invalid unit')

    num_str = s[:i]
    if num_str in ('+', '-', '.', '+.', '-.'):
        raise ValueError('invalid number')

    value = float(num_str)
    if value.is_integer():
        value = int(value)
    return (value, unit)

def normalize_histogram(counts):
    total = sum(counts)
    if len(counts) == 0:
        return []
    if total == 0:
        return [0.0] * len(counts)
    return [c / total for c in counts]

def normalize_route_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def best_signal_window(values, window_size):
    if not isinstance(window_size, int) or window_size < 0:
        raise ValueError("window_size must be a non-negative integer")
    if window_size == 0:
        return ()
    try:
        seq = tuple(values)
    except TypeError:
        raise TypeError("values must be iterable")
    n = len(seq)
    if window_size > n:
        return None
    current_sum = sum(seq[:window_size])
    best_sum = current_sum
    best_start = 0
    for start in range(1, n - window_size + 1):
        current_sum += seq[start + window_size - 1] - seq[start - 1]
        if current_sum > best_sum:
            best_sum = current_sum
            best_start = start
    return (best_start, best_sum, tuple(seq[best_start:best_start + window_size]))

def restore_rle_string(segments):
    if segments is None:
        raise TypeError("segments must be iterable")
    result = []
    for seg in segments:
        if not isinstance(seg, (tuple, list)) or len(seg) != 2:
            raise ValueError("each segment must be a 2-item tuple or list")
        count, character = seg
        if not isinstance(count, int):
            raise TypeError("count must be an int")
        if count < 0:
            raise ValueError("count must be non-negative")
        if not isinstance(character, str) or len(character) != 1:
            raise ValueError("character must be a one-character string")
        if count:
            result.append(character * count)
    return "".join(result)

def restore_rle_string(segments):
    """
    Reconstructs a string from a run-length encoded description.

    :param segments: List of 2-item tuples or lists, each of the form (count, character)
    :return: The decoded string formed by repeating each character exactly count times
    """
    if not segments:
        return ""

    decoded = []
    for count, char in segments:
        if not isinstance(count, int) or not isinstance(char, str) or count < 0:
            raise ValueError("All elements in segments must be integers and strings.")
        if count == 0:
            continue
        decoded.extend([char] * count)

    return ''.join(decoded)

