            result[item]['price'] = max(details['price'], result[item]['price'])
        else:
            # Add the item to the result with its default values
            result[item] = {
                'qty': details['qty'],
                'price': details['price']
            }

    # Sort the result dictionary alphabetically by item name
    sorted_result = dict(sorted(result.items()))

    return sorted_result

