import re

def normalize_ledger_entry(entry):
    if not isinstance(entry, str):
        raise ValueError('entry must be a string')
    parts = [p.strip() for p in entry.strip().split('|')]
    if len(parts) != 4:
        raise ValueError('expected exactly four fields')
    date, description, amount, currency = parts
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date):
        raise ValueError('invalid date')
    description = ' '.join(description.split())
    if not description:
        raise ValueError('invalid description')
    if amount == '':
        raise ValueError('invalid amount')
    if not re.fullmatch(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)', amount):
        raise ValueError('invalid amount')
    sign = ''
    if amount[0] in '+-':
        sign = amount[0]
        amount = amount[1:]
    if '.' in amount:
        int_part, frac_part = amount.split('.', 1)
    else:
        int_part, frac_part = amount, ''
    int_part = int_part.lstrip('0') or '0'
    frac_part = frac_part.rstrip('0')
    if int_part == '0' and frac_part == '':
        sign = ''
    normalized_amount = int_part if frac_part == '' else int_part + '.' + frac_part
    if sign == '-':
        normalized_amount = '-' + normalized_amount
    if not re.fullmatch(r'[A-Za-z]{3}', currency):
        raise ValueError('invalid currency')
    currency = currency.upper()
    return (date, description, normalized_amount, currency)

