    Returns:
    dict: A dictionary mapping each sku to a summary dictionary.
          The summary dictionary includes:
          - net: the sum of all deltas for that sku,
          - adds: the count of records with positive delta,
          - removes: the count of records with negative delta,
          - notes: a tuple of notes for that sku in the same order as the input records.

    Raises:
    ValueError: If the input is not iterable or contains invalid records.
    """
    if not isinstance(moves, iter):
        raise ValueError("Input must be an iterable of records.")

    summary = {}
    for sku, delta, note in moves:
        if not isinstance(sku, str) or not sku:
            raise ValueError("SKU must be a non-empty string.")
        if not isinstance(delta, int) or not isinstance(note, str):
            raise ValueError("Delta and note must be integers.")

        if delta == 0:
            continue

        net = delta + summary.get(sku, 0)
        if delta > 0:
            adds = summary.get(sku, 0) + 1
        else:
            removes = summary.get(sku, 0) - 1

        notes = (note,) if notes else ()
        summary[sku] = {'net': net, 'adds': adds, 'removes': removes, 'notes': notes}

    return summary

