def count_valid_rotations(s: str, alphabet: str) -> int:
    if s == '':
        return 1 if alphabet == '' else 0
    if alphabet == '':
        return 0
    if len(set(alphabet)) != len(alphabet):
        return 0

    k = len(alphabet)
    nxt = {alphabet[i]: alphabet[(i + 1) % k] for i in range(k)}
    if any(ch not in nxt for ch in s):
        return 0

    n = len(s)
    count = 0
    for shift in range(n):
        rot = s[shift:] + s[:shift]
        valid = True
        for i in range(n):
            a = rot[i]
            b = rot[(i + 1) % n]
            if nxt[a] != b:
                valid = False
                break
        if valid:
            count += 1
    return count

