        raise ValueError('routes must be a list')

    def canon_path(path):
        parts = []
        for segment in path.split('/'):
            if segment == '' or segment == '.':
                continue
            if segment == '..':
                if parts:
                    parts.pop()
                continue
            parts.append(segment)
        out = '/' + '/'.join(parts)
        if len(out) > 1 and out.endswith('/'):
            out = out[:-1]
        return out

    result = set()
    for item in routes:
        if not isinstance(item, str):
            raise ValueError('each route must be a string')
        if item.count(' ') != 1:
            raise ValueError('route must contain exactly one space')
        method, path = item.split(' ')
        if not path.startswith('/'):
            raise ValueError('path must start with /')
        method_u = method.upper()
        cpath = canon_path(path)
        if method_u == 'GET':
            result.add(cpath)
        else:
            result.add(method_u + ' ' + cpath)
    return sorted(result)

def normalize_sensor_report(report):
    if not isinstance(report, list):
        raise TypeError("report must be a list")

    for item in report:
        if not isinstance(item, tuple) or len(item) not in (2, 3):
            raise TypeError("invalid report item")
        sensor_id, value = item[0], item[1]
        if not isinstance(sensor_id, int) or isinstance(sensor_id, bool):
            raise TypeError("sensor_id must be an int")
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("value must be an int")
        if len(item) == 3:
            quality = item[2]
            if not isinstance(quality, str):
                raise TypeError("quality must be a string")

    grouped = {}
    order = []
    for item in report:
        sensor_id, value = item[0], item[1]
        quality = item[2] if len(item) == 3 else None
        if sensor_id not in grouped:
            grouped[sensor_id] = [0, value, value, 0, []]
            order.append(sensor_id)
        data = grouped[sensor_id]
        data[0] += 1
        data[1] = value if value < data[1] else data[1]
        data[2] = value if value > data[2] else data[2]
        data[3] += value
        if quality:
            if quality not in data[4]:
                data[4].append(quality)

    result = []
    for sensor_id in order:
        count, min_value, max_value, total, qualities = grouped[sensor_id]
        result.append((sensor_id, count, min_value, max_value, total / count, tuple(qualities)))
    return tuple(result)

def select_evenly_spaced_items(seq, k):
    if k < 0:
        raise ValueError("k must be non-negative")
    n = len(seq)
    if k == 0:
        return []
    if k >= n:
        return list(seq)
    result = []
    denom = k - 1
    for i in range(k):
        x = i * (n - 1) / denom
        idx = int(x + 0.5)
        result.append(seq[idx])
    return result

