def normalize_scorecard(scorecard):
    if not isinstance(scorecard, dict):
        raise TypeError('scorecard must be a dictionary')

    totals = {}
    for name, value in scorecard.items():
        if value is None:
            continue
        if isinstance(value, (int, float)):
            total = value
        elif isinstance(value, (list, tuple)):
            if len(value) == 0:
                raise TypeError('round scores must be non-empty')
            total = 0
            for item in value:
                if not isinstance(item, (int, float)):
                    raise TypeError('round scores must contain only numbers')
                total += item
        else:
            raise TypeError('invalid score value type')
        totals[name] = total

    if not totals:
        return {'totals': {}, 'winner': None, 'spread': 0}

    items = list(totals.items())
    values = [v for _, v in items]
    high = max(values)
    low = min(values)
    tied_winners = [name for name, total in items if total == high]
    winner = min(tied_winners)
    spread = high - low if len(totals) >= 2 else 0
    return {'totals': totals, 'winner': winner, 'spread': spread}

def normalize_scorecard(scorecard):
    """
    Normalize a mixed scorecard mapping into a normalized summary dictionary.

    Parameters:
    scorecard (dict): A dictionary where keys are player names and values are:
                      - an integer score,
                      - a float score,
                      - a list/tuple of numbers representing round scores,
                      - or None.

    Returns:
    dict: A dictionary with exactly three keys:
          - 'totals': a dictionary mapping each included player name to their total score.
          - 'winner': the name of the player with the highest total score, or None.
          - 'spread': the difference between the highest and lowest total scores among included players, or 0.
    """
    if not isinstance(scorecard, dict):
        raise TypeError("Input must be a dictionary.")

    totals = {}
    winner = None
    spread = 0

    for player, value in scorecard.items():
        if value is None:
            continue

        if isinstance(value, int):
            totals[player] = value
        elif isinstance(value, float):
            totals[player] = value
        elif isinstance(value, list) or isinstance(value, tuple):
            if len(value) == 0:
                raise TypeError("List/tuple must be non-empty.")

            total = sum(value)
            if total > spread:
                spread = total
            if total < winner:
                winner = player

    return {
        'totals': totals,
        'winner': winner,
        'spread': spread
    }

