def parse_mixed_ranges(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text.strip() == "":
        return []

    def parse_int(s):
        s = s.strip()
        if s == "":
            raise ValueError("empty integer")
        try:
            return int(s)
        except Exception:
            raise ValueError("invalid integer")

    result = set()
    parts = text.split(',')
    for part in parts:
        if part.strip() == "":
            raise ValueError("empty item")
        # Detect range with exactly one top-level hyphen separating two integers.
        # Allow whitespace around the hyphen.
        s = part.strip()
        hyphen_positions = []
        for i, ch in enumerate(s):
            if ch == '-':
                hyphen_positions.append(i)
        if len(hyphen_positions) == 0:
            result.add(parse_int(s))
            continue

        # For a valid range, there must be exactly one hyphen that acts as separator.
        # Since negative numbers are allowed, the separator is the last hyphen not
        # part of the first integer's sign, but the only supported syntax is:
        # integer, optional spaces, '-', optional spaces, integer.
        # We parse by matching the first integer prefix and last integer suffix.
        # Any internal extra hyphen means invalid.
        first = None
        last = None
        # Find a split point where left and right both parse as ints.
        for idx, ch in enumerate(s):
            if ch == '-':
                left = s[:idx].strip()
                right = s[idx+1:].strip()
                if left == "" or right == "":
                    continue
                try:
                    a = int(left)
                    b = int(right)
                except Exception:
                    continue
                first = a
                last = b
                # Ensure there is exactly one separator hyphen between the two parts.
                # Any additional hyphen in either side is allowed only as a sign.
                # If either side contains an internal hyphen after stripping sign, invalid.
                break
        if first is None:
            raise ValueError("invalid range")
        if first > last:
            raise ValueError("range start greater than end")
        for n in range(first, last + 1):
            result.add(n)

    return sorted(result)

def compress_intervals(points):
    if points == []:
        return []
    result = []
    prev_x = None
    prev_label = None
    start_x = None

    for idx, item in enumerate(points):
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each point must be a 2-tuple')
        x, label = item
        if type(x) is not int:
            raise TypeError('x must be an int')
        if isinstance(x, bool):
            raise TypeError('x must be an int')
        if not isinstance(label, str):
            raise TypeError('label must be a str')
        if idx == 0:
            start_x = x
        else:
            if x < prev_x:
                raise ValueError('points must be sorted by nondecreasing x')
            if x == prev_x + 1 and label == prev_label:
                pass
            else:
                result.append((start_x, prev_x, prev_label))
                start_x = x
        prev_x = x
        prev_label = label

    result.append((start_x, prev_x, prev_label))
    return result

def compress_ranges(values):
    if not isinstance(values, list):
        raise TypeError('values must be a list of integers')
    for item in values:
        if not isinstance(item, int):
            raise TypeError('values must be a list of integers')
    if not values:
        return []

    ranges = []
    start = prev = values[0]

    for x in values[1:]:
        if x == prev + 1:
            prev = x
        else:
            ranges.append((start, prev))
            start = prev = x
    ranges.append((start, prev))
    return ranges

def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    day_order = {
        "Monday": 0,
        "Tuesday": 1,
        "Wednesday": 2,
        "Thursday": 3,
        "Friday": 4,
        "Saturday": 5,
        "Sunday": 6,
    }

    normalized = []
    for record in events:
        if not isinstance(record, tuple) or len(record) != 4:
            raise ValueError("invalid record")
        day, start, end, title = record
        if not isinstance(day, str) or day == "":
            raise ValueError("invalid day")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("invalid times")
        if start < 0 or end < start:
            raise ValueError("invalid interval")
        if not isinstance(title, str):
            raise ValueError("invalid title")

        norm_day = day[:1].upper() + day[1:].lower()
        if norm_day not in day_order:
            raise ValueError("unknown day")
        normalized.append((day_order[norm_day], norm_day, start, end, title))

    if not normalized:
        return ""

    normalized.sort(key=lambda x: (x[0], x[2], x[3], x[4]))

    lines = []
    current_day = None
    current_events = []

    def fmt_minutes(m):
        return f"{m // 60:02d}:{m % 60:02d}"

    for _, day_name, start, end, title in normalized:
        item = f"{fmt_minutes(start)}-{fmt_minutes(end)} {title}"
        if current_day is None:
            current_day = day_name
            current_events = [item]
        elif day_name == current_day:
            current_events.append(item)
        else:
            lines.append(f"{current_day}: " + " | ".join(current_events))
            current_day = day_name
            current_events = [item]
    lines.append(f"{current_day}: " + " | ".join(current_events))
    return "\n".join(lines)

from typing import List

def normalize_schedule(events: List[Tuple[str, int, int, str]]) -> str:
    def normalize_day(day):
        return day.capitalize()[0] + day[1:].lower()

    def sort_events(events):
        events.sort(key=lambda x: (normalize_day(x[0]), x[1], x[2], x[3]))

    def group_events(events):
        day_groups = {}
        for day, start, end, title in events:
            if day not in day_groups:
                day_groups[day] = []
            day_groups[day].append((start, end, title))
        return day_groups

    def format_event(event):
        return f"{event[0]:02d}:{event[1]:02d}-{event[2]:02d}:{event[3]} {event[4]}"

    def join_events(events):
        day_lines = []
        for day, events in day_groups.items():
            day_lines.append(f"{day}:")
            for start, end, title in events:
                day_lines.append(format_event((start, end, title)))
        return "\n".join(day_lines)

    def join_day_lines(day_lines):
        return "\n".join(day_lines)

    if not events:
        return ""

    sort_events(events)
    day_groups = group_events(events)
    formatted_events = [format_event(event) for event in day_groups.values()]
    joined_events = join_events(formatted_events)
    joined_day_lines = join_day_lines(day_groups.keys())
    return joined_events + joined_day_lines

