def normalize_menu_orders(menu):
    if not isinstance(menu, dict):
        raise TypeError('menu must be a dict')

    result = {}
    for raw_category, items in menu.items():
        if not isinstance(raw_category, str):
            raise TypeError('category name must be a string')
        category = raw_category.strip()
        if not category:
            raise ValueError('category name cannot be empty')
        if not isinstance(items, list):
            raise TypeError('category value must be a list')

        normalized_items = []
        for item in items:
            if not isinstance(item, dict):
                raise TypeError('item must be a dict')
            if set(item.keys()) != {'name', 'price', 'tags'}:
                raise ValueError('item must contain exactly name, price, and tags')

            name = item['name']
            price = item['price']
            tags = item['tags']

            if not isinstance(name, str):
                raise TypeError('name must be a string')
            name = name.strip()
            if not name:
                raise ValueError('name cannot be empty')

            if not isinstance(price, (int, float)):
                raise TypeError('price must be numeric')
            if price < 0:
                raise ValueError('price cannot be negative')

            if not isinstance(tags, list):
                raise TypeError('tags must be a list')
            normalized_tags = []
            seen = set()
            for tag in tags:
                if not isinstance(tag, str):
                    raise TypeError('each tag must be a string')
                tag = tag.strip()
                if not tag:
                    continue
                if tag not in seen:
                    seen.add(tag)
                    normalized_tags.append(tag)
            normalized_tags.sort()

            normalized_items.append({'name': name, 'price': float(price), 'tags': normalized_tags})

        if category in result:
            result[category].extend(normalized_items)
        else:
            result[category] = normalized_items

    return result

def spiral_path_to_target(grid, target):
    if not isinstance(target, int):
        raise ValueError("target must be an integer")
    if not isinstance(grid, list) or not grid or not all(isinstance(row, list) and row for row in grid):
        raise ValueError("grid must be a non-empty list of non-empty lists")
    row_len = len(grid[0])
    if any(len(row) != row_len for row in grid):
        raise ValueError("all rows must have the same length")
    for row in grid:
        for value in row:
            if not isinstance(value, int):
                raise ValueError("all grid elements must be integers")

    top, bottom = 0, len(grid) - 1
    left, right = 0, row_len - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            if grid[top][c] == target:
                return (top, c)
        top += 1

        for r in range(top, bottom + 1):
            if grid[r][right] == target:
                return (r, right)
        right -= 1

        if top <= bottom:
            for c in range(right, left - 1, -1):
                if grid[bottom][c] == target:
                    return (bottom, c)
            bottom -= 1

        if left <= right:
            for r in range(bottom, top - 1, -1):
                if grid[r][left] == target:
                    return (r, left)
            left += 1

    return None

def balance_log_session(events):
    result = []
    balance = 0
    for event in events:
        if isinstance(event, bool):
            raise TypeError('boolean events are invalid')
        if isinstance(event, int):
            balance += event
            result.append(balance)
        elif event == 'RESET':
            result.append(balance)
            balance = 0
        else:
            raise TypeError('invalid event type')
    return result

def normalize_sensor_events(events):
    result = []
    for raw in events:
        s = raw.strip()
        if not s:
            continue
        parts = s.split('|')
        if len(parts) == 2 and parts[1].startswith('note:'):
            sensor_id = parts[0]
            text = parts[1][5:].strip()
            result.append(f'{sensor_id}|NOTE|{text}')
            continue
        if len(parts) != 3:
            raise ValueError('invalid event')
        sensor_id, value_text, unit = parts
        value_text = value_text.strip()
        unit = unit.strip()
        try:
            value = float(value_text)
        except Exception:
            raise ValueError('invalid value')
        if unit == 'C':
            conv = value
            result.append(f'{sensor_id}|{conv:.1f}|C')
        elif unit == 'F':
            conv = (value - 32) * 5 / 9
            result.append(f'{sensor_id}|{conv:.1f}|C')
        elif unit == 'K':
            conv = value - 273.15
            result.append(f'{sensor_id}|{conv:.1f}|C')
        elif unit == 'PCT':
            result.append(f'{sensor_id}|{value:.1f}|PCT')
        else:
            raise ValueError('invalid unit')
    return result

def compress_segments(values):
    if not isinstance(values, (list, tuple)):
        raise TypeError("values must be a list or tuple of integers")
    if len(values) == 0:
        return []
    for x in values:
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
    result = []
    current = values[0]
    length = 1
    for x in values[1:]:
        if x == current:
            length += 1
        else:
            result.append((current, length, 'even' if length % 2 == 0 else 'odd'))
            current = x
            length = 1
    result.append((current, length, 'even' if length % 2 == 0 else 'odd'))
    return result

def compact_intervals(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")

    result = []
    sentinel = object()
    prev = sentinel
    start = end = sentinel

    for x in iterator:
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if prev is sentinel:
            start = end = x
        else:
            if x < prev:
                raise ValueError("values must be non-decreasing")
            if x == prev:
                prev = x
                continue
            if x == end + 1:
                end = x
            else:
                result.append((start, end))
                start = end = x
        prev = x
    if prev is sentinel:
        return []
    result.append((start, end))
    return result

def ranked_unique_tokens(text: str, k: int) -> list[str]:
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return []

    counts = {}
    current = []

    def flush():
        if current:
            token = ''.join(current).lower()
            counts[token] = counts.get(token, 0) + 1
            current.clear()

    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            current.append(ch)
        else:
            flush()
    flush()

    if not counts:
        return []

    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [token for token, _ in ordered[:k]]

def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    grouped = {}
    for item in events:
        if not (isinstance(item, tuple) and len(item) == 4):
            raise ValueError('each event must be a 4-tuple')
        day, start, end, label = item
        if not (isinstance(day, int) and isinstance(start, int) and isinstance(end, int) and isinstance(label, str)):
            raise ValueError('invalid field types')
        if day < 0 or start < 0 or end > 1440 or start >= end:
            raise ValueError('invalid time bounds')
        grouped.setdefault(day, []).append((start, end, label))

    result = {}
    for day in sorted(grouped):
        items = sorted(grouped[day], key=lambda x: (x[0], x[1], x[2]))
        merged = []
        for start, end, label in items:
            if not merged:
                merged.append([start, end, label])
                continue
            cs, ce, cl = merged[-1]
            if label == cl and start <= ce:
                merged[-1][1] = max(ce, end)
            else:
                merged.append([start, end, label])
        result[day] = [tuple(x) for x in merged]
    return result

