    Normalize a list of event records into a normalized schedule.

    Parameters:
    events (list of tuples): A list of tuples, where each tuple contains:
        - day (int): The day of the event.
        - start (int): The start minute of the event.
        - end (int): The end minute of the event.
        - label (str): The label of the event.

    Returns:
    dict: A dictionary mapping each day to a list of merged tuples.
    """
    # Validate each event record
    for record in events:
        if len(record) != 4:
            raise ValueError("Each event record must be a 4-tuple.")
        if not all(isinstance(x, int) for x in record):
            raise ValueError("All fields in each event record must be integers.")
        if not isinstance(record[0], int) or record[0] < 0:
            raise ValueError("Day must be non-negative.")
        if not isinstance(record[1], int) or record[1] > 1440:
            raise ValueError("Start and end must be within the valid range.")
        if not isinstance(record[2], int) or record[2] > 1440:
            raise ValueError("End must be within the valid range.")
        if not isinstance(record[3], str):
            raise ValueError("Label must be a string.")

    # Normalize the records by grouping by day in ascending order
    normalized_events = {}
    for day, start, end, label in sorted(events, key=lambda x: (x[0], x[1])):
        if day not in normalized_events:
            normalized_events[day] = []
        merged_tuple = (min(start, end), max(start, end), label)
        normalized_events[day].append(merged_tuple)

    return normalized_events

