def summarize_runs(nums):
    try:
        iterator = iter(nums)
    except TypeError:
        raise TypeError("nums must be iterable")

    runs = []
    longest_run_length = 0
    longest_values = set()

    sentinel = object()
    current_value = sentinel
    current_length = 0

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all items must be integers")

        if current_value is sentinel:
            current_value = item
            current_length = 1
        elif item == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            if current_length > longest_run_length:
                longest_run_length = current_length
                longest_values = {current_value}
            elif current_length == longest_run_length:
                longest_values.add(current_value)
            current_value = item
            current_length = 1

    if current_value is not sentinel:
        runs.append((current_value, current_length))
        if current_length > longest_run_length:
            longest_run_length = current_length
            longest_values = {current_value}
        elif current_length == longest_run_length:
            longest_values.add(current_value)
    else:
        longest_run_length = 0
        longest_values = set()

    return {
        "runs": runs,
        "longest_run_length": longest_run_length,
        "longest_run_values": sorted(longest_values),
    }

def summarize_runs(nums):
    """
    Analyzes a sequence of integers by grouping consecutive equal values into runs.

    Parameters:
    nums (iterable): An iterable of integers.

    Returns:
    dict: A dictionary with keys 'runs', 'longest_run_length', and 'longest_run_values'.
    """
    if not isinstance(nums, Iterable):
        raise TypeError("Input must be an iterable.")

    if not all(isinstance(x, int) for x in nums):
        raise TypeError("All elements in the iterable must be integers.")

    # Initialize variables
    runs = []
    longest_run_length = 0
    longest_run_values = []

    # Iterate through the iterable
    for value in nums:
        if value == runs[-1][0]:
            runs[-1][1] += 1
        else:
            runs.append([value, 1])
            longest_run_length = max(longest_run_length, runs[-1][1])
            longest_run_values = sorted(set(runs[-1][0]), reverse=True)

    return {
        'runs': runs,
        'longest_run_length': longest_run_length,
        'longest_run_values': longest_run_values
    }

