        if not isinstance(line, str):
            continue
        s = line.strip()
        if not s:
            continue
        eq = s.find("=")
        if eq <= 0 or eq == len(s) - 1:
            continue
        name = s[:eq]
        rest = s[eq + 1:]
        if not name.isalpha():
            continue

        unit = None
        value_part = None
        for u in sorted(valid_units, key=len, reverse=True):
            if rest.endswith(u):
                unit = u
                value_part = rest[:-len(u)]
                break
        if unit is None or value_part in (None, ""):
            continue
        if value_part[0] in "+-":
            digits = value_part[1:]
            if len(value_part) == 1:
                continue
        else:
            digits = value_part
        if not digits.isdigit():
            continue
        try:
            value = int(value_part)
        except ValueError:
            continue
        latest[(name, unit)] = value

    if not latest:
        return {}

    by_unit = {}
    for (name, unit), value in latest.items():
        by_unit.setdefault(unit, {})[name] = value

    result = {}
    for unit in valid_units:
        if unit not in by_unit:
            continue
        names = tuple(sorted(by_unit[unit]))
        values = [by_unit[unit][n] for n in names]
        result[unit] = {"count": len(names), "sum": sum(values), "names": names}
    return result

def compress_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")

    normalized = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a 2-item sequence")
        a, b = item
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        if a <= b:
            normalized.append([a, b])
        else:
            normalized.append([b, a])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def serialize_patch(ops):
    if not isinstance(ops, (list, tuple)):
        raise TypeError('ops must be a list or tuple')

    def enc_text(s):
        return s.replace('%', '%25').replace(';', '%3B').replace('=', '%3D')

    parts = []
    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) != 2:
            raise ValueError('each operation must be a 2-item sequence')
        kind, value = op
        if kind == '=':
            if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
                raise ValueError("'=' value must be a positive integer")
            parts.append('=' + str(value))
        elif kind == '+' or kind == '-':
            if not isinstance(value, str) or len(value) < 1:
                raise ValueError("text value must be a non-empty string")
            parts.append(kind + enc_text(value))
        else:
            raise ValueError('invalid operation kind')
    return ';'.join(parts)

def merge_event_gaps(events, gap):
    if gap < 0:
        raise ValueError("gap must be non-negative")
    validated = []
    for ev in events:
        if not isinstance(ev, tuple) or len(ev) != 2:
            raise ValueError("each event must be a 2-tuple")
        start, end = ev
        if start > end:
            raise ValueError("event start must be <= end")
        validated.append((start, end))
    if not validated:
        return []
    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [validated[0]]
    for start, end in validated[1:]:
        prev_start, prev_end = merged[-1]
        if start - prev_end <= gap:
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))
    return merged

def parse_int_ranges(spec):
    if spec is None:
        raise ValueError('spec must be a string')
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')
    s = spec.strip()
    if s == '':
        return []

    def parse_nonnegative_int(token):
        token = token.strip()
        if token == '' or token[0] == '+':
            raise ValueError('invalid integer token')
        if token[0] == '-':
            raise ValueError('negative not allowed')
        if not token.isdigit():
            raise ValueError('invalid integer token')
        return int(token)

    result = []
    seen = set()
    parts = spec.split(',')
    for raw_part in parts:
        part = raw_part.strip()
        if part == '':
            raise ValueError('empty item')
        hyphen_count = part.count('-')
        if hyphen_count == 0:
            value = parse_nonnegative_int(part)
            if value not in seen:
                seen.add(value)
                result.append(value)
        else:
            if hyphen_count != 1:
                raise ValueError('malformed range')
            left, right = part.split('-', 1)
            if left.strip() == '' or right.strip() == '':
                raise ValueError('missing endpoint')
            start = parse_nonnegative_int(left)
            end = parse_nonnegative_int(right)
            step = 1 if start <= end else -1
            for value in range(start, end + step, step):
                if value not in seen:
                    seen.add(value)
                    result.append(value)
    return result

def parse_int_ranges(spec):
    """
    Parses a compact list of nonnegative integer ranges into an ordered list of unique integers.

    :param spec: A string containing comma-separated items.
    :return: A list of integers in the order they first appear after expanding ranges.
    """
    def expand_range(start, end):
        if start > end:
            return []
        if start == end:
            return [start]
        return [start, end]

    ranges = []
    current_range = []
    for item in spec.split(','):
        if item.strip():
            if '-' in item:
                start, end = map(int, item.split('-'))
                current_range.extend(expand_range(start, end))
            else:
                current_range.append(int(item))
        elif current_range:
            ranges.append(current_range)
            current_range = []

    if current_range:
        ranges.append(current_range)

    return sorted(set(ranges))

