def summarize_nested_records(data):
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not data:
        return {
            "group_count": 0,
            "record_count": 0,
            "group_sums": {},
            "category_totals": {},
            "max_group": None,
            "empty_groups": [],
        }

    group_sums = {}
    category_totals = {}
    empty_groups = []
    record_count = 0

    for group_name, records in data.items():
        if not isinstance(group_name, str):
            raise TypeError("group names must be strings")
        if not isinstance(records, list):
            raise TypeError("group values must be lists")

        group_total = 0
        if len(records) == 0:
            empty_groups.append(group_name)

        for record in records:
            if not isinstance(record, list) or len(record) != 2:
                raise TypeError("each record must be a list of exactly two integers")
            category_id, score = record
            if not isinstance(category_id, int) or not isinstance(score, int):
                raise TypeError("category_id and score must be integers")
            group_total += score
            category_totals[category_id] = category_totals.get(category_id, 0) + score
            record_count += 1

        group_sums[group_name] = group_total

    max_sum = max(group_sums.values())
    max_groups = [name for name, total in group_sums.items() if total == max_sum]
    max_group = min(max_groups)

    return {
        "group_count": len(data),
        "record_count": record_count,
        "group_sums": group_sums,
        "category_totals": category_totals,
        "max_group": max_group,
        "empty_groups": sorted(empty_groups),
    }

def parse_numeric_ranges(spec):
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')
    if spec.strip() == '':
        return []

    result = []
    items = spec.split(',')
    for raw_item in items:
        item = raw_item.strip()
        if item == '':
            raise ValueError('empty item')

        # Single integer
        if item.lstrip('-').isdigit() and item != '-':
            result.append(int(item))
            continue

        # Range: exactly one hyphen separator, not counting leading minus signs in the endpoints.
        # We only accept the form: integer-integer with no embedded spaces.
        # To avoid ambiguity, reject any item with more than one hyphen after removing a leading minus from each side.
        parts = item.split('-')
        if len(parts) != 2:
            raise ValueError('malformed range')

        left, right = parts[0].strip(), parts[1].strip()
        if left == '' or right == '':
            raise ValueError('missing endpoint')
        if not (left.lstrip('-').isdigit() and right.lstrip('-').isdigit()):
            raise ValueError('non-integer endpoint')
        if left == '-' or right == '-':
            raise ValueError('invalid endpoint')

        start = int(left)
        end = int(right)
        step = 1 if start <= end else -1
        result.extend(range(start, end + step, step))
    return result

def summarize_runs(text: str) -> dict:
    lines = text.splitlines()
    values = []
    for line in lines:
        if line.strip() == "":
            continue
        s = line
        if s[0] in "+-":
            if len(s) == 1 or not s[1:].isdigit():
                raise ValueError("invalid integer line")
        else:
            if not s.isdigit():
                raise ValueError("invalid integer line")
        values.append(int(s))

    runs = []
    if values:
        current = values[0]
        length = 1
        for v in values[1:]:
            if v == current:
                length += 1
            else:
                runs.append({"value": current, "length": length})
                current = v
                length = 1
        runs.append({"value": current, "length": length})

    longest_run = None
    if runs:
        longest_run = runs[0]
        for r in runs[1:]:
            if r["length"] > longest_run["length"]:
                longest_run = r

    return {
        "count": len(values),
        "runs": runs,
        "longest_run": longest_run,
        "distinct_values": len(set(values)),
    }

