def normalize_install_plan(spec):
    if spec is None:
        raise ValueError("spec must be a string")
    if spec.strip() == "":
        return []

    allowed_sources = {"repo", "local", "git"}
    items = spec.split(";")
    result = {}

    for raw_item in items:
        item = raw_item.strip()
        if item == "":
            raise ValueError("malformed item")

        source = "repo"
        if "@" in item:
            parts = item.split("@")
            if len(parts) != 2:
                raise ValueError("malformed item")
            item, source_part = parts[0].strip(), parts[1].strip()
            if source_part == "" or source_part not in allowed_sources:
                raise ValueError("invalid source")
            source = source_part

        version = "latest"
        if ":" in item:
            parts = item.split(":")
            if len(parts) != 2:
                raise ValueError("malformed item")
            name_part, version_part = parts[0].strip(), parts[1].strip()
            if version_part == "":
                raise ValueError("invalid version")
            version_segments = version_part.split(".")
            if any(seg == "" or not seg.isdigit() for seg in version_segments):
                raise ValueError("invalid version")
            version = version_part
            name = name_part
        else:
            name = item.strip()

        if name == "" or not name[0].isalpha() or any(ch not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-" for ch in name):
            raise ValueError("invalid name")

        result[name] = (name, version, source)

    return sorted(result.values(), key=lambda x: x[0])

