def summarize_logs(entries):
    """
    Analyzes a sequence of log entry strings and returns a dictionary with three keys:
    valid_count, categories, and first_seen. Each entry must be a string in the exact format
    '<category>|<severity>|<message>'. Where <category> and <message> are non-empty strings that do not contain the pipe character '|',
    and <severity> is one of the exact strings `'info'`, `'warn'`, or `'error'`. A valid entry contributes to the result as follows:
    valid_count is the number of valid entries; categories is a dictionary mapping each category to the number of valid entries in that category;
    first_seen is a dictionary mapping each category to the zero-based index of its first valid occurrence in the input sequence. Invalid entries must be ignored completely.
    The function must accept any iterable of strings, but if entries itself is not iterable, it must raise TypeError.
    The returned categories and first_seen dictionaries must contain only categories that appeared in at least one valid entry. If there are no valid entries, return {'valid_count': 0, 'categories': {}, 'first_seen': {}}.
    """
    if not isinstance(entries, Iterable):
        raise TypeError("Input must be an iterable of strings.")

    valid_count = 0
    categories = {}
    first_seen = {}

    for entry in entries:
        # Split the entry into category, severity, and message
        parts = entry.split('|')

        # Check if the entry is valid
        if len(parts) != 3:
            continue

        category, severity, message = parts

        # Update categories and first_seen
        if category in categories:
            categories[category] += 1
        else:
            categories[category] = 1

        if severity in first_seen:
            first_seen[severity] = min(first_seen[severity], len(entry))
        else:
            first_seen[severity] = len(entry)

    return {
        'valid_count': valid_count,
        'categories': categories,
        'first_seen': first_seen
    }

