def normalize_recipe_line(line: str) -> str:
    import re

    s = re.sub(r"[ \t\n\r\f\v]+", " ", line.strip())
    if s.startswith(('-', '*', '•')):
        s = s[1:]
        s = s.lstrip(' ')
    if s.endswith(')'):
        i = len(s) - 1
        depth = 0
        for j in range(len(s) - 1, -1, -1):
            ch = s[j]
            if ch == ')':
                depth += 1
            elif ch == '(':
                depth -= 1
                if depth == 0:
                    if '(' not in s[j+1:-1] and ')' not in s[j+1:-1]:
                        s = s[:j].rstrip(' ')
                    break
    return s

def normalize_tickets(records):
    priority_totals = {'low': 0, 'medium': 0, 'high': 0}
    projects = {}

    for rec in records:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            continue
        project, priority, points = rec
        if not isinstance(project, str):
            continue
        if priority not in ('low', 'medium', 'high'):
            continue
        if not isinstance(points, int) or points < 0:
            continue

        priority_totals[priority] += points
        projects[project] = projects.get(project, 0) + points

    return {'projects': projects, 'priority_totals': priority_totals}

def normalize_tickets(records):
    """
    Normalize ticket records into a dictionary summarizing the data by project and priority.

    Parameters:
    records (list of tuples or lists): Each element is a 3-item tuple or list of the form (project, priority, points).

    Returns:
    dict: A dictionary with two keys:
          - 'projects': a dictionary mapping each project name to the total points accumulated across all valid records for that project.
          - 'priority_totals': a dictionary mapping `'low'`, `'medium'`, and `'high'` to the total points accumulated for that priority across all valid records.
    """
    projects = {}
    priority_totals = {'low': 0, 'medium': 0, 'high': 0}

    for record in records:
        if isinstance(record, tuple) and len(record) == 3:
            project, priority, points = record
            if project in projects:
                projects[project] += points
            else:
                projects[project] = points

            if priority in priority_totals:
                priority_totals[priority] += points
            else:
                priority_totals[priority] = points

    return {
        'projects': projects,
        'priority_totals': priority_totals
    }

