def normalize_street_addresses(records):
    def collapse_space(s):
        return ' '.join(str(s).strip().split())

    result = []
    for rec in records:
        street = None
        num = None

        if isinstance(rec, str):
            parts = rec.split('|', 1)
            if len(parts) != 2:
                continue
            street, num = parts[0], parts[1]
        elif isinstance(rec, (list, tuple)) and len(rec) == 2:
            street, num = rec[0], rec[1]
        else:
            continue

        street = collapse_space(street)
        if not street:
            continue
        street = street.title()

        if isinstance(num, bool):
            continue
        try:
            if isinstance(num, int):
                n = num
            elif isinstance(num, float):
                if not num.is_integer():
                    continue
                n = int(num)
            elif isinstance(num, str):
                s = num.strip()
                if s == '':
                    continue
                n = int(s)
            else:
                continue
        except (TypeError, ValueError):
            continue

        result.append(f"{street} #{n}")
    return result

def parse_spaced_digits(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if text.strip() == '':
        raise ValueError('empty input')

    i = 0
    n = len(text)
    while i < n and text[i].isspace():
        i += 1

    sign = 1
    sign_seen = False
    digits = []
    digit_seen = False

    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch in '+-':
            if sign_seen or digit_seen:
                raise ValueError('invalid sign placement')
            sign_seen = True
            sign = -1 if ch == '-' else 1
            i += 1
            continue
        if ch.isdigit() and ch.isascii():
            digit_seen = True
            digits.append(ch)
            i += 1
            continue
        raise ValueError('invalid character')

    if not digits:
        raise ValueError('no digits found')

    return sign * int(''.join(digits))

def normalize_schedule(slots):
    def valid_slot(slot):
        if not isinstance(slot, tuple):
            return False
        if len(slot) == 2:
            s, e = slot
            label = None
        elif len(slot) == 3:
            s, e, label = slot
        else:
            return False
        if not isinstance(s, int) or not isinstance(e, int):
            return False
        if len(slot) == 3 and not isinstance(label, str):
            return False
        return s < e

    indexed = []
    for i, slot in enumerate(slots):
        if not valid_slot(slot):
            continue
        if len(slot) == 2:
            s, e = slot
            label = None
        else:
            s, e, label = slot
        indexed.append((s, e, label, i))

    if not indexed:
        return []

    indexed.sort(key=lambda x: (x[0], x[1], x[3]))
    merged = []

    cur_s, cur_e, cur_label, cur_i = indexed[0]
    for s, e, label, i in indexed[1:]:
        if s <= cur_e:
            if e > cur_e:
                cur_e = e
            continue
        merged.append((cur_s, cur_e, cur_label))
        cur_s, cur_e, cur_label, cur_i = s, e, label, i
    merged.append((cur_s, cur_e, cur_label))

    result = []
    for s, e, label in merged:
        if label is None:
            result.append((s, e))
        else:
            result.append((s, e, label))
    return result

def compress_spans(numbers):
    unique_sorted = sorted(set(numbers))
    if not unique_sorted:
        return []

    spans = []
    start = prev = unique_sorted[0]

    for n in unique_sorted[1:]:
        if n == prev + 1:
            prev = n
        else:
            spans.append((start, prev))
            start = prev = n
    spans.append((start, prev))
    return spans

def decode_runbook(data):
    if not isinstance(data, list):
        raise ValueError('data must be a list')
    result = []
    for pair in data:
        if not isinstance(pair, list) and not isinstance(pair, tuple):
            raise ValueError('each item must be a pair')
        if len(pair) != 2:
            raise ValueError('each pair must have exactly two items')
        value, count = pair
        if not isinstance(count, int) or isinstance(count, bool) or count < 0:
            raise ValueError('count must be a non-negative integer')
        result.extend([value] * count)
    return result

def compress_runs(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        return []

    result = []
    current = tokens[0]
    count = 1

    for item in tokens[1:]:
        if item == current:
            count += 1
        else:
            hash(current)
            result.append((current, count))
            current = item
            count = 1

    hash(current)
    result.append((current, count))
    return result

def canonicalize_routes(routes):
    result = set()
    for route in routes:
        if not isinstance(route, str):
            raise TypeError("all routes must be strings")
        if route == "":
            continue
        parts = route.split('/')
        stack = []
        valid = True
        saw_kept = False
        for part in parts:
            if part == '' or part == '.':
                continue
            if part == '..':
                if stack:
                    stack.pop()
                else:
                    valid = False
                    break
            else:
                stack.append(part)
                saw_kept = True
        if valid and saw_kept and stack:
            result.add('/' + '/'.join(stack))
    return sorted(result)

def spiral_layer_values(matrix):
    if not isinstance(matrix, list):
        raise ValueError('matrix must be a list of rows')
    if matrix == []:
        return []
    if any(not isinstance(row, list) for row in matrix):
        raise ValueError('matrix must be a list of lists')
    row_lengths = [len(row) for row in matrix]
    if len(set(row_lengths)) > 1:
        raise ValueError('all rows must have the same length')
    if row_lengths[0] == 0:
        return [[]] if len(matrix) > 0 else []

    top, bottom = 0, len(matrix) - 1
    left, right = 0, row_lengths[0] - 1
    result = []

    while top <= bottom and left <= right:
        layer = []

        for col in range(left, right + 1):
            layer.append(matrix[top][col])

        for row in range(top + 1, bottom + 1):
            layer.append(matrix[row][right])

        if bottom > top:
            for col in range(right - 1, left - 1, -1):
                layer.append(matrix[bottom][col])

        if right > left:
            for row in range(bottom - 1, top, -1):
                layer.append(matrix[row][left])

        result.append(layer)
        top += 1
        bottom -= 1
        left += 1
        right -= 1

    return result

def normalize_inventory(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')

    normalized = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dict')

        # name
        if 'name' not in record or record['name'] is None:
            name = ''
        else:
            name = str(record['name']).strip()

        # count
        if 'count' not in record or record['count'] is None:
            count = 0
        else:
            value = record['count']
            if isinstance(value, bool):
                count = 1 if value else 0
            elif isinstance(value, str):
                count = int(value.strip())
            else:
                count = int(value)

        # tags
        if 'tags' not in record or record['tags'] is None:
            tags = []
        else:
            raw_tags = record['tags']
            if isinstance(raw_tags, str):
                iterable = [raw_tags]
            else:
                try:
                    iterable = iter(raw_tags)
                except TypeError:
                    iterable = [raw_tags]
            seen = set()
            tags = []
            for tag in iterable:
                s = str(tag).strip()
                if s and s not in seen:
                    seen.add(s)
                    tags.append(s)

        normalized.append({'name': name, 'count': count, 'tags': tags})

    return normalized

def normalize_inventory(records):
    """
    Normalize a list of inventory records into a new list of normalized dictionaries.

    :param records: List of dictionaries, where each dictionary contains 'name', 'count', and 'tags'.
    :return: A new list of normalized dictionaries.
    """
    if not isinstance(records, list):
        raise TypeError("Input must be a list.")

    def normalize_record(record):
        name = record.get('name', '')
        count = record.get('count', 0)
        tags = record.get('tags', [])

        try:
            name = str(name).strip()
        except ValueError:
            name = ''

        try:
            count = int(count)
        except ValueError:
            count = 0

        try:
            tags = set(tag.strip() for tag in tags)
        except ValueError:
            tags = set()

        return {
            'name': name,
            'count': count,
            'tags': list(tags)
        }

    return [normalize_record(record) for record in records]

