def normalize_inventory(records):
    if records is None:
        raise ValueError("records must be iterable")
    totals = {}
    for rec in records:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            raise ValueError("each record must be a 3-item list or tuple")
        warehouse, sku, quantity = rec
        if not isinstance(warehouse, str) or not isinstance(sku, str):
