        key = (warehouse, sku)
        totals[key] = totals.get(key, 0) + quantity
    result = [(w, s, q) for (w, s), q in totals.items() if q != 0]
    result.sort(key=lambda item: (item[0], item[1]))
    return result

def normalize_inventory(records):
    """
    Normalize a list of inventory records into a canonical summary.

    Each record is a tuple or list of exactly 3 elements: (warehouse, sku, quantity).
    - Validate every record. If any record is malformed, raise ValueError.
    - Ignore records whose quantity is exactly 0.
    - Combine duplicate entries by summing quantities for the same (warehouse, sku) pair.
    - The result must be a list of 3-tuples (warehouse, sku, total_quantity) sorted lexicographically by warehouse, then sku.
    - If the summed quantity for a pair is 0 after combining positive and negative quantities, omit that pair from the result.
    - An empty input sequence should return an empty list.

    :param records: List of tuples or lists of (warehouse, sku, quantity)
    :return: List of 3-tuples (warehouse, sku, total_quantity) sorted lexicographically by warehouse, then sku
    """
    def validate_record(record):
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError("Invalid record format")
        if not all(isinstance(item, str) for item in record):
            raise ValueError("All items in the record must be strings")
        if not warehouse := record[0]:
            raise ValueError("Warehouse cannot be empty")
        if not sku := record[1]:
            raise ValueError("SKU cannot be empty")
        if not quantity := record[2]:
            raise ValueError("Quantity cannot be zero")
        return True

    def combine_entries(entry):
        warehouse, sku, quantity = entry
        if quantity == 0:
            return entry
        return (warehouse, sku, quantity + entry[2])

    def sort_records(records):
        return sorted(records, key=lambda x: (x[0], x[1]))

    normalized_records = []
    for record in records:
        if validate_record(record):
            combined_entry = combine_entries(record)
            normalized_records.append(combined_entry)

    return sort_records(normalized_records)

