def compress_intervals(values, gap=0):
    if gap < 0:
        raise ValueError("gap must be non-negative")

    unique_values = sorted(set(values))
    if not unique_values:
        return []

    intervals = []
    start = end = unique_values[0]

    for v in unique_values[1:]:
        if v - end <= gap + 1:
            end = v
        else:
            intervals.append((start, end))
            start = end = v

    intervals.append((start, end))
    return intervals

def encode_run_pairs(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if s == "":
        return ""

    parts = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f"{count}:{current}")
            current = ch
            count = 1

    parts.append(f"{count}:{current}")
    return "|".join(parts)

def apply_multipart_patch(base, patches):
    if not isinstance(base, str):
        raise TypeError("base must be a string")
    if not isinstance(patches, list):
        raise TypeError("patches must be a list")

    text = base
    for patch in patches:
        if not (isinstance(patch, tuple) and len(patch) == 3):
            raise TypeError("each patch must be a tuple of length 3")
        start, end, replacement = patch
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("start and end must be integers")
        if not isinstance(replacement, str):
            raise TypeError("replacement must be a string")
        if start < 0 or end < 0:
            raise ValueError("indices must be non-negative")
        if start > end:
            raise ValueError("start cannot be greater than end")
        if start > len(text) or end > len(text):
            raise IndexError("patch slice out of bounds")
        text = text[:start] + replacement + text[end:]
    return text

def apply_multipart_patch(base, patches):
    """
    Apply a series of multipart patches to the given base text.

    :param base: The starting text.
    :param patches: A list of patch records.
    :return: The modified text after applying all patches.
    """
    if not isinstance(base, str):
        raise TypeError("Base must be a string.")
    if not isinstance(patches, list):
        raise TypeError("Patches must be a list.")
    for patch in patches:
        if not isinstance(patch, tuple):
            raise TypeError("Each patch must be a tuple of exactly 3 items.")
        if len(patch) != 3:
            raise TypeError("Each patch must have exactly 3 items.")
        start, end, replacement = patch
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("Start and end must be integers.")
        if not isinstance(replacement, str):
            raise TypeError("Replacement must be a string.")
        if start < 0 or end < 0:
            raise ValueError("Index cannot be negative.")
        if start > end:
            raise ValueError("Start cannot be greater than end.")
        if start > len(base) or end > len(base):
            raise IndexError("Index out of bounds.")
        base = base[:start] + replacement + base[end:]
    return base

