def normalize_menu_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    parts = []
    for raw in path.split('/'):
        seg = raw.strip()
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts:
                parts.pop()
            continue
        parts.append(seg)
    return '/' + '/'.join(parts) if parts else '/'

def normalize_markdown_bullets(text: str) -> str:
    lines = text.split('\n')
    out = []
    for line in lines:
        if line == '':
            out.append(line)
            continue
        i = 0
        n = len(line)
        while i < n and line[i] == ' ':
            i += 1
        if i < n and line[i] in '-*+' and i + 1 < n and line[i + 1] == ' ':
            out.append(line[:i] + '- ' + line[i + 2:])
        else:
            out.append(line)
    return '\n'.join(out)

def segment_signature(seq):
    it = iter(seq)
    try:
        first = next(it)
    except StopIteration:
        raise ValueError('seq must not be empty')

    prev = first
    current_run = 1
    longest_run = 1
    changes = 0

    for x in it:
        if x == prev:
            current_run += 1
        else:
            changes += 1
            if current_run > longest_run:
                longest_run = current_run
            current_run = 1
            prev = x
    if current_run > longest_run:
        longest_run = current_run
    return (first, longest_run, changes)

def compress_ranges(values):
    if not isinstance(values, list):
        raise TypeError('values must be a list')
    if any(not isinstance(x, int) for x in values):
        raise TypeError('all elements must be integers')

    if not values:
        return []

    nums = sorted(set(values))
    result = []
    start = prev = nums[0]

    for x in nums[1:]:
        if x == prev + 1:
            prev = x
        else:
            if start == prev:
                result.append(str(start))
            else:
                result.append(f'{start}->{prev}')
            start = prev = x

    if start == prev:
        result.append(str(start))
    else:
        result.append(f'{start}->{prev}')

    return result

def summarize_runs(seq):
    it = iter(seq)
    try:
        first = next(it)
    except StopIteration:
        return {"runs": [], "longest": None, "change_points": []}

    runs = []
    change_points = []

    current_value = first
    current_length = 1
    index = 1

    for value in it:
        if value == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            change_points.append(index)
            current_value = value
            current_length = 1
        index += 1

    runs.append((current_value, current_length))

    longest = runs[0]
    for run in runs[1:]:
        if run[1] > longest[1]:
            longest = run

    return {"runs": runs, "longest": longest, "change_points": change_points}

def scan_signal_runs(values, threshold):
    data = list(values)
    runs = []
    start = None
    total = 0
    length = 0

    for i, x in enumerate(data):
        if x > threshold:
            if start is None:
                start = i
                total = x
                length = 1
            else:
                total += x
                length += 1
        else:
            if start is not None:
                runs.append((start, i - 1, length, total))
                start = None
                total = 0
                length = 0

    if start is not None:
        runs.append((start, len(data) - 1, length, total))

    return runs

def normalize_device_log(entries):
    groups = {}
    if entries is None:
        return []
    for entry in entries:
        try:
            if len(entry) != 3:
                continue
            device_id, metric, value = entry
        except Exception:
            continue
        if not isinstance(value, int):
            continue
        key = (str(device_id), str(metric))
        if key not in groups or value > groups[key]:
