def parse_action_log(log: str) -> dict:
    if not isinstance(log, str):
        raise TypeError('log must be a string')

    result = {
        'count_A': 0,
        'count_B': 0,
        'count_C': 0,
        'sum_A': 0,
        'sum_B': 0,
        'sum_C': 0,
        'first_value': None,
        'last_value': None,
    }

    if log == '':
        return result

    if any(ch.isspace() for ch in log):
        raise ValueError('whitespace is not allowed')

    records = log.split('|')
    if any(rec == '' for rec in records):
        raise ValueError('malformed record')

    for idx, rec in enumerate(records):
        if rec.count(':') != 1:
            raise ValueError('malformed record')
        typ, val_str = rec.split(':')
        if typ not in ('A', 'B', 'C'):
            raise ValueError('invalid type')
        if val_str in ('', '+'):
            raise ValueError('invalid value')
        if val_str[0] == '-':
            digits = val_str[1:]
            if digits == '':
                raise ValueError('invalid value')
        else:
            digits = val_str
        if not digits.isdigit():
            raise ValueError('invalid value')
        value = int(val_str)

        count_key = f'count_{typ}'
        sum_key = f'sum_{typ}'
        result[count_key] += 1
        result[sum_key] += value
        if idx == 0:
            result['first_value'] = value
        result['last_value'] = value

    return result

def normalize_event_log(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    grouped = {}
    min_ts = {}

    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a 3-tuple")
        timestamp, event_type, payload = record
        if not isinstance(timestamp, int):
            raise ValueError("timestamp must be an integer")
        if not isinstance(event_type, str):
            raise ValueError("event_type must be a string")
        if event_type == 'ignore':
            continue

        if event_type not in min_ts or timestamp < min_ts[event_type]:
            min_ts[event_type] = timestamp
            grouped[event_type] = [payload]
        elif timestamp == min_ts[event_type]:
            grouped[event_type].append(payload)

    return [(etype, grouped[etype]) for etype in sorted(grouped)]

def normalize_event_log(events):
    """
    Normalize an event log by grouping events by their type and selecting the smallest timestamp for each type.

    Parameters:
    events (list of tuples): A list of event records, each represented as a tuple (timestamp, event_type, payload).

    Returns:
    list of tuples: A list of (event_type, payload_list) pairs sorted by event_type in ascending lexicographic order.
    """
    def get_smallest_timestamp(event):
        return min(event)

    def filter_events_by_type(events, event_type):
        return [event for event in events if event[1] == event_type]

    def select_payloads(events, event_type):
        return [event[2] for event in filter_events_by_type(events, event_type)]

    result = []
    for event in events:
        if len(event) != 3:
            raise ValueError("Invalid event record.")
        if event[1] == 'ignore':
            continue
        event_type = event[1]
        timestamps = [event[0]]
        for timestamp in timestamps:
            if get_smallest_timestamp(timestamp) < get_smallest_timestamp(event[0]):
                timestamps = [timestamp]
            else:
                timestamps.append(get_smallest_timestamp(event[0]))
        result.append((event_type, select_payloads(timestamps, event_type)))

    return sorted(result, key=lambda x: x[0])

