def summarize_zones(records):
    totals = {}
    for record in records:
        if not isinstance(record, tuple) or len(record) != 2:
            continue
        zone, minutes = record
        if not isinstance(zone, str) or zone == "":
            continue
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes < 0:
            continue
        if zone not in totals:
            totals[zone] = [0, 0]
        totals[zone][0] += 1
        totals[zone][1] += minutes
    if not totals:
        return ""
    parts = []
    for zone in sorted(totals):
        count, total = totals[zone]
        parts.append(f"{zone}:count={count},sum={total}")
    return ";".join(parts)

def staircase_partitions(n):
    if not isinstance(n, int):
        raise TypeError('n must be an integer')
    if n < 0:
        raise ValueError('n must be non-negative')
    if n == 0:
        return []

    result = []

    def backtrack(remaining, start, current):
        if remaining == 0:
            result.append(tuple(current))
            return
        for x in range(start, remaining + 1):
            current.append(x)
            backtrack(remaining - x, x + 1, current)
            current.pop()

    backtrack(n, 1, [])
    result.sort(key=lambda t: (len(t), t))
    return result

def ranked_merge(records, priority_key):
    validated = []
    for rec in records:
        if not isinstance(rec, dict):
            raise ValueError('each record must be a dict')
        required = ('source', 'id', 'priority', 'payload')
        for key in required:
            if key not in rec:
                raise ValueError('missing required key')
        source = rec['source']
        rid = rec['id']
        priority = rec['priority']
        if not isinstance(source, str):
            raise ValueError('source must be a string')
        if not isinstance(rid, str) or rid == '':
            raise ValueError('id must be a non-empty string')
        if not isinstance(priority, int) or priority < 0:
            raise ValueError('priority must be a non-negative integer')
        validated.append(rec.copy())

    best = {}
    order = []
    for idx, rec in enumerate(validated):
        key = (rec['source'], rec['id'])
        if key not in best:
            best[key] = (idx, rec)
            order.append(key)
        else:
            old_idx, old = best[key]
            if rec['priority'] > old['priority']:
                best[key] = (idx, rec)
            # ties keep first; lower priority ignored

    merged = [best[k][1] for k in order if k in best]

    def sort_key(item):
        base = item['priority']
        if priority_key in item:
            return (0, base, item[priority_key])
        return (1, base, 0)

    def safe_compare(a, b):
        try:
            _ = a < b
            _ = a > b
            return True
        except Exception:
            return False

    # Stable sort by priority, then use priority_key only when both sides have comparable values.
    merged_sorted = sorted(merged, key=lambda r: r['priority'])
    if priority_key:
        i = 0
        result = []
        while i < len(merged_sorted):
            j = i + 1
            group = [merged_sorted[i]]
            while j < len(merged_sorted) and merged_sorted[j]['priority'] == merged_sorted[i]['priority']:
                group.append(merged_sorted[j])
                j += 1
            if len(group) > 1 and all(priority_key in r for r in group):
                values = [r[priority_key] for r in group]
                comparable = True
                for x in values:
                    for y in values:
                        if x is y:
                            continue
                        try:
                            _ = x < y
                        except Exception:
                            comparable = False
                            break
                    if not comparable:
                        break
                if comparable:
                    group = sorted(group, key=lambda r: r[priority_key])
            result.extend(group)
            i = j
        merged_sorted = result

    return [(r['source'], r['id'], r['priority'], r['payload']) for r in merged_sorted]

def select_balanced_subsequence(s, t, k):
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return ""
    if k > len(s):
        return ""

    # Precompute next occurrence positions for t.
    # next_pos[i][ch] = smallest index >= i where t[index] == ch, or -1 if none.
    # Build using dynamic dictionaries per suffix for Unicode support.
    suffix_maps = [None] * (len(t) + 1)
    suffix_maps[len(t)] = {}
    for i in range(len(t) - 1, -1, -1):
        m = dict(suffix_maps[i + 1])
        m[t[i]] = i
        suffix_maps[i] = m

    # Memoized feasibility: can we choose r chars from s[i:] and t[j:]?
    from functools import lru_cache

    @lru_cache(None)
    def can(i, j, r):
        if r == 0:
            return True
        if i >= len(s) or j >= len(t):
            return False
        if len(s) - i < r:
            return False
        # Try to find the next character by scanning s and matching in t.
        # For lexicographically smallest, consider possible characters in sorted order.
        seen = set()
        for ii in range(i, len(s)):
            ch = s[ii]
            if ch in seen:
                continue
            seen.add(ch)
            # Find ch in t at or after j.
            pos = suffix_maps[j].get(ch, -1)
            if pos != -1 and can(ii + 1, pos + 1, r - 1):
                return True
        return False

    # Greedy reconstruction of lexicographically smallest valid subsequence.
    result = []
    i = 0
    j = 0
    r = k
    while r > 0:
        candidates = []
        seen = set()
        for ii in range(i, len(s)):
            ch = s[ii]
            if ch in seen:
                continue
            seen.add(ch)
            pos = suffix_maps[j].get(ch, -1)
            if pos != -1 and can(ii + 1, pos + 1, r - 1):
                candidates.append((ch, ii, pos))
        if not candidates:
            return ""
        ch, ii, pos = min(candidates, key=lambda x: (x[0], x[1]))
        result.append(ch)
        i = ii + 1
        j = pos + 1
        r -= 1
    return "".join(result)

def normalize_alarm_schedule(events):
    if events is None:
        raise TypeError('events must be iterable')
    schedule = {}
    for rec in events:
        try:
            n = len(rec)
        except Exception:
            raise ValueError('each record must have exactly 3 items')
        if n != 3:
            raise ValueError('each record must have exactly 3 items')
        label, start, end = rec
        if not isinstance(label, str) or not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('invalid record types')
        if start > end:
            continue
        mins = schedule.setdefault(label, set())
        for minute in range(start, end + 1):
            mins.add(minute)
    return [(label, tuple(sorted(schedule[label]))) for label in sorted(schedule)]

def normalize_event_log(events):
    totals = {}
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        day, category, count = record
        if not isinstance(day, int):
            continue
        if not isinstance(category, str) or category == "":
            continue
        if not isinstance(count, int):
            continue
        if count < 0:
            continue
        key = (day, category)
        totals[key] = totals.get(key, 0) + count
    return [(day, category, totals[(day, category)]) for day, category in sorted(totals.keys())]

def normalize_inventory(events):
    inventory = {}
    for event in events:
        if not isinstance(event, str):
            continue
        parts = event.split(':')
        if len(parts) != 3:
            continue
        action, item, count_text = parts
        if action not in {'ADD', 'REMOVE', 'SET'}:
            continue
        if not item or ':' in item:
            continue
        try:
            count = int(count_text)
        except Exception:
            continue
        current = inventory.get(item, 0)
        if action == 'ADD':
            inventory[item] = current + count
        elif action == 'REMOVE':
            inventory[item] = current - count
        else:
            inventory[item] = count
    return [(item, qty) for item, qty in sorted(inventory.items()) if qty != 0]

def normalize_inventory(events):
    """
    Normalize a sequence of inventory update strings into a canonical summary.

    Each event string has the form 'ACTION:ITEM:COUNT' where:
    - ACTION is one of 'ADD', 'REMOVE', or 'SET'.
    - ITEM is a non-empty string that must not contain a colon.
    - COUNT is a base-10 integer that may be negative.

    Behavior:
    - 'ADD' increases the item's quantity by `COUNT`.
    - 'REMOVE' decreases the item's quantity by `COUNT`.
    - 'SET' assigns the item's quantity to `COUNT`.
    - Items not previously seen start at 0.
    - Events are applied in order.
    - The function must ignore any event string that is malformed in any way: wrong number of fields, unknown action, empty item, item containing a colon, or count that cannot be parsed as an integer.
    - After all valid events are processed, return a list of `(item, quantity)` tuples sorted by item name in ascending lexicographic order.
    - Include only items whose final quantity is not zero.

    :param events: An iterable of strings representing inventory updates.
    :return: A list of `(item, quantity)` tuples sorted by item name in ascending lexicographic order.
    """
    def parse_quantity(quantity_str):
        if ':' in quantity_str:
            return int(quantity_str.split(':')[1])
        else:
            return int(quantity_str)

    def process_event(event):
        action, item, count = event.split(':')
        if action == 'ADD':
            items[item] += count
        elif action == 'REMOVE':
            items[item] -= count
        elif action == 'SET':
            items[item] = count
        else:
            raise ValueError(f"Unknown action: {action}")

    items = {}
    for event in events:
        try:
            process_event(event)
        except ValueError as e:
            print(f"Invalid event: {e}")

    # Filter out items with zero quantity
    result = [(item, quantity) for item, quantity in items.items() if quantity != 0]
    result.sort(key=lambda x: x[0])  # Sort by item name in ascending order

    return result

