import re

_DAY_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')
_TIME_RE = re.compile(r'^\d{2}:\d{2}$')


def _parse_day(day):
    if not isinstance(day, str) or not _DAY_RE.match(day):
        raise ValueError('invalid day')
    return day


def _parse_time(t):
    if not isinstance(t, str) or not _TIME_RE.match(t):
        raise ValueError('invalid time')
    hh = int(t[:2])
    mm = int(t[3:])
    if not (0 <= hh <= 23 and 0 <= mm <= 59):
        raise ValueError('invalid time')
    return hh * 60 + mm


def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    if not events:
        return []

    grouped = {}
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 4:
            raise ValueError('malformed record')
        day, start, end, title = rec
        day = _parse_day(day)
        s = _parse_time(start)
        e = _parse_time(end)
        if not isinstance(title, str) or title == '':
            raise ValueError('invalid title')
        if s >= e:
            raise ValueError('start must be before end')
        grouped.setdefault(day, []).append((s, e, title))

    out = []
    for day in sorted(grouped):
        items = sorted(grouped[day], key=lambda x: (x[0], x[1], x[2]))
        cur_s, cur_e, cur_t = items[0]
        for s, e, t in items[1:]:
            if s <= cur_e:
                if t != cur_t:
                    raise ValueError('conflicting overlapping events')
                cur_e = max(cur_e, e)
            else:
                out.append((day, f'{cur_s//60:02d}:{cur_s%60:02d}', f'{cur_e//60:02d}:{cur_e%60:02d}', cur_t))
                cur_s, cur_e, cur_t = s, e, t
        out.append((day, f'{cur_s//60:02d}:{cur_s%60:02d}', f'{cur_e//60:02d}:{cur_e%60:02d}', cur_t))
    return out

from typing import List

def normalize_schedule(events: List[tuple[str, str, str, str]]) -> List[tuple[str, str, str, str]]:
    """
    Normalize a list of event records into a single, normalized schedule.

    Each event record is a tuple (day, start, end, title) where:
    - day is a string in the format YYYY-MM-DD.
    - start and end are strings in HH:MM format.
    - title is a non-empty string.

    The function validates every record. If any record is malformed, raises ValueError.
    It treats an event as valid only if start < end on the same day.
    Merges overlapping or touching events on the same day only when their titles are exactly the same.
    If two events on the same day overlap or touch but have different titles, raises ValueError.
    Returns a list of normalized records sorted by day, then by start time. Each output record must be a tuple (day, start, end, title).
    If the input list is empty, returns an empty list.
    """
    def is_valid_event(event):
        try:
            day, start, end, title = event
            return day == event[0] and 0 <= int(start) <= 23 and 0 <= int(end) <= 59 and title != ''
        except ValueError:
            raise ValueError(f"Invalid event: {event}")

    def merge_events(event1, event2):
        if event1[0] == event2[0]:
            start = min(event1[1], event2[1])
            end = max(event1[2], event2[2])
            return (event1[0], start, end, event1[3])
        else:
            raise ValueError("Events do not overlap or touch.")

    normalized_schedule = []
    for event in events:
        if not is_valid_event(event):
            raise ValueError(f"Invalid event: {event}")

        if event[0] in normalized_schedule:
            merged_event = merge_events(normalized_schedule[event[0]], event)
            if merged_event[3] == event[3]:
                continue
            else:
                raise ValueError(f"Duplicate event found: {event}")

        normalized_schedule.append(event)

    # Sort by day, then by start time
    normalized_schedule.sort(key=lambda x: (x[0], x[1]))

    return

def compress_intervals(points):
    unique = sorted(set(points))
    if not unique:
        return []

    intervals = []
    start = prev = unique[0]

    for x in unique[1:]:
        if x == prev + 1:
            prev = x
        else:
            intervals.append((start, prev))
            start = prev = x

    intervals.append((start, prev))
    return intervals

def normalize_phrase(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = []
    for raw in text.split():
        cleaned = ''.join(ch for ch in raw if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'))
        if cleaned:
            words.append(cleaned.lower())
    return '-'.join(words)

def normalize_inventory(items):
    if items is None:
        raise TypeError('items must be an iterable of pairs')
    totals = {}
    for pair in items:
        try:
            name, quantity = pair
        except Exception as e:
            raise TypeError('each item must be a pair') from e
        if not isinstance(name, str):
            raise TypeError('name must be a string')
        if isinstance(quantity, bool) or not isinstance(quantity, int):
            raise TypeError('quantity must be an integer')
        normalized = name.strip().lower()
        if normalized == '':
            continue
        totals[normalized] = totals.get(normalized, 0) + quantity
    ordered = {}
    for key in sorted(totals):
        ordered[key] = totals[key]
    return ordered

def normalize_inventory(items):
    """
    Normalize inventory items by converting them to lowercase, removing leading/trailing whitespace,
    and summing quantities for each unique normalized name. Raise TypeError for invalid inputs.

    :param items: List of tuples (name, quantity)
    :return: Dictionary with normalized item names as keys and total quantities as values
    """
    from typing import List, Tuple, Dict

    def normalize_name(name: str) -> str:
        return name.strip().lower()

    def validate_quantity(quantity: int) -> bool:
        return isinstance(quantity, int) and quantity >= 0

    normalized_items = {}
    for name, quantity in items:
        normalized_name = normalize_name(name)
        if normalized_name:
            if normalized_name in normalized_items:
                normalized_items[normalized_name] += quantity
            else:
                normalized_items[normalized_name] = quantity

    return dict(sorted(normalized_items.items(), key=lambda x: x[0]))

