def parse_marker_grid(text: str) -> dict:
    if text == "":
        raise ValueError("empty input")

    lines = text.split("\n")
    if any(line == "" for line in lines):
        raise ValueError("blank line")

    normalized = [line[:-1] if line.endswith("\r") else line for line in lines]
    width = len(normalized[0])
    if width == 0:
        raise ValueError("zero width")

    for line in normalized:
        if len(line) != width:
            raise ValueError("ragged grid")

    blocked = set()
    markers = {}
    for r, line in enumerate(normalized):
        for c, ch in enumerate(line):
            if ch == ".":
                continue
            if ch == "#":
                blocked.add((r, c))
                continue
            if ch.isdigit():
                if ch in markers:
                    raise ValueError("duplicate marker")
                markers[ch] = (r, c)
                continue
            raise ValueError("invalid character")

    return {
        "width": width,
        "height": len(normalized),
        "blocked": blocked,
        "markers": markers,
    }

def parse_marker_grid(text: str) -> dict:
    # Split the text into lines
    lines = text.split('\n')

    # Check if the list is empty
    if not lines:
        raise ValueError("Input is empty")

    # Initialize variables
    width = len(lines[0])
    height = len(lines)
    blocked = set()
    markers = {}

    # Iterate over each line
    for i, line in enumerate(lines):
        # Strip trailing \r and check if the line is empty
        if line.rstrip().strip() == '':
            raise ValueError("Line is empty")

        # Check if the line has the correct length
        if len(line) != width:
            raise ValueError("Line has incorrect length")

        # Iterate over each character in the line
        for j, char in enumerate(line):
            # Check if the character is a digit
            if not char.isdigit():
                raise ValueError(f"Character '{char}' is not a digit")

            # Check if the character is a block
            if char == '#':
                blocked.add((i, j))

            # Check if the character is a marker
            if char == '.':
                if char in markers:
                    raise ValueError(f"Duplicate marker label '{char}' found")
                markers[char] = (i, j)

    # Return the results as a dictionary
    return {
        'width': width,
        'height': height,
        'blocked': blocked,
        'markers': markers
    }

