def compress_ranges(nums):
    values = list(nums)
    if not values:
        return ""

    parts = []
    start = prev = values[0]

    def emit(a, b):
        length = b - a + 1
        if length == 1:
            return str(a)
        if length == 2:
            return f"{a},{b}"
        return f"{a}-{b}"

    for x in values[1:]:
        if x == prev + 1:
            prev = x
        else:
            parts.append(emit(start, prev))
            start = prev = x
    parts.append(emit(start, prev))
    return ";".join(parts)

def summarize_runs(data):
    if not isinstance(data, list):
        raise ValueError("data must be a list")

    total_length = 0
    expanded_first = None
    expanded_last = None
    transitions = 0
    prev_value_set = False
    prev_value = None
    counts = {}
    first_seen_order = {}
    seen_index = 0

    for item in data:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError("each element must be a 2-item tuple")
        value, count = item
        if not isinstance(count, int) or count < 0:
            raise ValueError("count must be a non-negative integer")

        if count == 0:
            continue

        total_length += count
        if value not in counts:
            counts[value] = 0
            first_seen_order[value] = seen_index
            seen_index += 1
        counts[value] += count

        if not prev_value_set:
            expanded_first = value
            prev_value_set = True
        else:
            if prev_value != value:
                transitions += 1
        prev_value = value
        expanded_last = value

    if total_length == 0:
        return {
            "length": 0,
            "unique_values": 0,
            "first_value": None,
            "last_value": None,
            "transitions": 0,
            "most_common": None,
        }

    max_count = None
    most_common_value = None
    for value, count in counts.items():
        if max_count is None or count > max_count:
            max_count = count
            most_common_value = value
        elif count == max_count:
            if first_seen_order[value] < first_seen_order[most_common_value]:
                most_common_value = value

    return {
        "length": total_length,
        "unique_values": len(counts),
        "first_value": expanded_first,
        "last_value": expanded_last,
        "transitions": transitions,
        "most_common": most_common_value,
    }

def normalize_signal_runs(data):
    result = []
    iterator = iter(data)
    try:
        first = next(iterator)
    except StopIteration:
        return result

    if type(first) is not int:
        raise TypeError("all elements must be exact integers")

    current_value = first
    count = 1

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be exact integers")
        if item == current_value:
            count += 1
        else:
            result.append((current_value, count))
            current_value = item
            count = 1

    result.append((current_value, count))
    return result

def normalize_tally(records):
    if not records:
        return []

    totals = {}
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 2:
            raise ValueError('each record must be a 2-item tuple')
        key, delta = rec
        if not isinstance(key, str) or not isinstance(delta, int):
            raise TypeError('key must be str and delta must be int')
        if key == '' or any(ch.isspace() for ch in key):
            raise ValueError('invalid key')
        totals[key] = totals.get(key, 0) + delta

    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))

def compress_rle_segments(data):
    try:
        items = list(data)
    except TypeError:
        raise TypeError("data must be iterable")

    if not items:
        return []

    for x in items:
        if type(x) is not int:
            raise TypeError("all items must be integers")

    result = []
    current = items[0]
    count = 1

    for x in items[1:]:
        if x == current:
            count += 1
        else:
            if count == 1:
                result.append(current)
            else:
                result.append((current, count))
            current = x
            count = 1

    if count == 1:
        result.append(current)
    else:
        result.append((current, count))

    return result

def compact_ranges(nums):
    try:
        iterator = iter(nums)
    except TypeError:
        raise TypeError("input must be an iterable of integers")

    values = []
    for x in iterator:
        if type(x) is not int:
            raise TypeError("all elements must be integers")
        values.append(x)

    if not values:
        return ""

    values = sorted(set(values))
    parts = []
    start = prev = values[0]

    for n in values[1:]:
        if n == prev + 1:
            prev = n
        else:
            parts.append(f"{start}-{prev}" if start != prev else str(start))
            start = prev = n
    parts.append(f"{start}-{prev}" if start != prev else str(start))
    return ", ".join(parts)

def normalize_inventory_updates(updates):
