            continue
        if sku != sku.strip():
            continue
        if any(not (ch.isascii() and (ch.isalnum() or ch == '-')) for ch in sku):
            continue
        if not isinstance(delta, int) or isinstance(delta, bool):
            continue

        norm = sku.upper()
        if norm not in totals:
            totals[norm] = 0
            order.append(norm)
        totals[norm] += delta

    for norm in order:
        result.append((norm, totals[norm]))
    return result

def parse_weighted_pairs(spec: str) -> dict:
    text = spec.strip()
    if text == "":
        return {}

    result = {}
    parts = text.split(';')
    for part in parts:
        entry = part.strip()
        if entry == "":
            raise ValueError("empty entry")
        if ':' not in entry:
            raise ValueError("missing colon")
        name, weight_text = entry.split(':', 1)
        name = name.strip()
        weight_text = weight_text.strip()
        if name == "" or weight_text == "":
            raise ValueError("empty name or weight")
        if any(ch.isspace() for ch in name):
            raise ValueError("invalid name")
        if any(ch in ':;' for ch in name):
            raise ValueError("invalid name")
        if not all(ch.isalnum() or ch == '_' for ch in name):
            raise ValueError("invalid name")
        try:
            weight = int(weight_text, 10)
        except ValueError as e:
            raise ValueError("invalid weight") from e
        result[name] = result.get(name, 0) + weight
    return result

def normalize_history_events(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    result = []
    for event in events:
        if not isinstance(event, dict):
            raise TypeError("each event must be a dict")

        if 'type' not in event:
            raise ValueError("missing type")
        event_type = event['type']
        if not isinstance(event_type, str):
            raise ValueError("type must be a non-empty string")
        event_type_stripped = event_type.strip()
        if not event_type_stripped:
            raise ValueError("type must be a non-empty string")

        payload = event.get('payload', None)
        if payload is None:
            payload_norm = 'NONE'
        elif isinstance(payload, int) and not isinstance(payload, bool):
            payload_norm = str(payload)
        elif isinstance(payload, str):
            payload_norm = payload.upper()
        else:
            raise TypeError("invalid payload")

        tags = event.get('tags', [])
        if not isinstance(tags, list):
            raise TypeError("tags must be a list")
        normalized_tags = []
        seen = set()
        for tag in tags:
            if not isinstance(tag, str):
                raise TypeError("tags must contain strings")
            t = tag.strip()
            if not t:
                continue
            t = t.upper()
            if t not in seen:
                seen.add(t)
                normalized_tags.append(t)
        normalized_tags.sort()
        tag_field = ','.join(normalized_tags)

        result.append(f"{event_type_stripped.upper()}|{payload_norm}|{tag_field}")

    return tuple(result)

def select_weighted_route(routes, preferences):
    try:
        max_duration, max_toll, scenic_required = preferences
    except Exception:
        raise ValueError("preferences must be a 3-tuple")

    if type(max_duration) is not int or type(max_toll) is not int or type(scenic_required) is not bool:
        raise ValueError("invalid preferences types")
    if max_duration < 0 or max_toll < 0:
        raise ValueError("preferences must be non-negative")

    best = None
    for record in routes:
        try:
            route_id, duration, toll, scenic = record
        except Exception:
            raise ValueError("routes must contain 4-tuples")

        if not isinstance(route_id, str):
            raise ValueError("route_id must be a string")
        if type(duration) is not int or type(toll) is not int or type(scenic) is not bool:
            raise ValueError("invalid route record types")
        if duration < 0 or toll < 0:
            raise ValueError("route values must be non-negative")

        if duration > max_duration or toll > max_toll:
            continue
        if scenic_required and not scenic:
            continue

        candidate = (duration, toll, route_id)
        if best is None or candidate < best[0]:
            best = (candidate, route_id)

    return None if best is None else best[1]

def normalize_path_segments(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        if not stack:
            return '/'
        return '/' + '/'.join(stack)

    if not stack:
        return '.'
    return '/'.join(stack)

def merge_intervals_with_labels(intervals):
    if intervals is None:
        raise ValueError('intervals must be a list')
    validated = []
    for item in intervals:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('each interval must be a tuple of (start, end, label)')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('start and end must be integers')
        if start > end:
            raise ValueError('start must be <= end')
        if not isinstance(label, str) or label == '':
            raise ValueError('label must be a non-empty string')
        validated.append((start, end, label))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1], x[2]))
    merged = []
    cur_start, cur_end = validated[0][0], validated[0][1]
    cur_labels = {validated[0][2]}

    for start, end, label in validated[1:]:
        if start <= cur_end + 1:
            if end > cur_end:
                cur_end = end
            cur_labels.add(label)
        else:
            merged.append((cur_start, cur_end, tuple(sorted(cur_labels))))
            cur_start, cur_end = start, end
            cur_labels = {label}

    merged.append((cur_start, cur_end, tuple(sorted(cur_labels))))
    return merged

def decode_run_length(s):
    if s == "":
        return []

    result = []
    i = 0
    n = len(s)

    while i < n:
        if not s[i].isdigit():
            raise ValueError("expected count")

        start = i
        while i < n and s[i].isdigit():
            i += 1
        count_str = s[start:i]
        count = int(count_str)
        if count <= 0:
            raise ValueError("count must be positive")

        if i >= n:
            raise ValueError("missing token")

        if s[i] == '[':
            i += 1
            token_start = i
            while i < n and s[i] != ']':
                i += 1
            if i >= n:
                raise ValueError("unclosed bracket")
            token = s[token_start:i]
            if token == "":
                raise ValueError("empty bracketed token")
            i += 1
        else:
            if s[i].isdigit():
                raise ValueError("invalid unbracketed token")
            token = s[i]
            i += 1

        result.extend([token] * count)

    return result

def normalize_event_log(entries):
    if not isinstance(entries, list):
        raise ValueError("entries must be a list")

    normalized = []
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) not in (2, 3):
            raise ValueError("invalid entry shape")

        if len(entry) == 2:
            timestamp, payload = entry
            tag = None
        else:
            timestamp, payload, tag = entry

        if not isinstance(timestamp, int):
            raise ValueError("timestamp must be int")
        if not isinstance(payload, str):
            raise ValueError("payload must be str")
        if tag is not None and not isinstance(tag, str):
            raise ValueError("tag must be str or None")

        size = len(payload)
        if size <= 3:
            level = "short"
        elif size <= 7:
            level = "medium"
        else:
            level = "long"

        normalized.append({
            "time": timestamp,
            "payload": payload,
            "tag": tag,
            "size": size,
            "level": level,
        })

    normalized.sort(key=lambda d: (d["time"], d["size"], d["payload"], "" if d["tag"] is None else d["tag"], d["tag"] is not None))
    return normalized

def merge_weighted_events(events):
    result = []
    aggregates = {}
    order = []

    for record in events:
        try:
            label, delta, weight = record
        except Exception:
            raise ValueError('Each record must be a 3-item sequence')

        if not isinstance(label, str) or label == '':
            raise ValueError('label must be a non-empty string')
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise ValueError('delta must be an integer')
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:
            raise ValueError('weight must be a positive integer')

        if label not in aggregates:
            aggregates[label] = {'label': label, 'count': 0, 'net_delta': 0, 'weighted_total': 0}
            order.append(label)

        agg = aggregates[label]
        agg['count'] += 1
        agg['net_delta'] += delta
        agg['weighted_total'] += delta * weight

    for label in order:
        result.append(aggregates[label])

    return result

def merge_weighted_events(events):
    """
    Normalize and aggregate weighted event records.

    Parameters:
    events (iterable): A list of tuples, where each tuple contains a label, a delta, and a weight.

    Returns:
    list: A list of dictionaries, each representing a label and its aggregated data.
    """
    # Validate input
    if not isinstance(events, list):
        raise ValueError("Input must be a list of tuples.")
    for record in events:
        if len(record) != 3:
            raise ValueError("Each record must be a 3-item sequence.")
        if not isinstance(record[0], str):
            raise ValueError("Label must be a non-empty string.")
        if not isinstance(record[1], int):
            raise ValueError("Delta must be an integer.")
        if not isinstance(record[2], int):
            raise ValueError("Weight must be an integer greater than 0.")

    # Initialize result list
    result = []
    # Group events by label
    for label, delta, weight in events:
        count = 1
        net_delta = delta
        weighted_total = weight
        while count < len(events):
            if events[count][0] == label:
                net_delta += events[count][1]
                weighted_total += events[count][1] * events[count][2]
                count += 1
            else:
                break
        result.append({'label': label, 'count': count, 'net_delta': net_delta, 'weighted_total': weighted_total})

    return result

