def normalize_inventory_updates(base, updates):
    def is_seq(x):
        return isinstance(x, (list, tuple))

    inventory = {}

    for rec in base:
        if not is_seq(rec) or len(rec) != 3:
            raise ValueError('invalid base record')
        sku, name, quantity = rec
        if not isinstance(sku, str):
            raise TypeError('sku must be string')
        if not isinstance(name, str):
            raise TypeError('name must be string')
        if not isinstance(quantity, int):
            raise TypeError('quantity must be int')
        inventory[sku] = [name, quantity]

    for upd in updates:
        if not is_seq(upd) or len(upd) not in (3, 4):
            raise ValueError('invalid update record')
        kind = upd[0]
        if kind == 'set':
            if len(upd) != 4:
                raise ValueError('invalid set update')
            _, sku, name, quantity = upd
            if not isinstance(sku, str):
                raise TypeError('sku must be string')
            if not isinstance(name, str):
                raise TypeError('name must be string')
            if not isinstance(quantity, int):
                raise TypeError('quantity must be int')
            inventory[sku] = [name, quantity]
        elif kind == 'add':
            if len(upd) != 3:
                raise ValueError('invalid add update')
            _, sku, delta = upd
            if not isinstance(sku, str):
                raise TypeError('sku must be string')
            if not isinstance(delta, int):
                raise TypeError('delta must be int')
            name, quantity = inventory.get(sku, ['', 0])
            inventory[sku] = [name, quantity + delta]
        else:
            raise ValueError('unknown update kind')

    return [(sku, inventory[sku][0], inventory[sku][1]) for sku in sorted(inventory)]

def decode_telegraph(code: str) -> str:
    s = code.strip()
    if not s:
        return ""

    tokens = s.split()
    out = []
    for token in tokens:
        if token == "/":
            out.append(" ")
            continue
        if not token.isdigit():
            raise ValueError(f"invalid token: {token!r}")
        n = int(token)
        if not 1 <= n <= 26:
            raise ValueError(f"invalid token: {token!r}")
        out.append(chr(ord('a') + n - 1))
    return "".join(out)

def summarize_signal_runs(signal):
    if not isinstance(signal, (list, tuple)):
        raise TypeError('signal must be a list or tuple of integers')
    for x in signal:
        if not isinstance(x, int):
            raise TypeError('signal must contain only integers')

    if len(signal) == 0:
        return {'runs': [], 'longest': None, 'sum_positive': 0, 'sum_negative': 0}

    runs = []
    sum_positive = 0
    sum_negative = 0

    current_value = signal[0]
    current_length = 1

    if current_value > 0:
        sum_positive += current_value
    elif current_value < 0:
        sum_negative += current_value

    for x in signal[1:]:
        if x > 0:
            sum_positive += x
        elif x < 0:
            sum_negative += x

        if x == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            current_value = x
            current_length = 1

    runs.append((current_value, current_length))

    longest = runs[0]
    for run in runs[1:]:
        if run[1] > longest[1]:
            longest = run

    return {
        'runs': runs,
        'longest': longest,
        'sum_positive': sum_positive,
        'sum_negative': sum_negative,
    }

def schedule_lanes(jobs, lanes):
    if not isinstance(lanes, int) or lanes <= 0:
        raise ValueError("lanes must be a positive integer")
    if not isinstance(jobs, list):
        raise ValueError("jobs must be a list")

    validated = []
    for idx, job in enumerate(jobs):
        if not isinstance(job, dict):
            raise ValueError("each job must be a dictionary")
        if set(job.keys()) != {"id", "arrival", "duration"}:
            raise ValueError("each job must contain exactly id, arrival, duration")
        arrival = job["arrival"]
        duration = job["duration"]
        if not isinstance(arrival, int) or arrival < 0:
            raise ValueError("arrival must be a non-negative integer")
        if not isinstance(duration, int) or duration <= 0:
            raise ValueError("duration must be a positive integer")
        validated.append((idx, job["id"], arrival, duration))

    ordered = sorted(validated, key=lambda x: (x[2], x[0]))
    lane_free = [0] * lanes
    result = []

    for _, job_id, arrival, duration in ordered:
        best_lane = 0
        best_free = lane_free[0]
        for lane in range(1, lanes):
            free = lane_free[lane]
            if free < best_free or (free == best_free and lane < best_lane):
                best_lane = lane
                best_free = free
        start = best_free if best_free > arrival else arrival
        finish = start + duration
        lane_free[best_lane] = finish
        result.append({"id": job_id, "lane": best_lane, "start": start, "finish": finish})

    return result

def normalize_event_records(records):
    normalized = []
    seen = set()
    for record in records:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError("Each record must be a list or tuple of exactly 3 items")
        day, minute, payload = record
        if not isinstance(day, int) or day < 0:
            raise ValueError("day must be a non-negative integer")
        if not isinstance(minute, int) or minute < 0 or minute > 1439:
            raise ValueError("minute must be an integer in 0..1439")
        if not isinstance(payload, str):
            raise ValueError("payload must be a string")
        norm_payload = payload.strip().upper()
        if norm_payload == "":
            continue
        key = (day, minute, norm_payload)
        if key not in seen:
            seen.add(key)
            normalized.append(key)
    normalized.sort(key=lambda x: (x[0], x[1], x[2]))
    return normalized

def normalize_inventory(operations):
    inventory = {}
    for op in operations:
        if not isinstance(op, tuple) or len(op) != 3:
            raise ValueError('invalid operation')
        action, item, amount = op
        if action not in {'add', 'remove', 'set'}:
            raise ValueError('invalid operation')
        if not isinstance(item, str) or item == '':
            raise ValueError('invalid operation')
        if not isinstance(amount, int):
            raise ValueError('invalid operation')
        if action == 'add':
            inventory[item] = inventory.get(item, 0) + amount
        elif action == 'remove':
            inventory[item] = inventory.get(item, 0) - amount
        else:
            inventory[item] = amount
    result = [(item, count) for item, count in inventory.items() if count != 0]
    result.sort(key=lambda x: (-x[1], x[0]))
    return result

def normalize_mixed_key(s: str) -> str:
    if not isinstance(s, str) or s == "":
        return ""

    n = len(s)
    i = 0

    # Leading ASCII letters
    if not ('A' <= s[0] <= 'Z' or 'a' <= s[0] <= 'z'):
        return ""
    while i < n and (('A' <= s[i] <= 'Z') or ('a' <= s[i] <= 'z')):
        i += 1

    prefix = s[:i].lower()

    # Validate trailing part
    while i < n:
        if s[i] == '-':
            # Hyphen must be followed by at least one digit
            i += 1
            if i >= n or not ('0' <= s[i] <= '9'):
                return ""
        elif not ('0' <= s[i] <= '9'):
            return ""

        if not ('0' <= s[i] <= '9'):
            return ""
        while i < n and ('0' <= s[i] <= '9'):
            i += 1

    return prefix + s[len(prefix):]

def normalize_grid(grid):
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError("grid must be a non-empty rectangular list of lists")

    if not all(isinstance(row, list) and len(row) > 0 for row in grid):
        raise ValueError("grid must contain non-empty lists")

    row_len = len(grid[0])
    if any(len(row) != row_len for row in grid):
        raise ValueError("all rows must have the same length")

    for row in grid:
        for x in row:
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("all elements must be integers")

    result = []
    for row in grid:
        m = min(row)
        M = max(row)
        if m == M:
            result.append([0] * row_len)
        else:
            denom = M - m
            result.append([round((x - m) * 9 / denom) for x in row])
    return result

def normalize_event_lines(text: str) -> list[str]:
    lines = []
    for raw in text.splitlines():
        stripped = raw.strip()
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        parts = stripped.split()
        cleaned = ' '.join(parts)
        lines.append(cleaned)
    return lines

def merge_intervals_weighted(events):
    deltas = {}
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError('each event must be a tuple (start, end, weight)')
        start, end, weight = item
        if start >= end or weight == 0:
            continue
        deltas[start] = deltas.get(start, 0) + weight
        deltas[end] = deltas.get(end, 0) - weight

    if not deltas:
        return []

    points = sorted(deltas)
    result = []
    active = 0
    prev = None

    for point in points:
        if prev is not None and prev < point and active != 0:
            if result and result[-1][1] == prev and result[-1][2] == active:
                result[-1] = (result[-1][0], point, active)
            else:
                result.append((prev, point, active))
        active += deltas[point]
        prev = point

    return result

def summarize_run_lengths(data):
    if not isinstance(data, str):
        raise TypeError("data must be a string")
    if data == "":
        return []

    result = []
    current_char = data[0]
    count = 1

    for ch in data[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = ch
            count = 1

    result.append((current_char, count))
    return result

def normalize_doc_ids(tokens):
    try:
        iterator = iter(tokens)
    except TypeError:
        raise TypeError("tokens must be iterable")

    doc_ids = []
    counts = []
    mapping = {}

    for tok in iterator:
        if not isinstance(tok, str):
            raise ValueError("each token must be a string")
        if tok == "" or any(not (ch.isascii() and (ch.isalpha() or ch.isdigit() or ch == "_")) for ch in tok):
            raise ValueError("invalid token")
        key = tok.lower()
        if key not in mapping:
            mapping[key] = len(counts)
            counts.append(0)
        idx = mapping[key]
        doc_ids.append(idx)
        counts[idx] += 1

    return doc_ids, counts

def dominant_runs(nums):
    it = iter(nums)
    try:
        first = next(it)
    except StopIteration:
        return None
    if not isinstance(first, int):
        raise TypeError("all elements must be integers")

    best_value = first
    best_len = 1
    best_start = 0

    current_value = first
    current_len = 1
    current_start = 0

    index = 0
    for x in it:
        index += 1
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if x == current_value:
            current_len += 1
        else:
            if current_len > best_len:
                best_value = current_value
                best_len = current_len
                best_start = current_start
            current_value = x
            current_len = 1
            current_start = index
    if current_len > best_len:
        best_value = current_value
        best_len = current_len
        best_start = current_start
    return (best_value, best_len)

def parse_ledger_events(lines):
    from collections import defaultdict
    import math

    accounts = {}
    tag_totals = defaultdict(float)
    seen_any = False

    for raw_line in lines:
        if raw_line is None:
            raise ValueError("Malformed line")
        line = raw_line.strip()
        if not line:
            continue
        seen_any = True
        parts = [part.strip() for part in line.split('|')]
        if len(parts) != 4:
            raise ValueError("Malformed line")
        account_id, direction, amount_text, tag = parts
        if not account_id or not tag:
            raise ValueError("Malformed line")
        if direction not in ('credit', 'debit'):
            raise ValueError("Malformed line")
        try:
            amount = float(amount_text)
        except Exception:
            raise ValueError("Malformed line")
        if not math.isfinite(amount):
            raise ValueError("Malformed line")

        if account_id not in accounts:
            accounts[account_id] = {'credit': 0.0, 'debit': 0.0}
        accounts[account_id][direction] += amount
        tag_totals[tag] += amount

    if not seen_any:
        return {'accounts': {}, 'tags': {}}

    sorted_accounts = {}
    for account_id in sorted(accounts):
        credit = float(accounts[account_id]['credit'])
        debit = float(accounts[account_id]['debit'])
        sorted_accounts[account_id] = {
            'credit': credit,
            'debit': debit,
            'net': float(credit - debit),
        }

    sorted_tags = {tag: float(tag_totals[tag]) for tag in sorted(tag_totals)}
    return {'accounts': sorted_accounts, 'tags': sorted_tags}

def merge_intervals_with_labels(intervals, labels):
    if len(intervals) != len(labels):
        raise ValueError("intervals and labels must have the same length")
    if not intervals:
        return []
    normalized = []
    for iv, label in zip(intervals, labels):
        if len(iv) != 2:
            raise ValueError("each interval must contain exactly two items")
        start, end = iv
        if start > end:
            raise ValueError("interval start must be <= end")
        normalized.append((start, end, label))
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end, cur_labels = normalized[0][0], normalized[0][1], {normalized[0][2]}
    for start, end, label in normalized[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
            cur_labels.add(label)
