def normalize_dag_edges(edges):
    result = []
    seen_oriented = set()
    seen_unordered = set()

    for item in edges:
        try:
            u, v = item
        except TypeError:
            raise TypeError("Each edge must be an iterable of length 2")
        except ValueError:
            raise ValueError("Each edge must contain exactly 2 items")

        if u == v:
            continue

        try:
            oriented_key = (u, v)
            unordered_key = frozenset((u, v))
            hash(oriented_key)
            hash(unordered_key)
        except TypeError:
            raise TypeError("Edge nodes must be hashable")

        if unordered_key in seen_unordered:
            continue

        if oriented_key in seen_oriented:
            continue

        seen_oriented.add(oriented_key)
        seen_unordered.add(unordered_key)
        result.append((u, v))

    return result

def normalize_checkout_totals(items):
    grand_total = 0.0
