        if not hasattr(record, '__len__') or len(record) != 3:
            raise ValueError('Each record must be a sequence of length exactly 3')
        sku, amount, currency = record

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError('Amount must be an int or float')
        if not isinstance(currency, str) or currency == '':
            raise ValueError('Currency must be a non-empty string')

