def normalize_checkout_totals(items):
    """
    Normalize checkout totals by summing up amounts for each currency.

    :param items: List of tuples (sku, amount, currency)
    :return: Tuple (grand_total, by_currency)
    """
    grand_total = 0.0
    by_currency = {}

    for item in items:
        if len(item) != 3:
            raise ValueError("Invalid purchase record format")

        sku, amount, currency = item

        try:
            amount = float(amount)
            currency = currency.strip()

            if not isinstance(amount, (int, float)):
                raise TypeError("Amount must be an int or float")

            if not isinstance(currency, str):
                raise TypeError("Currency must be a non-empty string")

            if bool(amount):
                raise TypeError("Boolean values for amount are invalid")

            grand_total += amount

            if currency in by_currency:
                by_currency[currency] += amount
            else:
                by_currency[currency] = amount

    return grand_total, by_currency

