def normalize_vms_config(spec):
    if not isinstance(spec, dict):
        raise TypeError("spec must be a dictionary")

    required_keys = {"memory_mb", "cpu_cores", "disk_gb", "tags", "metadata"}
    if set(spec.keys()) != required_keys:
        raise TypeError("spec must contain exactly the required keys")

    def parse_non_negative_int(value):
        if isinstance(value, bool):
            raise TypeError("invalid integer field")
        if isinstance(value, int):
            if value < 0:
                raise TypeError("invalid integer field")
            return value
        if isinstance(value, str) and value.isdigit():
            return int(value)
        raise TypeError("invalid integer field")

    def dedupe_tags(tags):
        if not isinstance(tags, list):
            raise TypeError("tags must be a list")
        seen = set()
        out = []
        for tag in tags:
            if not isinstance(tag, str):
                raise TypeError("tags must be a list of strings")
            if tag not in seen:
                seen.add(tag)
                out.append(tag)
        return out

    def clean_metadata(value):
        if isinstance(value, dict):
            cleaned = {}
            for k, v in value.items():
                if v is None:
                    continue
                cleaned_v = clean_metadata(v)
                cleaned[k] = cleaned_v
            return cleaned
        if isinstance(value, list):
            cleaned_list = []
            for item in value:
                if item is None:
                    continue
                cleaned_list.append(clean_metadata(item))
            return cleaned_list
        return value

    memory_mb = parse_non_negative_int(spec["memory_mb"])
    cpu_cores = parse_non_negative_int(spec["cpu_cores"])
    disk_gb = parse_non_negative_int(spec["disk_gb"])
    tags = dedupe_tags(spec["tags"])
    metadata = spec["metadata"]
    if not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")
    metadata = clean_metadata(metadata)

    return {
        "memory_mb": memory_mb,
        "cpu_cores": cpu_cores,
        "disk_gb": disk_gb,
        "tags": tags,
        "metadata": metadata,
    }

def normalize_vms_config(spec):
    """
    Normalize a small virtual-machine configuration dictionary.

    Args:
    spec (dict): A dictionary with exactly the keys "memory_mb", "cpu_cores", "disk_gb", "tags", and "metadata".

    Returns:
    dict: A new dictionary with the same five keys.
    """
    # Check if the input is a dictionary
    if not isinstance(spec, dict):
        raise TypeError("Input must be a dictionary.")

    # Check for missing keys
    missing_keys = [key for key in spec if key not in ["memory_mb", "cpu_cores", "disk_gb", "tags", "metadata"]]
    if missing_keys:
        raise KeyError(f"Missing keys: {missing_keys}")

    # Convert memory_mb, cpu_cores, disk_gb to integers
    memory_mb = int(spec.get("memory_mb", 0))
    cpu_cores = int(spec.get("cpu_cores", 0))
    disk_gb = int(spec.get("disk_gb", 0))

    # Convert tags to a list of unique strings
    tags = set(spec.get("tags", []))

    # Convert metadata to a dictionary
    metadata = {}
    for key, value in spec.get("metadata", {}).items():
        if value is None:
            continue
        elif isinstance(value, dict):
            metadata.update(normalize_vms_config(value))
        else:
            metadata[key] = value

    # Normalize tags
    normalized_tags = []
    for tag in tags:
        if isinstance(tag, str):
            try:
                tag = int(tag)
            except ValueError:
                tag = tag.lower()
            normalized_tags.append(tag)

    # Normalize metadata
    normalized_metadata = {}
    for key, value in metadata.items():
        if value is None:
            continue
        elif isinstance(value, dict):
            normalized_metadata.update(normalize_vms_config(value))
        else:
            normalized_metadata[key] = value

    # Return the normalized dictionary
    return {
        "memory_mb": memory_mb,
        "cpu_cores": cpu_cores,
        "disk_gb": disk_gb,
        "tags": normalized_tags,
        "metadata": normalized_metadata
    }

def summarize_rle_segments(text: str) -> list[tuple[str, int, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return []

    segments = []
    start = 0
    current = text[0]
    length = 1

    for i in range(1, len(text)):
        ch = text[i]
        if ch == current:
            length += 1
        else:
            segments.append((current, start, length))
            current = ch
            start = i
            length = 1

    segments.append((current, start, length))
    return segments

def normalize_tournament_table(rows):
