def normalize_schedule(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    canonical = []
    for item in events:
        if not isinstance(item, (tuple, list)) or len(item) != 3:
            raise TypeError("each event must be a tuple/list of length 3")
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int) or not isinstance(label, str):
            raise TypeError("invalid event field types")
        if start > end:
            raise ValueError("start cannot be greater than end")
        canonical.append((start, end, label))

    by_label = {}
    for start, end, label in canonical:
        by_label.setdefault(label, []).append((start, end))

    merged = []
    for label, intervals in by_label.items():
        intervals.sort(key=lambda x: (x[0], x[1]))
        cur_start, cur_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= cur_end + 1:
                if end > cur_end:
                    cur_end = end
            else:
                merged.append((label, cur_start, cur_end))
                cur_start, cur_end = start, end
        merged.append((label, cur_start, cur_end))

    merged.sort(key=lambda x: (x[0], x[1], x[2]))
    return [(start, end, label) for label, start, end in merged]

def normalize_schedule(events):
    """
    Normalize a list of event records into a canonicalized schedule.

    Parameters:
    events (list): A list of tuples or lists with exactly 3 items: (start, end, label).

    Returns:
    list: A list of tuples representing the normalized schedule.
    """
    def merge_intervals(interval1, interval2):
        # Check if two intervals overlap
        if interval1[0] > interval2[1]:
            return interval2
        elif interval2[0] > interval1[1]:
            return interval1
        else:
            # Find the intersection of the two intervals
            start = max(interval1[0], interval2[0])
            end = min(interval1[1], interval2[1])
            return (start, end, interval1[2])

    def normalize_event(event):
        if len(event) != 3:
            raise TypeError("Each event must be a tuple or list of length 3.")
        if not isinstance(event[0], int) or not isinstance(event[1], int) or not isinstance(event[2], str):
            raise TypeError("All elements of events must be integers and strings.")
        if event[0] > event[1]:
            raise ValueError("Start time cannot be greater than end time.")
        return (event[0], event[1], event[2])

    def normalize_schedule(events):
        normalized_events = []
        for event in events:
            normalized_event = normalize_event(event)
            if normalized_event not in normalized_events:
                normalized_events.append(normalized_event)
        return sorted(normalized_events, key=lambda x: (x[2], x[0], x[1]))

    return normalize_schedule(events)

