def normalize_dna_segments(segments):
    result = []
    seen = set()
    for frag in segments:
        s = frag.strip().upper()
        if not s:
            continue
        for ch in s:
            if ch not in {'A', 'C', 'G', 'T', 'N'}:
                raise ValueError(f'invalid character: {ch}')
        i = 0
        while i < len(s) and s[i] == 'N':
            i += 1
        s = s[i:]
        if not s:
            continue
        if s not in seen:
            seen.add(s)
            result.append(s)
    return result

