        except Exception as e:
            raise ValueError("start and end must be integers") from e
        if start > end:
            raise ValueError("start cannot be greater than end")
        records.append((code, start, end))

    records.sort(key=lambda r: (r[1], r[2], r[0]))
    result = []
    if not records:
        return result

    cur_code, cur_start, cur_end = records[0]
    count = 1
    for code, start, end in records[1:]:
        if code == cur_code and start == cur_end:
            cur_end = end
            count += 1
        else:
            result.append((cur_code, cur_start, cur_end, count))
            cur_code, cur_start, cur_end = code, start, end
            count = 1
    result.append((cur_code, cur_start, cur_end, count))
    return result

def compress_segments(intervals):
    if intervals == []:
        return []

    validated = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("Each interval must be a pair")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Interval endpoints must be integers")
        if start > end:
            raise ValueError("Interval start must not exceed end")
        validated.append((start, end))

    validated.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = validated[0]

    for start, end in validated[1:]:
        if start <= cur_end + 1:
            if end > cur_end:
                cur_end = end
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end

    merged.append([cur_start, cur_end])
    return merged

def normalize_event_weights(events):
