    for item in intervals:
        try:
            if len(item) != 3:
                raise ValueError('each interval must have exactly 3 items')
        except TypeError:
            raise ValueError('each interval must have exactly 3 items')
        start, end, label = item
        if start > end:
            raise ValueError('start must be <= end')
        label = str(label)
        grouped.setdefault(label, []).append((start, end))
    merged = []
    for label, spans in grouped.items():
        spans.sort(key=lambda x: (x[0], x[1]))
        cur_start, cur_end = spans[0]
        for start, end in spans[1:]:
            if start <= cur_end:
                if end > cur_end:
                    cur_end = end
            else:
                merged.append((cur_start, cur_end, label))
                cur_start, cur_end = start, end
        merged.append((cur_start, cur_end, label))
    merged.sort(key=lambda x: (x[0], x[1], x[2]))
    return merged

