    merged = sorted(set(merged), key=lambda x: (x[0], x[1], x[2]))
    return merged

def normalize_event_schedule(events):
    """
    Normalize a list of event records. Each record is a tuple (start, end, label).
    The function returns a new list of tuples sorted by (start, end, label) with these rules applied:
    - Reject invalid records by raising ValueError if any record is not a 3-tuple, if `start` or `end` is not an `int`, if `label` is not a `str`, or if `start > end`.
    - Merge overlapping or touching intervals that have the same label. Two intervals with the same label should be merged if the next interval starts at or before the current merged interval ends plus 1. The merged interval uses the minimum start and maximum end among the merged records, and keeps that label.
    - Do not merge intervals with different labels, even if they overlap.
    - Discard exact duplicates after normalization.
    - The input list must not be modified.
    - If the input list is empty, return an empty list.

    Examples:
    >>> normalize_event_schedule([(1, 3, 'a'), (4, 5, 'a')])
    [(1, 5, 'a')]
    >>> normalize_event_schedule([(1, 4, 'a'), (3, 6, 'b')])
    [(1, 4, 'a')]
    >>> normalize_event_schedule([(2, 2, 'x'), (2, 2, 'x')])
    [(2, 2, 'x')]
    """
    def merge_intervals(interval1, interval2):
        start = min(interval1[0], interval2[0])
        end = max(interval1[1], interval2[1])
        return (start, end, interval1[2])

    def normalize_interval(record):
        if len(record) != 3:
            raise ValueError("Invalid record format")
        start, end, label = record
        if start > end:
            raise ValueError("Start must be less than or equal to end")
        if label not in {'a', 'b'}:
            raise ValueError("Label must be 'a' or 'b'")
        return merge_intervals((start, end, label))

    normalized_events = [normalize_interval(event) for event in events]
    return sorted(normalized_events)

