def parse_ledger(lines):
    credits = 0
    debits = 0
    net = 0
    by_category = {}

    for raw in lines:
        line = raw.strip()
        if line == '':
            continue

        parts = line.split(':')
        if len(parts) != 3:
            raise ValueError('Malformed ledger entry')

        kind, amount_text, category_text = parts
        kind = kind.strip()
        amount_text = amount_text.strip()
        category = category_text.strip()

        if kind not in ('C', 'D'):
            raise ValueError('Malformed ledger entry')
        if category == '' or ':' in category:
            raise ValueError('Malformed ledger entry')
        if amount_text == '':
            raise ValueError('Malformed ledger entry')

        signless = amount_text
        if signless[0] in '+-':
            if len(signless) == 1:
                raise ValueError('Malformed ledger entry')
            signless = signless[1:]
        if not signless.isdigit():
            raise ValueError('Malformed ledger entry')

        amount = int(amount_text)
        if amount <= 0:
            raise ValueError('Malformed ledger entry')

        if kind == 'C':
            credits += 1
            net += amount
            by_category[category] = by_category.get(category, 0) + amount
        else:
            debits += 1
            net -= amount
            by_category[category] = by_category.get(category, 0) - amount

    return {
        'credits': credits,
        'debits': debits,
        'net': net,
        'by_category': by_category,
    }

def normalize_chat_command(command: str) -> str:
    stripped = command.strip()
    if stripped == "":
        raise ValueError("empty command")

    prefix = ""
    if stripped[0] in "/!":
        prefix = "/"
        stripped = stripped[1:].lstrip()
        if stripped == "":
            raise ValueError("missing command name")

    parts = stripped.split(None, 1)
    cmd = parts[0].lower()
    if len(parts) == 1:
        return prefix + cmd

    args = " ".join(parts[1].split())
    if args == "":
        return prefix + cmd
    return f"{prefix}{cmd} {args}"

def summarize_rle_segments(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if s == "":
        return (0, None, 0)
    parts = s.split(';')
    total = 0
    best_letter = None
    best_count = None
    count_segments = 0
    for part in parts:
        if part == "":
            raise ValueError("empty segment")
        if ':' not in part:
            raise ValueError("invalid segment")
        if part.count(':') != 1:
            raise ValueError("invalid segment")
        letter, count_str = part.split(':')
        if len(letter) != 1 or not ('A' <= letter <= 'Z'):
            raise ValueError("invalid letter")
        if count_str == "" or not count_str.isdigit():
            raise ValueError("invalid count")
        count = int(count_str)
        total += count
        count_segments += 1
        if best_count is None or count > best_count:
            best_count = count
            best_letter = letter
    if count_segments == 0:
        return (0, None, 0)
    return (total, best_letter, count_segments)

def summarize_segments(text: str) -> list[tuple[str, int, int]]:
    def char_type(ch: str) -> str:
        if 'a' <= ch <= 'z':
            return 'lower'
        if 'A' <= ch <= 'Z':
            return 'upper'
        if '0' <= ch <= '9':
            return 'digit'
        return 'other'

    if text == '':
        return []

    segments = []
    start = 0
    current_type = char_type(text[0])

    for i in range(1, len(text)):
        t = char_type(text[i])
        if t != current_type:
            segments.append((current_type, start, i - 1))
            start = i
            current_type = t

    segments.append((current_type, start, len(text) - 1))
    return segments

def normalize_filename(name):
    s = name.strip()
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            out.append('_')
            i += 1
            while i < n and s[i].isspace():
                i += 1
            continue
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch in '_-.':
            out.append(ch)
        else:
            out.append('-')
        i += 1
    s = ''.join(out)
    collapsed = []
    i = 0
    while i < len(s):
        if s[i] == '-':
            collapsed.append('-')
            while i < len(s) and s[i] == '-':
                i += 1
        else:
            collapsed.append(s[i])
            i += 1
    s = ''.join(collapsed).strip('-.')
    return s if s else 'unnamed'

def top_k_sparse_columns(matrix, k):
    if not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k < 0:
        raise ValueError("k must be non-negative")
    if not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError("matrix must be a non-empty rectangular list of lists")
    if not all(isinstance(row, list) and len(row) > 0 for row in matrix):
        raise ValueError("matrix must be a non-empty rectangular list of lists")
    row_length = len(matrix[0])
    if any(len(row) != row_length for row in matrix):
        raise ValueError("matrix must be rectangular")
    for row in matrix:
        for value in row:
            if not isinstance(value, int):
                raise ValueError("all matrix elements must be integers")
    if k > row_length:
        raise ValueError("k cannot exceed number of columns")
    if k == 0:
        return []
    zero_counts = []
    for col in range(row_length):
        count = 0
        for row in matrix:
            if row[col] == 0:
                count += 1
        zero_counts.append((count, col))
    zero_counts.sort(key=lambda item: (-item[0], item[1]))
    return [col for _, col in zero_counts[:k]]

def normalize_schedule_intervals(intervals):
    if intervals is None:
        raise ValueError('intervals must be an iterable of 2-item integer sequences')

    normalized = []
    for item in intervals:
        try:
            if len(item) != 2:
                raise ValueError
            a, b = item
        except Exception:
            raise ValueError('each interval must contain exactly two values')
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError('each interval endpoint must be an integer')
        start, end = (a, b) if a <= b else (b, a)
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def parse_patch_counts(patch: str) -> tuple[int, int]:
    if not isinstance(patch, str):
        raise TypeError("patch must be a string")

    added = 0
    removed = 0
    for line in patch.split('\n'):
        stripped = line.lstrip(' \t')
        if not stripped:
            continue
        if stripped.startswith('+++') or stripped.startswith('---'):
            continue
        if stripped.startswith('+'):
            added += 1
        elif stripped.startswith('-'):
            removed += 1
    return added, removed

def normalize_inventory_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    totals = {}
    order = []

    for entry in entries:
        if not isinstance(entry, str):
            continue
        if entry.count(':') != 1:
            continue
        item_part, qty_part = entry.split(':')
        item = item_part.strip()
        qty_text = qty_part.strip()
        if not item or ':' in item:
            continue
        if qty_text in ('', '+', '-'):
            continue
        sign = 1
        if qty_text[0] in '+-':
            sign = -1 if qty_text[0] == '-' else 1
            digits = qty_text[1:]
        else:
            digits = qty_text
        if not digits.isdigit():
            continue
        qty = sign * int(digits)
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += qty

    return [f'{item}:{totals[item]}' for item in order]

def normalize_csv_row(row: str) -> str:
    parts = row.split(',')
