    for part in parts:
        s = part.strip()
        if len(s) >= 2 and s[0] == '[' and s[-1] == ']':
            s = s[1:-1].strip()
        s = s.upper()
        if s != '':
            normalized.append(s)
    return ';'.join(normalized)

def segment_transitions(labels):
    if not isinstance(labels, list):
        raise TypeError("labels must be a list of integers")
    for x in labels:
        if type(x) is not int:
            raise TypeError("labels must contain only integers")
    if not labels:
        return []
    lengths = []
    current = labels[0]
    count = 1
    for value in labels[1:]:
        if value == current:
            count += 1
        else:
            lengths.append(count)
            current = value
            count = 1
    lengths.append(count)
    return lengths

def collapse_runs(items, combine):
    result = []
    iterator = iter(items)
    try:
        current = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == current:
            count += 1
        else:
            result.append(combine(current, count))
            current = item
            count = 1
    result.append(combine(current, count))
    return result

def normalize_record(record):
    if not isinstance(record, dict):
        raise TypeError('record must be a dict')

    result = {}

    if 'name' in record:
        name = record['name']
        if not isinstance(name, str):
            raise TypeError('name must be a string')
        cleaned_name = name.strip().title()
        if cleaned_name:
            result['name'] = cleaned_name

    if 'age' in record:
        age = record['age']
        if isinstance(age, int):
            cleaned_age = age
        elif isinstance(age, str) and age.isdigit():
            cleaned_age = int(age)
        else:
            raise TypeError('age must be an int or digit string')
        if cleaned_age >= 0:
            result['age'] = cleaned_age

    if 'email' in record:
        email = record['email']
        if not isinstance(email, str):
            raise TypeError('email must be a string')
        cleaned_email = email.strip().lower()
        if cleaned_email.count('@') == 1:
            local, domain = cleaned_email.split('@')
            if local and domain:
                result['email'] = cleaned_email

    if 'tags' in record:
        tags = record['tags']
        if not isinstance(tags, (list, tuple)):
            raise TypeError('tags must be a list or tuple')
        seen = set()
        normalized_tags = []
        for tag in tags:
            tag_str = str(tag).strip().lower()
            if not tag_str:
                continue
            if tag_str not in seen:
                seen.add(tag_str)
                normalized_tags.append(tag_str)
        result['tags'] = tuple(normalized_tags)

    return result

def normalize_record(record):
    """
    Normalize a single dictionary describing a person and return a new dictionary.

    :param record: A dictionary with keys "name", "age", "email", and "tags".
    :return: A new dictionary with keys in the exact order and values according to the rules.
    """
    if not isinstance(record, dict):
        raise TypeError("Input must be a dictionary.")

    # Normalize each field
    normalized = {
        "name": record.get("name", "").title(),
        "age": record.get("age", "").strip().isdigit() and int(record.get("age", "").strip()) if record.get("age") else None,
        "email": record.get("email", "").strip().lower(),
        "tags": tuple(record.get("tags", []))
    }

    return normalized

