def parse_spaced_ints(text: str) -> list[int]:
    if text is None:
        raise TypeError("text must be a string")
    if text.strip() == "":
        return []

    result = []
    tokens = text.split()
    for token in tokens:
        if token in {"+", "-"}:
            raise ValueError(f"invalid integer token: {token!r}")

        sign = 1
        digits = token
        if token[0] in "+-":
            sign = -1 if token[0] == "-" else 1
            digits = token[1:]
            if digits == "":
                raise ValueError(f"invalid integer token: {token!r}")

        if not digits.isdigit():
            raise ValueError(f"invalid integer token: {token!r}")
        if len(digits) > 1 and digits[0] == "0":
            raise ValueError(f"invalid integer token: {token!r}")

        result.append(sign * int(digits))
    return result

def normalize_path_segments(path: str) -> str:
    segments = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if segments:
                segments.pop()
            continue
        segments.append(part)
    return '/'.join(segments)

def normalize_inventory_updates(inventory, updates):
    if not isinstance(inventory, dict) or not isinstance(updates, dict):
        raise TypeError("inventory and updates must be dictionaries")

    for k, v in inventory.items():
        if not isinstance(k, str):
            raise TypeError("inventory keys must be strings")
        if not isinstance(v, int):
            raise TypeError("inventory values must be integers")

    for k, v in updates.items():
        if not isinstance(k, str):
            raise TypeError("updates keys must be strings")
        if not isinstance(v, int):
            raise TypeError("updates values must be integers")

    result = dict(inventory)
    for item, delta in updates.items():
        current_stock = result.get(item, 0)
        new_stock = current_stock + delta
        if new_stock < 0:
            raise ValueError("inventory cannot go below zero")
        result[item] = new_stock

    zero_keys = [k for k, v in result.items() if v == 0]
    for k in zero_keys:
        del result[k]

    return result

def normalize_inventory_updates(inventory, updates):
    """
    Normalize the inventory by adding or removing stock based on the given updates.

    Parameters:
    inventory (dict): A dictionary mapping item names to integers stock counts.
    updates (dict): A dictionary mapping item names to integers deltas.

    Returns:
    dict: A dictionary representing the normalized inventory.
    """
    if not isinstance(inventory, dict) or not isinstance(updates, dict):
        raise TypeError("Both inputs must be dictionaries.")

    for item, delta in updates.items():
        if not isinstance(item, str) or not isinstance(delta, int):
            raise TypeError("All keys in inventory and updates must be strings and integers.")

        # Start with a shallow copy of inventory
        new_inventory = inventory.copy()

        # Update stock based on delta
        new_inventory[item] += delta

        # Check if stock goes below zero and raise ValueError if so
        if new_inventory[item] < 0:
            raise ValueError(f"Cannot have negative stock for item: {item}")

        # Remove items with stock equal to zero
        if new_inventory[item] == 0:
            del new_inventory[item]

    return new_inventory

