def compress_runs(text: str, min_run: int) -> str:
    if min_run < 2:
        raise ValueError("min_run must be at least 2")
    if text == "":
        return ""

    result = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            if count >= min_run:
                result.append(current + str(count))
            else:
                result.append(current * count)
            current = ch
            count = 1

    if count >= min_run:
        result.append(current + str(count))
    else:
        result.append(current * count)

    return "".join(result)

def normalize_booking_code(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    cleaned_chars = []
    for ch in code.strip():
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ('0' <= ch <= '9'):
            cleaned_chars.append(ch.upper())
    result = ''.join(cleaned_chars)
    if not result:
        raise ValueError('normalized code is empty')
    if len(result) < 6 or len(result) > 12:
        raise ValueError('normalized code must contain 6 to 12 alphanumeric characters')
    return result

def compress_runs(values):
    if values is None:
        raise TypeError('values must be an iterable of integers')

    result = []
    iterator = iter(values)

    try:
        first = next(iterator)
    except StopIteration:
        return result

    if type(first) is not int:
        raise TypeError('all elements must be integers')

    current_value = first
    current_count = 1

    for item in iterator:
        if type(item) is not int:
            raise TypeError('all elements must be integers')
        if item == current_value:
            current_count += 1
        else:
            result.append((current_value, current_count))
            current_value = item
            current_count = 1

    result.append((current_value, current_count))
    return result

def normalize_priority_events(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")
    selected = {}
    order_index = {}
    for idx, rec in enumerate(events):
        if not isinstance(rec, tuple) or len(rec) != 4:
            raise ValueError("each record must be a 4-tuple")
        category, priority, timestamp, payload = rec
        if not isinstance(category, str) or category == "":
            raise ValueError("category must be a non-empty string")
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError("priority must be an integer")
        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise ValueError("timestamp must be an integer")
        if not isinstance(payload, str):
            raise ValueError("payload must be a string")
        key = (category, priority)
        if key not in selected:
            selected[key] = rec
            order_index[key] = idx
        else:
            cur = selected[key]
            cur_ts = cur[2]
            if timestamp > cur_ts:
                selected[key] = rec
                order_index[key] = idx
            elif timestamp == cur_ts:
                cur_payload = cur[3]
                if payload < cur_payload:
                    selected[key] = rec
                    order_index[key] = idx
                elif payload == cur_payload:
                    pass
    result = list(selected.values())
    result.sort(key=lambda r: (-r[1], r[0]))
    return result

def normalize_priority_events(events):
    """
    Normalize priority events by grouping by category and priority,
    keeping the most recent event for each group.

    :param events: List of tuples (category, priority, timestamp, payload)
    :return: List of normalized event records
    """
    def get_max_timestamp(group):
        return max(record[2] for record in group)

    def get_min_payload(group):
        return min(record[3] for record in group)

    # Group events by category and priority
    grouped = {key: [record for record in events if record[0] == key and record[1] == priority] for key, group in groupby(events, key=lambda x: (x[0], x[1]))}

    # Filter groups to keep only the most recent event for each group
    normalized = []
    for category, group in grouped.items():
        if group:
            max_timestamp_group = get_max_timestamp(group)
            min_payload_group = get_min_payload(group)
            if max_timestamp_group > min_payload_group:
                normalized.append(group[0])

    # Sort the normalized list by priority and category
    normalized.sort(key=lambda x: (-x[1], x[0]))

    return normalized

