def best_price_plan(prices, window):
    if not isinstance(window, int):
        raise TypeError("window must be an integer")
    if window < 0:
        raise ValueError("window must be non-negative")
    n = len(prices)
    if window == 0:
        return 1
    if window > n:
        raise ValueError("window larger than prices length")
    if n == 0:
        raise ValueError("prices cannot be empty when window > 0")

    current_sum = sum(prices[:window])
    min_sum = current_sum
    best_start = 1

    for start in range(1, n - window + 1):
        current_sum += prices[start + window - 1] - prices[start - 1]
        if current_sum < min_sum:
            min_sum = current_sum
            best_start = start + 1
    return best_start

def normalize_inventory(records, rename_map):
    if not isinstance(records, list):
        raise TypeError("records must be a list")
    if not isinstance(rename_map, dict):
        raise TypeError("rename_map must be a dict")

    result = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError("each record must be a dict")
        if 'id' not in record:
            raise ValueError("missing id")

        item_id = record['id']
        name = record.get('name')
        if name in rename_map:
            name = rename_map[name]
        quantity = int(record.get('quantity', 0))
        tags = record.get('tags', [])
        unique_sorted_tags = sorted({str(tag) for tag in tags})

        result.append({
            'id': item_id,
            'name': name,
            'quantity': quantity,
            'tags': unique_sorted_tags,
        })
    return result

def normalize_inventory(records, rename_map):
    """
    Normalize inventory records by mapping old item names to new ones,
    replacing missing values with default values, and sorting tags.

    :param records: List of dictionaries representing inventory items.
    :param rename_map: Dictionary mapping old item names to new ones.
    :return: List of dictionaries with normalized inventory records.
    """
    if not isinstance(records, list):
        raise TypeError("Records must be a list.")
    if not isinstance(rename_map, dict):
        raise TypeError("Rename map must be a dictionary.")

    def normalize_record(record):
        if 'id' not in record:
            raise ValueError("Missing 'id'")
        if 'quantity' not in record:
            record['quantity'] = 0
        if 'tags' not in record:
            record['tags'] = []

        # Replace old item names with new ones
        for old_name, new_name in rename_map.items():
            if old_name in record:
                record[new_name] = record[old_name]

        # Convert quantity to integer
        record['quantity'] = int(record['quantity'])

        # Sort tags
        record['tags'] = sorted(set(record['tags']))

        return record

    return [normalize_record(record) for record in records]

