def normalize_registry(records):
    result = []
    seen = set()
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        name, kind, value = rec
        if not isinstance(name, str) or not isinstance(kind, str):
            continue
        canon_name = name.strip().lower()
        canon_kind = kind.strip().lower()
        if not canon_name or not canon_kind:
            continue
        key = (canon_name, canon_kind)
        if key in seen:
            continue
        seen.add(key)
        if value is None:
            value = "<missing>"
        result.append((canon_name, canon_kind, value))
    return result

def canonicalize_path_tokens(path):
    if isinstance(path, str):
        tokens = path.split('/')
    elif isinstance(path, (list, tuple)):
        tokens = list(path)
    else:
        raise TypeError('path must be a string, list, or tuple')

    result = []
    for token in tokens:
        if token is None:
            continue
        token = str(token).strip()
        if token == '' or token == '.':
            continue
        if token == '..':
            if result:
                result.pop()
            continue
        result.append(token)
    return result

def normalize_cli_command(command: str) -> str:
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    tokens = command.split()
    if not tokens:
        return ""

    def normalize_int_token(token: str) -> str:
        sign = ""
        body = token
        if token[0] in "+-":
            sign = token[0]
            body = token[1:]
        if not body.isdigit():
            return None
        body = body.lstrip("0")
        if body == "":
            body = "0"
        if body == "0":
            return "0"
        if sign == "-":
            return "-" + body
        if sign == "+":
            return body
        return body

    cmd = tokens[0].lower().replace("-", "").replace("_", "")
    normalized = [cmd]

    for token in tokens[1:]:
        maybe_int = normalize_int_token(token)
        if maybe_int is not None:
            normalized.append(maybe_int)
        else:
            normalized.append(token.lower())

    return " ".join(normalized)

def condense_runs(seq):
    out = []
    it = iter(seq)
    try:
        first = next(it)
    except StopIteration:
        return out

    if type(first) is not int:
        raise TypeError("all elements must be integers")

    current_value = first
    current_sum = first

    for x in it:
        if type(x) is not int:
            raise TypeError("all elements must be integers")
        if x == current_value:
            current_sum += x
        else:
            out.append(current_sum)
            current_value = x
            current_sum = x
    out.append(current_sum)
    return out

def compress_segments(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if s == '':
        return ''

    out = []
    current = s[0]
    count = 1

    def encode(ch: str, n: int) -> str:
        prefix = '#' if ch.isdigit() else ''
        if n == 1:
            return f'{prefix}{ch}'
        return f'{prefix}{ch}{n}'

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            out.append(encode(current, count))
            current = ch
            count = 1
    out.append(encode(current, count))
    return ''.join(out)

def normalize_tag_paths(paths):
    if paths is None:
        return []
    result = []
    seen = set()
    for raw in paths:
        if raw is None:
            continue
        s = raw.strip()
        if not s:
            continue
        stack = []
        for part in s.split('/'):
            seg = part.strip()
            if not seg or seg == '.':
                continue
            if seg == '..':
                if stack:
                    stack.pop()
                continue
            stack.append(seg)
        if not stack:
            continue
        normalized = '/'.join(stack)
        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result

def select_nonoverlapping_intervals(intervals):
    valid = []
    for item in intervals:
        try:
            if len(item) != 2:
                continue
            start, end = item[0], item[1]
        except Exception:
            continue
        if isinstance(start, bool) or isinstance(end, bool):
            continue
        if isinstance(start, int) and isinstance(end, int) and start < end:
            valid.append((start, end))

    # Sort by end time, then start time for deterministic greedy processing.
    valid.sort(key=lambda x: (x[1], x[0]))

    # Dynamic programming over sorted intervals to maximize count, then minimize lexicographic result.
    n = len(valid)
    prev = [0] * n
    starts = [iv[0] for iv in valid]
    ends = [iv[1] for iv in valid]
    for i in range(n):
        j = i - 1
        while j >= 0 and ends[j] >= starts[i]:
            j -= 1
        prev[i] = j

    dp_count = [0] * n
    dp_seq = [None] * n

    def best_seq(a, b):
        if a is None:
            return b
        if b is None:
            return a
        if len(a) != len(b):
            return a if len(a) > len(b) else b
        return a if a < b else b

    for i in range(n):
        take_count = 1
        take_seq = (valid[i],)
        if prev[i] >= 0:
            take_count += dp_count[prev[i]]
            take_seq = dp_seq[prev[i]] + (valid[i],)
        skip_count = dp_count[i - 1] if i > 0 else 0
        skip_seq = dp_seq[i - 1] if i > 0 else ()
        if take_count > skip_count:
            dp_count[i] = take_count
            dp_seq[i] = take_seq
        elif take_count < skip_count:
            dp_count[i] = skip_count
            dp_seq[i] = skip_seq
        else:
            chosen = best_seq(take_seq, skip_seq)
            dp_count[i] = take_count
            dp_seq[i] = chosen

    return list(dp_seq[-1]) if n else []

def normalize_path_segments(path: str) -> str:
    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            continue
        stack.append(part)

    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def compress_runs(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if not values:
        return []

    def is_valid_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    for x in values:
        if not is_valid_int(x):
            raise TypeError("all elements must be integers")

    result = []
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.append([current, count])
            current = x
            count = 1
    result.append([current, count])
    return result

def rle_blocks(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if text == '':
        return []
    result = []
    current = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            result.append((current, count))
            current = ch
            count = 1
    result.append((current, count))
    return result

def normalize_event_durations(events, unit='s'):
    valid_units = {'ms', 's', 'min'}
    if unit not in valid_units:
        raise ValueError('invalid unit')

    to_seconds = {'ms': 1 / 1000, 's': 1, 'min': 60}
    from_seconds = {'ms': 1000, 's': 1, 'min': 1 / 60}

    if events is None:
        raise ValueError('invalid events')

    result = []
    for event in events:
        if not isinstance(event, tuple) or len(event) != 3:
            raise ValueError('malformed event')
        name, duration, scale = event
        if not isinstance(name, str):
            raise ValueError('invalid name')
        if scale not in valid_units:
            raise ValueError('invalid scale')
        if not isinstance(duration, (int, float)) or isinstance(duration, bool):
            raise ValueError('invalid duration')
        if duration < 0:
            raise ValueError('negative duration')

        seconds = duration * to_seconds[scale]
        normalized = seconds * from_seconds[unit]

        if isinstance(normalized, float) and normalized.is_integer():
            normalized = int(normalized)
        result.append((name, normalized, unit))
    return result

def normalize_sequence_labels(seq):
    result = []
    prev = object()
    for item in seq:
        if item is None:
            normalized = None
        elif isinstance(item, bool):
            normalized = "true" if item else "false"
        elif isinstance(item, int):
            normalized = f"int:{item}"
        elif isinstance(item, str):
            normalized = item.strip().lower()
            if normalized == "":
                raise ValueError("empty label after normalization")
        else:
            raise TypeError(f"unsupported type: {type(item).__name__}")
        if normalized is None:
            result.append(None)
            prev = object()
        else:
            if normalized != prev:
                result.append(normalized)
                prev = normalized
    return result

def normalize_sequence_labels(seq):
    """
    Normalize sequence labels according to the specified rules.

    Parameters:
    seq (list): A list of labels.

    Returns:
    list: A new list with normalized labels.
    """
    def normalize_label(label):
        if isinstance(label, str):
            return label.strip().lower()
        elif isinstance(label, int):
            return f'int:{label}'
        elif isinstance(label, bool):
            return 'true' if label else 'false'
        else:
            raise TypeError(f"Unsupported type: {type(label)}")

    normalized = []
    for i, label in enumerate(seq):
        if label is None:
            normalized.append(None)
        else:
            normalized.append(normalize_label(label))
    return normalized

