def normalize_sql_identifier(name: str) -> str:
    s = name.strip().lower()
    if not s:
        return "unnamed"

    out = []
    prev_underscore = False
    for ch in s:
        if 'a' <= ch <= 'z' or '0' <= ch <= '9':
            out.append(ch)
            prev_underscore = False
        elif ch.isspace():
            if not prev_underscore:
                out.append('_')
                prev_underscore = True
        elif ch == '_':
            if not prev_underscore:
                out.append('_')
                prev_underscore = True
        else:
            continue

    result = ''.join(out).strip('_')
    return result if result else "unnamed"

def normalize_identifier_parts(parts):
    try:
        iterator = iter(parts)
    except TypeError:
        raise TypeError("parts must be an iterable of strings")

    out = []
    for item in iterator:
        if not isinstance(item, str):
            raise TypeError("parts must be an iterable of strings")
        item = item.strip()
        if not item:
            continue
        for sub in item.split('.'):
            sub = sub.strip()
            if not sub:
                continue
            if not sub[0].isalpha() and sub[0] != '_':
                raise ValueError("invalid identifier fragment")
            for ch in sub:
                if not (ch.isalnum() or ch == '_'):
                    raise ValueError("invalid identifier fragment")
            out.append(sub)
    return '.'.join(out)

def normalize_identifier_parts(parts):
    """
    Normalize a sequence of raw identifier fragments into a normalized dot-separated module path.

    :param parts: An iterable of strings representing identifier fragments.
    :return: A normalized path formed by joining all valid subparts with '.'.
    """
    def is_valid_identifier(subpart):
        if not subpart:
            return False
        if subpart[0] == '.':
            return False
        if not subpart.isalnum():
            return False
        return True

    valid_subparts = [subpart.strip() for part in parts if is_valid_identifier(part)]
    if not valid_subparts:
        return ""

    return ".".join(valid_subparts)

