def apply_piecewise_adjustment(values, rule):
    if not isinstance(rule, tuple) or len(rule) != 3:
        raise TypeError("rule must be a tuple of length 3")
    if any(isinstance(x, bool) or not isinstance(x, int) for x in rule):
        raise TypeError("rule elements must be integers")

    threshold, low_delta, high_delta = rule

    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")

    result = []
    for x in iterator:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("values must contain only integers")
        if x < threshold:
            result.append(x + low_delta)
        else:
            result.append(x + high_delta)
    return result

def normalize_inventory_updates(updates):
    seen_order = []
    latest = {}
    for item in updates:
        if not isinstance(item, tuple) or len(item) != 3:
            continue
        sku, delta, category = item
        if not isinstance(sku, str) or not isinstance(category, str):
            continue
        if not isinstance(delta, int):
            continue
        if sku == '' or category == '':
            continue
        if sku not in latest:
            seen_order.append(sku)
        action = 'add' if delta > 0 else 'remove' if delta < 0 else 'noop'
        latest[sku] = {'sku': sku, 'delta': delta, 'category': category, 'action': action}
    return [latest[sku] for sku in seen_order if sku in latest]

def normalize_inventory_updates(updates):
    """
    Normalize inventory updates by filtering and normalizing the records.

    Parameters:
    updates (iterable of tuples): A list of 3-tuples representing inventory updates.

    Returns:
    list of dictionaries: Normalized records.
    """
    normalized_records = []
    for sku, delta, category in updates:
        if isinstance(sku, str) and isinstance(category, str) and isinstance(delta, int):
            if sku != "" and category != "":
                if delta > 0:
                    action = "add"
                elif delta < 0:
                    action = "remove"
                else:
                    action = "noop"
                normalized_records.append({"sku": sku, "delta": delta, "category": category, "action": action})
    return normalized_records

