def summarize_page_ranges(pages):
    try:
        iterator = iter(pages)
    except TypeError:
        raise TypeError("pages must be iterable")

    unique_pages = set()
    for p in iterator:
        if type(p) is not int:
            raise TypeError("all page identifiers must be integers")
        unique_pages.add(p)

    if not unique_pages:
        return ""

    nums = sorted(unique_pages)
    ranges = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        if start == prev:
            ranges.append(str(start))
        else:
            ranges.append(f"{start}-{prev}")
        start = prev = n

    if start == prev:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}-{prev}")

    return ", ".join(ranges)

def summarize_page_ranges(pages):
    """
    Returns a compact human-readable summary string of page identifiers.

    :param pages: An iterable of integers representing page identifiers.
    :return: A string containing the summary of page ranges.
    """
    if not isinstance(pages, Iterable) or not all(isinstance(page, int) for page in pages):
        raise TypeError("Input must be an iterable of integers.")

    # Remove duplicates by converting to a set and back to a list
    unique_pages = list(set(pages))

    # Sort the unique page numbers in ascending order
    unique_pages.sort()

    # Initialize variables for the result
    result = ""
    start = end = None

    # Iterate through the sorted unique page numbers
    for page in unique_pages:
        if start is None:
            start = page
        elif end is None:
            end = page
        else:
            # If the current page is consecutive to the previous one
            if page - start == 1:
                end = page
            else:
                # If the current page is consecutive to the previous two
                if page - start == 2:
                    result += f"{start}-{end}, "
                else:
                    result += f"{start}-{end}, {start}-{page}"
                start = page
                end = page

    # Add the last group if it exists
    if start is not None:
        result += f"{start}-{end}, "

    return result.strip()

