def encode_ranges(values):
    sentinel = object()
    parts = []
    start = end = sentinel

    def emit(a, b):
        if a == b:
            parts.append(str(a))
        else:
            parts.append(f"{a}-{b}")

    for x in values:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("all elements must be integers")
        if start is sentinel:
            start = end = x
            continue
        if x <= end + 1:
            if x > end:
                end = x
        else:
            emit(start, end)
            start = end = x
    if start is not sentinel:
        emit(start, end)
    return ",".join(parts)

def run_length_merge(s):
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if s == '':
        return '', []

    segments = []
    start = 0
    n = len(s)
    for i in range(1, n + 1):
        if i == n or s[i] != s[start]:
            ch = s[start]
            count = i - start
            segments.append((ch, count))
            start = i

    encoded_parts = []
    for ch, count in segments:
        if count == 1:
            encoded_parts.append(ch)
        else:
            encoded_parts.append(f'{ch}{count}')
    return ''.join(encoded_parts), segments

def trimmed_segment_stats(nums, k):
    if k < 0:
        raise ValueError("k must be non-negative")
    n = len(nums)
    if k > n:
        raise ValueError("k cannot exceed the length of nums")
    start = k
    end = n - k
    if start >= end:
        return (0, 0, None, None)
    segment = nums[start:end]
    count = len(segment)
    total = sum(segment)
    min_value = min(segment)
    max_value = max(segment)
    return (count, total, min_value, max_value)

def canonicalize_alert_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)

    return '/' + '/'.join(parts) if parts else '/'

def stable_bucket_sort(records, key):
    if not callable(key):
        raise TypeError("key must be callable")

    items = list(records)
    if not items:
        return []

    buckets = {}
    order = []
    for item in items:
        k = key(item)
        if k not in buckets:
            buckets[k] = []
            order.append(k)
        buckets[k].append(item)

    # Stable ascending order by key without using sorted() / list.sort()
    unique_keys = order[:]
    n = len(unique_keys)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if unique_keys[j] < unique_keys[min_idx]:
                min_idx = j
        if min_idx != i:
            unique_keys[i], unique_keys[min_idx] = unique_keys[min_idx], unique_keys[i]

    result = []
    for k in unique_keys:
        result.extend(buckets[k])
    return result

def normalize_codec_label(label):
    if not isinstance(label, str):
        raise TypeError("label must be a string")

    s = label.strip().lower()
    if not s:
        raise ValueError("label cannot be empty")

    result = []
    prev_sep = False
    for ch in s:
        if ch.isalnum():
            result.append(ch)
            prev_sep = False
        elif ch in "-_ \t\n\r\v\f":
            if not prev_sep and result:
                result.append('-')
            prev_sep = True
        else:
            raise ValueError("invalid character in label")

    normalized = ''.join(result).strip('-')
    if not normalized:
        raise ValueError("label cannot be empty")

    for ch in normalized:
        if not (ch.isascii() and (ch.isalpha() or ch.isdigit() or ch == '-')):
            raise ValueError("invalid character in label")

    return normalized

def normalize_address_components(components):
    if not isinstance(components, dict):
        raise TypeError('components must be a dictionary')

    def clean(value, upper=False, remove_spaces=False):
        if value is None:
            return ''
        text = str(value)
        text = ' '.join(text.split())
        if remove_spaces:
            text = text.replace(' ', '')
        if upper:
            text = text.upper()
        return text

    out = {}
    for key in ['street', 'city', 'region', 'postal_code', 'country']:
        value = components.get(key)
        if key == 'country':
            out[key] = clean(value, upper=True)
        elif key == 'postal_code':
            out[key] = clean(value, remove_spaces=True)
        else:
            out[key] = clean(value)

    parts = [out[k] for k in ['street', 'city', 'region', 'postal_code', 'country'] if out[k] != '']
    out['label'] = ', '.join(parts)
    return out

def normalize_address_components(components):
    """
    Normalize address-like fields into a canonicalized dictionary.

    Parameters:
    components (dict): A dictionary containing address-like fields.

    Returns:
    dict: A canonicalized dictionary with keys 'street', 'city', 'region', 'postal_code', 'country', 'label'.
    """
    # Check if components is a dictionary
    if not isinstance(components, dict):
        raise TypeError("Input must be a dictionary.")

    # Initialize the label with an empty string
    label = ''

    # Normalize street, city, region, postal_code, country
    for key, value in components.items():
        if value is None or value == '':
            label += ''
        else:
            # Convert to string, strip whitespace, and collapse internal runs
            value = str(value).strip()
            if key == 'country':
                value = value.upper()
            elif key == 'postal_code':
                value = value.replace(' ', '')
            label += value + ', '

    # Remove trailing comma and space, and convert to lowercase
    label = label.rstrip(', ')
    label = label.lower()

    return {'street': label, 'city': label, 'region': label, 'postal_code': label, 'country': label, 'label': label}

