                last[1] = end
        else:
            merged.append([start, end])
    return merged

def stable_group_sort(items, priorities):
    priority_order = {}
    ordered_labels = []
    for label in priorities:
        if label not in priority_order:
            priority_order[label] = len(ordered_labels)
            ordered_labels.append(label)

    groups = {label: [] for label in ordered_labels}
    remainder = []

    for item in items:
        if item in priority_order:
            groups[item].append(item)
        else:
            remainder.append(item)

    result = []
    for label in ordered_labels:
        result.extend(groups[label])
    result.extend(remainder)
    return result

def interval_multiset_signature(intervals):
    try:
        items = list(intervals)
    except TypeError:
        raise TypeError("intervals must be iterable")

    counts = {}
    for pair in items:
        try:
            a, b = pair
        except Exception:
            raise TypeError("each interval must be a length-2 iterable")
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        start, end = (a, b) if a <= b else (b, a)
        for v in range(start, end + 1):
            counts[v] = counts.get(v, 0) + 1
    return sorted(counts.items())

def summarize_routes(routes):
    out_degree = {}
    in_degree = {}

    for route in routes:
        try:
            src, dst = route
        except Exception as e:
            raise ValueError("each route must be a 2-item iterable") from e

        if not isinstance(src, str) or not isinstance(dst, str):
            raise ValueError("route endpoints must be strings")

        src = src.strip()
        dst = dst.strip()
        if not src or not dst:
            raise ValueError("route endpoints must be non-empty after stripping")

        if src == dst:
            continue

        out_degree[src] = out_degree.get(src, 0) + 1
        in_degree[dst] = in_degree.get(dst, 0) + 1
        out_degree.setdefault(dst, out_degree.get(dst, 0))
        in_degree.setdefault(src, in_degree.get(src, 0))

    nodes = sorted(set(out_degree) | set(in_degree))
    out_degree = {node: out_degree.get(node, 0) for node in nodes}
    in_degree = {node: in_degree.get(node, 0) for node in nodes}

    sinks = sorted([node for node in nodes if out_degree[node] == 0 and in_degree[node] > 0])
    sources = sorted([node for node in nodes if in_degree[node] == 0 and out_degree[node] > 0])

    return {
        "nodes": len(nodes),
        "out_degree": out_degree,
        "in_degree": in_degree,
        "sinks": sinks,
        "sources": sources,
        "isolated": [],
    }

