from datetime import datetime


def normalize_alarm_events(events):
    normalized = []
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        timestamp, severity, code = record
        if not isinstance(timestamp, str):
            continue
        try:
            dt = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
        except Exception:
            continue
        if not isinstance(severity, int) or isinstance(severity, bool) or severity < 1 or severity > 5:
            continue
        if not isinstance(code, str):
            continue
        cleaned_code = code.strip()
        if not cleaned_code:
            continue
        normalized_ts = dt.strftime("%Y%m%dT%H%M")
        normalized.append((dt, severity, cleaned_code.upper(), f"{normalized_ts}|S{severity}|{cleaned_code.upper()}"))
    normalized.sort(key=lambda x: (x[0], -x[1], x[2]))
    return [item[3] for item in normalized]

def normalize_section_order(sections):
    if not isinstance(sections, list):
        raise TypeError('sections must be a list')
    result = []
    seen = set()
    for item in sections:
        if not isinstance(item, str):
            raise TypeError('all items must be strings')
        normalized = ' '.join(item.strip().lower().split())
        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result

def normalize_schedule(intervals, *, inclusive=False):
    if not isinstance(intervals, list):
        raise TypeError('intervals must be a list')
    normalized = []
    for item in intervals:
        try:
            start, end = item
        except Exception:
            raise TypeError('each interval must be a 2-item iterable of integers')
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('each interval must be a 2-item iterable of integers')
        if start > end:
            raise ValueError('interval start must be <= end')
        normalized.append((start, end))
    if not normalized:
        return []
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        should_merge = start <= last_end or (inclusive and start == last_end + 1)
        if should_merge:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def normalize_acl_rules(rules):
