        principal, action, resource = rule
        if not isinstance(principal, str) or not isinstance(action, str) or not isinstance(resource, str):
            raise TypeError("all rule fields must be strings")

        norm_rule = (
            principal.strip().lower(),
            action.strip().lower(),
            resource.strip().upper(),
        )

        if norm_rule not in seen:
            seen.add(norm_rule)
            normalized.append(norm_rule)

    normalized.sort(key=lambda x: (x[0], x[1], x[2]))
    return normalized

