def merge_interval_schedules(schedule_a, schedule_b):
    def validate(schedule):
        validated = []
        for interval in schedule:
            if not hasattr(interval, '__len__') or len(interval) != 2:
                raise ValueError('Each interval must have exactly two items')
            start, end = interval
            if not isinstance(start, int) or not isinstance(end, int):
                raise ValueError('Interval endpoints must be integers')
            if start > end:
                raise ValueError('Interval start must be <= end')
            validated.append((start, end))
        return validated

    intervals = validate(schedule_a) + validate(schedule_b)
    if not intervals:
        return []

    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged

