    if not cleaned:
        return []

    cleaned.sort(key=lambda x: (x[2], x[0], x[1]))
    merged_by_value = []

    current_start, current_end, current_value = cleaned[0]
    for start, end, value in cleaned[1:]:
        if value == current_value and start <= current_end:
            if end > current_end:
                current_end = end
        else:
            merged_by_value.append((current_start, current_end, current_value))
            current_start, current_end, current_value = start, end, value
