def normalize_call_history(entries):
    if not isinstance(entries, list):
        raise ValueError('entries must be a list')

    validated = []
    for idx, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError('each entry must be a 3-tuple')
        timestamp, event_type, payload = entry
        if not isinstance(timestamp, (int, float)):
            raise ValueError('invalid timestamp')
        if isinstance(timestamp, bool):
            raise ValueError('invalid timestamp')
        if not isinstance(event_type, str):
            raise ValueError('invalid event_type')
        if not event_type or any(not (c.isalnum() or c == '_') or ord(c) > 127 for c in event_type):
            raise ValueError('invalid event_type')
        if not isinstance(payload, str):
            raise ValueError('invalid payload')
        validated.append((timestamp, idx, event_type, payload))

    if not validated:
        return ''

    validated.sort(key=lambda x: (x[0], x[1]))

    def fmt_ts(ts):
        if isinstance(ts, bool):
            raise ValueError('invalid timestamp')
        if isinstance(ts, int):
            return str(ts)
        if float(ts).is_integer():
            return str(int(ts))
        s = str(float(ts))
        return s

    collapsed = []
    for ts, _, et, payload in validated:
        if not collapsed:
            collapsed.append([ts, et, payload])
            continue
        prev_ts, prev_et, prev_payload = collapsed[-1]
        if et == prev_et and payload == prev_payload and abs(float(ts) - float(prev_ts)) <= 0.5:
            continue
        collapsed.append([ts, et, payload])

    return '|'.join(f"{fmt_ts(ts)}:{et}:{payload}" for ts, et, payload in collapsed)

def ranked_window_sums(nums, window_size, top_k):
    if not isinstance(nums, list):
        raise TypeError("nums must be a list")
    if not isinstance(window_size, int):
        raise TypeError("window_size must be an int")
    if not isinstance(top_k, int):
        raise TypeError("top_k must be an int")
    if window_size <= 0:
        raise ValueError("window_size must be greater than 0")
    if top_k < 0:
        raise ValueError("top_k must be non-negative")
    for x in nums:
        if not isinstance(x, int):
            raise TypeError("all nums elements must be int")
    n = len(nums)
    if top_k == 0 or window_size > n:
        return []
    window_sums = []
    current = sum(nums[:window_size])
    window_sums.append((0, current))
    for i in range(window_size, n):
        current += nums[i] - nums[i - window_size]
        window_sums.append((i - window_size + 1, current))
    window_sums.sort(key=lambda item: (-item[1], item[0]))
    return window_sums[:top_k]

def normalize_command_sequence(commands):
