        if token == "":
            raise ValueError("empty command token")
        if token == ".":
            continue
        if token == "..":
            if kept:
                kept.pop()
            continue
        kept.append(token)
    return "/".join(kept)

def normalize_command_sequence(commands):
    """
    Normalize a sequence of text command tokens according to specific rules.

    Parameters:
    commands (iterable of str): An iterable of strings representing command tokens.

    Returns:
    str: A single string consisting of the kept normal command tokens joined by '/'.
    """
    if not isinstance(commands, iter):
        raise TypeError("commands must be an iterable")
    if not all(isinstance(token, str) for token in commands):
        raise TypeError("all elements in commands must be strings")
    if any(token == '.' for token in commands):
        return ''

    # Initialize a list to store normal command tokens
    normal_tokens = []

    # Iterate over each command token
    for token in commands:
        if token == '.':
            continue  # Ignore '.' tokens
        elif token == '..':
            # Remove the most recent kept normal command token
            if normal_tokens:
                normal_tokens.pop()
            else:
                continue  # Ignore '..' tokens if no previous normal command was found
        else:
            normal_tokens.append(token)

    # Join the normal command tokens with '/'
    return '/'.join(normal_tokens)

