def split_runs(text: str, delimiter: str) -> list[tuple[str, int]]:
    if delimiter == '':
        raise ValueError('delimiter must be non-empty')
    parts = text.split(delimiter)
    if not parts:
        return []
    result = []
    current = parts[0]
    count = 1
    for part in parts[1:]:
        if part == current:
            count += 1
        else:
            result.append((current, count))
            current = part
            count = 1
    result.append((current, count))
    return result

def normalize_inventory(records):
