def normalize_inventory(records):
    """
    Normalize a list of inventory records into a dictionary mapping warehouses to lists of (sku, total_quantity) tuples.

    Parameters:
    records (list of tuples): A list of tuples, each representing an inventory record (warehouse, sku, quantity).

    Returns:
    dict: A dictionary where keys are warehouse names and values are lists of (sku, total_quantity) tuples.
    """
    # Check if records is empty
    if not records:
        return {}

    # Initialize an empty dictionary to store normalized inventory
    normalized = {}

    # Iterate over each record in the input list
    for record in records:
        # Extract warehouse, SKU, and quantity from the record
        warehouse, sku, quantity = record

        # Check if the record is exactly 3 items long
        if len(record) != 3:
            raise ValueError("Each record must be exactly 3 items.")

        # Check if warehouse or SKU is not a non-empty string
        if not warehouse or not sku:
            raise ValueError("Warehouse and SKU must be non-empty strings.")

        # Check if quantity is an integer
        if not isinstance(quantity, int):
            raise ValueError("Quantity must be an integer.")

        # If the warehouse is already in the dictionary, append the (SKU, total_quantity)
        if warehouse in normalized:
            normalized[warehouse].append((sku, quantity))
        else:
            # Otherwise, add the warehouse with a list containing the (SKU, total_quantity)
            normalized[warehouse] = [(sku, quantity)]

    # Sort the list of (sku, total_quantity) tuples by SKU in ascending lexicographic order
    normalized = {warehouse: sorted(tup) for warehouse, tup in normalized.items()}

    return normalized

