def plan_axis_moves(start, target, blocked):
    def validate_point(p, name):
        if not isinstance(p, tuple) or len(p) != 2:
            raise TypeError(f"{name} must be a 2-tuple of integers")
        x, y = p
        if not isinstance(x, int) or not isinstance(y, int):
            raise TypeError(f"{name} must be a 2-tuple of integers")
        return x, y

    sx, sy = validate_point(start, "start")
    tx, ty = validate_point(target, "target")

    blocked_set = set()
    for b in blocked:
        bx, by = validate_point(b, "blocked")
        blocked_set.add((bx, by))

    if (sx, sy) in blocked_set or (tx, ty) in blocked_set:
        return None
    if (sx, sy) == (tx, ty):
        return 0

    # On an unbounded grid with unit orthogonal moves, the shortest path exists
    # iff neither endpoint is blocked, and its length is Manhattan distance.
    return abs(sx - tx) + abs(sy - ty)

def summarize_runs(stream):
    try:
        iterator = iter(stream)
    except TypeError:
        raise TypeError("stream must be an iterable of integers")

    try:
        first = next(iterator)
    except StopIteration:
        return {'run_count': 0, 'max_run_length': 0, 'first_values': [], 'transitions': 0}

    if not isinstance(first, int):
        raise TypeError("all elements must be integers")

    run_count = 1
    max_run_length = 1
    first_values = [first]
    transitions = 0
    current_value = first
    current_run_length = 1

    for value in iterator:
        if not isinstance(value, int):
            raise TypeError("all elements must be integers")
        if value == current_value:
            current_run_length += 1
        else:
            transitions += 1
            run_count += 1
            first_values.append(value)
            if current_run_length > max_run_length:
                max_run_length = current_run_length
            current_value = value
            current_run_length = 1

    if current_run_length > max_run_length:
        max_run_length = current_run_length

    return {
        'run_count': run_count,
        'max_run_length': max_run_length,
        'first_values': first_values,
        'transitions': transitions,
    }

def normalize_inventory(events):
    inventory = {}
    for event in events:
        if not isinstance(event, tuple) or len(event) != 3:
            raise ValueError('Malformed event')
        action, item, amount = event
        if action not in ('add', 'remove'):
            raise ValueError('Malformed event')
        if not isinstance(item, str) or item == '':
            raise ValueError('Malformed event')
        if not isinstance(amount, int):
            raise ValueError('Malformed event')
        current = inventory.get(item, 0)
        if action == 'add':
            new_value = current + amount
        else:
            new_value = current - amount
        if new_value < 0:
            raise ValueError('Negative inventory')
        if new_value == 0:
            inventory.pop(item, None)
        else:
            inventory[item] = new_value
    return inventory

