    try:
        current = date.fromisoformat(start_date)
    except Exception as e:
        raise ValueError("start_date must be a valid ISO date") from e

    result = []
    for interval in intervals:
        if not isinstance(interval, (tuple, list)) or len(interval) != 2:
            raise TypeError("each interval must be a 2-item tuple/list")
        amount, unit = interval
        if not isinstance(amount, int):
            raise TypeError("amount must be an integer")
        if unit not in ('D', 'W', 'M'):
            raise ValueError("unit must be one of 'D', 'W', 'M'")

        if unit == 'D':
            current = current + timedelta(days=amount)
        elif unit == 'W':
            current = current + timedelta(weeks=amount)
        else:
            year = current.year
            month = current.month + amount
            year += (month - 1) // 12
            month = (month - 1) % 12 + 1
            day = min(current.day, calendar.monthrange(year, month)[1])
            current = date(year, month, day)

        result.append(current.isoformat())
    return result

def merge_intervals_with_labels(intervals):
    groups = {}
    for item in intervals:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError("Each interval must be a 3-tuple")
        start, end, label = item
        if start >= end:
            continue
        groups.setdefault(label, []).append((start, end))

    result = []
    for label in sorted(groups, key=lambda x: x):
        spans = sorted(groups[label])
        merged = []
        for start, end in spans:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                if end > merged[-1][1]:
                    merged[-1][1] = end
        for start, end in merged:
            result.append((start, end, label))
    return result

def normalize_item_weights(items):
    try:
        iterator = iter(items)
    except TypeError:
        raise ValueError("items must be iterable")

    records = []
    total = 0
    for record in iterator:
        if not isinstance(record, tuple) or len(record) != 2:
            raise ValueError("each item must be a 2-tuple")
        name, weight = record
        if not isinstance(name, str) or not name or not all(ch.isalnum() or ch == '_' for ch in name):
            raise ValueError("invalid name")
        if not isinstance(weight, int) or isinstance(weight, bool) or weight < 0:
            raise ValueError("invalid weight")
        records.append((name, weight))
        total += weight

    if total == 0:
        raise ValueError("total weight must be positive")

    return [(name, weight / total) for name, weight in records]

def normalize_step_sequence(steps):
    try:
        iterator = iter(steps)
    except TypeError:
        raise TypeError("steps must be iterable")

    merged = {}
    order = []

    for item in iterator:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each item must be a 2-tuple")
        name, action = item
        if not isinstance(name, str):
            raise TypeError("step name must be a string")
        if action is not None and not isinstance(action, str):
            raise TypeError("action must be a string or None")

        trimmed_name = name.strip()
        if trimmed_name == "":
            continue

        normalized_action = "" if action is None else action.strip()
        key = trimmed_name.lower()

        if key not in merged:
            merged[key] = [trimmed_name, [normalized_action]]
            order.append(key)
        else:
            merged[key][1].append(normalized_action)

    result = []
    for key in order:
        name, actions = merged[key]
        result.append((name, ";".join(actions)))
    return result

def normalize_step_sequence(steps):
    """
    Normalize a sequence of step descriptions for a simple text-based workflow.

    Parameters:
    steps (iterable of tuples): A list of tuples, where each tuple contains a step name and an action.

    Returns:
    list of tuples: A list of tuples, where each tuple contains a step name and an action.
    """
    def normalize_action(action):
        if action is None:
            return ""
        else:
            return action.strip()

    def merge_duplicates(step_names):
        seen = set()
        result = []
        for name, action in step_names:
            if name in seen:
                result.append(f"{name};{action}")
            else:
                seen.add(name)
                result.append((name, action))
        return result

    def normalize_name(name):
        return name.strip().title()

    def normalize_steps(steps):
        return [normalize_name(name) for name, action in steps]

    # Normalize each step
    normalized_steps = normalize_steps(steps)

    # Merge duplicates
    merged_steps = merge_duplicates(normalized_steps)

    # Prepare the output
    output = []
    for name, action in merged_steps:
        output.append((name, normalize_action(action)))

    return output

