def compress_ranges(nums):
    """Return a compact range string for distinct sorted integers in nums."""
    if not nums:
        return ""

    values = sorted(set(nums))
    parts = []

    start = prev = values[0]
    for x in values[1:]:
        if x == prev + 1:
            prev = x
            continue

        if start == prev:
            parts.append(str(start))
        else:
            parts.append(f"{start}-{prev}")
        start = prev = x

    if start == prev:
        parts.append(str(start))
    else:
        parts.append(f"{start}-{prev}")

    return ",".join(parts)

def normalize_call_tree(edges):
    valid = {}
