            continue
        caller, callee = item
        if not isinstance(caller, str) or not isinstance(callee, str):
            continue
        if caller == callee:
            continue
        valid.setdefault(caller, set()).add(callee)
    result = {}
    for caller in sorted(valid):
        result[caller] = sorted(valid[caller])
    return result

