def longest_stable_run(s: str, k: int) -> int:
    if not isinstance(s, str):
        raise ValueError('s must be a string')
    if not isinstance(k, int) or isinstance(k, bool) or k < 0:
        raise ValueError('k must be a non-negative integer')
    if any(ch < '0' or ch > '9' for ch in s):
        raise ValueError('s must contain only decimal digits')
    n = len(s)
    if n == 0:
        return 0
    if k >= n:
        return n

    best = 0
    for digit in '0123456789':
        left = 0
        mismatches = 0
        for right, ch in enumerate(s):
            if ch != digit:
                mismatches += 1
            while mismatches > k:
                if s[left] != digit:
                    mismatches -= 1
                left += 1
            current_len = right - left + 1
            if current_len > best:
                best = current_len
    return best

def normalize_event_log(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    result = []
    seen = set()
    for event in events:
        if not isinstance(event, str):
            raise TypeError('all events must be strings')
        if event.strip() == '':
            raise ValueError('empty event')
        parts = event.split(':')
        if len(parts) not in (2, 3):
            raise ValueError('malformed event')
        user = parts[0].strip()
        action = parts[1].strip()
        if user == '' or action == '':
            raise ValueError('empty user or action')
        normalized = f"{user.lower()}:{action.upper()}"
        if len(parts) == 3:
            payload = parts[2].strip()
            normalized = f"{normalized}:{payload}"
        if normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result

def normalize_query_params(params):
    if type(params) is not dict:
        raise TypeError("params must be a dict")

    def normalize_value(value):
        if value is None:
            return ''
        if type(value) is str:
            return value
        if type(value) is int or type(value) is bool:
            return str(value)
        if type(value) is list or type(value) is tuple:
            parts = []
            for item in value:
                parts.append(normalize_value(item))
            return ','.join(parts)
        raise TypeError("unsupported value type")

    normalized_items = []
    for key in sorted(params.keys()):
        if type(key) is not str:
            raise TypeError("keys must be strings")
        normalized_items.append((key, normalize_value(params[key])))
    return tuple(normalized_items)

def normalize_query_params(params):
    """
    Normalize a mapping of query-parameter names to values into a deterministic,
    normalized tuple of (key, value) pairs.

    Parameters:
    params (dict): A dictionary-like mapping of query-parameter names to values.

    Returns:
    tuple: A tuple of pairs sorted by key in ascending lexicographic order.
    """
    if not isinstance(params, dict):
        raise TypeError("Input must be a dictionary-like mapping.")

    # Helper function to normalize a single value
    def normalize_value(value):
        if value is None:
            return ''
        elif isinstance(value, str):
            return value
        elif isinstance(value, int) or isinstance(value, bool):
            return str(value)
        elif isinstance(value, list) or isinstance(value, tuple):
            return ','.join(normalize_value(item) for item in value)
        else:
            raise TypeError(f"Unsupported value type: {type(value)}")

    # Normalize all values in the dictionary
    normalized_params = {key: normalize_value(value) for key, value in params.items()}

    # Sort the normalized parameters by key in ascending lexicographic order
    normalized_params_sorted = sorted(normalized_params.items(), key=lambda x: x[0])

    return normalized_params_sorted

