def merge_interval_maps(map_a, map_b):
    def validate_map(m):
        for item in m:
            if not isinstance(item, tuple) or len(item) != 3:
                raise ValueError("Each interval must be a 3-tuple")
            start, end, label = item
            if not isinstance(start, int) or not isinstance(end, int):
                raise ValueError("Interval endpoints must be integers")
            if start >= end:
                raise ValueError("Interval must satisfy start < end")
            if not isinstance(label, str):
                raise ValueError("Label must be a string")

    validate_map(map_a)
    validate_map(map_b)

    events = []
    for start, end, label in map_a:
        events.append((start, 1, 'a_add', label))
        events.append((end, 1, 'a_remove', label))
    for start, end, label in map_b:
        events.append((start, 1, 'b_add', label))
        events.append((end, 1, 'b_remove', label))

    points = sorted(set([x for x, _, _, _ in events]))
    if not points:
        return []

    def active_label_for(intervals, x):
        labels = [label for s, e, label in intervals if s <= x < e]
        unique = set(labels)
        if len(unique) > 1:
            raise ValueError("Conflicting overlaps within a map")
        return next(iter(unique)) if unique else None

    result = []
    all_segments = sorted(set([p for ivs in (map_a, map_b) for seg in ivs for p in seg[:2]]))
    if len(all_segments) < 2:
        return []
    for i in range(len(all_segments) - 1):
        s, e = all_segments[i], all_segments[i + 1]
        if s == e:
            continue
        la = active_label_for(map_a, s)
        lb = active_label_for(map_b, s)
        if la is None and lb is None:
            continue
        if la is None:
            lab = lb
        elif lb is None:
            lab = la
        elif la == lb:
            lab = la
        else:
            lab = f"{la}|{lb}"
        if result and result[-1][2] == lab and result[-1][1] == s:
            result[-1] = (result[-1][0], e, lab)
        else:
            result.append((s, e, lab))
    return result

def compress_ranges(nums):
    if not nums:
        return ""
    unique_sorted = sorted(set(nums))
    parts = []
    start = prev = unique_sorted[0]
    for x in unique_sorted[1:]:
        if x == prev + 1:
            prev = x
        else:
            parts.append(f"{start}" if start == prev else f"{start}-{prev}")
            start = prev = x
    parts.append(f"{start}" if start == prev else f"{start}-{prev}")
    return ",".join(parts)

def compress_segments(data):
    if not isinstance(data, list):
        raise TypeError("data must be a list")
    if len(data) == 0:
        return []

    for x in data:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("all elements must be integers")

    result = []
    current = data[0]
    count = 1

    for x in data[1:]:
        if x == current:
            count += 1
        else:
            if count == 1:
                result.append(current)
            else:
                result.append((current, count))
            current = x
            count = 1

    if count == 1:
        result.append(current)
    else:
        result.append((current, count))

    return result

def normalize_inventory_changes(entries):
    totals = {}
    for record in entries:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        product, location, delta = record
        if not isinstance(product, str) or not isinstance(location, str) or not isinstance(delta, int):
            continue
        key = (product, location)
        totals[key] = totals.get(key, 0) + delta
    return [(product, location, totals[(product, location)]) for product, location in sorted(totals)]

def normalize_measurements(records):
    seen = set()
    valid = []
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 2:
            continue
        label, value = rec
        if not isinstance(label, str) or label.strip() == "":
            continue
        if value is None:
            continue
        if not isinstance(value, (int, float)):
            continue
        if label in seen:
            continue
        seen.add(label)
        valid.append((label, float(value)))
    valid.sort(key=lambda x: (len(x[0]), x[0]))
    return valid

def normalize_slack_schedule(lines):
    import re

    day_map = {
        'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
        'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
    }
    day_pattern = re.compile(r'\b(mon|tue|wed|thu|fri|sat|sun)\b', re.IGNORECASE)
    time_pattern = re.compile(r'\b(\d{2}):(\d{2})-(\d{2}):(\d{2})\b')

    result = []
    seen = set()

    for line in lines:
        if not isinstance(line, str):
            continue
        day_match = day_pattern.search(line)
        time_match = time_pattern.search(line)
        if not day_match or not time_match:
            continue

        day = day_map[day_match.group(1).lower()]
        sh, sm, eh, em = map(int, time_match.groups())
        if not (0 <= sh <= 23 and 0 <= eh <= 23 and 0 <= sm <= 59 and 0 <= em <= 59):
            continue
        start = sh * 60 + sm
        end = eh * 60 + em
        if start >= end:
            continue

        slot = f"{day} {sh:02d}:{sm:02d}-{eh:02d}:{em:02d}"
        if slot not in seen:
            seen.add(slot)
            result.append(slot)

    return result

def decode_run_lengths(data):
    if isinstance(data, str):
        if data.strip() == "":
            return []
        result = []
        tokens = data.split()
        for token in tokens:
            if token.count(":") != 1:
                raise ValueError("invalid token format")
            left, right = token.split(":")
            if left == "" or right == "":
                raise ValueError("invalid token format")
            try:
                count = int(left)
                value = int(right)
            except Exception:
                raise ValueError("invalid integer")
            if count < 0:
                raise ValueError("negative count")
            result.extend([value] * count)
        return result
    if isinstance(data, list):
        if len(data) == 0:
            return []
        if len(data) % 2 != 0:
            raise ValueError("list must have even length")
        result = []
        for i in range(0, len(data), 2):
            count = data[i]
            value = data[i + 1]
            if not isinstance(count, int) or not isinstance(value, int):
                raise ValueError("list elements must be integers")
            if count < 0:
                raise ValueError("negative count")
            result.extend([value] * count)
        return result
    raise ValueError("unsupported type")

def run_length_encode_deltas(seq):
    try:
        items = list(seq)
    except TypeError:
        raise TypeError('seq must be iterable')

    for x in items:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')

    if len(items) < 2:
        return []

    diffs = [items[i] - items[i - 1] for i in range(1, len(items))]
    result = []
    current = diffs[0]
    count = 1

    for d in diffs[1:]:
        if d == current:
            count += 1
        else:
            result.append((current, count))
            current = d
            count = 1

    result.append((current, count))
    return result

