            continue
        name = a.strip()
        value = b.strip()
        if not name:
            continue
        cleaned.append((name.lower(), value))

    last_index = {}
    for idx, (name, value) in enumerate(cleaned):
        last_index[name] = idx

    result = []
    for idx, (name, value) in enumerate(cleaned):
        if last_index[name] == idx:
            result.append([name, value])
    return result

def normalize_inventory_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    totals = {}
    order = {}
    next_index = 0

    for rec in entries:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            raise TypeError('each record must be a 3-item sequence')
        item_id, delta, location = rec
        if not isinstance(item_id, str) or not isinstance(location, str):
            raise TypeError('item_id and location must be strings')
        if item_id == '' or location == '':
            raise ValueError('item_id and location must be non-empty strings')
        if not isinstance(delta, int) or isinstance(delta, bool):
            raise TypeError('delta must be an integer')

        key = (item_id, location)
        if key not in totals:
            totals[key] = 0
            order[key] = next_index
            next_index += 1
        totals[key] += delta

    result = [(item_id, location, total) for (item_id, location), total in totals.items() if total != 0]
    result.sort(key=lambda x: (x[0], x[1]))
    return result

def canonicalize_inventory_changes(changes):
    totals = {}
    for record in changes:
        try:
            item_id, delta = record
        except Exception:
            raise ValueError("each record must be a 2-item iterable")
        if not isinstance(item_id, str):
            raise ValueError("item_id must be a string")
        if not isinstance(delta, int):
            raise ValueError("delta must be an int")
        normalized = item_id.strip().lower()
        if normalized == "":
            raise ValueError("item_id cannot be empty after normalization")
        totals[normalized] = totals.get(normalized, 0) + delta
    result = [(item_id, net_delta) for item_id, net_delta in totals.items() if net_delta != 0]
    result.sort(key=lambda pair: (-abs(pair[1]), pair[0]))
    return result

def canonicalize_inventory_changes(changes):
    """
    Normalize a list of inventory adjustment records.

    Each record is a 2-item iterable (item_id, delta) where item_id is a non-empty string and delta is an integer.
    The function processes the records in order and returns a new list of (item_id, net_delta) tuples with these rules:

    1. item_id strings are normalized by stripping leading and trailing whitespace and converting to lowercase.
    2. Records with a normalized `item_id` of the empty string are invalid.
    3. Records with a `delta` that is not an `int` are invalid.
    4. If any record is invalid, raise ValueError.
    5. For valid records, combine all entries with the same normalized `item_id` by summing their deltas.
    6. In the returned list, keep only items whose summed delta is not zero.
    7. Sort the result by descending absolute value of `net_delta`; break ties by ascending `item_id` alphabetically.
    8. The function must accept any iterable of records, but it must return a list.

    Examples:
    >>> canonicalize_inventory_changes([(' A ', 2), ('a', -1), ('b', 3)])
    [('b', 3), ('a', 1)]
    >>> canonicalize_inventory_changes([('x', 5), ('X', -5)])
    []
    """
    def normalize_item_id(item_id):
        return item_id.strip().lower()

    def validate_record(record):
        if not isinstance(record, tuple) or len(record) != 2:
            raise ValueError("Invalid record format")
        item_id, delta = record
        if not isinstance(item_id, str) or not item_id.strip():
            raise ValueError("Invalid item_id")
        if not isinstance(delta, int):
            raise ValueError("Invalid delta")
        return item_id, delta

    valid_records = [record for record in changes if validate_record(record)]

    def sum_deltas(records):
        return sum(record[1] for record in records)

    def normalize_and_sum(records):
        normalized_records = [(normalize_item_id(item_id), sum_deltas(records)) for item_id, delta in valid_records]
        return sorted(normalized_records, key=lambda x: (-abs(x[1]), x[0]))

    return normalize_and_sum(valid_records)

