def summarize_shelf(records):
    active = set()
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError('each record must be a 3-tuple')
        shelf_id, book_code, status = rec
        if status not in ('placed', 'removed'):
            raise ValueError('invalid status')
        key = (shelf_id, book_code)
        if status == 'placed':
            active.add(key)
        else:
            active.discard(key)
    active_list = sorted(active)
    counts = {}
    for shelf_id, book_code in active_list:
        counts[shelf_id] = counts.get(shelf_id, 0) + 1
    return {'active': active_list, 'counts': counts}

def summarize_shelf(records):
    """
    Analyzes a sequence of library shelf placement records and returns a dictionary
    with two keys: 'active' and 'counts'. The 'active' list contains tuples
    (shelf_id, book_code) representing books currently on shelves after processing
    the records in order. The 'counts' dictionary maps each shelf_id to the
    number of books currently active on that shelf.

    Parameters:
    records (iterable): A collection of 3-tuples representing shelf placement records.

    Returns:
    dict: A dictionary with 'active' and 'counts' keys.
    """
    active_books = set()
    counts = {}

    for shelf_id, book_code, status in records:
        if not isinstance(shelf_id, str) or not isinstance(book_code, str) or not isinstance(status, str):
            raise ValueError("All records must be tuples of strings.")

        if status == 'placed':
            active_books.add((shelf_id, book_code))
        elif status == 'removed':
            if (shelf_id, book_code) in active_books:
                active_books.remove((shelf_id, book_code))
            else:
                raise ValueError("Book not found on this shelf.")

        # Sort by shelf_id and then by book_code
        active_books.sort(key=lambda x: (x[0], x[1]))

    return {'active': list(active_books), 'counts': counts}

