def compress_ranges(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    unique = []
    seen = set()
    for x in values:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if x not in seen:
            seen.add(x)
            unique.append(x)

    if not unique:
        return ""

    nums = sorted(unique)
    parts = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        length = prev - start + 1
        if length >= 3:
            parts.append(f"{start}-{prev}")
        else:
            parts.extend(str(i) for i in range(start, prev + 1))
        start = prev = n

    length = prev - start + 1
    if length >= 3:
        parts.append(f"{start}-{prev}")
