def longest_balanced_block(s: str, open_char: str, close_char: str) -> int:
    if not isinstance(open_char, str) or not isinstance(close_char, str):
        raise ValueError("open_char and close_char must be strings")
    if len(open_char) != 1 or len(close_char) != 1:
        raise ValueError("open_char and close_char must be single-character strings")
    if open_char == close_char:
        return 0

    best = 0
    n = len(s)
    i = 0
    while i < n:
        if s[i] != open_char and s[i] != close_char:
            i += 1
            continue

        # Consider each maximal segment consisting only of open_char/close_char.
        j = i
        while j < n and (s[j] == open_char or s[j] == close_char):
            j += 1

        # Scan all substrings within [i, j) using prefix balance constraints.
        for start in range(i, j):
            balance = 0
            closes = 0
            for end in range(start, j):
                ch = s[end]
                if ch == open_char:
                    balance += 1
                elif ch == close_char:
                    balance -= 1
                    closes += 1
                else:
                    break

                if balance < 0:
                    break
                if balance == 0 and closes > 0:
                    best = max(best, end - start + 1)

        i = j + 1
    return best

