    result = []
    for item in items:
        if not isinstance(item, str):
            raise ValueError('all items must be strings')
        if item == '':
            raise ValueError('empty string is invalid')
        suffix = item[-1]
        if suffix not in ('s', 'm', 'h'):
            raise ValueError('invalid suffix')
        num_part = item[:-1]
        if num_part == '':
            raise ValueError('missing numeric part')
        if num_part[0] == '-':
            raise ValueError('negative values are invalid')
        if not num_part.isdigit():
            raise ValueError('invalid numeric part')
        value = int(num_part)
        seconds = value
        if suffix == 'm':
            seconds = value * 60
        elif suffix == 'h':
            seconds = value * 3600
        if seconds % 3600 == 0:
            result.append(f'{seconds // 3600}h')
        elif seconds % 60 == 0:
            result.append(f'{seconds // 60}m')
        else:
            result.append(f'{seconds}s')
    return result

