def summarize_runs(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if s == "":
        return {"count": 0, "longest_nondec_run": 0, "first_invalid_index": None}

    parts = s.split(',')
    count = 0
    first_invalid_index = None
    longest = 0
    current = 0
    prev_val = None

    for idx, raw in enumerate(parts):
        token = raw.strip()
        valid = False
        if token:
            if token[0] == '-':
                valid = len(token) > 1 and token[1:].isdigit()
            else:
                valid = token.isdigit()
        if not valid:
            if first_invalid_index is None:
                first_invalid_index = idx
            current = 0
            prev_val = None
            continue

        val = int(token)
        count += 1
        if current == 0:
            current = 1
        else:
            if prev_val is not None and val >= prev_val:
                current += 1
            else:
                current = 1
        prev_val = val
        if current > longest:
            longest = current

    return {"count": count, "longest_nondec_run": longest, "first_invalid_index": first_invalid_index}

