def compress_runs(values):
    result = []
    iterator = iter(values)
    try:
        current = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_path_tokens(path: str) -> str:
    if path == "":
        return "."

    absolute = path.startswith("/")
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            else:
                if not absolute:
                    stack.append("..")
        else:
            stack.append(part)

    if absolute:
        return "/" + "/".join(stack) if stack else "/"
    return "/".join(stack) if stack else "."

def compress_intervals(intervals):
    validated = []
    for item in intervals:
        try:
            if len(item) != 2:
                raise TypeError("Each interval must have exactly two elements")
        except TypeError:
            raise TypeError("Each interval must have exactly two elements")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("Interval endpoints must be integers")
        if start > end:
            raise ValueError("Interval start must be <= end")
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [validated[0]]
    for start, end in validated[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def decode_run_length(pattern: str) -> str:
    if pattern == "":
        return ""

    result = []
    i = 0
    n = len(pattern)

    while i < n:
        if not pattern[i].isdigit():
            raise ValueError("Malformed run-length pattern")

        start = i
        while i < n and pattern[i].isdigit():
            i += 1
        count_str = pattern[start:i]

        if i >= n:
            raise ValueError("Malformed run-length pattern")

        ch = pattern[i]
        if not ('A' <= ch <= 'Z'):
            raise ValueError("Malformed run-length pattern")

        count = int(count_str)
        if count <= 0:
            raise ValueError("Malformed run-length pattern")

        result.append(ch * count)
        i += 1

    return ''.join(result)

def normalize_table(headers, rows):
    if not isinstance(headers, (list, tuple)):
        raise TypeError('headers must be a list or tuple of strings')
    for h in headers:
        if not isinstance(h, str):
            raise TypeError('headers must be a list or tuple of strings')
    try:
        iterator = iter(rows)
    except TypeError:
        raise TypeError('rows must be iterable')
    result = []
    for row in iterator:
        if not isinstance(row, (list, tuple)):
            raise TypeError('each row must be a list or tuple')
        d = {}
        for i, h in enumerate(headers):
            value = row[i] if i < len(row) else None
            d[h] = value
        result.append(d)
    return result

def summarize_plateau_runs(seq, min_run_length=2):
    if not isinstance(min_run_length, int) or min_run_length < 1:
        raise ValueError("min_run_length must be an integer >= 1")

    items = list(seq)
    if not items:
        return []

    for x in items:
        if not isinstance(x, int):
            raise TypeError("seq must contain only integers")

    result = []
    start = 0
    current = items[0]

    for i in range(1, len(items) + 1):
        if i == len(items) or items[i] != current:
            length = i - start
            if length >= min_run_length:
                result.append({
                    "value": current,
                    "start": start,
                    "end": i - 1,
                    "length": length,
                })
            if i < len(items):
                start = i
                current = items[i]
    return result

def summarize_transcript(log: str) -> dict:
    speakers = []
    seen = set()
    total_words = 0
    longest_message = ""
    longest_count = -1

    for line in log.splitlines():
        stripped = line.strip()
        if ":" not in stripped:
            continue
        speaker_part, message_part = stripped.split(":", 1)
        speaker = speaker_part.strip()
        if speaker == "":
            continue
        message = message_part.strip()
        words = message.split() if message else []
        count = len(words)
        if speaker not in seen:
            seen.add(speaker)
            speakers.append(speaker)
        total_words += count
        if count > longest_count:
            longest_count = count
            longest_message = message
    if longest_count == -1:
        return {'speakers': [], 'word_count': 0, 'longest_message': ''}
    return {'speakers': speakers, 'word_count': total_words, 'longest_message': longest_message}

def select_weighted_variant(items, top_k, variant):
    if not isinstance(items, list):
        raise ValueError('items must be a list')
    if not isinstance(top_k, int):
        raise ValueError('top_k must be an integer')
    if top_k < 0:
        raise ValueError('top_k must be non-negative')
    if variant not in {'score', 'weight', 'hybrid'}:
        raise ValueError('invalid variant')

    validated = []
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('each item must be a dict')
        if set(item.keys()) != {'id', 'score', 'weight'}:
            raise ValueError('each item must have exactly id, score, and weight')
        item_id = item['id']
        score = item['score']
        weight = item['weight']
        if not isinstance(item_id, str) or item_id == '':
            raise ValueError('id must be a non-empty string')
        if not isinstance(score, int):
            raise ValueError('score must be an integer')
        if not isinstance(weight, (int, float)):
            raise ValueError('weight must be numeric')
        validated.append({'id': item_id, 'score': score, 'weight': weight})

    if top_k == 0:
        return []

    if variant == 'score':
        key_func = lambda x: (-x['score'], x['id'])
    elif variant == 'weight':
        key_func = lambda x: (-x['weight'], x['id'])
    else:
        key_func = lambda x: (-(x['score'] * x['weight']), x['id'])

    sorted_items = sorted(validated, key=key_func)
    return [dict(item) for item in sorted_items[:top_k]]

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    result = []
    for record in events:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dict")
        if set(record.keys()) != {"id", "when"}:
            raise ValueError("each record must contain exactly id and when")

        event_id = record["id"]
        when = record["when"]

        if not isinstance(event_id, str) or event_id == "":
            raise ValueError("id must be a non-empty string")

        if isinstance(when, int):
            canonical_when = when
        elif isinstance(when, str):
            stripped = when.strip()
            if stripped == "":
                raise ValueError("when must be an integer")
            try:
                canonical_when = int(stripped)
            except ValueError:
                raise ValueError("when must be an integer")
        else:
            raise ValueError("when must be an integer")

        if canonical_when < 0:
            bucket = "past"
        elif canonical_when == 0:
            bucket = "now"
        else:
            bucket = "future"

        result.append({"id": event_id, "when": canonical_when, "bucket": bucket})

    result.sort(key=lambda r: (r["when"], r["id"]))
    return result

def compress_intervals(points):
    values = sorted(set(points))
    if not values:
