def normalize_name_pairs(records):
    result = []
    seen = set()
    for record in records:
        if not isinstance(record, (list, tuple)) or len(record) != 2:
            continue
        last_name, first_name = record
        if not isinstance(last_name, str) or not isinstance(first_name, str):
