            seen.add(normalized)
            result.append(normalized)
    return result

def format_duration(seconds):
    if not isinstance(seconds, int) or isinstance(seconds, bool) or seconds < 0:
        raise ValueError("seconds must be a non-negative integer")

    if seconds == 0:
        return "now"

    units = [
        (365 * 24 * 60 * 60, "year"),
        (24 * 60 * 60, "day"),
        (60 * 60, "hour"),
        (60, "minute"),
        (1, "second"),
    ]

    parts = []
    remaining = seconds
    for unit_seconds, name in units:
        value, remaining = divmod(remaining, unit_seconds)
        if value:
            label = name if value == 1 else name + "s"
            parts.append(f"{value} {label}")

    if len(parts) == 1:
        return parts[0]
    return ", ".join(parts[:-1]) + " and " + parts[-1]

def normalize_mixed_numbers(values):
    if not isinstance(values, list):
        raise ValueError("values must be a list")

    result = []
    for item in values:
        if not isinstance(item, str):
            raise ValueError("all items must be strings")
        s = item
        if s == "":
            raise ValueError("invalid number string")

        sign = ""
        if s[0] in "+-":
            sign = s[0]
            s = s[1:]
        if s == "":
            raise ValueError("invalid number string")

        if s.count(".") > 1:
            raise ValueError("invalid number string")

        if "." in s:
            left, right = s.split(".", 1)
            if left == "" and right == "":
                raise ValueError("invalid number string")
            if left and not left.isdigit():
                raise ValueError("invalid number string")
            if right and not right.isdigit():
                raise ValueError("invalid number string")
            if left == "":
                left = "0"
            left = left.lstrip("0") or "0"
            right = right.rstrip("0")
            if left == "0" and right == "":
                result.append("0")
                continue
            normalized = left
            if right != "":
                normalized += "." + right
        else:
            if not s.isdigit():
                raise ValueError("invalid number string")
            left = s.lstrip("0") or "0"
            if left == "0":
                result.append("0")
                continue
            normalized = left

        if normalized == "0":
            result.append("0")
        else:
            if sign == "-":
                result.append("-" + normalized)
            else:
                result.append(normalized)
    return result

def merge_interval_logs(entries):
    if entries is None:
        raise TypeError('entries must be an iterable of records')
    normalized = {}
    for item in entries:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each entry must be a 2-tuple')
        label, interval = item
        if not isinstance(label, str) or label == '':
            raise ValueError('label must be a non-empty string')
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise TypeError('interval must be a 2-tuple')
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError('interval endpoints must be integers')
        if start > end:
            start, end = end, start
        normalized.setdefault(label, []).append((start, end))

    result = []
    for label in sorted(normalized):
        intervals = sorted(normalized[label])
        merged = []
        for start, end in intervals:
            if not merged:
                merged.append([start, end])
                continue
            prev_start, prev_end = merged[-1]
            if start <= prev_end + 1:
                if end > prev_end:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        for start, end in merged:
            result.append((label, (start, end)))
    return result

def parse_coordinate_path(s):
    if not isinstance(s, str):
        raise ValueError('input must be a string')
    if s.strip() == '':
        return [(0, 0)]

    result = [(0, 0)]
    x = y = 0
    tokens = s.split(',')
    for raw in tokens:
        token = raw.strip()
        if not token:
            raise ValueError('empty token')
        if len(token) < 2:
            raise ValueError('malformed token')
        direction = token[0]
        steps_str = token[1:]
        if direction not in 'UDLR':
            raise ValueError('unknown direction')
        if not steps_str.isdigit():
            raise ValueError('invalid steps')
        steps = int(steps_str)
        if steps <= 0:
            raise ValueError('steps must be positive')
        if direction == 'U':
            y += steps
        elif direction == 'D':
            y -= steps
        elif direction == 'R':
            x += steps
        else:
            x -= steps
        result.append((x, y))
    return result

def merge_intervals_with_payloads(items):
    if items is None:
        raise ValueError('items must be a list of interval-payload pairs')
    merged_input = []
    for item in items:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError('each item must be a 2-tuple')
        interval, payload = item
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise ValueError('interval must have exactly two endpoints')
        a, b = interval
        if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
            raise ValueError('endpoints must be numeric')
        start, end = (a, b) if a <= b else (b, a)
        merged_input.append((start, end, payload))
    if not merged_input:
        return []
    merged_input.sort(key=lambda x: (x[0], x[1]))
    result = []
    cur_start, cur_end, cur_payloads = merged_input[0][0], merged_input[0][1], [merged_input[0][2]]
    for start, end, payload in merged_input[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
            cur_payloads.append(payload)
        else:
            result.append(((cur_start, cur_end), cur_payloads))
            cur_start, cur_end, cur_payloads = start, end, [payload]
    result.append(((cur_start, cur_end), cur_payloads))
    return result

def normalize_event_windows(windows):
    """Validate and merge event windows grouped by (day, label)."""
    grouped = {}
    for item in windows:
        if not isinstance(item, tuple) or len(item) != 4:
            raise ValueError("each window must be a 4-tuple")
        day, start, end, label = item
        if not isinstance(day, int):
            raise ValueError("day must be an integer")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("start and end must be integers")
        if not isinstance(label, str) or label == "":
            raise ValueError("label must be a non-empty string")
        if start >= end:
            raise ValueError("start must be less than end")
        grouped.setdefault((day, label), []).append((start, end))

    merged = []
    for (day, label), intervals in grouped.items():
        intervals.sort()
        cur_start, cur_end = intervals[0]
        for start, end in intervals[1:]:
            if start <= cur_end:
                if end > cur_end:
                    cur_end = end
            else:
                merged.append((day, cur_start, cur_end, label))
                cur_start, cur_end = start, end
        merged.append((day, cur_start, cur_end, label))

    merged.sort(key=lambda x: (x[0], x[3], x[1]))
    return merged

def normalize_event_windows(windows):
    """
    Normalize event windows into a canonical schedule.

    :param windows: List of tuples of the form (day, start, end, label).
    :return: A list of tuples (day, start, end, label) sorted by day, then label lexicographically, then start.
    """
    def merge_intervals(interval1, interval2):
        start = max(interval1[0], interval2[0])
        end = min(interval1[1], interval2[1])
        return (start, end)

    def merge_windows_by_day_and_label(windows):
        merged_windows = []
        for window in windows:
            day, label, start, end = window
            if day not in merged_windows:
                merged_windows.append((day, label, start, end))
            else:
                merged_windows[-1] = merge_intervals(merged_windows[-1], window)
        return merged_windows

    def sort_windows_by_day_and_label(merged_windows):
        return sorted(merged_windows, key=lambda x: (x[0], x[1], x[2]))

    normalized_windows = merge_windows_by_day_and_label(windows)
    return sort_windows_by_day_and_label(normalized_windows)

def normalize_event_log(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")
    normalized = []
    seen = set()
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError("each record must be a 3-item tuple")
        timestamp, kind, payload = rec
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError("timestamp must be a non-negative integer")
        if not isinstance(kind, str):
            raise ValueError("kind must be a string")
        key = (timestamp, kind, repr(payload))
        if key in seen:
            continue
        seen.add(key)
        normalized.append({"timestamp": timestamp, "kind": kind, "payload": payload})
    normalized.sort(key=lambda d: d["timestamp"])
    return normalized

def normalize_inventory_events(events):
    totals = {}
    for event in events:
        try:
            item, delta = event
        except Exception:
            raise ValueError("each event must be a 2-tuple")

        if not isinstance(item, str):
            raise ValueError("item must be a string")
        normalized_item = item.strip()
        if normalized_item == "":
            raise ValueError("item cannot be empty after stripping")

        if isinstance(delta, int):
            normalized_delta = delta
        elif isinstance(delta, str):
            s = delta.strip()
            if s == "":
                raise ValueError("delta string cannot be empty")
            sign = 1
            if s[0] in "+-":
                if s[0] == '-':
                    sign = -1
                s = s[1:]
            if s == "" or not s.isdigit():
                raise ValueError("delta must be an integer")
            normalized_delta = sign * int(s)
        else:
            raise ValueError("delta must be an integer or integer string")

        totals[normalized_item] = totals.get(normalized_item, 0) + normalized_delta
        if totals[normalized_item] == 0:
            del totals[normalized_item]

    return sorted(totals.items(), key=lambda kv: kv[0])

def normalize_schedule(slots, inclusive_end=False):
    try:
        items = list(slots)
    except TypeError:
        raise TypeError("slots must be an iterable of 2-item sequences")

    validated = []
    for slot in items:
        if len(slot) != 2:
            raise ValueError("each slot must contain exactly two integers")
        start, end = slot
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("slot boundaries must be integers")
        if start >= end:
            raise ValueError("each slot must satisfy start < end")
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [validated[0]]

    for start, end in validated[1:]:
        last_start, last_end = merged[-1]
        if inclusive_end:
            overlaps = start <= last_end
        else:
            overlaps = start < last_end

        if overlaps:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

def compress_intervals(values, gap):
    if not isinstance(gap, int) or gap <= 0:
        raise ValueError("gap must be a positive integer")

    vals = list(values)
    for v in vals:
        if not isinstance(v, int):
            raise ValueError("all values must be integers")

    if not vals:
        return []

    runs = []
    start = prev = vals[0]
    count = 1

    for v in vals[1:]:
        if abs(v - prev) <= gap:
            prev = v
            count += 1
        else:
            runs.append((start, prev, count))
            start = prev = v
            count = 1

    runs.append((start, prev, count))
    return runs

def segment_signature(text: str) -> list[int]:
    if text == "":
        return []

    result = []
    current = text[0]
    length = 1

    def signed_len(ch: str, n: int) -> int:
        if "A" <= ch <= "Z":
            return n
        if "a" <= ch <= "z":
            return -n
        return 0

    for ch in text[1:]:
        if ch == current:
            length += 1
        else:
            result.append(signed_len(current, length))
            current = ch
            length = 1

    result.append(signed_len(current, length))
    return result

def normalize_org_path(path: str) -> str:
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)
    return '/'.join(parts)

def normalize_org_path(path: str) -> str:
    """
    Normalize a slash-separated organization path with special segment handling.

    Parameters:
    - path (str): A string containing zero or more segments separated by '/'.

    Returns:
    - str: A normalized string with special segment handling.
    """
    segments = path.split('/')
    result = []

    for segment in segments:
        if segment == '.':
            continue  # Skip empty segments
        elif segment == '..':
            if result and result[-1] != '':
                result.pop()
            else:
                continue  # Ignore '..' without a previous segment
        else:
            result.append(segment)

    return '/'.join(result)

