def compact_intervals(values):
    try:
        items = list(values)
    except TypeError:
        raise TypeError("values must be iterable")

    for x in items:
        if type(x) is not int:
            raise TypeError("all elements must be ints")

    if not items:
        return []

    uniq = sorted(set(items))
    result = []
    start = prev = uniq[0]

    for n in uniq[1:]:
        if n == prev + 1:
            prev = n
        else:
            result.append([start, prev])
            start = prev = n
    result.append([start, prev])
    return result

def compress_intervals(intervals):
    normalized = []
    for item in intervals:
        try:
            if len(item) != 2:
                raise ValueError
            start, end = item
        except Exception:
            raise ValueError("Each interval must contain exactly two values")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Interval endpoints must be integers")
        if start > end:
            raise ValueError("Interval start must be <= end")
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def canonicalize_event_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    s = path.strip()
    if s == "":
        return "/"

    parts = []
    for segment in s.split("/"):
        if segment == "" or segment == ".":
            continue
        if segment == "..":
            if parts:
                parts.pop()
            continue
        parts.append(segment)

    return "/" + "/".join(parts) if parts else "/"

def normalize_log_fields(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    result = []
    for item in records:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each record must be a 2-item tuple")
        timestamp, message = item
        if not isinstance(timestamp, int):
            raise TypeError("timestamp must be an int")
        if not isinstance(message, str):
            continue
        if timestamp < 0:
            continue
        normalized_message = '_'.join(message.strip().lower().split())
        result.append((timestamp // 60, normalized_message))
    return result

def select_minimal_cover(segments, universe):
    points = sorted(set(universe))
    if not points:
        return []

    n = len(segments)
    seg_sets = []
    for start, end in segments:
        if start <= end:
            covered = set(range(start, end + 1))
        else:
            covered = set()
        seg_sets.append(covered)

    target = set(points)
    best = None

    # Enumerate subsets by increasing size, then lexicographically by indices.
    for size in range(1, n + 1):
        def backtrack(start_idx, chosen, covered):
            nonlocal best
            if best is not None:
                return
            if len(chosen) == size:
                if covered >= target:
                    best = chosen.copy()
                return
            # Prune if not enough segments left.
            if start_idx >= n or len(chosen) + (n - start_idx) < size:
                return
            for i in range(start_idx, n):
                chosen.append(i)
                backtrack(i + 1, chosen, covered | seg_sets[i])
                chosen.pop()
                if best is not None:
                    return

        backtrack(0, [], set())
        if best is not None:
            return best

    return None

def normalize_inventory(lines):
    result = {}
    units = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError('each line must be a string')
        parts = line.split(',')
        if len(parts) != 3:
            raise ValueError('malformed line')
        name_raw, qty_raw, unit_raw = (p.strip() for p in parts)
        if not name_raw or not qty_raw or not unit_raw:
            raise ValueError('empty field')
        name = name_raw.lower()
        unit = unit_raw.lower()
        if not unit.isalpha():
            raise ValueError('invalid unit')
        try:
            qty = int(qty_raw)
        except Exception:
            raise ValueError('invalid quantity')
        if name in units and units[name] != unit:
            raise ValueError('conflicting units')
        units[name] = unit
        if name in result:
            result[name] = (result[name][0] + qty, unit)
        else:
            result[name] = (qty, unit)
    return result

def parse_prefixed_integer(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    sign = 1
    if s[0] in "+-":
        sign = -1 if s[0] == '-' else 1
        s = s[1:]
        if not s:
            raise ValueError("sign without digits")

    base = 10
    if len(s) >= 2 and s[0] == '0' and s[1] in 'xXbBoO':
        prefix = s[1]
        if prefix in 'xX':
            base = 16
        elif prefix in 'bB':
            base = 2
        else:
            base = 8
        s = s[2:]
        if not s:
            raise ValueError("prefix without digits")

    if any(ch.isspace() for ch in s):
        raise ValueError("embedded whitespace")

    if base == 10:
        digits = '0123456789'
    elif base == 16:
        digits = '0123456789abcdefABCDEF'
    elif base == 8:
        digits = '01234567'
    else:
        digits = '01'

    if not all(ch in digits for ch in s):
        raise ValueError("invalid digit")

    return sign * int(s, base)

def cluster_run_lengths(seq, gap=0):
    if not isinstance(gap, int) or gap < 0:
        raise ValueError("gap must be a non-negative integer")

    items = list(seq)
    for x in items:
        if not isinstance(x, int):
            raise TypeError("seq must contain only integers")

    if not items:
        return []

    runs = []
    cur_val = items[0]
    cur_len = 1
    for x in items[1:]:
        if x == cur_val:
            cur_len += 1
        else:
            runs.append((cur_val, cur_len))
            cur_val = x
            cur_len = 1
    runs.append((cur_val, cur_len))

    clusters = [[runs[0]]]
    for value, length in runs[1:]:
        prev_value = clusters[-1][-1][0]
        if abs(value - prev_value) <= gap:
            clusters[-1].append((value, length))
        else:
            clusters.append([(value, length)])
    return clusters

def decode_rle_path(s):
    if not isinstance(s, str) or s == '':
        raise ValueError('invalid input')

    moves = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}
    x = y = 0
    out = []

    tokens = s.split(',')
    for token in tokens:
        if token == '':
            raise ValueError('invalid token')
        i = 0
        while i < len(token) and token[i].isdigit():
            i += 1
        if i == 0 or i == len(token):
            raise ValueError('invalid token')
        count_str = token[:i]
        step = token[i:]
        if len(step) != 1 or step not in moves:
            raise ValueError('invalid token')
        if count_str[0] == '0':
            raise ValueError('count must be positive')
        count = int(count_str)
        if count <= 0:
            raise ValueError('count must be positive')
        dx, dy = moves[step]
        for _ in range(count):
            x += dx
            y += dy
            out.append((x, y))
    return out

def encode_rle_with_counts(values):
    if not isinstance(values, (list, tuple)):
        raise TypeError("values must be a list or tuple")
    result = []
    if len(values) == 0:
        return result
    for item in values:
        if not isinstance(item, int):
            raise TypeError("all elements must be integers")
    current = values[0]
    count = 1
    for item in values[1:]:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_route(path: str) -> str:
    if path == '':
        return '.'

    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not is_absolute:
                    stack.append('..')
        else:
            stack.append(part)

    if is_absolute:
        return '/' + '/'.join(stack) if stack else '/'

    return '/'.join(stack) if stack else '.'

def normalize_phone_groups(text: str) -> list[str]:
    groups = []
    current = []

    for ch in text:
        if '0' <= ch <= '9':
            current.append(ch)
        else:
            if current:
                s = ''.join(current)
                if len(s) >= 2:
                    for i in range(0, len(s), 4):
                        groups.append(s[i:i+4])
                current = []

    if current:
        s = ''.join(current)
        if len(s) >= 2:
            for i in range(0, len(s), 4):
                groups.append(s[i:i+4])

    return groups

def normalize_inventory_changes(events):
    result = {}
    for event in events:
        if not isinstance(event, str):
            continue
        parts = event.split(':')
        if len(parts) != 3:
            continue
        item, action, amount_str = parts
        if not item:
            continue
        if any(ch not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-' for ch in item):
            continue
        if action not in ('ADD', 'REMOVE'):
            continue
        if amount_str in ('', '+', '-'):
            continue
        signless = amount_str[1:] if amount_str[0] in '+-' else amount_str
        if not signless.isdigit():
            continue
        try:
            amount = int(amount_str, 10)
        except ValueError:
            continue
        delta = amount if action == 'ADD' else -amount
        if item in result:
            result[item] += delta
        else:
            result[item] = delta
    return result

def parse_duration(spec: str) -> int:
    if not isinstance(spec, str) or spec == '':
        raise ValueError('invalid duration')

    multipliers = {'w': 7 * 24 * 60 * 60, 'd': 24 * 60 * 60, 'h': 60 * 60, 'm': 60, 's': 1}
    order = {'w': 0, 'd': 1, 'h': 2, 'm': 3, 's': 4}

    sign = 1
    i = 0
    if spec[0] in '+-':
        sign = -1 if spec[0] == '-' else 1
        i = 1
        if i >= len(spec):
            raise ValueError('invalid duration')

    total = 0
    last_order = -1
    seen = set()

    while i < len(spec):
        if not spec[i].isdigit():
            raise ValueError('invalid duration')
        start = i
        while i < len(spec) and spec[i].isdigit():
            i += 1
        if i >= len(spec):
            raise ValueError('invalid duration')
        unit = spec[i]
        if unit not in multipliers:
            raise ValueError('invalid duration')
        unit_order = order[unit]
        if unit_order <= last_order or unit in seen:
            raise ValueError('invalid duration')
        seen.add(unit)
        last_order = unit_order
        value = int(spec[start:i])
        total += value * multipliers[unit]
        i += 1

    return sign * total

def canonicalize_permissions(entries):
    result = {}

    def normalize_path(path):
        path = path.strip()
        while '//' in path:
            path = path.replace('//', '/')
        if path.endswith('/') and path != '/':
            path = path[:-1]
        if path == '':
            path = '/'
        return path

    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError('each entry must be a 2-item tuple')
        path, mode = entry
        if not isinstance(path, str):
            raise TypeError('path must be a string')
        norm_path = normalize_path(path)

        if isinstance(mode, int):
            if mode < 0 or mode > 0o777:
                raise ValueError('integer mode out of range')
            norm_mode = mode
        elif isinstance(mode, str):
            if mode == '' or not mode.isdigit():
                raise ValueError('string mode must contain digits only')
            norm_mode = int(mode, 8)
            if norm_mode < 0 or norm_mode > 0o777:
                raise ValueError('string mode out of range')
        else:
            raise TypeError('mode must be int or str')

        result[norm_path] = norm_mode

    return result

def normalize_inventory(records):
    result = []
    for record in records:
        if not isinstance(record, str):
            raise ValueError('record must be a string')
        parts = record.split('|')
        if len(parts) != 3:
            raise ValueError('malformed record')
        location, item, quantity_text = parts
        location = location.strip()
        item = item.strip()
        if not location or not item:
            raise ValueError('empty location or item')
        if '|' in location or '|' in item:
            raise ValueError('invalid separator in field')
        try:
            quantity = int(quantity_text)
        except Exception:
            raise ValueError('invalid quantity')
        result.append(f'{location.upper()}|{item.upper()}|{quantity}')
    return result

def normalize_route_steps(path):
    if path is None:
        raise ValueError("path must be a string")
    if not isinstance(path, str):
        raise ValueError("path must be a string")

    stripped = path.strip()
    if stripped == "":
        return [(0, 0)]

    steps = stripped.split(',')
    if any(step.strip() == "" for step in steps):
        raise ValueError("malformed route")

    x, y = 0, 0
    visited = [(0, 0)]
    seen = {(0, 0)}

    for raw_step in steps:
        step = raw_step.strip()
        if ':' not in step:
            raise ValueError("malformed route")
        parts = step.split(':')
        if len(parts) != 2:
            raise ValueError("malformed route")
        direction = parts[0].strip()
        count_text = parts[1].strip()
        if direction not in {'N', 'S', 'E', 'W'}:
            raise ValueError("malformed route")
        if count_text == "" or not count_text.isdigit():
            raise ValueError("malformed route")
        count = int(count_text)
        if count < 0:
            raise ValueError("malformed route")

        dx, dy = 0, 0
        if direction == 'N':
            dy = 1
        elif direction == 'S':
            dy = -1
        elif direction == 'E':
            dx = 1
        else:
            dx = -1

        for _ in range(count):
            x += dx
            y += dy
            coord = (x, y)
            if coord not in seen:
                seen.add(coord)
                visited.append(coord)

    return visited

def normalize_records(records):
    try:
        iterator = iter(records)
    except TypeError:
        raise TypeError("records must be iterable")

    seen = {}
    for rec in iterator:
        key = value = None
        is_mapping = False
        if hasattr(rec, 'keys') and callable(getattr(rec, 'keys')):
            try:
                keys = set(rec.keys())
            except Exception:
                keys = None
            if keys == {'key', 'value'}:
                is_mapping = True
                key = rec['key']
                value = rec['value']
        if not is_mapping:
            try:
                pair = list(rec)
            except TypeError:
                raise TypeError("invalid record")
            if len(pair) != 2:
                raise TypeError("record must have exactly two items")
            key, value = pair
        norm_key = str(key).strip().upper()
        if norm_key == '':
            continue
        if norm_key in seen:
            continue
        norm_value = str(value).strip()
        seen[norm_key] = f"{norm_key}={norm_value}"
    return [seen[k] for k in sorted(seen)]

def compress_runs(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError('values must be iterable')

    result = []
    sentinel = object()
    current = sentinel
    count = 0

    for item in iterator:
        try:
            hash(item)
        except TypeError:
            raise TypeError('elements must be hashable')

        if current is sentinel:
            current = item
            count = 1
        elif item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    if current is not sentinel:
        result.append((current, count))

    return result

def decode_runlength_segments(text: str) -> list[str]:
    if text == "":
        return []
    result = []
    segments = text.split(';')
    for segment in segments:
        if segment == "":
            raise ValueError("empty segment")
        parts = segment.split(':')
        if len(parts) != 2:
            raise ValueError("malformed segment")
        count_str, payload = parts
        if count_str == "" or count_str[0] in '+-':
            raise ValueError("invalid count")
        if not count_str.isdigit():
            raise ValueError("invalid count")
        count = int(count_str)
        if count < 0:
            raise ValueError("negative count")
        result.extend([payload] * count)
    return result

def compress_intervals(values):
    seen = set()
    for v in values:
        if type(v) is not int:
            raise TypeError("all elements must be integers")
        seen.add(v)

    if not seen:
        return []

    nums = sorted(seen)
    intervals = []
    start = prev = nums[0]

    for x in nums[1:]:
        if x == prev + 1:
            prev = x
        else:
            intervals.append((start, prev))
            start = prev = x
    intervals.append((start, prev))
    return intervals

def normalize_log_lines(lines):
    allowed = {"INFO", "WARN", "ERROR"}
    result = []
    for item in lines:
        if not isinstance(item, str):
            continue
        s = item.strip()
        if not s:
            continue
        if '|' not in s:
            continue
        level_part, message_part = s.split('|', 1)
        level = level_part.strip().upper()
        if level not in allowed:
            continue
        message = ' '.join(message_part.strip().split())
        result.append(f"{level}|{message}")
    return result

def normalize_invoice_lines(lines):
    try:
        iterator = iter(lines)
    except TypeError:
        raise TypeError('lines must be an iterable of strings')

    normalized_lines = []
    comments_removed = 0

    for item in iterator:
        if not isinstance(item, str):
            raise TypeError('lines must be an iterable of strings')

        stripped = item.strip()
        if stripped == '':
            continue
        if stripped.startswith('#'):
            comments_removed += 1
            continue

        def normalize_text(text):
            return ' '.join(text.strip().split()).upper()

        if '::' in stripped:
            left, right = stripped.split('::', 1)
            normalized = f"{normalize_text(left)} :: {normalize_text(right)}"
        else:
            normalized = normalize_text(stripped)

        normalized_lines.append(normalized)

    summary = {
        'count': len(normalized_lines),
        'unique': len(set(normalized_lines)),
        'comments_removed': comments_removed,
    }
    return normalized_lines, summary

def parse_grid_paths(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    count = 0
    labels = []
    total_weight = 0
    longest_path = ''
    valid = True

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if line == '':
            continue

        parts = [p.strip() for p in line.split(',')]
        if len(parts) != 3:
            valid = False
            continue

        label, weight_str, path = parts

        if not label or any(ch not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_' for ch in label):
            valid = False
            continue

        try:
            weight = int(weight_str, 10)
        except Exception:
            valid = False
            continue

        if not path or any(ch not in 'UDLR' for ch in path):
            valid = False
            continue

        count += 1
        labels.append(label)
        total_weight += weight
        if len(path) > len(longest_path):
            longest_path = path

    return {
        'count': count,
        'labels': labels,
        'total_weight': total_weight,
        'longest_path': longest_path,
        'valid': valid,
    }

def normalize_event_schedule(events):
    seen = set()
    by_day = {}
    total_events = 0
    total_duration = 0

    if not isinstance(events, list):
        return {"days": [], "total_events": 0, "total_duration": 0}

    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 4:
            continue
        day, start_minute, end_minute, label = rec
        if not isinstance(day, str):
            continue
        if not isinstance(label, str) or label == "":
            continue
        if not isinstance(start_minute, int) or not isinstance(end_minute, int):
            continue
        if not (0 <= start_minute < end_minute <= 1440):
            continue
        if rec in seen:
            continue
        seen.add(rec)
        by_day.setdefault(day, []).append((start_minute, end_minute, label))
        total_events += 1
        total_duration += end_minute - start_minute

    days = []
    for day in sorted(by_day):
        day_events = sorted(by_day[day], key=lambda x: (x[0], x[1], x[2]))
        duration = sum(end - start for start, end, _ in day_events)
        days.append({"day": day, "events": day_events, "duration": duration})

    return {"days": days, "total_events": total_events, "total_duration": total_duration}

def normalize_log_events(events):
    if not events:
        return []

    normalized = []
    for event in events:
        if not isinstance(event, dict):
            continue

        required = ("ts", "user", "action", "status", "tags")
        if any(key not in event for key in required):
            continue

        ts = event["ts"]
        user = event["user"]
        action = event["action"]
        status = event["status"]
        tags = event["tags"]

        if not isinstance(ts, int):
            continue
        if not isinstance(user, str) or user.strip() == "":
            continue
        if not isinstance(action, str) or action.strip() == "":
            continue
        if status not in ("ok", "fail"):
            continue
        if not isinstance(tags, list):
            continue

        norm_user = user.strip().lower()
        norm_action = action.strip().lower()
        if norm_user == "" or norm_action == "":
            continue

        seen = set()
        norm_tags = []
        for tag in tags:
            if not isinstance(tag, str):
                continue
            t = tag.strip().lower()
            if not t or t in seen:
                continue
            seen.add(t)
            norm_tags.append(t)

        normalized.append({
            "ts": ts,
            "user": norm_user,
            "action": norm_action,
            "status": status,
            "tags": norm_tags,
        })

    return normalized

def normalize_events(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    normalized = []
    seen = set()
    for event in events:
        try:
            if len(event) != 3:
                raise ValueError('each event must have exactly 3 items')
            timestamp, label, kind = event
        except TypeError:
            raise ValueError('each event must be a 3-item sequence')

        if not isinstance(timestamp, int):
            raise TypeError('timestamp must be int')
        if not isinstance(label, str):
            raise TypeError('label must be str')
        if kind not in ('start', 'end'):
            raise ValueError('kind must be start or end')

        norm_label = ' '.join(label.split()).lower()
        key = (timestamp, norm_label, kind)
        if key in seen:
            raise ValueError('duplicate event')
        seen.add(key)
        normalized.append((timestamp, norm_label, kind))

    grouped = {}
    for timestamp, label, kind in normalized:
        grouped.setdefault(label, []).append((timestamp, kind))

    result = []
    for label in sorted(grouped):
        items = sorted(grouped[label], key=lambda x: (x[0], 0 if x[1] == 'start' else 1))
        starts = ends = 0
        stack = []
        intervals = []
        valid = True
        for timestamp, kind in items:
            if kind == 'start':
                starts += 1
                stack.append(timestamp)
            else:
                ends += 1
                if not stack:
                    valid = False
                    break
                s = stack.pop(0)
                intervals.append((s, timestamp))
        if valid and starts == ends and not stack:
            result.append((label, intervals))

    return result

def canonicalize_route(route):
    if not isinstance(route, str):
        raise TypeError('route must be a string')

    parts = []
    for raw in route.split('/'):
        segment = raw.strip()
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        parts.append(segment)
    return '/' + '/'.join(parts)

def split_around_marker(s: str, marker: str) -> tuple[str, str]:
    if marker == "":
        raise ValueError("marker must not be empty")
    index = s.find(marker)
    if index == -1:
        raise ValueError("marker not found")
    return s[:index], s[index + len(marker):]

import re

def normalize_ticket_codes(codes):
    pattern = re.compile(r'^T-[A-Z]+-[0-9]+$')
    result = []
    seen = set()
    for item in codes:
        if not isinstance(item, str):
            continue
        normalized = item.strip().upper()
        if pattern.fullmatch(normalized) and normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result

def compress_sorted_runs(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if len(values) == 0:
        return []
    for x in values:
        if not isinstance(x, int):
            raise TypeError("all elements must be integers")
    result = []
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.append([current, count])
            current = x
            count = 1
    result.append([current, count])
    return result

def normalize_path_segments(path: str) -> str:
    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        if not stack:
            return '/'
        return '/' + '/'.join(stack)

    if not stack:
        return '.'
    return '/'.join(stack)

def normalize_file_manifest(entries):
    if not isinstance(entries, list):
        raise ValueError

    def normalize_path(path):
        path = path.replace('\\', '/')
        while '//' in path:
            path = path.replace('//', '/')
        while path.startswith('./'):
            path = path[2:]
        return path

    best = {}
    order = {}

    for idx, entry in enumerate(entries):
        if not (isinstance(entry, (tuple, list)) and len(entry) == 2):
            raise ValueError
        path, size = entry
        if not isinstance(path, str) or path == '' or '\x00' in path:
            raise ValueError
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ValueError

        norm_path = normalize_path(path)
        if norm_path == '':
            raise ValueError

        if norm_path not in best:
            best[norm_path] = size
            order[norm_path] = idx
        else:
            current_size = best[norm_path]
            if size > current_size:
                best[norm_path] = size
                order[norm_path] = idx
            elif size == current_size:
                pass

    result = [(p, best[p]) for p in sorted(best.keys())]
    return result

def normalize_chat_command(command: str) -> dict:
    if not isinstance(command, str):
        raise ValueError("command must be a string")

    s = command.strip()
    if not s or not s.startswith('/'):
        raise ValueError("invalid command")

    parts = s.split()
    first = parts[0]
    action = first[1:]
    if not action or not action.replace('_', '').isalnum() or not action[0].isalpha() and not action[0].isdigit():
        raise ValueError("invalid action")
    if not all(ch.isalnum() or ch == '_' for ch in action):
        raise ValueError("invalid action")

    target = None
    options = {}
    seen_target = False

    for token in parts[1:]:
        if '=' in token:
            key, value = token.split('=', 1)
            if not key or not all(ch.isalnum() or ch == '_' for ch in key):
                raise ValueError("invalid option key")
            options[key] = value
        else:
            if not seen_target:
                target = token
                seen_target = True
            else:
                raise ValueError("unexpected extra token")

    return {"action": action, "target": target, "options": options}

def normalize_chat_command(command: str) -> dict:
    """
    Parses a simple chat-style command string and returns a dictionary with exactly three keys:
    'action', 'target', and 'options'.

    Args:
    command (str): A single string that may contain leading/trailing whitespace.

    Returns:
    dict: A dictionary with exactly three keys: 'action', 'target', and 'options'.
    """
    # Split the command into words
    words = command.split()

    # Check if the command starts with a slash
    if not words[0].startswith('/'):
        raise ValueError("Invalid command format")

    # Parse the action
    action = words[0][1:]

    # Check if the action contains only letters, digits, or underscores
    if not action.isalpha() or not action.isalnum():
        raise ValueError("Invalid action format")

    # Initialize the target and options
    target = None
    options = {}

    # Iterate over the remaining words
    for i in range(1, len(words)):
        if words[i].startswith('='):
            # Parse the option
            key, value = words[i].split('=')
            if not key.isalpha() or not key.isalnum():
                raise ValueError("Invalid option format")

            # Update the target if it's not already set
            if target is None:
                target = words[i]
            else:
                raise ValueError("Duplicate option keys")

            # Add the option to the options dictionary
            options[key] = value

    # Return the parsed dictionary
    return {
        'action': action,
        'target': target,
        'options': options
    }

