def normalize_sensor_readings(readings, min_value, max_value):
    try:
        min_is_real = isinstance(min_value, (int, float)) and not isinstance(min_value, bool)
        max_is_real = isinstance(max_value, (int, float)) and not isinstance(max_value, bool)
    except Exception:
        raise ValueError("min_value and max_value must be real numbers")
    if not min_is_real or not max_is_real or not (min_value < max_value):
        raise ValueError("min_value and max_value must be real numbers with min_value < max_value")
    try:
        iterator = iter(readings)
    except TypeError:
        raise TypeError("readings must be iterable")
    result = []
    scale = max_value - min_value
    for x in iterator:
        if x is None:
            result.append(None)
            continue
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError("each reading must be a real number or None")
        if x < min_value:
            result.append(0.0)
        elif x > max_value:
            result.append(1.0)
        else:
            result.append(float((x - min_value) / scale))
    return result

def normalize_route_path(path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    path = path.strip()
    if not path.startswith('/'):
        raise ValueError("path must start with /")

    segments = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if any(ch.isspace() for ch in segment) or '#' in segment or '\x00' in segment:
            raise ValueError("invalid path segment")
        if segment == '..':
            if segments:
                segments.pop()
            continue
        segments.append(segment)

    return '/' + '/'.join(segments) if segments else '/'

def resolve_address_book(contacts, query):
    normalized = {}
