        normalized[name] = address
    if not isinstance(query, str):
        return None
    query = query.strip()
    if query == "":
        return None
    return normalized.get(query, None)

def normalize_path_tokens(tokens):
    if tokens is None:
        raise TypeError("tokens must be a sequence of strings")
    result = []
    for tok in tokens:
        if not isinstance(tok, str):
            raise TypeError("all tokens must be strings")
        if tok == '.':
            continue
        if tok == '..':
            if result:
                result.pop()
            continue
        result.append(tok)
    return result

def normalize_path_tokens(tokens):
    """
    Normalize a list of path tokens by removing special tokens and preserving normal tokens.

    :param tokens: List of path tokens (strings).
    :return: A list of normalized path tokens.
    """
    def remove_special_token(token):
        if token == '.':
            return ''
        elif token == '..':
            if not tokens:
                return ''
            else:
                tokens.pop()
        else:
            return token

    # Remove special tokens
    tokens = [remove_special_token(token) for token in tokens]

    # Initialize the result list with the first token
    result = [tokens[0]]

    # Iterate through the tokens starting from the second one
    for i in range(1, len(tokens)):
        if tokens[i] == '..':
            if result:
                result.pop()  # Remove the last element if it's not empty
        else:
            result.append(tokens[i])

    return result

