def summarize_shelf_layout(shelves):
    if not isinstance(shelves, list):
        raise TypeError("shelves must be a list")

    if len(shelves) == 0:
        return {"densest": None, "emptiest": None, "uniform": True}

    counts = []
    for shelf in shelves:
        if not isinstance(shelf, list):
            raise TypeError("each shelf must be a list")
        count = 0
        for title in shelf:
            if isinstance(title, str):
                if title.strip() != "":
                    count += 1
        counts.append(count)

    max_count = max(counts)
    min_count = min(counts)
    densest = next(i for i, c in enumerate(counts) if c == max_count)
    emptiest = next(i for i, c in enumerate(counts) if c == min_count)
    uniform = all(c == counts[0] for c in counts)
    return {"densest": densest, "emptiest": emptiest, "uniform": uniform}

def normalize_inventory_events(events):
    try:
        iterator = iter(events)
    except TypeError:
        raise ValueError("events must be iterable")

    result_order = []
    summary = {}

    for record in iterator:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a 3-tuple")
        item, delta, note = record

        if not isinstance(item, str) or item == "":
            raise ValueError("item must be a non-empty string")
        normalized_item = item.strip()
        if normalized_item == "":
            raise ValueError("item cannot be empty after stripping")

        if isinstance(delta, bool) or not isinstance(delta, int):
            raise ValueError("delta must be an integer")
        if not isinstance(note, str):
            raise ValueError("note must be a string")

        if normalized_item not in summary:
            summary[normalized_item] = [0, 0, []]
            result_order.append(normalized_item)
        entry = summary[normalized_item]
        entry[0] += delta
        entry[1] += 1
        if note != "" and note not in entry[2]:
            entry[2].append(note)

    return [(item, summary[item][0], summary[item][1], tuple(summary[item][2])) for item in result_order]

def schedule_windows(events, day_start, day_end):
    if not isinstance(day_start, int) or not isinstance(day_end, int):
        raise ValueError("day bounds must be integers")
    if day_start >= day_end:
        raise ValueError("day_start must be less than day_end")

    validated = []
    for ev in events:
        try:
            a, b = ev
        except Exception:
            raise ValueError("each event must be a 2-element iterable")
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError("event endpoints must be integers")
        if a > b:
            raise ValueError("event start must be <= end")
        if b <= day_start or a >= day_end:
            continue
        lo = max(a, day_start)
        hi = min(b, day_end)
        if lo < hi:
            validated.append((lo, hi))

    if not validated:
        return [[day_start, day_end]]

    validated.sort()
    merged = [list(validated[0])]
    for s, e in validated[1:]:
        if s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1][1] = e
        else:
            merged.append([s, e])

    free = []
    cur = day_start
    for s, e in merged:
        if cur < s:
            free.append([cur, s])
        cur = max(cur, e)
    if cur < day_end:
        free.append([cur, day_end])
    return free

def synthesize_patch(base, edits_a, edits_b):
    def apply_edits(text, edits):
        current = text
        for start, end, replacement in edits:
            if not isinstance(start, int) or not isinstance(end, int):
                raise ValueError("invalid edit")
            if start < 0 or end < 0 or start > end or end > len(current):
                raise ValueError("invalid edit")
            current = current[:start] + replacement + current[end:]
        return current

    def shortest_script(src, dst):
        if src == dst:
            return []
        # single edit if possible: replace maximal differing span
        prefix = 0
        limit = min(len(src), len(dst))
        while prefix < limit and src[prefix] == dst[prefix]:
            prefix += 1
        suffix = 0
        while (suffix < len(src) - prefix and suffix < len(dst) - prefix and
               src[len(src) - 1 - suffix] == dst[len(dst) - 1 - suffix]):
            suffix += 1
        s_start = prefix
        s_end = len(src) - suffix
        repl = dst[prefix:len(dst) - suffix]
        if s_start == s_end and repl == "":
            return []
        return [(s_start, s_end, repl)]

    result_a = apply_edits(base, edits_a)
    result_b = apply_edits(base, edits_b)

    if result_a == result_b:
        return shortest_script(base, result_a)
    chosen = result_a if result_a < result_b else result_b
    return shortest_script(base, chosen)

def normalize_event_ranges(ranges):
    if not isinstance(ranges, list):
        raise TypeError("ranges must be a list")

    normalized = []
    for interval in ranges:
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise TypeError("each interval must be a 2-element list or tuple")
        a, b = interval
        if type(a) is not int or type(b) is not int:
            raise TypeError("interval endpoints must be integers")
        start, end = (a, b) if a <= b else (b, a)
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def normalize_sensor_log(lines):
    import re

    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    latest = {}

    for raw in lines:
        if raw is None:
            continue
        line = raw.strip()
        if not line or line.startswith('#'):
            continue

        sep_index = -1
        sep_char = None
        for ch in ('=', ':'):
            idx = line.find(ch)
            if idx != -1 and (sep_index == -1 or idx < sep_index):
                sep_index = idx
                sep_char = ch

        if sep_index == -1:
            continue

        key = line[:sep_index].strip()
        value = line[sep_index + 1:].strip()

        if not key_pattern.match(key):
            continue

        latest[key] = value

    if not latest:
        return ''

    return '\n'.join(f'{k}={latest[k]}' for k in sorted(latest))

def normalize_label_counts(items):
