        counts[label] = counts.get(label, 0) + 1
    parts = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return "|".join(f"{label}:{count}" for label, count in parts)

def encode_runs(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if s == "":
        return ""

    parts = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f"{current}{count}")
