    parts.append(f"{current}{count}")
    return ";".join(parts)

def summarize_edit_runs(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    runs = []
    if text == "":
        return {"runs": [], "longest": 0, "starts_with": None, "ends_with": None}

    current_char = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current_char:
            count += 1
        else:
            runs.append((current_char, count))
            current_char = ch
            count = 1
    runs.append((current_char, count))

    longest = max(cnt for _, cnt in runs)
    return {
        "runs": runs,
        "longest": longest,
        "starts_with": text[0],
        "ends_with": text[-1],
    }

def score_compact_pattern(text: str, pattern: str) -> int:
    def tokenize(s: str):
        s = s.strip()
        if not s:
            return []
        return s.split()

    words = tokenize(text)
    tokens = tokenize(pattern)

    from functools import lru_cache

    n = len(words)
    m = len(tokens)

    @lru_cache(None)
    def dp(i, j):
        if j == m:
            return 0 if i == n else None
        tok = tokens[j]
        if tok == '?':
            if i >= n:
                return None
            rest = dp(i + 1, j + 1)
            return None if rest is None else 2 + rest
        if tok == '*':
            best = None
            for k in range(i, n + 1):
                rest = dp(k, j + 1)
                if rest is not None:
                    score = (k - i) + rest
                    if best is None or score > best:
                        best = score
            return best
        if i < n and words[i] == tok:
            rest = dp(i + 1, j + 1)
            return None if rest is None else 1 + rest
        return None

    ans = dp(0, 0)
    return -1 if ans is None else ans

def stable_group_sum(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')

    groups = {}
    order = []

    for item in records:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError('each record must be a 3-tuple')
        group_id, weight, label = item

        if not isinstance(group_id, int) or isinstance(group_id, bool):
            raise TypeError('group_id must be an int')
        if not isinstance(weight, (int, float)) or isinstance(weight, bool):
            raise TypeError('weight must be numeric')
        if not isinstance(label, str):
            raise TypeError('label must be a str')

        if group_id not in groups:
            groups[group_id] = [0, []]
            order.append(group_id)
        groups[group_id][0] += weight
        groups[group_id][1].append(label)

    result = []
    for group_id in sorted(order):
        total_weight, labels = groups[group_id]
        result.append((group_id, total_weight, labels))
    return result

from datetime import date


def _parse_iso_date(text):
    if not isinstance(text, str) or len(text) != 10:
        raise ValueError('invalid date')
    if text[4] != '-' or text[7] != '-':
        raise ValueError('invalid date')
    y = text[0:4]
    m = text[5:7]
    d = text[8:10]
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        raise ValueError('invalid date')
    try:
        return date(int(y), int(m), int(d))
    except ValueError:
        raise ValueError('invalid date')


def normalize_event_dates(records):
    result = []
    for record in records:
        try:
            name, start_date, end_date = record
        except Exception:
            raise ValueError('invalid record')
        start = _parse_iso_date(start_date)
        end = _parse_iso_date(end_date)
        if start > end:
            start, end = end, start
        result.append((name, start.isoformat(), end.isoformat()))
    return result

def summarize_event_log(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    count = len(events)
    if count == 0:
        return {
            "count": 0,
            "first_timestamp": None,
            "last_timestamp": None,
            "categories": {},
            "value_sums": {},
            "timeline": [],
        }

    categories = {}
    value_sums = {}
    timeline_items = []
    timestamps = []

    for idx, item in enumerate(events):
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError("each event must be a 3-item tuple")
        timestamp, category, value = item
        if not isinstance(timestamp, int) or not isinstance(category, str) or not isinstance(value, int):
            raise ValueError("invalid event field types")

        timestamps.append(timestamp)
        timeline_items.append((timestamp, idx, category))
        categories[category] = categories.get(category, 0) + 1
        value_sums[category] = value_sums.get(category, 0) + value

    timeline_items.sort(key=lambda x: (x[0], x[1]))
    timeline = [category for _, _, category in timeline_items]

    return {
        "count": count,
        "first_timestamp": min(timestamps),
        "last_timestamp": max(timestamps),
        "categories": categories,
        "value_sums": value_sums,
        "timeline": timeline,
    }

def summarize_runs(values):
    sentinel = object()
    runs = []
    prev = sentinel
    current_value = sentinel
    current_len = 0
    changes = 0
    seen = []

    for x in values:
        if type(x) is not int:
            raise TypeError('all elements must be integers')
        seen.append(x)
        if prev is sentinel:
            current_value = x
            current_len = 1
        elif x == current_value:
            current_len += 1
        else:
            runs.append((current_value, current_len))
            changes += 1
            current_value = x
            current_len = 1
        prev = x

    if prev is sentinel:
        return {'runs': [], 'longest_run': None, 'changes': 0, 'palindrome': True}

    runs.append((current_value, current_len))

    longest_run = runs[0]
    for run in runs[1:]:
        if run[1] > longest_run[1]:
            longest_run = run

    palindrome = seen == seen[::-1]
    return {'runs': runs, 'longest_run': longest_run, 'changes': changes, 'palindrome': palindrome}

def canonicalize_event_log(entries):
    result = []
    seen = set()

    for entry in entries:
        if not isinstance(entry, tuple):
            continue
        if len(entry) == 2:
            timestamp, label = entry
            metadata = {}
        elif len(entry) == 3:
            timestamp, label, metadata = entry
            if not isinstance(metadata, dict):
                continue
            metadata = dict(metadata)
        else:
            continue

        if type(timestamp) is bool or not isinstance(timestamp, int):
            continue
        if not isinstance(label, str):
            continue
        label = label.strip()
        if not label:
            continue

        tags = metadata.get("tags")
        if isinstance(tags, list):
            metadata["tags"] = tuple(tags)

        key = (timestamp, label)
        if key in seen:
            continue
        seen.add(key)
        result.append((timestamp, label, metadata))

    result.sort(key=lambda x: x[0])
    return result

def normalize_routing_table(entries):
    def parse_ip(ip):
        if not isinstance(ip, str):
            raise ValueError("IP must be a string")
        parts = ip.split('.')
        if len(parts) != 4:
            raise ValueError("Invalid IPv4 address")
        octets = []
        for part in parts:
            if part == '' or not part.isdigit():
                raise ValueError("Invalid IPv4 address")
            if len(part) > 1 and part[0] == '+':
                raise ValueError("Invalid IPv4 address")
            value = int(part)
            if value < 0 or value > 255:
                raise ValueError("Invalid IPv4 address")
            octets.append(str(value))
        return '.'.join(octets), tuple(int(x) for x in octets)

    if not isinstance(entries, list):
        raise ValueError("entries must be a list")

    best = {}
    for record in entries:
        if not (isinstance(record, tuple) and len(record) == 4):
            raise ValueError("Each record must be a 4-tuple")
        destination, prefix_length, gateway, metric = record
        dest_norm, dest_key = parse_ip(destination)
        if not isinstance(prefix_length, int) or isinstance(prefix_length, bool) or prefix_length < 0 or prefix_length > 32:
            raise ValueError("Invalid prefix length")
        if gateway is None:
            gw_norm = None
            gw_key = (-1,)
        else:
            gw_norm, gw_key = parse_ip(gateway)
        if not isinstance(metric, int) or isinstance(metric, bool) or metric < 0:
            raise ValueError("Invalid metric")
        key = (dest_norm, prefix_length, gw_norm)
        current = best.get(key)
        if current is None or metric < current[3]:
            best[key] = (dest_norm, prefix_length, gw_norm, metric, dest_key, gw_key)

    def sort_key(item):
        dest_norm, prefix_length, gw_norm, metric, dest_key, gw_key = item
        gw_sort = (0, ()) if gw_norm is None else (1, gw_key)
        return (dest_key, -prefix_length, gw_sort, metric)

    result = []
    for item in sorted(best.values(), key=sort_key):
        result.append((item[0], item[1], item[2], item[3]))
    return result

def compare_patch_counts(original: str, modified: str) -> dict:
    if not isinstance(original, str) or not isinstance(modified, str):
        raise TypeError("both arguments must be strings")

    o_lines = original.splitlines()
    m_lines = modified.splitlines()
    max_len = max(len(o_lines), len(m_lines))

    result = {"added": 0, "removed": 0, "changed": 0, "same": 0}
    for i in range(max_len):
        has_o = i < len(o_lines)
        has_m = i < len(m_lines)
        if has_o and has_m:
            if o_lines[i] == m_lines[i]:
                result["same"] += 1
            else:
                result["changed"] += 1
        elif has_m:
            result["added"] += 1
        else:
            result["removed"] += 1
    return result

