    result.append((current_char, count))
    return result

def normalize_dna_windows(seq, window_size):
    if not isinstance(seq, str):
        raise TypeError("seq must be a string")
    if not isinstance(window_size, int):
        raise TypeError("window_size must be an integer")
    if window_size <= 0:
        raise ValueError("window_size must be positive")

    seq = seq.upper()
    allowed = set("ACGTN")
    for ch in seq:
        if ch not in allowed:
            raise ValueError("seq contains invalid characters")

    result = []
    for i in range(0, len(seq) - len(seq) % window_size, window_size):
        window = seq[i:i + window_size]
        if window and all(ch == 'N' for ch in window):
            result.append('X' * window_size)
        else:
            result.append(window)
    return result

def summarize_sign_blocks(nums):
    def category(x):
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers")
        if x > 0:
            return "positive"
        if x < 0:
            return "negative"
        return "zero"

    it = iter(nums)
    try:
        first = next(it)
    except StopIteration:
        return {"blocks": [], "longest": None, "transitions": 0}

    first_cat = category(first)
    blocks = []
    current_cat = first_cat
    current_len = 1
    transitions = 0
    longest_cat = first_cat
    longest_len = 1

    for x in it:
        cat = category(x)
        if cat == current_cat:
            current_len += 1
        else:
            blocks.append((current_cat, current_len))
            transitions += 1
            if current_len > longest_len:
                longest_cat, longest_len = current_cat, current_len
            current_cat = cat
            current_len = 1
    blocks.append((current_cat, current_len))
    if current_len > longest_len:
        longest_cat, longest_len = current_cat, current_len

    return {"blocks": blocks, "longest": (longest_cat, longest_len), "transitions": transitions}

def summarize_sign_blocks(nums):
    """
    Analyzes a sequence of integers and returns a dictionary with three keys:
    blocks, longest, and transitions.

    :param nums: An iterable of integers.
    :return: A dictionary with keys 'blocks', 'longest', and 'transitions'.
    """
    if not isinstance(nums, Iterable):
        raise TypeError("Input must be an iterable of integers.")

    blocks = []
    longest = None
    transitions = 0

    for num in nums:
        if isinstance(num, int):
            if num == 0:
                if longest is None or longest[1] < 0:
                    longest = (num, 1)
            elif num > 0:
                if longest is None or longest[1] < 0:
                    longest = (num, 1)
            else:
                if longest is None or longest[1] < 0:
                    longest = (num, 1)
            blocks.append((num, 1))
            transitions += 1
        else:
            raise TypeError("All elements in the iterable must be integers.")

    return {
        'blocks': blocks,
        'longest': longest,
        'transitions': transitions
    }

