def normalize_path_windows(path: str) -> str:
    if path == "":
        return ""

    # Detect UNC path: starts with exactly two separators (either / or \),
    # but not three or more.
    is_unc = False
    if len(path) >= 2 and path[0] in "\\/" and path[1] in "\\/":
        is_unc = True
        i = 2
        while i < len(path) and path[i] in "\\/":
            i += 1
        # Normalize all leading separators to exactly two backslashes.
        leading = "\\\\"
    else:
        i = 0
        leading = ""

    drive = ""
    absolute = False
    if not is_unc and len(path) >= 2 and path[1] == ":":
        drive = path[:2]
        i = 2
        if i < len(path) and path[i] in "\\/":
            absolute = True
            while i < len(path) and path[i] in "\\/":
                i += 1
    elif is_unc:
        absolute = True

    components = []
    while i <= len(path):
        j = i
        while j < len(path) and path[j] not in "\\/":
            j += 1
        part = path[i:j]
        if part == "" or part == ".":
            pass
        elif part == "..":
            if components and components[-1] != "..":
                components.pop()
            else:
                if not absolute:
                    components.append("..")
        else:
            components.append(part)
        i = j + 1
        if j >= len(path):
            break

    if is_unc:
        if not components:
            return leading
        return leading + "\\".join(components)

    if drive:
        if absolute:
            if not components:
                return drive + "\\"
            return drive + "\\" + "\\".join(components)
        if not components:
            return drive
        return drive + "\\".join(components) if components[0] == ".." else drive + "\\".join(components)

    if not components:
        return ""
    return "\\".join(components)

def compress_ranges(nums):
    values = []
    for x in nums:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers")
        values.append(x)
    if not values:
        return ""

    unique_sorted = sorted(set(values))
    parts = []
    start = prev = unique_sorted[0]

    for n in unique_sorted[1:]:
        if n == prev + 1:
            prev = n
            continue
        if start == prev:
            parts.append(str(start))
        else:
            parts.append(f"{start}-{prev}")
        start = prev = n

    if start == prev:
        parts.append(str(start))
    else:
        parts.append(f"{start}-{prev}")

    return ";".join(parts)

