def canonicalize_path(path: str) -> str:
    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
        else:
            stack.append(part)

    if absolute:
        return '/' if not stack else '/' + '/'.join(stack)
    return '.' if not stack else '/'.join(stack)

