from math import gcd

def normalized_segment_signature(points):
    pts = list(points)
    if len(pts) < 2:
        return ()

    cleaned = [pts[0]]
    for p in pts[1:]:
        if not (isinstance(p, (tuple, list)) and len(p) == 2 and isinstance(p[0], int) and isinstance(p[1], int)):
            raise TypeError("each point must be a 2-item sequence of integers")
        if not (isinstance(cleaned[-1], (tuple, list)) and len(cleaned[-1]) == 2 and isinstance(cleaned[-1][0], int) and isinstance(cleaned[-1][1], int)):
            raise TypeError("each point must be a 2-item sequence of integers")
        if p[0] != cleaned[-1][0] or p[1] != cleaned[-1][1]:
            cleaned.append(p)

    first = cleaned[0]
    if not (isinstance(first, (tuple, list)) and len(first) == 2 and isinstance(first[0], int) and isinstance(first[1], int)):
        raise TypeError("each point must be a 2-item sequence of integers")

    if len(cleaned) < 2:
        return ()

    signature = []
    prev = cleaned[0]
    for curr in cleaned[1:]:
        dx = curr[0] - prev[0]
        dy = curr[1] - prev[1]
        g = gcd(abs(dx), abs(dy))
        signature.append((dx // g, dy // g))
        prev = curr
    return tuple(signature)

from typing import List, Tuple

def normalized_segment_signature(points: List[Tuple[int, int]]) -> Tuple[Tuple[int, int], ...]:
    """
    Analyzes a polyline-like sequence of 2D integer points.

    Parameters:
    - points: An iterable of (x, y) pairs. Each pair must contain exactly two integers.

    Returns:
    - A tuple of 2-tuples of integers representing the normalized step vectors.
    """
    # Check if the input is valid
    if len(points) < 2:
        return ()

    # Validate each point
    for point in points:
        if not isinstance(point, tuple) or len(point) != 2:
            raise TypeError("Each point must be a 2-item sequence of integers.")

    # Remove consecutive duplicate points
    unique_points = list(set(points))

    # If fewer than 2 points remain, return ()
    if len(unique_points) < 2:
        return ()

    # Normalize each step vector
    normalized_steps = []
    for i in range(len(unique_points) - 1):
        dx = unique_points[i + 1][0] - unique_points[i][0]
        dy = unique_points[i + 1][1] - unique_points[i][1]
        g = gcd(abs(dx), abs(dy))
        if g == 0:
            raise ValueError("Zero-length segments cannot occur after step 4.")
        normalized_steps.append((dx // g, dy // g))

    return tuple(normalized_steps)

