def normalize_nested_paths(data):
    def normalize_string(s):
        if s.startswith('~/'):
            s = '/home/user/' + s[2:]
        elif s.startswith('./'):
            s = s[2:]
        elif s.startswith('../'):
            s = s[3:]

        while '//' in s:
            s = s.replace('//', '/')

        if s == '':
            return '.'
        return s

    def walk(x):
        if isinstance(x, str):
            return normalize_string(x)
        if isinstance(x, bool) or x is None or isinstance(x, int):
            return x
        if isinstance(x, list):
            return [walk(v) for v in x]
        if isinstance(x, tuple):
            return tuple(walk(v) for v in x)
        if isinstance(x, dict):
            return {k: walk(v) for k, v in x.items()}
        raise TypeError('Unsupported type')

    return walk(data)

def normalize_nested_paths(data):
    """
    Normalize nested paths in a given data structure.

    Args:
    data (dict or list/tuple): A nested structure containing dictionaries, lists, tuples, strings, integers, booleans, and None.

    Returns:
    dict or list/tuple: A new structure with normalized paths.
    """
    def normalize_path(path):
        if isinstance(path, str):
            if path.startswith("~/"):
                return f"/home/user/{path[len("~/"):]}"
            elif path.startswith("./"):
                return path[len("./"):]
            elif path.startswith("../"):
                if len(path) == 2:
                    return ""
                else:
                    return path[2:]
            elif path == "//":
                return path.replace("//", "/")
            else:
                return path
        elif isinstance(path, (list, tuple)):
            return [normalize_path(item) for item in path]
        elif isinstance(path, int) or isinstance(path, bool) or path is None:
            return path
        else:
            raise TypeError(f"Unsupported type: {type(path)}")

    return normalize_path(data)

