def normalize_selector(selector: str) -> str:
    def valid_ident(name: str) -> bool:
        return bool(name) and all(ch.isalnum() or ch == '_' for ch in name)

    if selector.strip() == '':
        return ''

    out = []
    for token in selector.split():
        if token.count('.') > 1 or token.count('#') > 1:
            raise ValueError('multiple markers in token')

        elem = ''
        cls = ''
        ident = ''

        first_dot = token.find('.') if '.' in token else len(token)
        first_hash = token.find('#') if '#' in token else len(token)
        cut = min(first_dot, first_hash)
        if cut != len(token):
            elem = token[:cut]
            rest = token[cut:]
        else:
            elem = token
            rest = ''

        if elem and not elem.isalpha():
            raise ValueError('invalid element name')

        if rest:
            if rest[0] == '#':
                rest = rest[1:]
                if not rest:
                    raise ValueError('empty id')
                j = rest.find('.')
                if j == -1:
                    ident = rest
                    rest = ''
                else:
                    ident = rest[:j]
                    rest = rest[j:]
            elif rest[0] == '.':
                rest = rest[1:]
                if not rest:
                    raise ValueError('empty class')
                j = rest.find('#')
                if j == -1:
                    cls = rest
                    rest = ''
                else:
                    cls = rest[:j]
                    rest = rest[j:]
            else:
                raise ValueError('invalid token')

            if rest:
                if rest[0] == '#':
                    if ident:
                        raise ValueError('multiple ids')
                    rest = rest[1:]
                    if not rest:
                        raise ValueError('empty id')
                    j = rest.find('.')
                    if j != -1:
                        raise ValueError('too many markers')
                    ident = rest
                    rest = ''
                elif rest[0] == '.':
                    if cls:
                        raise ValueError('multiple classes')
                    rest = rest[1:]
                    if not rest:
                        raise ValueError('empty class')
                    j = rest.find('#')
                    if j != -1:
                        raise ValueError('too many markers')
                    cls = rest
                    rest = ''

        if ident and not valid_ident(ident):
            raise ValueError('invalid id')
        if cls and not valid_ident(cls):
            raise ValueError('invalid class')

        normalized = elem
        if ident:
            normalized += '#' + ident
        if cls:
            normalized += '.' + cls
        out.append(normalized)

    return ' '.join(out)

import re

def normalize_selector(selector: str) -> str:
    """
    Normalize a simple CSS-like selector string according to the specified rules.

    :param selector: A string representing a CSS selector.
    :return: A normalized string.
    """
    # Split the input string on whitespace
    tokens = re.split(r'\s+', selector)

    # Initialize variables to track the current token type and its value
    current_token_type = None
    current_value = ""

    # Iterate over each token
    for token in tokens:
        if not token:
            continue

        # Check if the token is a class or id
        if token.startswith('#'):
            if current_token_type != 'id':
                raise ValueError("Class and id tokens must be separated by a period.")
            current_value = token[1:]
        elif token.startswith('.'):
            if current_token_type != 'class':
                raise ValueError("Class and id tokens must be separated by a period.")
            current_value = token[1:]
        else:
            # Check if the token is an element name
            if not token.isalnum():
                raise ValueError("Element names must be alphabetic only.")
            current_value = token

        # Update the current token type and value
        current_token_type = token_type
        current_value = current_value

    # Join the normalized tokens with a single space
    return ' '.join(current_value)

