    if seen_any:
        result.append((current_value, count))
    return result

def normalize_inventory_events(events):
    inventory = {}
    processed = []

    for idx, event in enumerate(events):
        if not isinstance(event, tuple) or len(event) != 3:
            raise TypeError("each event must be a 3-tuple")
        timestamp, item, delta = event
        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise TypeError("timestamp must be an integer")
        if timestamp < 0:
            raise TypeError("timestamp must be non-negative")
        if not isinstance(item, str):
            raise TypeError("item must be a string")
        if item == "":
            raise TypeError("item must be non-empty")
        if not isinstance(delta, int) or isinstance(delta, bool):
            raise TypeError("delta must be an integer")
        processed.append((timestamp, idx, item, delta))

    processed.sort(key=lambda x: (x[0], x[1]))

    for _, _, item, delta in processed:
        new_count = inventory.get(item, 0) + delta
        if new_count < 0:
            raise ValueError("inventory count cannot be negative")
        if new_count == 0:
            inventory.pop(item, None)
        else:
            inventory[item] = new_count

    return sorted(inventory.items(), key=lambda x: x[0])

def ranked_common_elements(list_a, list_b):
    def validate(seq):
        for x in seq:
            if type(x) is not int:
                raise TypeError("all elements must be integers")

    validate(list_a)
    validate(list_b)

    counts_a = {}
    counts_b = {}
    for x in list_a:
        counts_a[x] = counts_a.get(x, 0) + 1
    for x in list_b:
        counts_b[x] = counts_b.get(x, 0) + 1

    common = set(counts_a) & set(counts_b)
    ranked = []
    for x in common:
        ranked.append((-(counts_a[x] + counts_b[x]), x))
    ranked.sort()
    return [x for _, x in ranked]

def normalize_deltas(deltas):
    try:
        iterator = iter(deltas)
    except TypeError:
        raise TypeError("deltas must be iterable")

    net_change = 0
    runs = []
    current_sign = None
    current_len = 0

    for x in iterator:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("all elements must be integers and not booleans")
        net_change += x
        if x == 0:
            continue
        sign = 1 if x > 0 else -1
        if current_sign is None:
            current_sign = sign
            current_len = 1
        elif sign == current_sign:
            current_len += 1
        else:
            runs.append((current_sign, current_len))
            current_sign = sign
            current_len = 1
    if current_sign is not None:
        runs.append((current_sign, current_len))
    return net_change, runs

def normalize_ledger(entries):
    result = {"balance": 0, "valid_entries": 0, "invalid_entries": 0}
    for raw in entries:
        if not isinstance(raw, str):
            result["invalid_entries"] += 1
            continue
        s = raw.strip()
        parts = s.split(":")
        if len(parts) != 3:
            result["invalid_entries"] += 1
            continue
        typ, amount_str, note = parts
        if typ not in ("CREDIT", "DEBIT"):
            result["invalid_entries"] += 1
            continue
        if amount_str == "" or not amount_str.isdigit():
            result["invalid_entries"] += 1
            continue
        if note == "" or ":" in note:
            result["invalid_entries"] += 1
            continue
        amount = int(amount_str)
        if typ == "CREDIT":
            result["balance"] += amount
        else:
            result["balance"] -= amount
        result["valid_entries"] += 1
    return result

def render_table(data, headers=None, align='left'):
    def pad(text, width):
        extra = width - len(text)
        if align == 'left':
            return text + ' ' * extra
        if align == 'right':
            return ' ' * extra + text
        # center
        left = extra // 2
        right = extra - left
        return ' ' * left + text + ' ' * right

    if align not in ('left', 'right', 'center'):
        raise ValueError('invalid align')
    if headers is not None and not isinstance(headers, (list, tuple)):
        raise ValueError('headers must be list or tuple')
    if not isinstance(data, list):
        raise ValueError('data must be a list')

    rows = []
    if headers is not None:
        header_row = [str(x) for x in headers]
        rows.append(header_row)
        expected_cols = len(header_row)
    else:
        expected_cols = len(data[0]) if data else 0

    for row in data:
        if not isinstance(row, (list, tuple)):
            raise ValueError('each row must be list or tuple')
        if len(row) != expected_cols:
            raise ValueError('inconsistent row length')
        rows.append([str(x) for x in row])

    if not rows:
        return ''

    col_widths = [0] * expected_cols
    for row in rows:
        for i, cell in enumerate(row):
            if len(cell) > col_widths[i]:
                col_widths[i] = len(cell)

    rendered = []
    for row in rows:
        pieces = []
        for i, cell in enumerate(row):
            pieces.append(pad(cell, col_widths[i]))
        rendered.append(' | '.join(pieces))
    return '\n'.join(rendered)

def choose_priority_items(items, budget):
    if budget < 0:
        raise ValueError("budget must be non-negative")

    items = list(items)
    for cost, priority in items:
        if cost < 0 or priority < 0:
            raise ValueError("item values must be non-negative")

    n = len(items)
    best = None  # (priority_sum, total_cost, indices_tuple)

    for mask in range(1 << n):
        total_cost = 0
        total_priority = 0
        chosen = []
        for i in range(n):
            if mask & (1 << i):
                cost, priority = items[i]
                total_cost += cost
                total_priority += priority
                if total_cost > budget:
                    break
                chosen.append(i)
        else:
            candidate = (total_priority, total_cost, tuple(chosen))
            if best is None:
                best = candidate
            else:
                if candidate[0] > best[0]:
                    best = candidate
                elif candidate[0] == best[0]:
                    if candidate[1] < best[1]:
                        best = candidate
                    elif candidate[1] == best[1] and candidate[2] < best[2]:
                        best = candidate

    return list(best[2]) if best is not None else []

def normalize_sensor_log(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')

    def valid_sensor_id(s):
        if not isinstance(s, str) or s == '':
            return False
        if s[0].isdigit():
            return False
        for ch in s:
            if not (ch.isalnum() or ch == '_'):
                return False
        return True

    result = {}
    for entry in entries:
        if isinstance(entry, str):
            if entry.count(':') != 1:
                raise ValueError('malformed string entry')
            sensor_id, reading_text = entry.split(':', 1)
            if not valid_sensor_id(sensor_id):
                raise ValueError('invalid sensor id')
            if reading_text == '' or reading_text[0] in '+-' and len(reading_text) == 1:
                raise ValueError('invalid reading')
            try:
                reading = int(reading_text)
            except Exception:
                raise ValueError('invalid reading')
            if str(reading) != reading_text and not (reading_text.startswith('+') and str(reading) == reading_text[1:]):
                raise ValueError('invalid reading')
        elif isinstance(entry, (tuple, list)):
            if len(entry) != 2:
                raise ValueError('malformed pair entry')
            sensor_id, reading = entry
            if not valid_sensor_id(sensor_id):
                raise ValueError('invalid sensor id')
            if not isinstance(reading, int):
                raise ValueError('reading must be int')
        else:
            raise ValueError('malformed entry')
        result[sensor_id] = reading

    return ';'.join(f'{k}={result[k]}' for k in sorted(result))

def normalize_event_log(events):
    valid = []
    for idx, record in enumerate(events):
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        timestamp, category, value = record
        if not isinstance(timestamp, int):
            continue
        if not isinstance(category, str) or category == '':
            continue
        if not isinstance(value, (int, float)):
            continue
        valid.append((timestamp, idx, category, value))

    if not valid:
        return []

    valid.sort(key=lambda x: (x[0], x[1]))

    result = []
    current = {}
    order = []

    for timestamp, _, category, value in valid:
        if category not in current:
            current[category] = {
                'count': 0,
                'total': 0,
                'first_timestamp': timestamp,
                'last_timestamp': timestamp,
            }
            order.append(category)
        summary = current[category]
        summary['count'] += 1
        summary['total'] += value
        summary['last_timestamp'] = timestamp

    for category in order:
        result.append((category, current[category]))
    return result

def render_sparse_grid(rows, cols, cells, fill='.'):
    if rows < 0 or cols < 0:
        raise ValueError('rows and cols must be non-negative')
    grid = [[str(fill) for _ in range(cols)] for _ in range(rows)]
    for cell in cells:
        try:
            r, c, v = cell
        except Exception as e:
            raise TypeError('each cell must be a length-3 iterable') from e
        if r < 0 or r >= rows or c < 0 or c >= cols:
            raise IndexError('cell coordinates out of bounds')
        grid[r][c] = str(v)
    return '\n'.join(' '.join(row) for row in grid)

def render_sparse_grid(rows, cols, cells, fill='.'):
    """
    Renders a sparse grid with specified dimensions and cell values.

    Parameters:
    - rows: non-negative integer number of rows.
    - cols: non-negative integer number of columns.
    - cells: an iterable of (row_index, col_index, value) triples.
    - fill: a string used for every cell that is not explicitly assigned; default is `'.'`.

    Returns:
    - A string representing the sparse grid.
    """
    # Check for valid inputs
    if not isinstance(rows, int) or not isinstance(cols, int):
        raise ValueError("Rows and cols must be integers.")
    if rows < 0 or cols < 0:
        raise ValueError("Rows and cols must be non-negative.")
    if not isinstance(cells, list) or len(cells) == 0:
        raise TypeError("Cells must be a list of triples.")
    if not all(isinstance(cell, tuple) for cell in cells):
        raise TypeError("Each cell must be a tuple of three integers.")
    if rows == 0 or cols == 0:
        return fill * rows * cols

    # Initialize the grid
    grid = []
    for row_index in range(rows):
        row = []
        for col_index in range(cols):
            if (row_index, col_index) in cells:
                row.append(str(cells[(row_index, col_index)]))
            else:
                row.append(fill)
        grid.append(' '.join(row))

    return '\n'.join(grid)

