def collapse_sorted_ranges(nums):
    try:
        items = list(nums)
    except TypeError:
        raise TypeError("nums must be iterable")

    for x in items:
        if type(x) is not int:
            raise TypeError("all elements must be integers")

    if not items:
        return []

    values = sorted(set(items))
    ranges = []
    start = end = values[0]

    for v in values[1:]:
        if v == end + 1:
            end = v
        else:
            ranges.append([start, end])
            start = end = v
    ranges.append([start, end])
    return ranges

def canonical_rle(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if text == '':
        return ''

    parts = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f"{count}#{current}")
            current = ch
            count = 1
    parts.append(f"{count}#{current}")
    return '|'.join(parts)

def normalize_inventory(events):
    stock = {}
    for event in events:
        if not isinstance(event, tuple) or len(event) != 3:
            continue
        sku, op, amount = event
        if not isinstance(sku, str) or sku == '':
            continue
        if op not in ('+', '-'):
            continue
        if not isinstance(amount, int) or isinstance(amount, bool):
            continue
        if amount < 0:
            continue
        current = stock.get(sku, 0)
        if op == '+':
            stock[sku] = current + amount
        else:
            stock[sku] = current - amount if current >= amount else 0
    return {k: stock[k] for k in sorted(k for k, v in stock.items() if v > 0)}

def compress_runs(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list of integers")
    for item in values:
        if not isinstance(item, int):
            raise TypeError("values must contain only integers")
    if not values:
        return []

    result = []
    current = values[0]
    count = 1
    for item in values[1:]:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

