def split_inventory_by_weight(items, max_weight):
    if not isinstance(max_weight, int):
        raise TypeError('max_weight must be an integer')
    if max_weight < 0:
        raise ValueError('max_weight must be non-negative')
    if items == []:
        return []
    result = []
    current_shipment = []
    current_weight = 0
    for item in items:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each item must be a 2-tuple')
        name, weight = item
        if not isinstance(name, str):
            raise TypeError('item name must be a string')
        if not isinstance(weight, int):
            raise TypeError('item weight must be an integer')
        if weight < 0:
            raise ValueError('item weight must be non-negative')
        if current_shipment and current_weight + weight > max_weight:
            result.append(current_shipment)
            current_shipment = [name]
            current_weight = weight
        else:
            if not current_shipment and weight > max_weight:
                current_shipment = [name]
                current_weight = weight
            else:
                current_shipment.append(name)
                current_weight += weight
    if current_shipment:
        result.append(current_shipment)
    return result

