def normalize_ledger(entries):
    def is_leap(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def valid_date(date_str):
        parts = date_str.split('-')
        if len(parts) != 3:
            return False
        y_s, m_s, d_s = parts
        if len(y_s) != 4 or len(m_s) != 2 or len(d_s) != 2 or not (y_s.isdigit() and m_s.isdigit() and d_s.isdigit()):
            return False
        year = int(y_s)
        month = int(m_s)
        day = int(d_s)
        if not (2000 <= year <= 2099):
            return False
        if not (1 <= month <= 12):
            return False
        days_in_month = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return 1 <= day <= days_in_month[month - 1]

    def valid_amount(amount_str):
        if amount_str == '':
            return False
        if amount_str[0] in '+-':
            digits = amount_str[1:]
            if digits == '':
                return False
            return digits.isdigit()
        return amount_str.isdigit()

    normalized = []
    for entry in entries:
        parts = entry.split('|', 2)
        if len(parts) != 3:
            raise ValueError('invalid entry')
        date_part = parts[0].strip()
        amount_part = parts[1].strip()
        desc_part = parts[2].strip()
        if not valid_date(date_part):
            raise ValueError('invalid entry')
        if not valid_amount(amount_part):
            raise ValueError('invalid entry')
        normalized.append(f'{date_part} | {str(int(amount_part))} | {desc_part}')
    return normalized

def encode_rle_preserving_case(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return ""
    parts = []
    current = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(current + (str(count) if count > 1 else ""))
            current = ch
            count = 1
    parts.append(current + (str(count) if count > 1 else ""))
    return "".join(parts)

def compact_codepoints(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if text == "":
        return ""

    parts = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(current if count == 1 else f"{current}*{count}")
            current = ch
            count = 1

    parts.append(current if count == 1 else f"{current}*{count}")
    return "|".join(parts)

def merge_runs(items):
    if isinstance(items, (str, bytes, bytearray)):
        seq = items
    else:
        try:
            seq = list(items)
        except TypeError:
            raise TypeError('items must be a finite sequence')
    if len(seq) == 0:
        return []
    out = []
    prev = seq[0]
    try:
        hash(prev)
    except TypeError:
        raise TypeError('items contains an unhashable element')
    count = 1
    for x in seq[1:]:
        try:
            hash(x)
        except TypeError:
            raise TypeError('items contains an unhashable element')
        if x == prev:
            count += 1
        else:
            out.append((prev, count))
            prev = x
            count = 1
    out.append((prev, count))
    return out

def decode_rle_stream(chunks):
    out = []
    count = None
    seen_any = False

    for chunk in chunks:
        if not isinstance(chunk, str):
            raise ValueError("all chunks must be strings")
        seen_any = True
        for ch in chunk:
            if ch.isdigit():
                if count is None:
                    count = int(ch)
                else:
                    count = count * 10 + int(ch)
            else:
                if count is None:
                    raise ValueError("character encountered before count")
                out.append(ch * count)
                count = None

    if count is not None:
        raise ValueError("stream ended with pending count")

    return "".join(out)

def decode_rle_stream(chunks):
    """
    Decodes a run-length encoded text stream.

    :param chunks: An iterable of strings representing the encoded text.
    :return: A fully decoded string.
    """
    decoded = ""
    count = 0
    for chunk in chunks:
        for char in chunk:
            if char.isdigit():
                count = int(char)
            elif char == ' ':
                continue
            else:
                raise ValueError(f"Invalid character '{char}' at position {chunk.index(char)}")
        if count > 0:
            decoded += char * count
            count = 0
    if count > 0:
        decoded += char * count
    return decoded

