def segment_runs(items):
    """
    Given a list of items, return a list of tuples representing the maximal consecutive runs of equal values.

    :param items: List of items (integers, strings, booleans, etc.)
    :return: List of tuples (value, start, length)
    """
    if not isinstance(items, list):
        raise TypeError("Input must be a list.")

    if not all(isinstance(item, (int, str, bool)) for item in items):
        raise TypeError("All items in the list must be comparable.")

    max_length = 0
    result = []

    for i, item in enumerate(items):
        if item == items[i - 1]:
            current_length += 1
        else:
            if current_length > max_length:
                result.append((items[i - 1], i - current_length + 1))
            current_length = 1

    if current_length > max_length:
        result.append((items[-1], len(items) - current_length + 1))

    return result

