def normalize_recipe_ingredients(ingredients):
    totals = {}
    for entry in ingredients:
        if not isinstance(entry, (list, tuple)) or len(entry) != 2:
            continue
        name, quantity = entry
        if not isinstance(name, str):
            continue
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)):
            continue
        normalized_name = name.strip().lower()
        if normalized_name == "":
            continue
        if normalized_name in totals:
            totals[normalized_name] += quantity
        else:
            totals[normalized_name] = quantity
    result = []
    for name in sorted(totals):
        total = totals[name]
        if isinstance(total, float) and total.is_integer():
            total = int(total)
        elif isinstance(total, int):
            total = int(total)
        result.append([name, total])
    return result

def normalize_role_records(records):
    if records == []:
        return []

    normalized = []
    seen = set()

    for record in records:
        if not hasattr(record, '__len__') or len(record) != 2:
            raise ValueError('Each record must be a 2-item sequence')
        user_id, role_string = record
        if type(user_id) is not int:
            raise ValueError('user_id must be an int and not a bool')
        if not isinstance(role_string, str):
            raise ValueError('role_string must be a str')
        if role_string == '' or not all(('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ch == '_' for ch in role_string):
            raise ValueError('role_string must be non-empty ASCII letters/underscores only')

        norm_role = role_string.lower()
        key = (user_id, norm_role)
        if key not in seen:
            seen.add(key)
            normalized.append([user_id, norm_role])

    normalized.sort(key=lambda item: (item[0], item[1]))
    return normalized

def summarize_moves(moves):
    x = 0
    y = 0
    min_x = 0
    min_y = 0
    max_x = 0
    max_y = 0
    visited = {(0, 0)}
    invalid_count = 0

    def apply(direction, steps):
        nonlocal x, y, min_x, min_y, max_x, max_y
        for _ in range(steps):
            if direction == 'N':
                y += 1
            elif direction == 'S':
                y -= 1
            elif direction == 'E':
                x += 1
            else:
                x -= 1
            visited.add((x, y))
            if x < min_x:
                min_x = x
            if y < min_y:
                min_y = y
            if x > max_x:
                max_x = x
            if y > max_y:
                max_y = y

    for move in moves:
        if not isinstance(move, str) or len(move) < 2:
            invalid_count += 1
            continue
        direction = move[0]
        steps_text = move[1:]
        if direction not in {'N', 'S', 'E', 'W'} or not steps_text.isdigit():
            invalid_count += 1
            continue
        steps = int(steps_text)
        apply(direction, steps)

    return {
        'final_position': (x, y),
        'bounding_box': (min_x, min_y, max_x, max_y),
        'invalid_count': invalid_count,
        'visited_count': len(visited),
    }

def analyze_token_stream(tokens):
    if not isinstance(tokens, (list, tuple)):
        raise TypeError("tokens must be a list or tuple of strings")
    for t in tokens:
        if not isinstance(t, str):
            raise TypeError("all tokens must be strings")

    count = len(tokens)
    distinct = len(set(tokens))
    all_upper = True
    longest = ""
    palindromes = []

    for t in tokens:
        if t == "" or t.upper() != t:
            all_upper = False
        if len(t) > len(longest):
            longest = t
        if t == t[::-1]:
            palindromes.append(t)

    if count == 0:
        boundary = ("", "")
    else:
        boundary = (tokens[0][-1], tokens[-1][0])

    return {
        "count": count,
        "distinct": distinct,
        "all_upper": all_upper,
        "longest": longest,
        "boundary": boundary,
        "palindrome_tokens": palindromes,
    }

def normalize_event_log(events):
    valid_segments = []
    prev = object()

    for event in events:
        if not isinstance(event, tuple) or len(event) != 2:
            continue
        kind, payload = event

        if kind == "num" and isinstance(payload, int) and not isinstance(payload, bool):
            seg = f"N:{abs(payload)}"
        elif kind == "text" and isinstance(payload, str):
            seg = f"T:{payload.strip().lower()}"
        elif kind == "mark" and payload is None:
            seg = "M"
        else:
            continue

        if seg != prev:
            valid_segments.append(seg)
            prev = seg

    return "|".join(valid_segments)

def decode_rle_grid(rows, encoding):
    if not isinstance(rows, int) or rows <= 0:
        raise ValueError("rows must be a positive integer")
    if not isinstance(encoding, list):
        raise ValueError("encoding must be a list")

    decoded = []
    for pair in encoding:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise ValueError("each encoding item must be a 2-item sequence")
        count, value = pair
        if not isinstance(count, int) or count <= 0:
            raise ValueError("count must be a positive integer")
        if not isinstance(value, str) or len(value) != 1:
            raise ValueError("value must be a single-character string")
        decoded.extend([value] * count)

    if len(decoded) % rows != 0:
        raise ValueError("decoded cell count must be divisible by rows")

    cols = len(decoded) // rows
    return [decoded[i * cols:(i + 1) * cols] for i in range(rows)]

def normalize_event_tags(events):
    result = []
    seen = set()
    for event in events:
        if len(event) != 3:
            raise ValueError('Each event must be a 3-tuple')
        category, subcategory, tags = event
        if not isinstance(category, str):
            raise TypeError('category must be a string')
        if subcategory is not None and not isinstance(subcategory, str):
            raise TypeError('subcategory must be a string or None')
        try:
            tag_iter = iter(tags)
        except TypeError:
            raise TypeError('tags must be iterable')

        cat_tag = category.strip().upper().replace(' ', '-')
        if cat_tag not in seen:
            seen.add(cat_tag)
            result.append(cat_tag)

        if subcategory is not None:
            sub_tag = subcategory.strip().lower().replace(' ', '_')
            if sub_tag not in seen:
                seen.add(sub_tag)
                result.append(sub_tag)

        for t in tag_iter:
            if not isinstance(t, str):
                raise TypeError('each tag must be a string')
            norm = t.strip()
            if norm == '':
                continue
            if norm not in seen:
                seen.add(norm)
                result.append(norm)
    return result

def normalize_event_log(events):
    result = []
    for event in events:
        is_mapping = hasattr(event, 'keys') and hasattr(event, '__getitem__')
        if is_mapping:
            if 'id' not in event or 'type' not in event or 'value' not in event:
                raise ValueError('missing required key')
            raw_id = event['id']
            raw_type = event['type']
            raw_value = event['value']
        else:
            try:
                if len(event) != 3:
                    raise TypeError('invalid event shape')
            except TypeError:
                raise TypeError('invalid event shape')
            raw_id, raw_type, raw_value = event

        norm_id = int(raw_id)
        norm_type = str(raw_type).strip()
        norm_value = float(raw_value)

        if norm_type == '':
            continue
        if norm_value != norm_value:  # NaN check
            continue
        result.append((norm_id, norm_type, norm_value))
    return result

def extract_balanced_sections(text: str) -> list[str]:
    sections = []
    stack = []
    start_stack = []

    for i, ch in enumerate(text):
        if ch == '(':
            if not stack:
                start_stack.append(i)
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
                if not stack:
                    start = start_stack.pop()
                    sections.append(text[start:i+1])
            else:
                continue
    return sections

def normalize_recipe_identifier(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")

    s = s.strip().lower()
    out = []
    prev_underscore = False

    for ch in s:
        if ch.isspace():
            if not prev_underscore:
                out.append('_')
                prev_underscore = True
            continue
        if 'a' <= ch <= 'z' or '0' <= ch <= '9' or ch == '-' or ch == '_':
            if ch == '_':
                if not prev_underscore:
                    out.append(ch)
                    prev_underscore = True
            else:
                out.append(ch)
                prev_underscore = False
    result = ''.join(out).strip('_')
    while '__' in result:
        result = result.replace('__', '_')
    return result

def best_window_sum(values, k):
    if not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k < 1:
        raise ValueError("k must be at least 1")

    vals = list(values)
    n = len(vals)
    if k > n:
        return None

    window_sum = sum(vals[:k])
    best = window_sum
    for i in range(k, n):
        window_sum += vals[i] - vals[i - k]
        if window_sum > best:
            best = window_sum
    return best

def normalize_ragged_grid(grid):
    if not isinstance(grid, list):
        raise TypeError("grid must be a list of rows")

    max_len = 0
    for row in grid:
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        if len(row) > max_len:
            max_len = len(row)
        for value in row:
            if not isinstance(value, int):
                raise TypeError("all row elements must be integers")

    result = []
    for row in grid:
        new_row = row[:] + [0] * (max_len - len(row))
        result.append(new_row)
    return result

def merge_intervals_strict(intervals):
    items = []
    for interval in intervals:
        try:
            start, end = interval
        except Exception:
            raise ValueError("Each interval must contain exactly two elements")
        if start > end:
            raise ValueError("Interval start cannot be greater than end")
        items.append((start, end))

    if not items:
        return []

    items.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = items[0]

    for start, end in items[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end

    merged.append([cur_start, cur_end])
    return merged

def merge_sorted_intervals(intervals):
    if intervals is None:
        raise TypeError("intervals must be a list of intervals")
    normalized = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each interval must be a pair")
        a, b = item
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError("interval endpoints must be integers")
        if a > b:
            raise ValueError("interval start must be <= end")
        normalized.append([a, b])
    if not normalized:
        return []
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def normalize_inventory(records):
    if records == []:
        return []
    totals = {}
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError('each record must be a tuple of length 3')
        warehouse, item, quantity = rec
        if not isinstance(warehouse, str) or not isinstance(item, str) or not isinstance(quantity, int):
            raise ValueError('invalid record types')
        w = warehouse.strip()
        i = item.strip()
        if w == '' or i == '':
            raise ValueError('warehouse and item must be non-empty after stripping')
        key = (w, i)
        totals[key] = totals.get(key, 0) + quantity
    return [(w, i, totals[(w, i)]) for (w, i) in sorted(totals.keys())]

def normalize_inventory(records):
    if not isinstance(records, list):
        raise ValueError("records must be a list")

    merged = {}
    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a tuple of length 3")
        product_code, quantity, price = record
        if not isinstance(product_code, str):
            raise ValueError("product_code must be a string")
        if not isinstance(quantity, int):
            raise ValueError("quantity must be an integer")
        if not isinstance(price, (int, float)):
            raise ValueError("price must be a number")

        code = product_code.strip().upper()
        if code == "":
            continue

        if code not in merged:
            merged[code] = [0, 0.0]
        merged[code][0] += quantity
        merged[code][1] += quantity * float(price)

    result = []
    for code in sorted(merged):
        total_qty, total_weighted = merged[code]
        if total_qty == 0:
            avg_price = 0.0
        else:
            avg_price = round(total_weighted / total_qty, 2)
        result.append((code, total_qty, avg_price))
    return result

