def normalize_event_schedule(events):
    valid = []
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 4:
            continue
        day, start, end, label = rec
        if not isinstance(day, str) or not day:
            continue
        if not isinstance(label, str) or not label:
            continue
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        if start >= end:
            continue
        valid.append((day, start, end, label))

    by_day = {}
    for day, start, end, label in valid:
        by_day.setdefault(day, []).append((start, end, label))

    result = []
    for day in sorted(by_day):
        intervals = sorted(by_day[day], key=lambda x: (x[0], x[1], x[2]))
        merged = []
        for start, end, label in intervals:
            if not merged:
                merged.append([start, end, label])
                continue
            ps, pe, pl = merged[-1]
            if label == pl and start <= pe:
                merged[-1][1] = max(pe, end)
            else:
                merged.append([start, end, label])
        result.append((day, [(s, e, l) for s, e, l in merged]))
    return result

def normalize_router_rules(rules):
    import re

    allowed_methods = {"GET", "POST", "PUT", "DELETE", "PATCH"}
    target_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    unreserved = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")

    def decode_path(path):
        res = []
        i = 0
        n = len(path)
        while i < n:
            ch = path[i]
            if ch == '%' and i + 2 < n and all(c in '0123456789ABCDEFabcdef' for c in path[i+1:i+3]):
                byte = int(path[i+1:i+3], 16)
                c = chr(byte)
                if c in unreserved:
                    res.append(c)
                else:
                    res.append('%' + path[i+1:i+3].upper())
                i += 3
            else:
                res.append(ch)
                i += 1
        return ''.join(res)

    def normalize_path(path):
        if not path:
            raise ValueError('empty path')
        absolute = path.startswith('/')
        path = decode_path(path)
        parts = [p for p in path.split('/') if p != '']
        stack = []
        for part in parts:
            if part == '.':
                continue
            if part == '..':
                if stack and stack[-1] != '..':
                    stack.pop()
                else:
                    if absolute:
                        raise ValueError('path escapes root')
                    stack.append('..')
            else:
                stack.append(part)
        if absolute:
            norm = '/' + '/'.join(stack)
            return '/' if norm == '' else norm
        else:
            norm = '/'.join(stack)
            return norm or '.'

    out = []
    seen = set()
    for rule in rules:
        if not isinstance(rule, str):
            raise ValueError('rule must be string')
        if '->' in rule:
            left, right = rule.split('->', 1)
            target = right.strip()
            if not target_re.match(target):
                raise ValueError('invalid target')
        else:
            left = rule
            target = None
        left = left.strip()
        if not left:
            raise ValueError('empty rule')
        parts = left.split(None, 1)
        if len(parts) != 2:
            raise ValueError('missing path')
        method, path = parts[0].upper(), parts[1].strip()
        if method not in allowed_methods:
            raise ValueError('invalid method')
        norm_path = normalize_path(path)
        normalized = f'{method} {norm_path}'
        if target is not None:
            normalized += f' -> {target}'
        if normalized not in seen:
            seen.add(normalized)
            out.append(normalized)
    return out

def normalize_chat_threads(threads):
    if not isinstance(threads, list):
        raise TypeError('threads must be a list')

    topic_data = {}
    thread_count = 0
    total_messages = 0
    total_read = 0

    for thread in threads:
        if not isinstance(thread, dict) or set(thread.keys()) != {'topic', 'messages'}:
            continue
        topic = thread['topic']
        messages = thread['messages']
        if not isinstance(topic, str) or not isinstance(messages, list):
            continue

        thread_count += 1
        entry = topic_data.setdefault(topic, {'message_count': 0, 'read_count': 0, 'senders': set()})

        for message in messages:
            if not isinstance(message, dict) or set(message.keys()) != {'sender', 'text', 'read'}:
                continue
            sender = message['sender']
            text = message['text']
            read = message['read']
            if not isinstance(sender, str) or not isinstance(text, str) or not isinstance(read, bool):
                continue

            entry['message_count'] += 1
            if read:
                entry['read_count'] += 1
            entry['senders'].add(sender)
            total_messages += 1
            if read:
                total_read += 1

    topics = []
    for topic in sorted(topic_data):
        entry = topic_data[topic]
        topics.append({
            'topic': topic,
            'message_count': entry['message_count'],
            'read_count': entry['read_count'],
            'senders': sorted(entry['senders']),
        })

    return {
        'topics': topics,
        'totals': {
            'thread_count': thread_count,
            'message_count': total_messages,
            'read_count': total_read,
            'topic_count': len(topic_data),
        }
    }

def decode_rle_segments(encoded):
    if encoded == "":
        return []
    if not isinstance(encoded, str):
        raise ValueError("encoded must be a string")
    parts = encoded.split("|")
    if any(part == "" for part in parts):
        raise ValueError("empty segment")
    result = []
    for part in parts:
        if ":" not in part:
            raise ValueError("missing colon")
        count_text, char = part.split(":", 1)
        if count_text == "" or char == "":
            raise ValueError("malformed segment")
        if count_text.startswith("-") or not count_text.isdigit():
            raise ValueError("invalid count")
        if len(char) != 1:
            raise ValueError("segment must contain exactly one character")
        count = int(count_text)
        result.append(char * count)
    return result

def compress_ranges(values):
    if not isinstance(values, list):
        raise TypeError('values must be a list')
    for x in values:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
    if not values:
        return []
    nums = sorted(set(values))
    ranges = []
    start = end = nums[0]
    for n in nums[1:]:
        if n == end + 1:
            end = n
        else:
            ranges.append((start, end))
            start = end = n
    ranges.append((start, end))
    return ranges

def canonicalize_path(path):
    if path == '':
        return '.'

    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)

    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def compress_intervals(intervals):
    if not isinstance(intervals, list):
        raise ValueError('intervals must be a list')
    normalized = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError('each interval must have exactly two elements')
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('interval endpoints must be integers')
        if start > end:
            raise ValueError('interval start must not exceed end')
        normalized.append((start, end))
    if not normalized:
        return []
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [list(normalized[0])]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

def normalize_schedule(records):
    normalized = []
    for idx, rec in enumerate(records):
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        label, start, end = rec
        if not isinstance(label, str) or label == '':
            continue
        if not isinstance(start, int) or not isinstance(end, int):
            continue
        if start >= end:
            continue
        normalized.append((start, idx, {'label': label.upper().replace('_', ' '), 'start': start, 'end': end}))
    normalized.sort(key=lambda x: (x[0], x[1]))
    return [item[2] for item in normalized]

def stable_partition_runs(nums, pivot):
    items = list(nums)
    if not items:
        return []

    runs = []
    current_run = [items[0]]
    current_is_low = items[0] < pivot

    for x in items[1:]:
        is_low = x < pivot
        if is_low == current_is_low:
            current_run.append(x)
        else:
            runs.append((current_is_low, current_run))
            current_run = [x]
            current_is_low = is_low
    runs.append((current_is_low, current_run))

    low_runs = []
    high_runs = []
    for is_low, run in runs:
        if is_low:
            low_runs.extend(run)
        else:
            high_runs.extend(run)
    return low_runs + high_runs

def normalize_labeled_segments(items):
    if items is None:
        raise TypeError("items must be an iterable of 2-tuples")

    result = {}
    for entry in items:
        if not isinstance(entry, (tuple, list)) or len(entry) != 2:
            raise ValueError("each item must be a 2-tuple or 2-list")
        label, value = entry
        if not isinstance(label, str) or label == "":
            raise TypeError("label must be a non-empty string")
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("value must be an integer")
        if label not in result:
            result[label] = []
        result[label].append(value)

    for label in result:
        result[label].sort()
    return result

def normalize_path_segments(path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    if path == "":
        return "."

    absolute = path.startswith("/")
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            else:
                if not absolute:
                    stack.append("..")
            continue
        stack.append(part)

    if absolute:
        return "/" + "/".join(stack) if stack else "/"

    if not stack:
        return "."

    return "/".join(stack)

