def pack_intervals(intervals):
    try:
        items = list(intervals)
    except TypeError:
        raise TypeError("intervals must be iterable")

    normalized = []
    for iv in items:
        if not hasattr(iv, '__len__') or len(iv) != 2:
            raise TypeError("each interval must have exactly two items")
        start, end = iv[0], iv[1]
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must be <= end")
        normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [[normalized[0][0], normalized[0][1]]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def extract_weighted_digests(records):
    result = []
    for record in records:
        if not isinstance(record, str):
            continue
        if record.count(':') != 1 or record.count('*') != 1:
            continue
        label, rest = record.split(':', 1)
        if not label:
            continue
        if '*' not in rest:
            continue
        payload, weight_text = rest.rsplit('*', 1)
        if '*' in payload:
            continue
        try:
            weight = int(weight_text)
        except ValueError:
            continue
        if weight == 0:
            continue
        digest = sum(ord(ch) for ch in payload) * abs(weight)
        out_label = label[::-1] if weight < 0 else label
        result.append((out_label, digest))
    return result

def normalize_inventory_changes(events):
    inventory = {}
    seen = set()
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError('invalid record')
        item, action, amount = record
        if not isinstance(item, str):
            raise ValueError('invalid item')
        if action not in ('add', 'remove'):
            raise ValueError('invalid action')
        if not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid amount')
        seen.add(item)
        if item not in inventory:
            inventory[item] = 0
        if action == 'add':
            inventory[item] += amount
        else:
            inventory[item] -= amount
            if inventory[item] < 0:
                inventory[item] = 0
    if not events:
        return ''
    items = sorted(seen)
    return ';'.join(f'{item}={inventory.get(item, 0)}' for item in items)

