def normalize_recipe_steps(steps):
    if not isinstance(steps, list):
        raise TypeError("steps must be a list")

    def strip_prefix(s):
        t = s.strip()
        lower = t.lower()

        # Pattern 1: optional 'step' + optional whitespace + optional integer + punctuation
        i = 0
        if lower.startswith('step'):
            i = 4
            while i < len(t) and t[i].isspace():
                i += 1
            start_digits = i
            while i < len(t) and t[i].isdigit():
                i += 1
            if i > start_digits:
                while i < len(t) and t[i] in '.):-':
                    i += 1
                if i > 4:
                    return t[i:].strip()
            else:
                # 'step' followed by punctuation directly, e.g. step: text is not specified, so no removal here
                pass

        # Pattern 2: optional integer + punctuation
        i = 0
        start_digits = i
        while i < len(t) and t[i].isdigit():
            i += 1
        if i > start_digits:
            while i < len(t) and t[i] in '.):-':
                i += 1
            if i > 0:
                return t[i:].strip()

        return t

    out = []
    for item in steps:
        if not isinstance(item, str):
            raise TypeError("all steps must be strings")
        cleaned = strip_prefix(item)
        cleaned = ' '.join(cleaned.split())
        out.append(cleaned.title())
    return out

def normalize_port_specs(specs):
    normalized = set()
    for raw in specs:
        if not isinstance(raw, str):
            raise ValueError("all specs must be strings")
        s = raw.strip()
        if not s:
            raise ValueError("empty spec")

        host = "*"
        port_str = None

        if s.startswith('['):
            end = s.find(']')
            if end == -1:
                raise ValueError("missing closing bracket")
            host = s[:end + 1]
            rest = s[end + 1:]
            if not rest.startswith(':'):
                raise ValueError("missing colon after IPv6 literal")
            port_str = rest[1:]
            if not port_str:
                raise ValueError("missing port")
            if ':' in host[1:-1]:
                pass
            else:
                raise ValueError("invalid IPv6 literal")
        else:
            if ':' in s:
                host, port_str = s.rsplit(':', 1)
                if not host:
                    raise ValueError("empty host")
            else:
                port_str = s

        if port_str is None or not port_str or any(ch.isspace() for ch in port_str):
            raise ValueError("invalid port")
        if not port_str.isdigit():
            raise ValueError("invalid port")
        port = int(port_str)
        if port < 0 or port > 65535:
            raise ValueError("port out of range")

        if host != "*" and any(ch.isspace() for ch in host):
            raise ValueError("invalid host")
        if host.startswith('[') and not host.endswith(']'):
            raise ValueError("invalid IPv6 literal")
        if host == "*" and ':' in s:
            if s.startswith('['):
                pass
            else:
                if s.count(':') != 1:
                    raise ValueError("too many colons")

        normalized.add(f"{host}:{port}")

    return sorted(normalized)

import re

def normalize_port_specs(specs):
    """
    Normalize a list of port specification strings into a sorted list of normalized strings.

    Each input string can be in one of the following forms:
    - "PORT" meaning an implicit wildcard host, normalized to "*:PORT".
    - "HOST:PORT" where HOST is any non-empty string that does not contain ":".
    - "[IPv6]:PORT" where the host is a bracketed IPv6 literal, and the brackets must be preserved.

    A "PORT" must be an integer from 0 to 65535 with no sign, no decimal point, and no surrounding whitespace inside the token.
    The function must trim leading and trailing whitespace around each entire input string before parsing, but must not allow internal whitespace within HOST or PORT tokens.
    The returned list must contain duplicates only once, preserve the normalized host exactly as provided except that an implicit host becomes ".*", and be sorted lexicographically by the full normalized string.
    If any specification is invalid, the function must raise ValueError and return nothing. An empty input list should return an empty list.

    :param specs: List of port specification strings.
    :return: Sorted list of normalized port strings.
    """
    def parse_port_spec(spec):
        if spec.startswith("PORT"):
            return int(spec[4:])
        elif spec.startswith("[IPv6]"):
            return re.sub(r"\[([^\]]+)\]", r"\[\1\]", spec)
        else:
            raise ValueError(f"Invalid port specification: {spec}")

    normalized_specs = []
    for spec in specs:
        try:
            normalized_spec = parse_port_spec(spec)
            normalized_specs.append(normalized_spec)
        except ValueError as e:
            print(f"Error parsing {spec}: {e}")

    # Remove duplicates and sort lexicographically
    unique_sorted_specs = sorted(set(normalized_specs))

    return unique_sorted_specs

