def normalize_route(steps):
    if not isinstance(steps, list):
        raise TypeError('steps must be a list')

    allowed = {'N', 'S', 'E', 'W', 'U', 'D'}
    counts = {'N': 0, 'S': 0, 'E': 0, 'W': 0, 'U': 0, 'D': 0}

    for step in steps:
        if isinstance(step, str):
            if step not in allowed:
                raise ValueError('invalid direction')
            counts[step] += 1
        elif isinstance(step, tuple):
            if len(step) != 2:
                raise ValueError('tuple step must have length 2')
            label, count = step
            if label not in allowed:
                raise ValueError('invalid direction')
            if not isinstance(count, int):
                raise ValueError('count must be an integer')
            if count < 0:
                raise ValueError('count must be non-negative')
            counts[label] += count
        else:
            raise TypeError('invalid step type')

    result_counts = {
        'N': max(counts['N'] - counts['S'], 0),
        'S': max(counts['S'] - counts['N'], 0),
        'E': max(counts['E'] - counts['W'], 0),
        'W': max(counts['W'] - counts['E'], 0),
        'U': max(counts['U'] - counts['D'], 0),
        'D': max(counts['D'] - counts['U'], 0),
    }

    parts = []
    for direction in ['N', 'S', 'E', 'W', 'U', 'D']:
        parts.extend([direction] * result_counts[direction])
    return '>'.join(parts)

def normalize_route(steps):
    """
    Normalize a list of route instructions into a canonical route string.

    :param steps: List of strings or tuples representing route instructions.
    :return: A canonical route string.
    """
    if not isinstance(steps, list):
        raise TypeError("Input must be a list.")
    if not all(isinstance(step, (str, tuple)) for step in steps):
        raise TypeError("All elements in the list must be strings or tuples.")
    if not all(isinstance(label, str) for label in step[0]):
        raise ValueError("Each tuple step must have a string label.")
    if not all(isinstance(count, int) for count in step[1]):
        raise ValueError("Each tuple step must have an integer count.")
    if not all(count >= 0 for count in step[1]):
        raise ValueError("Each tuple step count must be non-negative.")

    directions = []
    for label, count in steps:
        if label == 'N':
            directions.extend(['N'] * count)
        elif label == 'S':
            directions.extend(['S'] * count)
        elif label == 'E':
            directions.extend(['E'] * count)
        elif label == 'W':
            directions.extend(['W'] * count)
        elif label == 'U':
            directions.extend(['U'] * count)
        elif label == 'D':
            directions.extend(['D'] * count)

    # Cancel opposite directions within each axis independently
    directions = [directions[i] for i in range(len(directions)) if i % 2 != 0]

    # Join the remaining directions with a single > character
    return '>' + ''.join(directions)

