def flatten_headers(headers, joiner):
    if not isinstance(joiner, str):
        raise ValueError('joiner must be a string')
    if not isinstance(headers, list) or len(headers) == 0:
        raise ValueError('headers must be a non-empty list')
    max_len = 0
    for row in headers:
        if not isinstance(row, list):
            raise ValueError('each row must be a list')
        if len(row) > max_len:
            max_len = len(row)
        for cell in row:
            if not isinstance(cell, str):
                raise ValueError('all cells must be strings')
    result = []
    for col in range(max_len):
        parts = []
        for row in headers:
            if col < len(row):
                cell = row[col]
                if cell != '':
                    parts.append(cell)
        result.append(joiner.join(parts) if parts else '')
    return result

def canonical_compose(commands):
    if not isinstance(commands, list):
        raise TypeError("commands must be a list")
    parts = []
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        if cmd.startswith('/'):
            parts = []
        for segment in cmd.split('/'):
            if segment == '' or segment == '.':
                continue
            if segment == '..':
                if parts:
                    parts.pop()
            else:
                parts.append(segment)
    return '/' + '/'.join(parts) if parts else '/'

