    Normalize a stack of patch operation records into a canonical, validated version.

    Each operation record is a list of exactly 3 elements: [op, start, end].
    The function ensures that adjacent operations with the same op are merged,
    and the stack has no overlapping intervals between consecutive records.

    :param stack: List of patch operation records.
    :return: A list of normalized records.
    """
    def merge_operations(op, start, end):
        if op == 'add':
            return [op, start, end]
        elif op == 'remove':
            return [op, start, end]
        else:
            raise TypeError("Invalid operation type")

    def validate_intervals(start, end):
        if start > end:
            raise ValueError("Start of interval must be less than end")
        return True

    def merge_records(record1, record2):
        if record1[1] < record2[0]:
            return record1
        elif record2[1] < record1[0]:
            return record2
        else:
            return [record1[0], min(record1[1], record2[1])]

    normalized_stack = []
    for i in range(len(stack)):
        op, start, end = stack[i]
        if op == 'add':
            normalized_stack.append(merge_operations(op, start, end))
        elif op == 'remove':
            normalized_stack.append(merge_operations(op, start, end))
        else:
            raise TypeError("Invalid operation type")

    # Check for overlapping intervals
    for i in range(len(normalized_stack) - 1):
        if normalized_stack[i][1] >= normalized_stack[i + 1][0]:
            raise ValueError("Overlapping intervals")

    return normalized_stack

