def normalize_betting_slip(slip):
    if not isinstance(slip, list):
        raise TypeError("slip must be a list")

    def normalize_name(name):
        if not isinstance(name, str):
            raise ValueError("name must be a string")
        stripped = name.strip()
        if not stripped:
            raise ValueError("name must be non-empty")
        return " ".join(stripped.split())

    def normalize_odds(odds):
        if isinstance(odds, bool):
            raise ValueError("odds must be a positive integer")
        if isinstance(odds, int):
            if odds <= 0:
                raise ValueError("odds must be positive")
            return odds
        if isinstance(odds, str) and odds.isdigit():
            value = int(odds)
            if value <= 0:
                raise ValueError("odds must be positive")
            return value
        raise ValueError("unsupported odds type")

    seen = set()
    entries = []
    total = 0

    for entry in slip:
        if isinstance(entry, dict):
            if set(entry.keys()) != {"name", "odds"}:
                raise ValueError("invalid entry dict")
            name = entry["name"]
            odds = entry["odds"]
        elif isinstance(entry, (tuple, list)) and len(entry) == 2:
            name, odds = entry
        else:
            raise ValueError("invalid entry format")

        normalized_name = normalize_name(name)
        normalized_odds = normalize_odds(odds)

        if normalized_name in seen:
            continue
        seen.add(normalized_name)
        entries.append((normalized_name, normalized_odds))
        total += normalized_odds

    return total, entries

def normalize_packet_labels(labels):
    if not isinstance(labels, list):
        raise TypeError("labels must be a list of strings")
    result = []
    for item in labels:
        if not isinstance(item, str):
            raise TypeError("all labels must be strings")
        trimmed = item.strip()
        if not any(ch.isalpha() for ch in trimmed):
            continue
        out = []
        prev_was_ws = False
        for ch in trimmed:
            if ch.isspace():
                prev_was_ws = True
                continue
            if prev_was_ws and out:
                out.append('_')
            prev_was_ws = False
            if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
                out.append(ch.upper())
            elif ch.isdigit() or ch == '_':
                out.append(ch)
        normalized = ''.join(out)
        if normalized:
            result.append(normalized)
    return result

def parse_ledger(lines):
    records = []
    total = 0.0
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        parts = raw.split('|', 2)
        if len(parts) != 3:
            raise ValueError('Invalid ledger line')
        date_part, amount_part, desc_part = parts
        date = date_part.strip()
        amount_str = amount_part.strip()
        description = desc_part.strip()
        if not date or not description:
            # description may be empty only if explicitly given as empty text; still valid
            # but date must not be empty.
            if not date:
                raise ValueError('Invalid ledger line')
        try:
            amount = float(amount_str)
        except Exception as e:
            raise ValueError('Invalid amount') from e
        record = {'date': date, 'amount': amount, 'description': description}
        records.append(record)
        total += amount
    return records, total

def schedule_windows(intervals, start, end):
    if start >= end:
        return []

    clipped = []
    for item in intervals:
        if len(item) != 2:
            raise ValueError("Each interval must have exactly two elements")
        a, b = item
        if a >= b:
            continue
        left = max(a, start)
        right = min(b, end)
        if left < right:
            clipped.append((left, right))

    if not clipped:
        return []

    clipped.sort(key=lambda x: (x[0], x[1]))
    merged = [list(clipped[0])]
    for left, right in clipped[1:]:
        last = merged[-1]
        if left <= last[1]:
            if right > last[1]:
                last[1] = right
        else:
            merged.append([left, right])
    return merged

def compress_audit(records):
    if isinstance(records, (str, bytes)) or not hasattr(records, '__iter__'):
        raise TypeError('records must be a sequence of strings')

    try:
        iterator = iter(records)
    except TypeError:
        raise TypeError('records must be a sequence of strings')

    parts = []
    for item in iterator:
        if not isinstance(item, str):
            raise TypeError('all records must be strings')
        parts.append(item)

    s = ''.join(parts)
    if not s:
        return []

    result = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            result.append((current, count))
            current = ch
            count = 1
    result.append((current, count))
    return result

def compress_audit(records):
    """
    Compresses a list of strings into a list of tuples representing run-length encoding.

    :param records: List of strings to be compressed.
    :return: A list of tuples, where each tuple contains a character and its count.
    """
    if not records:
        return []

    compressed = []
    for record in records:
        if not isinstance(record, str):
            raise TypeError("All elements in records must be strings.")

        # Concatenate the string with itself to handle overlapping runs
        concatenated = record + record
        # Find all occurrences of the character in the concatenated string
        char_counts = {}
        for i in range(len(concatenated)):
            if concatenated[i] in char_counts:
                char_counts[concatenated[i]] += 1
            else:
                char_counts[concatenated[i]] = 1

        # Append the counts to the compressed list
        for char, count in char_counts.items():
            compressed.append((char, count))

    return compressed

