def merge_weighted_segments(segments):
    events = {}
    for seg in segments:
        if not isinstance(seg, tuple) or len(seg) != 3:
            raise TypeError('each segment must be a 3-tuple')
        start, end, weight = seg
        if start >= end:
            continue
        events[start] = events.get(start, 0) + weight
        events[end] = events.get(end, 0) - weight

    if not events:
        return []

    points = sorted(events)
    result = []
    current_weight = 0
    prev = None
    for point in points:
        if prev is not None and current_weight != 0 and prev != point:
            if result and result[-1][2] == current_weight and result[-1][1] == prev:
                result[-1] = (result[-1][0], point, current_weight)
            else:
                result.append((prev, point, current_weight))
        current_weight += events[point]
        prev = point
    return result

