def normalize_nested_numbers(data):
    """
    Recursively processes a nested structure and returns a new, fully converted structure with the same shape.

    :param data: Any Python object.
    :return: A new, fully converted structure with the same shape.
    """
    if isinstance(data, bool):
        return data
    elif isinstance(data, int) or isinstance(data, float):
        if data.is_integer():
            return int(data)
        else:
            return float(data)
    elif isinstance(data, str):
        if data.isdigit() or data.startswith('-'):
