    elif isinstance(data, list) or isinstance(data, tuple) or isinstance(data, set):
        return [normalize_nested_numbers(item) for item in data]
    elif isinstance(data, dict):
        return {key: normalize_nested_numbers(value) for key, value in data.items()}
    else:
        return data

