def plan_stair_tokens(n, tokens):
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return []

    valid = []
    for t in tokens:
        if isinstance(t, int) and t > 0:
            valid.append(t)

    valid.sort()
    m = len(valid)
    if m == 0:
        return []

    best = None

    def better(a, b):
        if b is None:
            return True
        if len(a) != len(b):
            return len(a) < len(b)
        return a < b

    def backtrack(i, remaining, chosen):
        nonlocal best
        if remaining == 0:
            candidate = chosen.copy()
            if better(candidate, best):
                best = candidate
            return
        if remaining < 0 or i == m:
            return
        if best is not None and len(chosen) >= len(best):
            return

        # include current token
        chosen.append(valid[i])
        backtrack(i + 1, remaining - valid[i], chosen)
        chosen.pop()

        # skip current token
        backtrack(i + 1, remaining, chosen)

    backtrack(0, n, [])
    return best if best is not None else []

def ranked_merge(left, right):
    if not hasattr(left, "__len__") or not hasattr(left, "__getitem__"):
        raise TypeError("left must be a finite sequence")
    if not hasattr(right, "__len__") or not hasattr(right, "__getitem__"):
        raise TypeError("right must be a finite sequence")

    i = j = 0
    n, m = len(left), len(right)
    result = []

    while i < n and j < m:
        a = left[i]
        b = right[j]
        try:
            if a <= b:
                result.append(a)
                i += 1
            else:
                result.append(b)
                j += 1
        except TypeError:
            raise TypeError("elements are not comparable")

    while i < n:
        result.append(left[i])
        i += 1
    while j < m:
        result.append(right[j])
        j += 1

    return result

