def parse_weighted_pairs(text):
    if text == "":
        return []
    parts = text.split(';')
    result = []
    for part in parts:
        if part == "":
            raise ValueError("empty entry")
        if part != part.strip():
            raise ValueError("whitespace around entry")
        if ':' not in part or '@' not in part:
            raise ValueError("missing separator")
        left, rest = part.split(':', 1)
        right, weight_str = rest.rsplit('@', 1)
        if left == "" or right == "" or weight_str == "":
            raise ValueError("empty token")
        if any(ch in left for ch in ':@;') or any(ch in right for ch in ':@;'):
            raise ValueError("invalid token")
