def normalize_event_log(events):
    required = {'id', 'timestamp', 'priority', 'payload'}
    best = {}
    order = {}

    if not isinstance(events, list):
        raise TypeError('events must be a list')

    for idx, record in enumerate(events):
        if not isinstance(record, dict):
            continue
        if set(record.keys()) != required:
            continue
        _id = record['id']
        ts = record['timestamp']
        pr = record['priority']
        if not isinstance(_id, str) or _id == '':
            continue
        if not isinstance(ts, int):
            continue
        if not isinstance(pr, int) or not (0 <= pr <= 9):
            continue

        candidate = dict(record)
        candidate['normalized_id'] = _id.upper()

        if _id not in best:
            best[_id] = candidate
            order[_id] = idx
        else:
            cur = best[_id]
            if ts > cur['timestamp'] or (ts == cur['timestamp'] and pr > cur['priority']):
                best[_id] = candidate
                order[_id] = idx

    return sorted(best.values(), key=lambda r: (-r['priority'], r['timestamp'], r['id']))

def compress_runs(items):
    result = []
    iterator = iter(items)
    try:
        current = next(iterator)
    except StopIteration:
        return result

    count = 1
    for value in iterator:
        if value == current:
            count += 1
        else:
            result.append((current, count))
            current = value
            count = 1
    result.append((current, count))
    return result

def normalize_inventory_events(events):
    if events == []:
        return []

    groups = {}
    order = {}

    for idx, event in enumerate(events):
        if not isinstance(event, dict):
            raise ValueError('each event must be a dictionary')
        if 'item' not in event or 'delta' not in event:
            raise ValueError('missing required keys')
        item = event['item']
        delta = event['delta']
        batch = event.get('batch', None)

        if not isinstance(item, str) or item == '':
            raise ValueError('item must be a non-empty string')
        if not isinstance(delta, int):
            raise ValueError('delta must be an integer')
        if batch is not None and not isinstance(batch, str):
            raise ValueError('batch must be a string or None')

        key = (item, batch)
        if key not in groups:
            groups[key] = 0
            order[key] = idx
        groups[key] += delta

    result = []
    for (item, batch), total in groups.items():
        if total != 0:
            result.append((item, batch, total, order[(item, batch)]))

    result.sort(key=lambda t: (t[0], ('' if t[1] is None else t[1]), 0 if t[1] is None else 1, t[3]))
    return [{'item': item, 'batch': batch, 'delta': total} for item, batch, total, _ in result]

import re

def normalize_heading(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    s = text.strip().lower()
    s = re.sub(r'\s+', '-', s)
    s = re.sub(r'[^a-z0-9-]', '', s)
    s = re.sub(r'-+', '-', s)
    return s.strip('-')

def compress_intervals(points):
    if not isinstance(points, list):
        raise TypeError("points must be a list")
    for p in points:
        if not isinstance(p, int):
            raise TypeError("all points must be integers")
    if not points:
        return []
    uniq = sorted(set(points))
    intervals = []
    start = prev = uniq[0]
    for x in uniq[1:]:
        if x == prev + 1:
            prev = x
        else:
            intervals.append((start, prev))
            start = prev = x
    intervals.append((start, prev))
    return intervals

def normalize_room_label(label):
    if not isinstance(label, str):
        raise TypeError('label must be a string')
    s = label.strip()
    if s == '':
        raise ValueError('normalized label is empty')
    out = []
    prev_space = False
    for ch in s:
        if ch.isspace():
            if not prev_space:
                out.append('_')
                prev_space = True
            continue
        prev_space = False
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch in '_-':
            out.append(ch.upper())
    result = ''.join(out)
    if result == '':
        raise ValueError('normalized label is empty')
    return result

def normalize_path(path: str) -> str:
    if path == '':
        return '.'

    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                if is_absolute:
                    stack.pop()
                else:
                    stack.pop()
            else:
                if not is_absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if is_absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def normalize_identifier_path(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    parts = []
    for segment in s.split('/'):
        trimmed = segment.strip()
        if trimmed:
            parts.append(trimmed.lower())
    return '/'.join(parts)

