def repair_timeline(events):
    best = {}
    order = {}
    for idx, rec in enumerate(events):
        if not isinstance(rec, (tuple, list)) or len(rec) != 2:
            continue
        label, minute = rec
        if not isinstance(label, str) or label == "":
            continue
        if not isinstance(minute, int) or isinstance(minute, bool) or minute < 0:
            continue
        if label not in best:
            best[label] = minute
            order[label] = idx
        else:
            if minute < best[label]:
                best[label] = minute
                order[label] = idx
            elif minute == best[label] and idx < order[label]:
                order[label] = idx
    survivors = [(m, lbl) for lbl, m in best.items()]
    survivors.sort(key=lambda x: (x[0], x[1]))
    return ";".join(f"{lbl}@{m}" for m, lbl in survivors)

def parse_weighted_pairs(text: str) -> dict[str, int]:
    if text is None:
        raise TypeError('text must be a string')
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    result: dict[str, int] = {}
    if text.strip() == '':
        return result

    items = text.split(';')
    for raw_item in items:
        item = raw_item.strip()
        if item == '':
            continue
        if '=' not in item:
            raise ValueError('malformed item')
        key, weight = item.split('=', 1)
        if key == '' or weight == '':
            raise ValueError('malformed item')
        if key.strip() != key or weight.strip() != weight:
            raise ValueError('malformed item')
        if any(ch not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-' for ch in key):
            raise ValueError('malformed item')
        if weight[0] in '+-':
            digits = weight[1:]
            if digits == '':
                raise ValueError('malformed item')
        else:
            digits = weight
        if not digits.isdigit():
            raise ValueError('malformed item')
        value = int(weight)
        result[key] = result.get(key, 0) + value
    return result

