def parse_packet_flags(spec: str) -> int:
    flags = {
        'URG': 1,
        'ACK': 2,
        'PSH': 4,
        'RST': 8,
        'SYN': 16,
        'FIN': 32,
    }
    if spec.strip() == '':
        return 0
    result = 0
    for token in spec.split():
        if token == '0':
            continue
        if token not in flags:
            raise ValueError(f'Invalid token: {token}')
        result |= flags[token]
    return result

def normalize_route(stops):
    if not isinstance(stops, (list, tuple)):
        raise TypeError('stops must be a list or tuple of strings')
    normalized = []
    for stop in stops:
        if not isinstance(stop, str):
            raise TypeError('all stops must be strings')
        s = stop.strip().upper()
        if s == '':
            raise ValueError('stop names must not be empty after normalization')
        if not normalized or normalized[-1] != s:
            normalized.append(s)
    if not normalized:
        return tuple()
    if normalized[0] == normalized[-1]:
        normalized.append('CIRCULAR')
    return tuple(normalized)

def normalize_route(stops):
    """
    Normalize a sequence of transit stop names into a canonical route signature.

    Parameters:
    stops (list or tuple): A list or tuple of strings representing transit stop names.

    Returns:
    tuple: A tuple of normalized stop names, with duplicates collapsed and the circular marker appended.
    """
    if not isinstance(stops, (list, tuple)):
        raise TypeError("Stops must be a list or tuple of strings.")
    if not all(isinstance(stop, str) for stop in stops):
        raise TypeError("All elements in stops must be strings.")
    if any(stop.strip() == '' for stop in stops):
        raise ValueError("Empty strings are not allowed.")
    if len(stops) < 2:
        return tuple()

    normalized_stops = []
    for i in range(len(stops) - 1):
        normalized_stops.append(stops[i].strip())
        if normalized_stops[-1] != normalized_stops[i]:
            normalized_stops.append(normalized_stops[-1])

    if normalized_stops[0] == normalized_stops[-1]:
        return tuple(normalized_stops[:-1] + ['CIRCULAR'])

    return tuple(normalized_stops)

