def compress_spans(values):
    if not values:
        return []

    result = []
    start = 0
    current = values[0]

    for i in range(1, len(values)):
        if values[i] != current:
            result.append((start, i - 1, current))
            start = i
            current = values[i]

    result.append((start, len(values) - 1, current))
    return result

