def decode_run_lengths(data):
    if data == '':
        return ''
    parts = data.split(';')
    out = []
    for part in parts:
        if part == '':
            raise ValueError('empty segment')
        if '*' not in part:
            raise ValueError('missing *')
        count_str, char = part.split('*', 1)
        if count_str == '' or char == '':
            raise ValueError('missing count or char')
        if not count_str.isdigit():
            raise ValueError('invalid count')
        if len(char) != 1:
            raise ValueError('segment must have exactly one character')
        count = int(count_str)
        if count > 0:
            out.append(char * count)
    return ''.join(out)

def canonicalize_accounts(records):
    if not isinstance(records, (list, tuple)):
        raise TypeError('records must be a sequence of records')

    merged = {}
    order = []

    for record in records:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise TypeError('each record must be a 3-item list or tuple')
        name, amount, tags = record
        if not isinstance(name, str):
            raise TypeError('name must be a string')
        if not isinstance(amount, int):
            raise TypeError('amount must be an int')
        if not isinstance(tags, (list, tuple)):
            raise TypeError('tags must be a list or tuple of strings')

        norm_name = name.strip()
        if norm_name == '':
            norm_name = '<blank>'

        norm_tags = []
        seen = set()
        for tag in tags:
            if not isinstance(tag, str):
                raise TypeError('each tag must be a string')
            t = tag.strip()
            if t == '' or t in seen:
                continue
            seen.add(t)
            norm_tags.append(t)

        if norm_name not in merged:
            merged[norm_name] = [0, []]
            order.append(norm_name)
        merged[norm_name][0] += amount
        merged[norm_name][1].extend(norm_tags)

    lines = []
    for name in sorted(merged.keys()):
        total, tags = merged[name]
        lines.append(f'{name}|{total}|{",".join(tags)}')
    return '\n'.join(lines)

def summarize_plateau_runs(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")

    items = []
    for x in iterator:
        if type(x) is not int:
            raise TypeError("all elements must be integers")
        items.append(x)

    runs = []
    n = len(items)
    i = 0
    while i < n:
        j = i + 1
        while j < n and items[j] == items[i]:
            j += 1
        length = j - i
        if length >= 2:
            runs.append((items[i], i, j - 1, length))
        i = j

    if not runs:
        return {"count": 0, "runs": [], "longest": None}

    longest = runs[0]
    for run in runs[1:]:
        if run[3] > longest[3] or (run[3] == longest[3] and run[1] < longest[1]):
            longest = run

    return {"count": len(runs), "runs": runs, "longest": longest}

def normalize_schedule(schedule):
    days = {
        'monday': 0,
        'tuesday': 1,
        'wednesday': 2,
        'thursday': 3,
        'friday': 4,
        'saturday': 5,
        'sunday': 6,
    }
    if not isinstance(schedule, list):
        raise ValueError('schedule must be a list')
    normalized = []
    for item in schedule:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('each entry must be a 3-tuple')
        day, start_minute, end_minute = item
        if not isinstance(day, str):
            raise ValueError('day must be a string')
        day_key = day.lower()
        if day_key not in days:
            raise ValueError('invalid day')
        if not isinstance(start_minute, int) or not isinstance(end_minute, int):
            raise ValueError('minutes must be integers')
        if not (0 <= start_minute <= 1440) or not (0 <= end_minute <= 1440):
            raise ValueError('minutes out of range')
        if start_minute >= end_minute:
            raise ValueError('start must be less than end')
        normalized.append((days[day_key], day_key, start_minute, end_minute))
    normalized.sort(key=lambda x: (x[0], x[2], x[3]))
    merged = []
    for _, day_key, start_minute, end_minute in normalized:
        if not merged or merged[-1][0] != day_key or start_minute > merged[-1][2]:
            merged.append([day_key, start_minute, end_minute])
        else:
            if end_minute > merged[-1][2]:
                merged[-1][2] = end_minute
    return [tuple(item) for item in merged]

def merge_interval_multiset(intervals):
    valid = []
    for item in intervals:
        if len(item) != 2:
            continue
        a, b = item
        if a <= b:
            valid.append((a, b))
    if not valid:
        return []
    valid.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = valid[0]
    for start, end in valid[1:]:
        if start <= cur_end + 1:
            if end > cur_end:
                cur_end = end
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

def chunked_range_labels(start, stop, size):
    if not isinstance(start, int) or not isinstance(stop, int) or not isinstance(size, int):
        raise TypeError("start, stop, and size must be integers")
    if size <= 0:
        raise ValueError("size must be positive")
    if start > stop:
        raise ValueError("start must be <= stop")
    if start == stop:
        return []

    labels = []
    cur = start
    while cur < stop:
        nxt = min(cur + size, stop)
        labels.append(f"{cur}:{nxt}")
        cur = nxt
    return labels

