    consolidated = {}
    for record in transfers:
        if len(record) != 4:
            raise TypeError("each transfer must have exactly 4 elements")
        source, destination, item, quantity = record
        if quantity < 0:
            raise ValueError("quantity cannot be negative")
        if source == destination:
            raise ValueError("source and destination must differ")
        if quantity == 0:
