    Normalize inventory transfer records by summing quantities for identical source, destination, and item.
    Ignore records with quantity 0 or invalid inputs.

    :param transfers: List of tuples (source, destination, item, quantity)
    :return: List of consolidated tuples (source, destination, item, quantity)
    """
    consolidated = []
    for source, destination, item, quantity in transfers:
        if not isinstance(source, str) or not isinstance(destination, str) or not isinstance(item, str) or not isinstance(quantity, int):
            raise TypeError("All elements must be strings.")

        if quantity == 0:
            continue

        if source != destination:
            raise ValueError("Source and destination must be identical.")

        if quantity < 0:
            raise ValueError("Quantity cannot be negative.")

        if len(transfers) > 1:
            raise ValueError("Only one record per source, destination, and item allowed.")

        if len(transfers) == 1:
            consolidated.append((source, destination, item, quantity))
            continue

        # Merge quantities
        total_quantity = quantity
        for other_transfer in transfers[1:]:
            if other_transfer[0] == source and other_transfer[1] == destination and other_transfer[2] == item:
                total_quantity += other_transfer[3]

        consolidated.append((source, destination, item, total_quantity))

    return consolidated

