def merge_interval_counts(events):
    deltas = {}
    for item in events:
        if len(item) != 3:
            raise ValueError("Each event must be a 3-tuple (start, end, weight)")
        start, end, weight = item
        if start >= end:
            continue
        deltas[start] = deltas.get(start, 0) + weight
        deltas[end] = deltas.get(end, 0) - weight

    if not deltas:
        return []

    points = sorted(deltas)
    result = []
    current_weight = 0
    prev_point = None

    for point in points:
        if prev_point is not None and current_weight != 0 and prev_point < point:
            if result and result[-1][2] == current_weight and result[-1][1] == prev_point:
                result[-1] = (result[-1][0], point, current_weight)
            else:
                result.append((prev_point, point, current_weight))
        current_weight += deltas[point]
        prev_point = point

    return result

def pack_transition_table(states, alphabet, transitions):
    if len(set(states)) != len(states):
        raise ValueError('duplicate states')
    if len(set(alphabet)) != len(alphabet):
        raise ValueError('duplicate alphabet')

    state_set = set(states)
    alpha_set = set(alphabet)

    table = []
    for s in states:
        row = []
        for a in alphabet:
            row.append(None)
        table.append(row)

    for key, dest in transitions.items():
        if not isinstance(key, tuple) or len(key) != 2:
            raise ValueError('invalid transition key')
        s, a = key
        if s not in state_set:
            raise ValueError('unknown state in transition')
        if a not in alpha_set:
            raise ValueError('unknown symbol in transition')
        if dest is not None and dest not in state_set:
            raise ValueError('unknown destination state')
        i = states.index(s)
        j = alphabet.index(a)
        table[i][j] = dest

    return table

def parse_quota_spec(spec):
    if not isinstance(spec, str):
        raise TypeError('spec must be a string')

    if spec.strip() == '':
        return {}

    result = {}
    parts = spec.split(';')
    for raw_part in parts:
        part = raw_part.strip()
        if part == '':
            raise ValueError('empty entry')
        if part.count('=') != 1:
            raise ValueError('each entry must contain exactly one =')

        name, values_text = part.split('=', 1)
        name = name.strip()
        values_text = values_text.strip()
        if name == '' or values_text == '':
            raise ValueError('missing account name or values')
        if name in result:
            raise ValueError('duplicate account name')

        values = []
        for token in values_text.split(','):
            token = token.strip()
            if token == '':
                raise ValueError('empty quota value')
            try:
                value = int(token, 10)
            except Exception:
                raise ValueError('invalid integer token')
            if str(value) != token.lstrip('+') and not (token.startswith('+') and str(value) == token[1:]):
                # Reject tokens like '01', '+01', and forms with extra characters.
                # int() accepts them, but the specification requires valid integer literals.
                raise ValueError('invalid integer literal')
            values.append(value)

        result[name] = tuple(values)

    return result

def parse_quota_spec(spec):
    """
    Parses a compact quota specification string into a dictionary of account limits.

    :param spec: A semicolon-separated list of entries.
    :return: A dictionary mapping each account name to a tuple of integers.
    """
    # Split the input string into individual quota entries
    quota_entries = spec.split(';')

    # Initialize an empty dictionary to store account limits
    quota_limits = {}

    # Iterate over each quota entry
    for entry in quota_entries:
        # Split the entry into account name and values
        parts = entry.split('=')

        # Check if there are enough parts
        if len(parts) != 2:
            raise ValueError("Invalid quota specification")

        # Extract the account name and values
        account_name = parts[0].strip()
        values = [int(val.strip()) for val in parts[1].split(',')]

        # Validate the account name
        if not account_name:
            raise ValueError("Account name cannot be empty")

        # Validate the values
        if not all(isinstance(val, int) for val in values):
            raise ValueError("All values must be integers")

        # Add the account name and values to the quota_limits dictionary
        quota_limits[account_name] = values

    return quota_limits

