def normalize_header_fields(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    out = []
    index = {}

    for rec in records:
        if not (isinstance(rec, tuple) and len(rec) == 3):
            raise TypeError("each record must be a tuple of length 3")
        name, value, status = rec
        if not isinstance(name, str) or not isinstance(value, str):
            raise TypeError("name and value must be strings")
        if status not in ("keep", "drop"):
            raise ValueError("status must be 'keep' or 'drop'")
        if status == "drop":
            continue

        norm_name = "-".join(name.strip().lower().split())
        norm_value = " ".join(value.strip().split())

        if norm_name in index:
            out[index[norm_name]] = (norm_name, out[index[norm_name]][1] + "; " + norm_value)
        else:
            index[norm_name] = len(out)
            out.append((norm_name, norm_value))

    return out

def merge_event_sequences(events_a, events_b):
    def is_sequence(obj):
        return isinstance(obj, (list, tuple))

    def validate_and_normalize(events, source_rank):
        normalized = []
        for index, item in enumerate(events):
            if not is_sequence(item):
                raise ValueError("event record must be a sequence")
            if len(item) == 2:
                timestamp, label = item
                source = "unknown"
            elif len(item) == 3:
                timestamp, label, source = item
            else:
                raise ValueError("event record must have length 2 or 3")
            if isinstance(timestamp, bool) or not isinstance(timestamp, (int, float)):
                raise TypeError("timestamp must be int or float")
            if not isinstance(label, str):
                raise TypeError("label must be a string")
            if not isinstance(source, str):
                raise TypeError("source must be a string")
            normalized.append((timestamp, label, source, source_rank, index))
        return normalized

    if not is_sequence(events_a) or not is_sequence(events_b):
        raise TypeError("inputs must be sequences")

    combined = validate_and_normalize(events_a, 0) + validate_and_normalize(events_b, 1)
    combined.sort(key=lambda x: (x[0], x[1], x[3], x[4]))
    return [(timestamp, label, source) for timestamp, label, source, _, _ in combined]

def normalize_book_index(entries):
    result = {}
    seen_order = []
    for entry in entries:
        if not isinstance(entry, str) or ':' not in entry:
            raise ValueError('malformed entry')
        chapter, pages_part = entry.split(':', 1)
        if chapter == '':
            raise ValueError('empty chapter name')
        if chapter not in result:
            result[chapter] = set()
            seen_order.append(chapter)
        if pages_part == '':
            raise ValueError('empty page list')
        for token in pages_part.split(','):
            if token == '':
                raise ValueError('invalid token')
            if '-' in token:
                parts = token.split('-')
                if len(parts) != 2 or parts[0] == '' or parts[1] == '':
                    raise ValueError('invalid range')
                try:
                    a = int(parts[0])
                    b = int(parts[1])
                except Exception:
                    raise ValueError('non-integer range endpoint')
                if a <= 0 or b <= 0:
                    raise ValueError('non-positive page number')
                start = a if a <= b else b
                end = b if a <= b else a
                for n in range(start, end + 1):
                    if n <= 0:
                        raise ValueError('non-positive page number')
                    result[chapter].add(n)
            else:
                try:
                    n = int(token)
                except Exception:
                    raise ValueError('non-integer page number')
                if n <= 0:
                    raise ValueError('non-positive page number')
                result[chapter].add(n)
    return {chapter: sorted(result[chapter]) for chapter in seen_order}

def plan_dependency_levels(tasks):
    try:
        items = list(tasks)
    except TypeError:
        raise

    defined = set()
    prereq_map = {}

    for item in items:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("Each task entry must be a 2-tuple")
        task_name, prerequisites = item
        try:
            prereqs = list(prerequisites)
        except TypeError:
            raise
        if task_name in prereq_map:
            raise ValueError("Duplicate task_name entries are not allowed")
        defined.add(task_name)
        prereq_map[task_name] = set(prereqs)

    all_nodes = set(prereq_map)
    for prereqs in prereq_map.values():
        all_nodes.update(prereqs)

    incoming = {node: set() for node in all_nodes}
    outgoing = {node: set() for node in all_nodes}
    for task_name, prereqs in prereq_map.items():
        for p in prereqs:
            incoming[task_name].add(p)
            outgoing[p].add(task_name)

    indeg = {node: len(incoming[node]) for node in all_nodes}
    levels = []
    current = sorted([node for node in all_nodes if indeg[node] == 0])
    seen = set()

    while current:
        levels.append(current)
        next_nodes = set()
        for node in current:
            seen.add(node)
            for child in outgoing[node]:
                indeg[child] -= 1
                if indeg[child] == 0:
                    next_nodes.add(child)
        current = sorted(next_nodes)

    if len(seen) != len(all_nodes):
        raise ValueError("Dependency cycle detected")

    return levels

from typing import List, Tuple

def plan_dependency_levels(tasks: Iterable[Tuple[str, List[str]]]) -> List[List[str]]:
    """
    Analyzes a directed graph of dependencies and returns a scheduling plan by levels.

    Parameters:
    - tasks: An iterable of 2-tuples (task_name, prerequisites).

    Returns:
    - A list of levels, where each level is a list of task names that can be completed in parallel after all tasks in earlier levels are completed.
    """
    # Check for valid input
    if not isinstance(tasks, Iterable):
        raise TypeError("Input must be an iterable of tuples.")
    if not all(isinstance(task, tuple) for task in tasks):
        raise TypeError("All elements in the input must be tuples.")
    if not all(isinstance(prerequisite, str) for prerequisite in tasks[0][1]):
        raise TypeError("All prerequisites must be strings.")
    if not all(isinstance(task, str) for task in tasks[1][1]):
        raise TypeError("All prerequisites must be strings.")

    # Build the graph
    graph = {task: set() for task in tasks}
    for task, prerequisites in tasks:
        for prerequisite in prerequisites:
            graph[task].add(prerequisite)

    # Find the root of the graph
    root = None
    for task in graph:
        if not graph[task]:
            root = task
            break

    # If there's no root, raise an error
    if root is None:
        raise ValueError("Graph contains a cycle.")

    # Perform depth-first search to find all levels
    levels = []
    current_level = [root]
    while current_level:
        next_level = []
        for task in current_level:
            for prerequisite in graph[task]:
                if prerequisite not in levels:
                    next_level.append(prerequisite)
        levels.append(current_level)
        current_level = next_level

    return levels

