def compress_runs(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if s == '':
        return ''

    parts = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f'{current}{count}')
            current = ch
            count = 1

    parts.append(f'{current}{count}')
    return ''.join(parts)

def normalize_path_segments(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if path == '':
        return '.'

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' if not stack else '/' + '/'.join(stack)
    return '.' if not stack else '/'.join(stack)

