def reorder_shelf(items, priority_tags, separator):
    if not isinstance(separator, str):
        raise TypeError('separator must be a string')

    seen = set()
    unique_items = []
    for tag in items:
        if tag not in seen:
            seen.add(tag)
            unique_items.append(tag)

    priority_set = set(priority_tags)
    prioritized = []
    for tag in priority_tags:
        if tag in seen and tag not in prioritized:
            prioritized.append(tag)

    remainder = [tag for tag in unique_items if tag not in priority_set]
    ordered = prioritized + remainder
    return separator.join(ordered)

def reduce_coordinate_path(path: str) -> tuple[int, int]:
    if path is None:
        raise ValueError('path must be a non-empty string')
    stripped = path.strip()
    if not stripped:
        raise ValueError('path must be a non-empty string')

    x = 0
    y = 0
    tokens = stripped.split(',')
    for raw in tokens:
        token = raw.strip()
        if not token:
            raise ValueError('empty token')
        t = token.upper()
        if t == 'N':
            y += 1
        elif t == 'S':
            y -= 1
        elif t == 'E':
            x += 1
        elif t == 'W':
            x -= 1
        else:
            raise ValueError(f'invalid token: {token}')
    return (x, y)

def compress_segments(values):
    result = []
    iterator = iter(values)
    index = 0

    try:
        first = next(iterator)
    except StopIteration:
        return result

    if type(first) is not int:
        raise TypeError("all elements must be integers")

    current_value = first
    start_index = 0
    length = 1

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        if item == current_value:
            length += 1
        else:
            result.append((current_value, start_index, length))
            start_index = index + 1
            current_value = item
            length = 1
        index += 1

    result.append((current_value, start_index, length))
    return result

def expand_compact_tags(text: str) -> str:
    parts = [part.strip() for part in text.split(';')]
    out = []
    for part in parts:
        if not part:
            continue
        if '[' not in part and ']' not in part:
            out.append(part)
            continue
        if part.count('[') != 1 or part.count(']') != 1:
            raise ValueError('unmatched or nested brackets')
        open_idx = part.find('[')
        close_idx = part.rfind(']')
        if open_idx > close_idx:
            raise ValueError('unmatched brackets')
        tag = part[:open_idx]
        content = part[open_idx + 1:close_idx]
        if not tag or not tag.isalpha() or not tag.isupper():
            raise ValueError('invalid tag name')
        if '[' in content or ']' in content:
            raise ValueError('nested brackets in content')
        if close_idx != len(part) - 1:
            raise ValueError('trailing invalid characters')
        out.append(f'<{tag}>{content}</{tag}>')
    return ''.join(out)

def expand_compact_tags(text: str) -> str:
    """
    Expands compact tag shortcuts in a string. A compact tag shortcut is of the form
    TAG[content], where TAG is one or more uppercase ASCII letters and content is any
    string that does not contain [ or ].

    :param text: A semicolon-separated sequence of items.
    :return: A string with expanded tags.
    """
    def expand_tag(tag: str, content: str) -> str:
        if tag == '':
            return content
        elif tag[0] == '[' and tag[-1] == ']':
            return f'<{tag[1:-1]}>{content}</{tag[1:-1]}>'
        else:
            raise ValueError(f"Invalid tag: {tag}")

    # Split the input string into items
    items = text.split(';')

    # Process each item
    result = []
    for item in items:
        if item.strip():
            try:
                # Expand the tag if it's a valid compact tag
                result.append(expand_tag(item.strip(), item.strip()))
            except ValueError as e:
                # Handle invalid tags
                raise ValueError(f"Invalid tag: {e}")
        else:
            # Preserve non-empty items
            result.append(item.strip())

    # Join the processed items into a single string
    return ''.join(result)

