def plan_round_robin(tasks, slot_size, rounds):
    if not isinstance(slot_size, int):
        raise TypeError("slot_size must be an int")
    if not isinstance(rounds, int):
        raise TypeError("rounds must be an int")
    if slot_size < 1:
        raise ValueError("slot_size must be positive")
    if rounds < 0:
        raise ValueError("rounds must be non-negative")

    task_list = list(tasks)
    for name in task_list:
        if not isinstance(name, str) or name == "":
            raise ValueError("all task names must be non-empty strings")

    if not task_list or rounds == 0:
        return []

    schedule = []
    for _ in range(rounds):
        for idx, name in enumerate(task_list, start=1):
            schedule.append((name, slot_size * idx))
    return schedule

def normalize_inventory(transactions):
    totals = {}
    order = []

    for tx in transactions:
        if not isinstance(tx, str):
            raise ValueError("Invalid transaction")
        if tx.count(":") != 1:
            raise ValueError("Invalid transaction")
        name, qty_text = tx.split(":")
        if name == "":
            raise ValueError("Invalid transaction")
        if qty_text == "":
            raise ValueError("Invalid transaction")
        if qty_text[0] in "+-":
            digits = qty_text[1:]
            if digits == "" or not digits.isdigit():
                raise ValueError("Invalid transaction")
        else:
            if not qty_text.isdigit():
                raise ValueError("Invalid transaction")
        qty = int(qty_text)
        if name not in totals:
            totals[name] = 0
            order.append(name)
        totals[name] += qty

    parts = []
    for name in order:
        total = totals[name]
        if total != 0:
            parts.append(f"{name}={total}")
    return ";".join(parts)

def normalize_inventory(transactions):
    """
    Normalize a list of inventory transactions into a canonical summary string.

    Each transaction is a string of the form 'NAME:QTY', where NAME is the item name
    and QTY is a signed integer written in base 10. Item names are case-sensitive and
    may contain any characters except ':'. The function validates every transaction string,
    aggregates quantities by exact item name, and builds the return value.

    :param transactions: List of strings representing inventory transactions.
    :return: A canonical summary string.
    """
    def validate_transaction(transaction):
        if ':' not in transaction:
            raise ValueError("Invalid transaction format")
        name, qty = transaction.split(':')
        if not name.isalnum() or len(name) == 0:
            raise ValueError("Invalid item name")
        try:
            qty = int(qty)
        except ValueError:
            raise ValueError("Invalid quantity")
        return name, qty

    def aggregate_quantities(transactions):
        seen_names = set()
        total_quantity = 0
        for name, qty in transactions:
            if name in seen_names:
                raise ValueError(f"Duplicate item name: {name}")
            seen_names.add(name)
            total_quantity += qty
        return total_quantity

    def build_summary(total_quantity):
        return ';'.join(f"{name}={total_quantity}" for name, _ in seen_names.items())

    try:
        validated_transactions = [validate_transaction(tx) for tx in transactions]
        total_quantity = aggregate_quantities(validated_transactions)
        return build_summary(total_quantity)
    except ValueError as e:
        return str(e)

# Check function to verify the correctness of the solution
def check():
    assert normalize_inventory(["apple:3", "banana:2", "apple:-1"]) == 'apple=2;banana=2'
    assert normalize_inventory(["x:+4", "x:-4"]) == ''
    print("All tests passed!")

check()

def normalize_schedules(schedules):
    validated = []
    for item in schedules:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('Each schedule must be a tuple of length 3')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('Start and end must be integers')
        if not isinstance(label, str) or label == '':
            raise ValueError('Label must be a non-empty string')
        if start > end:
            raise ValueError('Start must be less than or equal to end')
        validated.append((start, end, label))

    validated.sort(key=lambda x: (x[0], x[1], x[2]))

    result = []
    for start, end, label in validated:
        if result and result[-1][2] == label and start <= result[-1][1] + 1:
            prev_start, prev_end, prev_label = result[-1]
            result[-1] = (prev_start, max(prev_end, end), prev_label)
        else:
            result.append((start, end, label))
    return result

def normalize_permissions(spec):
    if spec is None:
        raise ValueError('spec must be a string')
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')

    action_rank = {'admin': 0, 'execute': 1, 'write': 2, 'read': 3}
    allowed_actions = set(action_rank)
    result = set()

    if spec.strip() == '':
        return []

    for raw_token in spec.split(','):
        token = raw_token.strip()
        if token == '':
            continue
        if ':' not in token:
            raise ValueError('missing colon')
        left, right = token.split(':', 1)
        action = left.strip().lower()
        target = right.strip().lower()
        if action not in allowed_actions:
            raise ValueError('unknown action')
        if target == '':
            raise ValueError('empty target')
        for ch in target:
            if not (ch.isalnum() or ch == '_'):
                raise ValueError('invalid target')
        result.add((action, target))

    return [f'{a}:{t}' for a, t in sorted(result, key=lambda p: (action_rank[p[0]], p[1]))]

def normalize_route_segments(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a str')

    absolute = path.startswith('/')
    trailing = path.endswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            continue
        stack.append(part)

    if not stack:
        return '/' if absolute else ''

    result = '/'.join(stack)
    if absolute:
        result = '/' + result
    if trailing:
        result += '/'
    return result

def normalize_route_segments(path: str) -> str:
    """
    Normalize a route-style path string according to the specified rules.

    Args:
    path (str): The route-style path to be normalized.

    Returns:
    str: The normalized route-style path.

    Raises:
    TypeError: If path is not a string.
    """
    if not isinstance(path, str):
        raise TypeError("Input must be a string.")

    # Split the path into segments
    segments = path.split('/')

    # Initialize variables to track the last retained segment
    last_retained = None

    # Process each segment
    for segment in segments:
        if segment == '.':
            # Remove the most recent retained segment if any
            if last_retained:
                last_retained = last_retained[:-1]
        elif segment == '..':
            # Remove the most recent retained segment if any
            if last_retained:
                last_retained = last_retained[:-1]
        else:
            # Keep the segment as is
            last_retained = segment

    # Normalize the path
    if last_retained is None:
        # Start with / if the input begins with /
        if path.startswith('/'):
            return '/'
        else:
            return ''

    # Ensure the path ends with /
    if not path.endswith('/'):
        return path + '/'

    # Use exactly one / between retained segments
    if len(segments) > 1:
        return '/'.join(segments)
    else:
        return path

# Check function to verify the correctness of the solution
def check():
    assert normalize_route_segments('/a//b/./c/../') == '/a/b/'
    assert normalize_route_segments('a/b/../../c') == 'c'
    assert normalize_route_segments('../x') == 'x'
    print("All tests passed!")

