def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    validated = []
    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError("each event must be a 3-item tuple")
        day, start, duration = rec
        if not isinstance(day, int) or isinstance(day, bool):
            raise ValueError("day must be int")
        if not isinstance(start, int) or isinstance(start, bool):
            raise ValueError("start must be int")
        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("duration must be int")
        if day < 1 or day > 7:
            raise ValueError("day out of range")
        if start < 0 or start > 1439:
            raise ValueError("start out of range")
        if duration <= 0:
            raise ValueError("duration must be positive")
        end = start + duration
        if end > 1440:
            raise ValueError("interval exceeds day")
        validated.append((day, start, end))

    if not validated:
        return ""

    by_day = {}
    for day, start, end in validated:
        by_day.setdefault(day, []).append((start, end))

    def fmt(mins):
        h, m = divmod(mins, 60)
        return f"{h:02d}:{m:02d}"

    parts = []
    for day in sorted(by_day):
        intervals = sorted(by_day[day])
        merged = []
        cur_s, cur_e = intervals[0]
        for s, e in intervals[1:]:
            if s <= cur_e:
                if e > cur_e:
                    cur_e = e
            else:
                merged.append((cur_s, cur_e))
                cur_s, cur_e = s, e
        merged.append((cur_s, cur_e))
        for s, e in merged:
            parts.append(f"D{day}:{fmt(s)}-{fmt(e)}")
    return ";".join(parts)

def normalize_profile_records(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    result = []
    for rec in records:
        if not isinstance(rec, dict):
            raise TypeError("each record must be a dict")

        rec_id = rec.get('id', None)
        if not isinstance(rec_id, int) or isinstance(rec_id, bool) or rec_id <= 0:
            continue

        name = rec.get('name', '')
        email = rec.get('email', '')
        tags = rec.get('tags', [])

        name = str(name).strip().title()
        email = str(email).strip().lower()

        if isinstance(tags, str):
            raw_tags = tags.split(',')
        else:
            try:
                raw_tags = list(tags)
            except TypeError:
                raw_tags = [tags]

        cleaned = []
        seen = set()
        for tag in raw_tags:
            t = str(tag).strip()
            if not t:
                continue
            if t not in seen:
                seen.add(t)
                cleaned.append(t)
        cleaned.sort()

        result.append({'id': rec_id, 'name': name, 'email': email, 'tags': cleaned})

    return result

