    """
    Normalize a list of user profile records by removing invalid ones and normalizing tags.

    Parameters:
    records (list of dict): A list of dictionaries representing user profile records.

    Returns:
    list of dict: A list of normalized user profile records.
    """
    def normalize_tag(tag):
        if isinstance(tag, str):
            return tag.strip().title()
        elif isinstance(tag, list):
            return [t.strip().title() for t in tag]
        else:
            return []

    def normalize_record(record):
        if 'id' not in record:
            return record
        id_value = record['id']
        if not isinstance(id_value, int) or id_value <= 0:
            return record
        name = record.get('name', '')
        email = record.get('email', '')
        tags = record.get('tags', [])

        # Normalize tags
        normalized_tags = [normalize_tag(tag) for tag in tags]

        # Filter out invalid records
        valid_records = [record for record in records if record['id'] > 0 and all(isinstance(value, str) or isinstance(value, list) for value in record.values())]

        # Return the normalized records
        return valid_records

    return normalize_record(records)

