def parse_purchase_order(lines):
    order_id = None
    customer = None
    items = []

    for raw in lines:
        if not isinstance(raw, str):
            raise ValueError('all lines must be strings')
        line = raw.strip()
        if line == '' or line.startswith('#'):
            continue
        if line.startswith('ORDER '):
            if order_id is not None:
                raise ValueError('duplicate ORDER')
            parts = line.split()
            if len(parts) != 2 or not parts[1]:
                raise ValueError('malformed ORDER')
            order_id = parts[1]
            if ' ' in order_id:
                raise ValueError('malformed ORDER')
        elif line.startswith('CUSTOMER='):
            if customer is not None:
                raise ValueError('duplicate CUSTOMER')
            customer = line[len('CUSTOMER='):]
            if customer == '':
                raise ValueError('malformed CUSTOMER')
        elif line.startswith('ITEM '):
            parts = line.split()
            if len(parts) != 4:
                raise ValueError('malformed ITEM')
            sku, qty_s, price_s = parts[1], parts[2], parts[3]
            if not sku or ' ' in sku:
                raise ValueError('malformed ITEM')
            try:
                quantity = int(qty_s)
            except Exception:
                raise ValueError('invalid quantity')
            if str(quantity) != qty_s or quantity <= 0:
                raise ValueError('invalid quantity')
            try:
                unit_price = float(price_s)
            except Exception:
                raise ValueError('invalid price')
            if unit_price < 0:
                raise ValueError('invalid price')
            line_total = quantity * unit_price
            items.append({'sku': sku, 'quantity': quantity, 'unit_price': unit_price, 'line_total': line_total})
        else:
            raise ValueError('malformed line')

    if order_id is None or customer is None:
        raise ValueError('missing required fields')

    grand_total = sum(item['line_total'] for item in items)
    return {
        'order_id': order_id,
        'customer': customer,
        'items': items,
        'grand_total': grand_total,
    }

def normalize_section_labels(labels):
    if not isinstance(labels, list):
        raise TypeError("labels must be a list")
    result = []
    for item in labels:
        if not isinstance(item, str):
            raise TypeError("all labels must be strings")
        collapsed = " ".join(item.split())
        if collapsed == "":
            result.append("<EMPTY>")
        else:
            result.append(collapsed.upper())
    return result

def normalize_route_segments(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if path == '':
        return ''
    parts = [seg for seg in path.split('/') if seg != '']
    normalized = []
    for seg in parts:
        low = seg.lower()
        if low.isalpha() and len(low) > 3:
            low = low[:3]
        normalized.append(low)
    return '/'.join(normalized)

def compress_ranges(nums):
    if not isinstance(nums, list):
        raise TypeError('nums must be a list')
    for x in nums:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
    if not nums:
        return []
    values = sorted(set(nums))
    ranges = []
    start = prev = values[0]
    for v in values[1:]:
        if v == prev + 1:
            prev = v
        else:
            ranges.append((start, prev))
            start = prev = v
    ranges.append((start, prev))
    return ranges

def normalize_priority_queue(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    validated = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('each event must be a 3-tuple')
        priority, timestamp, payload = item
        if not isinstance(priority, int):
            raise ValueError('priority must be int')
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('timestamp must be a non-negative int')
        validated.append(item)

    return sorted(validated, key=lambda x: (x[0], x[1], str(x[2])))

def normalize_inventory_movements(movements):
    totals = {}
    for record in movements:
        if record is None:
            continue
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            continue
        item, action, quantity = record
        if not isinstance(item, str) or item == '':
            continue
        if action not in ('in', 'out', 'adjust'):
            continue
        if not isinstance(quantity, int):
            continue
        if action == 'in':
            totals[item] = totals.get(item, 0) + quantity
        elif action == 'out':
            totals[item] = totals.get(item, 0) - quantity
        else:
            totals[item] = quantity
    return sorted((item, total) for item, total in totals.items() if total != 0)

def summarize_packet_stream(packets):
    accepted = []
    for item in packets:
        if item == 'DROP':
            if not accepted:
                raise ValueError('DROP with no packet to remove')
            accepted.pop()
            continue
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('Invalid packet description')
        kind, size = item
        if not isinstance(kind, str) or kind == '' or not isinstance(size, int) or size < 0:
            raise ValueError('Invalid packet tuple')
        accepted.append((kind, size))

    if not accepted:
        return ''

    order = []
    seen = set()
    totals = {}
    counts = {}
    for kind, size in accepted:
        if kind not in seen:
            seen.add(kind)
            order.append(kind)
        counts[kind] = counts.get(kind, 0) + 1
        totals[kind] = totals.get(kind, 0) + size

    parts = []
    for kind in order:
        parts.append(f'{kind}={counts[kind]}:{totals[kind]}')
    return ';'.join(parts)

def distribute_tokens(users, token_count):
    if not isinstance(users, list):
        raise TypeError("users must be a list")
    if not isinstance(token_count, int):
        raise TypeError("token_count must be an integer")
    if token_count < 0:
        raise ValueError("token_count must be non-negative")
    for u in users:
        if not isinstance(u, str) or u == "":
            raise ValueError("each user must be a non-empty string")

    result = {}
    for u in users:
        if u not in result:
            result[u] = []

    if token_count == 0 or not users:
        return result if users else {}

    distinct_order = []
    seen = set()
    for u in users:
        if u not in seen:
            seen.add(u)
            distinct_order.append(u)

    for token in range(1, token_count + 1):
        idx = (token - 1) % len(users)
        user = users[idx]
        result[user].append(token)
    return result

def normalize_event_stream(events):
    try:
        iterator = iter(events)
    except TypeError:
        raise TypeError("events must be iterable")

    total = 0
    tags = []
    seen = set()

    for item in iterator:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each event must be a 2-item tuple")
        event_type, value = item
        if not isinstance(event_type, str):
            raise TypeError("event type must be a string")

        if event_type == 'inc':
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("inc value must be an integer")
            total += value
        elif event_type == 'set':
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("set value must be an integer")
            total = value
        elif event_type == 'tag':
            if not isinstance(value, str):
                raise TypeError("tag value must be a string")
            if value not in seen:
                seen.add(value)
                tags.append(value)
        elif event_type == 'skip':
            if value is not None:
                raise TypeError("skip value must be None")
        else:
            raise ValueError("unknown event type")

    return {'total': total, 'tags': tags}

def summarize_changes(before, after):
    if not isinstance(before, list) or not isinstance(after, list):
        raise TypeError("before and after must be lists")
    if len(before) != len(after):
        raise ValueError("before and after must have the same length")

    increased = 0
    decreased = 0
    unchanged = 0
    delta_sum = 0

    for b, a in zip(before, after):
        diff = a - b
        delta_sum += diff
        if diff > 0:
            increased += 1
        elif diff < 0:
            decreased += 1
        else:
            unchanged += 1

    return {
        "increased": increased,
        "decreased": decreased,
        "unchanged": unchanged,
        "delta_sum": delta_sum,
    }

def summarize_spans(text, keywords):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        kws = list(keywords)
    except TypeError:
        raise TypeError("keywords must be iterable of strings")
    lowered = []
    for kw in kws:
        if not isinstance(kw, str):
            raise TypeError("keywords must be iterable of strings")
        if kw == "":
            raise ValueError("empty keyword is invalid")
        lowered.append(kw.lower())
    unique_keywords = []
    seen = set()
    for kw in lowered:
        if kw not in seen:
            seen.add(kw)
            unique_keywords.append(kw)
    if not unique_keywords:
        return {'counts': {}, 'first_positions': {}, 'longest_run': (None, 0)}
    words = []
    current = []
    for ch in text:
        if ch.isascii() and ch.isalnum():
            current.append(ch.lower())
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    counts = {kw: 0 for kw in unique_keywords}
    first_positions = {kw: -1 for kw in unique_keywords}
    positions = {kw: [] for kw in unique_keywords}
    for i, w in enumerate(words):
        if w in counts:
            counts[w] += 1
            positions[w].append(i)
            if first_positions[w] == -1:
                first_positions[w] = i
    best_kw = None
    best_len = 0
    best_first = None
    for kw in unique_keywords:
        pos = positions[kw]
        max_run = 0
        run = 0
        prev = None
        for p in pos:
            if prev is not None and p == prev + 1:
                run += 1
            else:
                run = 1
            if run > max_run:
                max_run = run
            prev = p
        if max_run > 0:
            candidate_first = first_positions[kw]
            if (max_run > best_len or
                (max_run == best_len and (best_first is None or candidate_first < best_first)) or
                (max_run == best_len and candidate_first == best_first and kw < best_kw)):
                best_kw = kw
                best_len = max_run
                best_first = candidate_first
    if best_kw is None:
        longest_run = (None, 0)
    else:
        longest_run = (best_kw, best_len)
    return {'counts': counts, 'first_positions': first_positions, 'longest_run': longest_run}

def summarize_spans(text, keywords):
    """
    Analyzes a given text and returns a summary dictionary for keyword occurrences.

    Parameters:
    text (str): The text to analyze.
    keywords (iterable of str): The keywords to search for.

    Returns:
    dict: A dictionary with counts, first positions, and longest run information.
    """
    if not isinstance(text, str) or not isinstance(keywords, Iterable):
        raise TypeError("text must be a string and keywords must be an iterable of strings.")
    if not keywords:
        raise ValueError("keywords cannot be empty.")

    # Convert text to lowercase and split into words
    words = text.lower().split()

    # Dictionary to store keyword counts
    keyword_counts = {}

    # Dictionary to store first position of each keyword
    first_positions = {}

    # Dictionary to store longest run information
    longest_run = (None, 0)

    # Iterate over each keyword
    for keyword in keywords:
        # Convert keyword to lowercase
        keyword = keyword.lower()

        # Count occurrences of the keyword
        count = sum(1 for word in words if word == keyword)

        # Update keyword counts
        if keyword in keyword_counts:
            keyword_counts[keyword] += count
        else:
            keyword_counts[keyword] = count

        # Update first positions
        if keyword in first_positions:
            first_positions[keyword] = max(first_positions[keyword], words.index(keyword))
        else:
            first_positions[keyword] = words.index(keyword)

        # Update longest run
        if keyword == longest_run[0] and count > longest_run[1]:
            longest_run = (keyword, count)
        elif keyword != longest_run[0] and count > longest_run[1]:
            longest_run = (keyword, count)

    # Return the summary dictionary
    return {
        "counts": keyword_counts,
        "first_positions": first_positions,
        "longest_run": longest_run
    }

