def normalize_inventory(records):
    valid = []
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        category, item_id, quantity = rec
        if not isinstance(category, str) or not isinstance(item_id, str):
            continue
        if not isinstance(quantity, int) or quantity < 0:
            continue
        valid.append((category, item_id, quantity))

    if not valid:
        return {'categories': {}, 'grand_total': 0}

    by_category = {}
    for category, item_id, quantity in valid:
        if category not in by_category:
            by_category[category] = {}
        if item_id not in by_category[category]:
            by_category[category][item_id] = 0
        by_category[category][item_id] += quantity

    categories_out = {}
