        total = 0
        for item_id in sorted(items):
            qty = items[item_id]
            items_out[item_id] = qty
            total += qty
        categories_out[category] = {'total': total, 'items': items_out}
        grand_total += total

    return {'categories': categories_out, 'grand_total': grand_total}

def normalize_inventory(records):
    """
    Normalize an inventory list into a summary dictionary.

    :param records: List of tuples (category, item_id, quantity)
    :return: A dictionary with categories and grand total
    """
    categories = {}
    grand_total = 0

    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            continue

        category, item_id, quantity = record

        if not isinstance(category, str) or not isinstance(item_id, str) or not isinstance(quantity, int) or quantity < 0:
