        if category in categories:
            categories[category]['total'] += quantity
            categories[category]['items'][item_id] += quantity
        else:
            categories[category] = {'total': quantity, 'items': {item_id: quantity}}

    for category, items in categories.items():
        grand_total += items['total']

    return {'categories': categories, 'grand_total': grand_total}

