def select_min_cost_path(grid):
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError("grid must be a non-empty list of rows")
    if not all(isinstance(row, list) for row in grid):
        raise ValueError("grid must be a list of lists")
    if any(len(row) == 0 for row in grid):
        raise ValueError("rows must be non-empty")
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("all rows must have the same length")
    for row in grid:
        for cell in row:
            if not isinstance(cell, int):
                raise ValueError("all cells must be integers")

    rows = len(grid)
    cols = width
    dp = [0] * cols
    dp[0] = grid[0][0]
    for j in range(1, cols):
        dp[j] = dp[j - 1] + grid[0][j]
    for i in range(1, rows):
        dp[0] += grid[i][0]
        for j in range(1, cols):
            dp[j] = min(dp[j], dp[j - 1]) + grid[i][j]
    return dp[-1]

def pack_ranges(values):
    items = []
    for v in values:
        if type(v) is not int:
            raise TypeError('all elements must be integers')
        items.append(v)

    if not items:
        return ''

    nums = sorted(set(items))
    parts = []
    i = 0
    n = len(nums)

    while i < n:
        start = nums[i]
        j = i
        while j + 1 < n and nums[j + 1] == nums[j] + 1:
            j += 1
        length = j - i + 1
        if length >= 3:
            parts.append(f'{start}-{nums[j]}')
        elif length == 2:
            parts.append(str(nums[i]))
            parts.append(str(nums[j]))
        else:
            parts.append(str(start))
        i = j + 1

    return ','.join(parts)

def normalize_spreadsheet_headers(headers):
    if not isinstance(headers, list):
        raise TypeError("headers must be a list")

    seen = {}
    result = []

    for header in headers:
        if not isinstance(header, str):
            raise TypeError("all headers must be strings")

        if header not in seen:
            seen[header] = 1
            result.append(header)
        else:
            k = seen[header] + 1
            candidate = f"{header}({k})"
            while candidate in seen:
                k += 1
                candidate = f"{header}({k})"
            seen[header] = k
            seen[candidate] = 1
            result.append(candidate)

    return result

def parse_tape(spec: str) -> list[tuple[int, str]]:
    s = spec.strip()
    if s == "":
        return []
    parts = [p.strip() for p in s.split(';')]
    if any(p == "" for p in parts):
        raise ValueError("empty segment")
    result = []
    for part in parts:
        if part.count('*') != 1:
            raise ValueError("malformed segment")
        count_str, symbol = part.split('*')
        if count_str == "" or symbol == "":
            raise ValueError("malformed segment")
        if count_str.startswith('-'):
            raise ValueError("negative count")
        if not count_str.isdigit():
            raise ValueError("non-numeric count")
        count = int(count_str)
        result.append((count, symbol))
    return result

def canonicalize_command_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    s = path.strip()
    parts = []
    for comp in s.split('/'):
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            if parts:
                parts.pop()
            continue
        parts.append(comp)
    return '/'.join(parts) if parts else '.'

def normalize_inventory(records):
