    weighted = {}
    for record in records:
        if len(record) != 3:
            raise TypeError('each record must have exactly 3 items')
        sku, quantity, price = record
        if not isinstance(sku, str) or not isinstance(quantity, int) or not isinstance(price, (int, float)):
            raise TypeError('invalid record types')
        if quantity < 0:
            raise ValueError('quantity cannot be negative')
        if quantity == 0:
            continue
        if sku not in totals:
            totals[sku] = 0
            weighted[sku] = 0.0
        totals[sku] += quantity
        weighted[sku] += quantity * float(price)
    result = []
    for sku in sorted(totals):
        total_quantity = totals[sku]
        if total_quantity == 0:
            continue
        avg = weighted[sku] / total_quantity
        result.append((sku, total_quantity, float(avg)))
    return result

def summarize_runs(data):
    runs = []
    total_items = 0
    distinct = set()

    iterator = iter(data)
    try:
        first = next(iterator)
    except StopIteration:
        return {"runs": [], "longest_run": None, "total_items": 0, "distinct_values": 0}

    if type(first) is not int:
        raise TypeError("all elements must be integers")

    current_value = first
    current_length = 1
    total_items = 1
    distinct.add(first)

    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        total_items += 1
        distinct.add(item)
        if item == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            current_value = item
            current_length = 1

    runs.append((current_value, current_length))

    longest = runs[0]
    for run in runs[1:]:
        if run[1] > longest[1]:
            longest = run

    return {
        "runs": runs,
        "longest_run": longest,
        "total_items": total_items,
        "distinct_values": len(distinct),
    }

