def summarize_runs(data: Iterable[int]) -> Dict[str, Tuple[int, int]]:
    """
    Analyzes a sequence of integer run lengths. Each consecutive equal integer is treated as one run.
    Returns a dictionary with exactly these keys:
    - "runs": a list of `(value, length)` tuples for each consecutive run in order.
    - "longest_run": a `(value, length)` tuple for the longest run. If there is a tie, choose the earliest run in the input.
    - "total_items": the total number of items seen.
    - "distinct_values": the number of distinct integer values appearing anywhere in the input.

    Raises TypeError if any element is not an integer.
    """
    if not data:
        return {"runs": [], "longest_run": None, "total_items": 0, "distinct_values": 0}

    distinct_values = set(data)
    runs = []
    longest_run = (None, 0)

    for value, length in enumerate(data):
        if value == longest_run[0]:
            longest_run = (value, length + 1)
        elif value != longest_run[0]:
            runs.append(longest_run)
            longest_run = (value, 1)

    runs.append(longest_run)

    return {
        "runs": runs,
        "longest_run": longest_run,
        "total_items": len(data),
        "distinct_values": len(distinct_values)
    }

