def compress_ranges(values):
    result = []
    sentinel = object()
    prev = sentinel
    count = 0

    for item in values:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        if prev is sentinel:
            prev = item
            count = 1
        elif item == prev:
            count += 1
        else:
            result.append(f"{prev}:{count}" if count > 1 else f"{prev}")
            prev = item
            count = 1

    if prev is not sentinel:
        result.append(f"{prev}:{count}" if count > 1 else f"{prev}")

    return result

def normalize_cli_args(args):
    result = []
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError('all arguments must be strings')
        if not arg.startswith('-'):
            continue
        if arg == '-':
            raise ValueError('invalid lone dash')
        if arg.startswith('--'):
            body = arg[2:]
            if body.startswith('no-'):
                name = body[3:]
                if not name or '=' in name or name.count('=') > 0:
                    raise ValueError('invalid long option')
                result.append((name, 'false'))
            else:
                if body.count('=') > 1:
                    raise ValueError('invalid long option')
                if '=' in body:
                    name, value = body.split('=', 1)
                    if not name:
                        raise ValueError('invalid long option')
                    result.append((name, value))
                else:
                    if not body:
                        raise ValueError('invalid long option')
                    result.append((body, 'true'))
        else:
            body = arg[1:]
            if not body or '=' in body:
                raise ValueError('invalid short option')
            if not body.isalpha():
                raise ValueError('invalid short option')
            for ch in body:
                result.append((ch, 'true'))
    return result

def normalize_transcript(lines):
    result = []
    for raw in lines:
        if not isinstance(raw, str):
            raise TypeError('all items must be strings')
        s = raw.strip()
        if not s:
            continue
        label_end = s.find(':')
        if label_end > 0:
            prefix = s[:label_end]
            if prefix and all(ch.isupper() or ch.isdigit() or ch == '_' for ch in prefix):
                s = s[label_end + 1:].lstrip()
        s = ' '.join(s.split())
        s = s.lower()
        if s:
            result.append(s)
    return result

