        if len(entry) != 2:
            raise TypeError("Each entry must contain exactly two elements.")
        account_name, amount = entry
        if not isinstance(account_name, str):
            raise TypeError("Account name must be a string.")
        if not isinstance(amount, (int, float)):
            raise TypeError("Amount must be a valid numeric type.")
        if not account_name.strip():
            raise ValueError("Account name cannot be empty.")
        if amount == 0:
            return f"{normalize_account(account_name)}=0"
        return f"{normalize_account(account_name)}={normalize_amount(amount)}"

    normalized_entries = [normalize_entry(entry) for entry in entries]
    normalized_entries.sort(key=lambda x: x[0])
    normalized_summary = '; '.join(normalized_entries)
    return normalized_summary

