            raise ValueError('each non-empty line must contain exactly one =')
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError('key must be non-empty')
        result[key] = value
    return result

def normalize_schedule(entries):
    normalized = []
    for item in entries:
        try:
            pair = tuple(item)
        except TypeError:
            raise TypeError("each entry must be an iterable of length 2")
        if len(pair) != 2:
            raise TypeError("each entry must be an iterable of length 2")
        start, end = pair
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("interval bounds must be integers")
        if start > end:
            raise ValueError("interval start cannot exceed end")
        normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged

def canonicalize_pairs(pairs):
    unique = set()
    for pair in pairs:
        try:
            a, b = pair
        except Exception as e:
            raise ValueError("each item must be a 2-element iterable") from e
        try:
            normalized = tuple(sorted((a, b)))
        except TypeError:
            raise
        unique.add(normalized)
    return tuple(sorted(unique))

def canonicalize_event_log(log: str) -> str:
    if log == "":
        return ""
    records = []
    for raw_record in log.split(";"):
        record = raw_record.strip()
        if not record:
            continue
        parts = record.split(",")
        if len(parts) != 2:
            continue
        ts_raw = parts[0].strip()
        name = parts[1].strip()
        if not name:
            continue
        try:
            ts = int(ts_raw, 10)
        except Exception:
            continue
        if ts_raw and any(ch.isspace() for ch in ts_raw):
            continue
        records.append((ts, name))
    records.sort(key=lambda x: (x[0], x[1]))
    return ";".join(f"{ts},{name}" for ts, name in records)

def normalize_inventory_changes(events):
    try:
        iterator = iter(events)
    except TypeError:
        raise TypeError("events must be iterable")

    totals = {}
    order = []

    for item in iterator:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each event must be a 2-item tuple")
        sku, delta = item
        if not isinstance(sku, str) or sku == "":
            raise TypeError("sku must be a non-empty string")
        if type(delta) is not int:
            raise TypeError("delta must be an integer")
        if sku not in totals:
            totals[sku] = 0
            order.append(sku)
        totals[sku] += delta

    parts = [f"{sku}={totals[sku]}" for sku in order if totals[sku] != 0]
    return ";".join(parts)

def normalize_schedule(events):
    # Validate and collect intervals by day
    grouped = {}
    for rec in events:
        if not isinstance(rec, (list, tuple)) or len(rec) != 3:
            raise ValueError('invalid record')
        day, start, end = rec
        if not isinstance(day, str) or not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('invalid record')
        if start < 0 or end > 1440 or start >= end:
            raise ValueError('invalid record')
        grouped.setdefault(day, []).append((start, end))

    result = []
    for day in sorted(grouped.keys()):
        intervals = sorted(grouped[day])
        merged = []
        for s, e in intervals:
            if not merged:
                merged.append([s, e])
            else:
                last_s, last_e = merged[-1]
                if s <= last_e:
                    if e > last_e:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
        for s, e in merged:
            result.append((day, s, e))
    return result

def summarize_runs(data):
    values = []
    for x in data:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
        values.append(x)

    if not values or all(x == 0 for x in values):
        return {'segments': 0, 'longest_streak': 0, 'net_change': 0, 'peak_count': 0}

    segments = 0
    longest_streak = 0
    net_change = 0
    peak_count = 0

    i = 0
    n = len(values)
    while i < n:
        net_change += values[i]
        if values[i] == 0:
            i += 1
            continue

        sign = 1 if values[i] > 0 else -1
        total = 0
        length = 0
        while i < n and values[i] != 0 and (1 if values[i] > 0 else -1) == sign:
            total += values[i]
            net_change += values[i] if length > 0 else 0
            length += 1
            i += 1
            if length > 1:
                pass
        segments += 1
        if length > longest_streak:
            longest_streak = length
        avg = total / length
        if sign > 0 and avg > 0:
            peak_count += 1
        elif sign < 0 and avg < 0:
            peak_count += 1

    return {'segments': segments, 'longest_streak': longest_streak, 'net_change': sum(values), 'peak_count': peak_count}

def normalize_inventory_changes(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    result = {}
    totals = {}
    abs_sums = {}
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError('each record must be a 3-item tuple')
        sku, delta, price = rec
        if not isinstance(sku, str):
            raise ValueError('sku must be a string')
        norm_sku = sku.strip()
        if not norm_sku:
            raise ValueError('sku must be non-empty')
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise ValueError('delta must be an integer')
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            raise ValueError('price must be numeric')
        if norm_sku not in result:
            result[norm_sku] = {'net_delta': 0, 'weighted_avg_price': 0.0, 'history': []}
            totals[norm_sku] = 0.0
            abs_sums[norm_sku] = 0
        result[norm_sku]['net_delta'] += delta
        result[norm_sku]['history'].append((delta, price))
        totals[norm_sku] += abs(delta) * price
        abs_sums[norm_sku] += abs(delta)
    for sku in result:
        if abs_sums[sku] == 0:
            result[sku]['weighted_avg_price'] = 0.0
        else:
            result[sku]['weighted_avg_price'] = totals[sku] / abs_sums[sku]
    return result

def parse_digit_columns(text: str) -> list[list[int]]:
    result = []
    for line in text.split('\n'):
        if line.strip() == '':
            continue
        digits = [int(ch) for ch in line if ch.isdigit()]
        result.append(digits)
    return result

def longest_balanced_prefix(nums):
    total = 0
    for i, x in enumerate(nums, start=1):
        total += x
        if total < 0:
            if i == 1:
                return (0, 0)
            # The prefix ending just before this element is the longest balanced prefix.
            prefix_total = total - x
            return (i - 1, prefix_total)
    return (len(nums), total)

def merge_sorted_rows(rows):
    try:
        outer = list(rows)
    except TypeError:
        raise TypeError("rows must be iterable")

    for row in outer:
        if not hasattr(row, '__iter__'):
            raise TypeError("each row must be iterable")

    merged = []
    prepared = []
    for row_index, row in enumerate(outer):
        items = []
        for item in row:
            if not isinstance(item, tuple) or len(item) != 2:
                raise TypeError("each element must be a 2-item tuple")
            items.append(item)
        prepared.append(items)

    indices = [0] * len(prepared)
    while True:
        best_row = None
        best_key = None
        for i, items in enumerate(prepared):
            j = indices[i]
            if j >= len(items):
                continue
            key = items[j][0]
            if best_row is None or key < best_key or (key == best_key and i < best_row):
                best_row = i
                best_key = key
        if best_row is None:
            break
        merged.append(prepared[best_row][indices[best_row]])
        indices[best_row] += 1
    return merged

def compress_intervals(intervals):
    if intervals is None:
        raise TypeError("intervals must be an iterable of intervals")
    normalized = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a 2-element sequence")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must not exceed end")
        normalized.append([start, end])
    if not normalized:
        return []
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def normalize_inventory(transactions):
    if transactions is None:
        raise ValueError('transactions must be iterable of 3-tuples')

    order = []
    totals = {}
    tags = {}

    for record in transactions:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError('invalid transaction record')
        sku, delta, tag = record
        if not isinstance(sku, str) or sku == '':
            raise ValueError('invalid sku')
        if not isinstance(delta, int):
            raise ValueError('invalid delta')
        if not (isinstance(tag, str) or tag is None):
            raise ValueError('invalid tag')

        if sku not in totals:
            order.append(sku)
            totals[sku] = 0
            tags[sku] = []
        totals[sku] += delta
        if tag is not None and tag not in tags[sku]:
            tags[sku].append(tag)

    result = []
    for sku in order:
        net = totals[sku]
        if net != 0:
            result.append((sku, net, '|'.join(tags[sku])))
    return result

def render_inventory_report(items, column_width):
    if type(column_width) is not int or column_width < 0:
        raise ValueError("column_width must be a non-negative integer")

    lines = []
    try:
        iterator = iter(items)
    except TypeError:
        raise ValueError("items must be iterable")

    for item in iterator:
        if not isinstance(item, dict):
            raise ValueError("each item must be a dictionary")
        if 'name' not in item or 'qty' not in item or 'price' not in item:
            raise ValueError("missing required key")
        name = item['name']
        qty = item['qty']
        price = item['price']
        if not isinstance(name, str):
            raise ValueError("name must be a string")
        if type(qty) is not int:
            raise ValueError("qty must be an integer")
        if type(price) not in (int, float):
            raise ValueError("price must be numeric")
        value = qty * price
        padded_name = name if len(name) >= column_width else name.ljust(column_width)
        lines.append(f"{padded_name} | qty={qty} | price={price:.2f} | value={value:.2f}")

    return "\n".join(lines)

def normalize_story_index(pages):
    if not isinstance(pages, list):
        raise TypeError("pages must be a list")

    seen = set()
    normalized = []

    for record in pages:
        if not isinstance(record, tuple) or len(record) != 3:
            raise TypeError("each record must be a 3-tuple")
        page_number, title, word_count = record
        if not isinstance(page_number, int) or not isinstance(title, str) or not isinstance(word_count, int):
            raise TypeError("invalid field types")
        if page_number < 0 or word_count < 0:
            raise ValueError("page_number and word_count must be non-negative")
        if page_number in seen:
            continue
        seen.add(page_number)

        cleaned_title = " ".join(title.split())
        if cleaned_title == "":
            cleaned_title = "Untitled"
        if word_count == 0:
            cleaned_title += " (empty)"
        normalized.append((page_number, cleaned_title, word_count))

    normalized.sort(key=lambda x: x[0])
    return normalized

def parse_log_summary(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    counts = {'INFO': 0, 'WARN': 0, 'ERROR': 0}
    meta = {}
    messages = []
    total_lines = 0

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        total_lines += 1

        if line.startswith('META '):
            payload = line[5:]
            if '=' not in payload:
                raise ValueError('invalid META line')
            key, value = payload.split('=', 1)
            if not key or not value:
                raise ValueError('invalid META line')
            meta[key] = value
            continue

        if ':' in line:
            typ, message = line.split(':', 1)
            if typ not in counts:
                raise ValueError('unknown log type')
            counts[typ] += 1
            messages.append((typ, message))
            continue

        raise ValueError('invalid line')

    return {'counts': counts, 'meta': meta, 'total_lines': total_lines, 'messages': messages}

def merge_runlength_strings(a, b):
    def parse(s):
        if not isinstance(s, str) or s == "":
            raise ValueError("invalid run-length string")
        groups = []
        i = 0
        n = len(s)
        while i < n:
            if not s[i].isdigit():
                raise ValueError("invalid run-length string")
            if s[i] == '0':
                raise ValueError("invalid run-length string")
            j = i
            while j < n and s[j].isdigit():
                j += 1
            if j >= n:
                raise ValueError("invalid run-length string")
            ch = s[j]
            if ch.isdigit():
                raise ValueError("invalid run-length string")
            count = int(s[i:j])
            if count <= 0:
                raise ValueError("invalid run-length string")
            groups.append((count, ch))
            i = j + 1
        return groups

    def expand(groups):
        out = []
        for count, ch in groups:
            out.append(ch * count)
        return ''.join(out)

    ga = parse(a)
    gb = parse(b)
    sa = expand(ga)
    sb = expand(gb)
    out = []
    max_len = max(len(sa), len(sb))
    for i in range(max_len):
        ca = sa[i] if i < len(sa) else None
        cb = sb[i] if i < len(sb) else None
        out.append(cb if cb is not None else ca)

    if not out:
        raise ValueError("invalid run-length string")

    result = []
    cur = out[0]
    cnt = 1
    for ch in out[1:]:
        if ch == cur:
            cnt += 1
        else:
            result.append(str(cnt) + cur)
            cur = ch
            cnt = 1
    result.append(str(cnt) + cur)
    return ''.join(result)

def compact_intervals(events):
    def normalize(record):
        if not isinstance(record, tuple) or len(record) not in (3, 4):
            raise ValueError('invalid record')
        if len(record) == 3:
            start, end, label = record
            attrs = {}
        else:
            start, end, label, attrs = record
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('invalid record')
        if start > end:
            raise ValueError('invalid record')
        if len(record) == 4 and not isinstance(attrs, dict):
            raise ValueError('invalid record')
        return (start, end, label, attrs)

    normalized = [normalize(r) for r in events]
    normalized.sort(key=lambda x: (x[0], x[1], x[2], tuple(sorted(x[3].items()))))

    merged = []
    for rec in normalized:
        if not merged:
            merged.append(rec)
            continue
        ps, pe, pl, pa = merged[-1]
        cs, ce, cl, ca = rec
        if pe == cs and pl == cl and pa == ca:
            merged[-1] = (ps, ce, pl, pa)
        else:
            merged.append(rec)
    return merged

import json

def compact_intervals(events):
    """
    Merges adjacent records in a list of event records into time intervals when they refer to the same label and share the same attributes.

    Parameters:
    events (list of tuples): A list where each tuple is either a 3-tuple or a 4-tuple.

    Returns:
    list of tuples: A list of 4-tuples representing the merged intervals.
    """
    def normalize_record(record):
        if len(record) != 3:
            raise ValueError("Record must be a 3-tuple or a 4-tuple.")
        if not isinstance(record[0], int) or not isinstance(record[1], int):
            raise ValueError("Start and end must be integers.")
        if record[0] > record[1]:
            raise ValueError("Start must be less than or equal to end.")
        return record

    def merge_intervals(record1, record2):
        start = max(record1[0], record2[0])
        end = min(record1[1], record2[1])
        label = record1[2]
        attrs = record1[3].copy()
        if record1[0] == record2[0]:
            attrs['start'] = start
        if record1[1] == record2[1]:
            attrs['end'] = end
        if record1[2] == record2[2]:
            attrs.update(record1[3])
        return (start, end, label, attrs)

    # Normalize and sort the events
    normalized_events = [normalize_record(event) for event in events]
    normalized_events.sort(key=lambda x: (x[0], x[1], x[2], json.dumps(x[3])))

    merged_intervals = []
    current_interval = None

    for record in normalized_events:
        if current_interval is None:
            current_interval = record
        else:
            if current_interval[1] < record[0]:
                merged_intervals.append(current_interval)
                current_interval = record
            elif current_interval[0] > record[1]:
                merged_intervals.append(current_interval)
                current_interval = record
            elif current_interval[1] == record[0]:
                current_interval[3].update(record[3])

    merged_intervals.append(current_interval)

    return merged_intervals

