def summarize_telemetry(records):
    allowed = {"OK", "WARN", "FAIL"}
    valid_count = 0
    invalid_count = 0
    ids_set = set()
    status_counts = {"OK": 0, "WARN": 0, "FAIL": 0}
    latest_timestamp_per_id = {}
    sums = {"OK": 0, "WARN": 0, "FAIL": 0}

    for rec in records:
        try:
            if not isinstance(rec, str):
                raise ValueError
            parts = rec.split("|")
            if len(parts) != 4:
                raise ValueError
            id_part, ts_part, value_part, status_part = parts
            if not id_part or "|" in id_part:
                raise ValueError
            if status_part not in allowed:
                raise ValueError
            if ts_part == "" or value_part == "":
                raise ValueError
            timestamp = int(ts_part, 10)
            value = int(value_part, 10)
            if timestamp < 0:
                raise ValueError
        except Exception:
            invalid_count += 1
            continue

        valid_count += 1
        ids_set.add(id_part)
        status_counts[status_part] += 1
        sums[status_part] += value
        if id_part not in latest_timestamp_per_id or timestamp > latest_timestamp_per_id[id_part]:
            latest_timestamp_per_id[id_part] = timestamp

    average_value_by_status = {}
    for status in ["OK", "WARN", "FAIL"]:
        if status_counts[status] == 0:
            average_value_by_status[status] = None
        else:
            average_value_by_status[status] = sums[status] / status_counts[status]

    return {
        "valid_count": valid_count,
        "invalid_count": invalid_count,
        "ids": sorted(ids_set),
        "status_counts": status_counts,
        "latest_timestamp_per_id": latest_timestamp_per_id,
        "average_value_by_status": average_value_by_status,
    }

def merge_colored_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")

    validated = []
    for item in intervals:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError("each interval must be a 3-tuple")
        start, end, color = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("start and end must be integers")
        if not isinstance(color, str):
            raise TypeError("color must be a string")
        if start >= end:
            raise ValueError("start must be less than end")
        validated.append((start, end, color))

    if not validated:
        return []

    grouped = {}
    for start, end, color in validated:
        grouped.setdefault(color, []).append((start, end))

    merged = []
    for color, spans in grouped.items():
        spans.sort()
        cur_start, cur_end = spans[0]
        for start, end in spans[1:]:
            if start <= cur_end:
                if end > cur_end:
                    cur_end = end
            else:
                merged.append((cur_start, cur_end, color))
                cur_start, cur_end = start, end
        merged.append((cur_start, cur_end, color))

    merged.sort(key=lambda x: (x[0], x[1], x[2]))
    return merged

def segment_runs(s: str) -> list[tuple[str, int]]:
    if s == "":
        return []
    result = []
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = ch
            count = 1
    result.append((current_char, count))
    return result

def compress_runs(tokens):
    result = []
    tokens = list(tokens)
    if not tokens:
        return result

    current = tokens[0]
    count = 1
    for item in tokens[1:]:
        if item == current:
            count += 1
        else:
            result.append([current, count])
            current = item
            count = 1
    result.append([current, count])
    return result

def normalize_breadcrumb_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    is_absolute = path.startswith('/')
    parts = []

    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts and parts[-1] != '..':
                parts.pop()
            else:
                if not is_absolute:
                    parts.append('..')
            continue
        parts.append(segment)

    if is_absolute:
        return '/' if not parts else '/' + '/'.join(parts)
    return '.' if not parts else '/'.join(parts)

def canonicalize_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        return "."

    is_absolute = path[0] in ("/", "\\")
    parts = []
    for segment in path.replace("\\", "/").split("/"):
        if segment == "" or segment == ".":
            continue
        if segment == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            else:
                if not is_absolute:
                    parts.append("..")
        else:
            parts.append(segment)

    if is_absolute:
        return "/" if not parts else "/" + "/".join(parts)
    return "." if not parts else "/".join(parts)

def merge_intervals_with_labels(intervals):
    if intervals == []:
        return []
    validated = []
    for item in intervals:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError('Each interval must be a 3-tuple')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int) or not isinstance(label, str):
            raise ValueError('Invalid interval types')
        if start > end:
            raise ValueError('start must be <= end')
        validated.append((start, end, label))
    validated.sort(key=lambda x: (x[0], x[1], x[2]))
    merged = []
    cur_start, cur_end, cur_label = validated[0]
    for start, end, label in validated[1:]:
        if label == cur_label and start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            merged.append((cur_start, cur_end, cur_label))
            cur_start, cur_end, cur_label = start, end, label
    merged.append((cur_start, cur_end, cur_label))
    return merged

def encode_compressed_runs(data):
    if not isinstance(data, list):
        raise TypeError('data must be a list of integers')
    for x in data:
        if type(x) is not int:
            raise TypeError('data must be a list of integers')

    if not data:
        return []

    out = []
    i = 0
    n = len(data)
    while i < n:
        value = data[i]
        j = i + 1
        while j < n and data[j] == value:
            j += 1
        count = j - i
        if count == 1:
            out.append(value)
        elif count == 2:
            out.append((value, 2))
        else:
            out.append((value, count, 'R'))
        i = j
    return out

def decode_rle_segments(encoded):
    if encoded is None:
        raise ValueError("encoded must be a string")
    if encoded.strip() == "":
        return []

    result = []
    segments = encoded.split("|")
    for segment in segments:
        seg = segment.strip()
        if seg == "":
            raise ValueError("malformed segment")
        if seg.count(":") != 1:
            raise ValueError("malformed segment")
        left, right = seg.split(":")
        left = left.strip()
        right = right.strip()
        if left == "" or right == "":
            raise ValueError("malformed segment")
        try:
            value = int(left)
        except Exception:
            raise ValueError("malformed value")
        try:
            count = int(right)
        except Exception:
            raise ValueError("malformed count")
        if count < 0:
            raise ValueError("negative count")
        result.extend([value] * count)
    return result

def summarize_runs(text: str) -> list[tuple[str, int, int]]:
    if text == "":
        return []

    result = []
    index = {}

    lines = text.split("\n")
    for raw_line in lines:
        if raw_line == "":
            continue
        parts = raw_line.split("|")
        if len(parts) != 3:
            raise ValueError("malformed line")
        run_id, status, value_str = parts
        if run_id == "":
            raise ValueError("malformed line")
        if status not in {"ok", "fail"}:
            raise ValueError("malformed line")
        if value_str == "":
            raise ValueError("malformed line")
        try:
            value = int(value_str, 10)
        except Exception:
            raise ValueError("malformed line")
        if str(value) != value_str and not (value_str.startswith("+") and str(value) == value_str[1:]):
            raise ValueError("malformed line")

        if run_id not in index:
            index[run_id] = len(result)
            result.append([run_id, 0, 0])
        entry = result[index[run_id]]
        if status == "ok":
            entry[1] += 1
        else:
            entry[2] += value

    return [tuple(item) for item in result]

def normalize_event_counts(events, allowed_events):
    if events is None or allowed_events is None:
        raise TypeError('events and allowed_events must not be None')

    canonical = {}
    for item in allowed_events:
        if not isinstance(item, str):
            raise TypeError('allowed_events must contain only strings')
        key = item.lower()
        if key in canonical:
            raise ValueError('duplicate allowed event ignoring case')
        canonical[key] = item

    normalized = []
    dropped = []
    for ev in events:
        if not isinstance(ev, str) or ev == '':
            dropped.append(ev)
            continue
        mapped = canonical.get(ev.lower())
        if mapped is None:
            dropped.append(ev)
        else:
            normalized.append(mapped)
    return normalized, dropped

def summarize_token_stream(tokens):
    count = 0
    unique_count = 0
    longest = None
    longest_len = -1
    first_positions = {}
    runs = []

    prev = object()
    run_len = 0

    for idx, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError('all tokens must be strings')

        count += 1

        if tok not in first_positions:
            first_positions[tok] = idx
            unique_count += 1

        tok_len = len(tok)
        if tok_len > longest_len:
            longest = tok
            longest_len = tok_len

        if idx == 0:
            prev = tok
            run_len = 1
        elif tok == prev:
            run_len += 1
        else:
            runs.append((prev, run_len))
            prev = tok
            run_len = 1

    if count == 0:
        return {'count': 0, 'unique_count': 0, 'longest': None, 'first_positions': {}, 'runs': []}

    runs.append((prev, run_len))
    return {
        'count': count,
        'unique_count': unique_count,
        'longest': longest,
        'first_positions': first_positions,
        'runs': runs,
    }

def decode_run_length_grid(spec: str):
    if not isinstance(spec, str):
        raise ValueError("spec must be a string")
    parts = spec.split('\n')
    if len(parts) != 2:
        raise ValueError("input must contain exactly two lines")
    header, body = parts
    header_parts = header.split()
    if len(header_parts) != 2:
        raise ValueError("header must contain two integers")
    try:
        rows = int(header_parts[0])
        cols = int(header_parts[1])
    except Exception:
        raise ValueError("invalid dimensions")
    if rows < 0 or cols < 0:
        raise ValueError("negative dimensions")
    if rows == 0:
        if body.strip():
            raise ValueError("non-empty body for zero rows")
        return []
    if cols == 0:
        if body.strip():
            raise ValueError("non-empty body for zero columns")
        return ['' for _ in range(rows)]
    tokens = body.split()
    flat = []
    for token in tokens:
        if ':' not in token:
            raise ValueError("malformed token")
        count_str, char = token.split(':', 1)
        if count_str == '' or char == '' or len(char) != 1:
            raise ValueError("malformed token")
        try:
            count = int(count_str)
        except Exception:
            raise ValueError("invalid count")
        if count < 0:
            raise ValueError("negative count")
        flat.append(char * count)
    flat_str = ''.join(flat)
    expected = rows * cols
    if len(flat_str) != expected:
        raise ValueError("expanded length mismatch")
    return [flat_str[i:i+cols] for i in range(0, expected, cols)]

def normalize_game_rounds(events):
    result = {}
    active = {}
    ended = set()

    for event in events:
        parts = event.split('|')
        if len(parts) != 3:
            raise ValueError('malformed event')
        player, round_name, state = parts
        if not player or not round_name or state not in {'start', 'score', 'end'}:
            raise ValueError('malformed event')

        key = (player, round_name)
        if key not in result:
            result[key] = {'started': False, 'ended': False, 'score': 0}
            active[key] = False

        if state == 'start':
            if not result[key]['started']:
                result[key]['started'] = True
                active[key] = True
        elif state == 'score':
            if active.get(key, False) and key not in ended:
                result[key]['score'] += 1
        else:  # end
            if result[key]['started'] and not result[key]['ended']:
                result[key]['ended'] = True
                active[key] = False
                ended.add(key)

    return result

def normalize_game_rounds(events):
    """
    Normalize a list of game round events into a summary dictionary.

    Each event string in the list has the format "player|round|state".
    The function returns a dictionary mapping each (player, round) tuple to another dictionary
    with exactly these keys:
    - "started": True if the round ever had a valid start, else False
    - "ended": True if the round had a valid end after a valid start, else False
    - "score": the total score accumulated during the active interval, as an integer

    :param events: List of event strings
    :return: Summary dictionary
    """
    # Check if the input list is empty
    if not events:
        return {}

    # Initialize the summary dictionary
    summary = {}

    # Iterate over each event string
    for event in events:
        # Split the event string into player, round, and state
        parts = event.split("|")

        # Check if the event string is malformed
        if len(parts) != 3:
            raise ValueError("Malformed event string")

        # Extract player, round, and state
        player, round, state = parts

        # Check if the state is valid
        if state not in ["start", "score", "end"]:
            raise ValueError(f"Invalid state: {state}")

        # Check if the player and round are valid
        if not (player and round):
            raise ValueError("Invalid player or round")

        # Update the summary dictionary
        if player not in summary:
            summary[player] = {}

        if round not in summary[player]:
            summary[player][round] = {}

        if state == "start":
            summary[player][round]["started"] = True
        elif state == "score":
            if round in summary[player][round]:
                summary[player][round]["score"] += 1
        elif state == "end":
            if round in summary[player][round]:
                summary[player][round]["ended"] = True

    return summary

