def normalize_timestamps(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    def parse_ts(ts):
        if not isinstance(ts, str) or ts == '':
            raise ValueError('invalid timestamp')
        z = ts.endswith('Z')
        core = ts[:-1] if z else ts
        parts = core.split('T')
        if len(parts) == 1:
            date_part = parts[0]
            time_part = '00:00:00'
        elif len(parts) == 2:
            date_part, time_part = parts
        else:
            raise ValueError('invalid timestamp')
        d = date_part.split('-')
        if len(d) != 3 or any(not x.isdigit() for x in d):
            raise ValueError('invalid timestamp')
        year, month, day = d
        if len(year) != 4 or len(month) != 2 or len(day) != 2:
            raise ValueError('invalid timestamp')
        t = time_part.split(':')
        if len(t) == 2:
            h, m = t
            s = '00'
        elif len(t) == 3:
            h, m, s = t
        else:
            raise ValueError('invalid timestamp')
        if any(not x.isdigit() for x in (h, m, s)):
            raise ValueError('invalid timestamp')
        if len(h) != 2 or len(m) != 2 or len(s) != 2:
            raise ValueError('invalid timestamp')
        hi, mi, si = int(h), int(m), int(s)
        if not (0 <= hi <= 23 and 0 <= mi <= 59 and 0 <= si <= 59):
            raise ValueError('invalid timestamp')
        # Basic calendar validation
        yi, moi, di = int(year), int(month), int(day)
        leap = (yi % 4 == 0 and yi % 100 != 0) or (yi % 400 == 0)
        mdays = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if not (1 <= moi <= 12 and 1 <= di <= mdays[moi - 1]):
            raise ValueError('invalid timestamp')
        normalized = f'{year}-{month}-{day}T{h}:{m}:{s}'
        return (yi, moi, di, hi, mi, si, normalized)

    parsed = []
    for idx, item in enumerate(events):
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each event must be a 2-tuple')
        ts, payload = item
        yi, moi, di, hi, mi, si, normalized = parse_ts(ts)
        parsed.append(((yi, moi, di, hi, mi, si), idx, normalized, payload))

    parsed.sort(key=lambda x: (x[0], x[1]))
    return [(normalized, payload) for _, _, normalized, payload in parsed]

def run_length_transform(s: str) -> str:
    if s == "":
        return ""
    parts = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f"{current}{count}")
            current = ch
            count = 1
    parts.append(f"{current}{count}")
    return "".join(parts)

def summarize_run_length(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError('text must be a str')
    if text == '':
        return []
    result = []
    current_char = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = ch
            count = 1
    result.append((current_char, count))
    return result

def compress_runs(items):
    result = []
    iterator = iter(items)
    try:
        current = next(iterator)
    except StopIteration:
        return result
    count = 1
    for value in iterator:
        if value == current:
            count += 1
        else:
            result.append((current, count))
            current = value
            count = 1
    result.append((current, count))
    return result

def compress_runs(values):
    result = []
    iterator = iter(values)
    try:
        first = next(iterator)
    except StopIteration:
        return result

    def is_valid_int(x):
        return type(x) is int

    if not is_valid_int(first):
        raise TypeError("all elements must be integers")

    current = first
    count = 1

    for item in iterator:
        if not is_valid_int(item):
            raise TypeError("all elements must be integers")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    result.append((current, count))
    return result

def normalize_durations(values):
    result = []
    for item in values:
        if not isinstance(item, str):
            raise ValueError('each item must be a string')
        s = item.strip()
        if s == '':
            raise ValueError('empty duration')
        parts = s.split(':')
        if len(parts) == 2:
            h = 0
            m_str, sec_str = parts
            fields = [m_str, sec_str]
        elif len(parts) == 3:
            h_str, m_str, sec_str = parts
            fields = [h_str, m_str, sec_str]
        else:
            raise ValueError('invalid format')
        for field in fields:
            if field == '' or field.startswith(('+', '-')) or not field.isdigit():
                raise ValueError('invalid numeric field')
        if len(parts) == 2:
            m = int(m_str)
            sec = int(sec_str)
            if not (0 <= m <= 59 and 0 <= sec <= 59):
                raise ValueError('minute/second out of range')
            total = m * 60 + sec
        else:
            h = int(h_str)
            m = int(m_str)
            sec = int(sec_str)
            if not (0 <= m <= 59 and 0 <= sec <= 59):
                raise ValueError('minute/second out of range')
            total = h * 3600 + m * 60 + sec
        result.append(total)
    return result

def merge_event_markers(text: str, markers: list[tuple[int, str]]) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(markers, list):
        raise TypeError("markers must be a list")

    buckets = [[] for _ in range(len(text) + 1)]
    for item in markers:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise TypeError("each marker must be a tuple of (position, marker_text)")
        position, marker_text = item
        if not isinstance(position, int):
            raise TypeError("position must be an int")
        if not isinstance(marker_text, str):
            raise TypeError("marker_text must be a string")
        if position < 0 or position > len(text):
            raise ValueError("position out of range")
        buckets[position].append(marker_text)

    parts = []
    for i, ch in enumerate(text):
        if buckets[i]:
            parts.append("".join(buckets[i]))
        parts.append(ch)
    if buckets[len(text)]:
        parts.append("".join(buckets[len(text)]))
    return "".join(parts)

def normalize_schedule_slots(slots):
    if not isinstance(slots, list):
        raise ValueError('slots must be a list')

    day_order = {'Mon': 0, 'Tue': 1, 'Wed': 2, 'Thu': 3, 'Fri': 4, 'Sat': 5, 'Sun': 6}
    seen = set()
    normalized = []

    def parse_time(t):
        if len(t) != 5 or t[2] != ':':
            raise ValueError('invalid time format')
        hh, mm = t[:2], t[3:]
        if not (hh.isdigit() and mm.isdigit()):
            raise ValueError('invalid time digits')
        h = int(hh)
        m = int(mm)
        if h < 0 or h > 23 or m < 0 or m > 59:
            raise ValueError('invalid time value')
        return h * 60 + m

    for slot in slots:
        if not isinstance(slot, str):
            raise ValueError('slot must be a string')
        if ':' not in slot or '-' not in slot:
            raise ValueError('malformed slot')
        day, rest = slot.split(':', 1)
        if day not in day_order:
            raise ValueError('invalid day')
        if rest.count('-') != 1:
            raise ValueError('malformed slot')
        start_s, end_s = rest.split('-', 1)
        start = parse_time(start_s)
        end = parse_time(end_s)
        if start >= end:
            raise ValueError('non-increasing interval')
        if slot not in seen:
            seen.add(slot)
            normalized.append((day_order[day], start, slot))

    normalized.sort(key=lambda x: (x[0], x[1]))
    return [slot for _, _, slot in normalized]

def resolve_feature_flags(text: str) -> dict:
    result = {}
    order = []

    lines = text.splitlines()
    for raw_line in lines:
        line = raw_line.strip()
        if not line:
            continue
        if line.count('=') != 1:
            raise ValueError('each non-empty line must contain exactly one =')
        name_part, value_part = line.split('=')
        name = name_part.strip()
        value = value_part.strip()
        if not name:
            raise ValueError('feature name cannot be empty')
        if name not in result:
            order.append(name)
        if value == 'on':
            parsed = True
        elif value == 'off':
            parsed = False
        elif value == 'inherit':
            parsed = None
        elif value == 'default':
            parsed = 'default'
        else:
            if value in ('+', '-'):
                raise ValueError('invalid integer literal')
            signless = value[1:] if value[:1] in '+-' else value
            if signless.isdigit() and signless:
                try:
                    parsed = int(value)
                except ValueError:
                    raise ValueError('invalid integer literal')
            else:
                raise ValueError('unrecognized value')
        result[name] = parsed

    return {name: result[name] for name in order}

def normalize_event_fields(record):
    if not isinstance(record, dict):
        raise TypeError('record must be a dictionary')

    result = {}

    def first_present(keys):
        for key in keys:
            if key in record:
                return record[key]
        return None

    event_id_value = first_present(['id', 'eventId', 'event_id'])
    if event_id_value is not None:
        event_id = str(event_id_value).strip()
        if event_id:
            result['event_id'] = event_id

    timestamp_value = first_present(['ts', 'time', 'timestamp'])
    if timestamp_value is not None:
        try:
            result['timestamp'] = int(timestamp_value)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')

    source_value = first_present(['src', 'source', 'origin'])
    if source_value is not None:
        source = str(source_value).strip()
        if source:
            result['source'] = source

    payload_value = first_present(['data', 'payload', 'body'])
    if payload_value is not None:
        if isinstance(payload_value, dict):
            result['payload'] = payload_value.copy()
        elif isinstance(payload_value, list):
            result['payload'] = payload_value.copy()
        else:
            result['payload'] = payload_value

    return result

def normalize_inventory(transactions):
    result = {}
    for record in transactions:
        if not isinstance(record, tuple) or len(record) != 2:
            continue
        sku, delta = record
        if not isinstance(sku, str) or sku == '':
            continue
        if any(not (ch.isalnum() or ch == '_') for ch in sku):
            continue
        if type(delta) is not int:
            continue
        result[sku] = result.get(sku, 0) + delta
    return {sku: total for sku, total in result.items() if total != 0}

def normalize_event_log(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    normalized = []
    for idx, record in enumerate(events):
        item = None
        if isinstance(record, tuple) and len(record) == 2:
            timestamp, label = record
            if isinstance(timestamp, int) and isinstance(label, str):
                item = (timestamp, label, idx)
        elif isinstance(record, dict) and set(record.keys()) == {'time', 'name'}:
            timestamp = record['time']
            label = record['name']
            if isinstance(timestamp, int) and isinstance(label, str):
                item = (timestamp, label, idx)

        if item is not None:
            normalized.append(item)

    normalized.sort(key=lambda x: (x[0], x[2]))
    return [(timestamp, label) for timestamp, label, _ in normalized]

def normalize_name_records(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")

    normalized = []
    for record in records:
        if not isinstance(record, tuple) or len(record) != 2:
            raise TypeError("each record must be a tuple of length 2")
        first, last = record
        if not isinstance(first, str) or not isinstance(last, str):
            raise TypeError("name parts must be strings")

        def _norm(s):
            return " ".join(s.split()).title()

        normalized.append((_norm(first), _norm(last)))

    return normalized

def normalize_tag_counts(records):
    totals = {}
    for record in records:
        if not isinstance(record, str):
            raise ValueError('each record must be a string')
        if record.count(':') != 1:
            raise ValueError('malformed record')
        tag, count_text = record.split(':', 1)
        if not tag or not all('A' <= ch <= 'Z' for ch in tag):
            raise ValueError('invalid tag')
        if not count_text:
            raise ValueError('missing count')
        if count_text[0] in '+-':
            sign = count_text[0]
            digits = count_text[1:]
            if not digits:
                raise ValueError('invalid count')
        else:
            sign = ''
            digits = count_text
        if not digits.isdigit():
            raise ValueError('invalid count')
        count = int(sign + digits)
        totals[tag] = totals.get(tag, 0) + count
    items = [f'{tag}={total}' for tag, total in sorted(totals.items()) if total != 0]
    return '|'.join(items)

def parse_signal_frames(text: str) -> list[tuple[int, int, str]]:
    if text == "":
        return []

    frames = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        parts = line.split(',', 2)
        if len(parts) != 3:
            raise ValueError("malformed line")

        frame_id_s, duration_s, payload = (p.strip() for p in parts)
        if not frame_id_s.isdigit() or not duration_s.isdigit():
            raise ValueError("frame_id and duration must be non-negative integers")

        frames.append((int(frame_id_s), int(duration_s), payload))

    return frames

def merge_event_intervals(events):
    normalized = []
    for item in events:
        try:
            start, end = item
        except Exception as e:
            raise TypeError("each event must be a 2-item iterable") from e
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("event boundaries must be integers")
        if start < end:
            normalized.append((start, end))
    if not normalized:
        return []
    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [list(normalized[0])]
    for start, end in normalized[1:]:
        cur_start, cur_end = merged[-1]
        if start <= cur_end:
            if end > cur_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return [tuple(x) for x in merged]

def normalize_invoice_lines(lines):
    result = []
    for i, line in enumerate(lines):
        if not isinstance(line, str):
            raise ValueError(f"Invalid line at index {i}: line must be a string")
        if line.count('|') != 2:
            raise ValueError(f"Invalid line at index {i}: expected exactly two pipe characters")
        parts = line.split('|')
        desc = parts[0].strip()
        qty_str = parts[1].strip()
        price_str = parts[2].strip()
        if not desc:
            raise ValueError(f"Invalid line at index {i}: description is empty")
        try:
            qty = int(qty_str)
        except Exception:
            raise ValueError(f"Invalid line at index {i}: quantity is not an integer")
        if qty <= 0:
            raise ValueError(f"Invalid line at index {i}: quantity must be positive")
        try:
            price = float(price_str)
        except Exception:
            raise ValueError(f"Invalid line at index {i}: unit price is not a number")
        if price < 0:
            raise ValueError(f"Invalid line at index {i}: unit price must be non-negative")
        total = qty * price
        result.append(f"{desc}|{qty}|{price:.2f}|{total:.2f}")
    return result

def parse_timeline_events(text: str) -> list[tuple[int, str, str]]:
    if text == "":
        return []
    events = []
    for raw_line in text.splitlines():
        line = raw_line.rstrip("\r")
        if line.strip() == "":
            continue
        parts = line.split(",", 2)
        if len(parts) != 3:
            raise ValueError("malformed line")
        year_s, month_s, label = parts
        try:
            year = int(year_s)
            month = int(month_s)
        except Exception as e:
            raise ValueError("malformed line") from e
        if not (1 <= month <= 12):
            raise ValueError("malformed line")
        events.append((year, month, label))
    events.sort(key=lambda x: (x[0], x[1], x[2]))
    return events

def summarize_runs(s):
    if s == "":
        return {'total_runs': 0, 'total_length': 0, 'chars': [], 'longest_run': None}
    if not isinstance(s, str):
        raise ValueError('input must be a string')
    segments = s.split(';')
    chars = []
    total_length = 0
    longest_run = None
    max_count = None
    for seg in segments:
        if seg == "":
            raise ValueError('empty segment')
        i = 0
        while i < len(seg) and not seg[i].isdigit():
            i += 1
        if i != 1:
            raise ValueError('each segment must start with exactly one character')
        ch = seg[0]
        count_str = seg[1:]
        if count_str == "" or not count_str.isdigit():
            raise ValueError('invalid count')
        count = int(count_str)
        chars.append(ch)
        total_length += count
        if max_count is None or count > max_count:
            max_count = count
            longest_run = (ch, count)
    return {
        'total_runs': len(segments),
        'total_length': total_length,
        'chars': chars,
        'longest_run': longest_run,
    }

def normalize_event_schedule(events):
    valid = []
    for item in events:
        if not isinstance(item, tuple) or len(item) != 4:
            continue
        title, start, end, priority = item
        if not isinstance(title, str) or title == "":
            continue
        if not isinstance(start, int) or not isinstance(end, int) or not isinstance(priority, int):
            continue
        if start >= end:
            continue
        valid.append((title, start, end, priority))

    if not valid:
        return []

    valid.sort(key=lambda x: (x[1], -x[3], x[0]))

    merged = []
    cur_titles = [valid[0][0]]
    cur_start = valid[0][1]
    cur_end = valid[0][2]
    cur_max_priority = valid[0][3]

    for title, start, end, priority in valid[1:]:
        if start <= cur_end:
            cur_titles.append(title)
            if end > cur_end:
                cur_end = end
            if priority > cur_max_priority:
                cur_max_priority = priority
        else:
            merged.append((tuple(cur_titles), cur_start, cur_end, cur_max_priority))
            cur_titles = [title]
            cur_start = start
            cur_end = end
            cur_max_priority = priority

    merged.append((tuple(cur_titles), cur_start, cur_end, cur_max_priority))
    return merged

def normalize_schedule(entries):
    normalized = []
    warnings = []
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) not in (2, 3):
            warnings.append(f"bad-shape: {entry!r}")
            continue
        if len(entry) == 2:
            start, end = entry
            label = ""
        else:
            start, end, label = entry
            if not isinstance(label, str):
                warnings.append(f"bad-types: {entry!r}")
                continue
        if not isinstance(start, int) or not isinstance(end, int):
            warnings.append(f"bad-types: {entry!r}")
            continue
        if start > end:
            warnings.append(f"bad-range: {entry!r}")
            continue
        if start == end:
            warnings.append(f"empty-span: {entry!r}")
            continue
        clamped_start = 0 if start < 0 else 1439 if start > 1439 else start
        clamped_end = 0 if end < 0 else 1439 if end > 1439 else end
        normalized.append((clamped_start, clamped_end, label))
    return normalized, warnings

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    normalized = []
    for idx, event in enumerate(events):
        if not isinstance(event, dict):
            raise ValueError("each event must be a dict")
        if "name" not in event or "start" not in event or "duration" not in event:
            raise ValueError("missing required key")

        start = event["start"]
        if isinstance(start, int):
            start_min = start
        elif isinstance(start, str):
            parts = start.split(":")
            if len(parts) != 2:
                raise ValueError("invalid time format")
            hh, mm = parts
            if len(hh) != 2 or len(mm) != 2 or not hh.isdigit() or not mm.isdigit():
                raise ValueError("invalid time format")
            hour = int(hh)
            minute = int(mm)
            if hour < 0 or hour > 23 or minute < 0 or minute > 59:
                raise ValueError("time out of range")
            start_min = hour * 60 + minute
        else:
            raise ValueError("invalid start type")

        duration = event["duration"]
        if not isinstance(duration, int) or duration < 0:
            raise ValueError("invalid duration")

        new_event = dict(event)
        new_event["start"] = start_min
        normalized.append((start_min, idx, new_event))

    normalized.sort(key=lambda t: (t[0], t[1]))
    return [item[2] for item in normalized]

def merge_overlapping_intervals(intervals):
    validated = []
    for interval in intervals:
        try:
            a, b = interval
        except Exception:
            raise ValueError("each interval must contain exactly two elements")
        if a > b:
            raise ValueError("interval start must not exceed end")
        validated.append((a, b))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [[validated[0][0], validated[0][1]]]

    for start, end in validated[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

def normalize_event_window(events, start, end):
    if start > end:
        raise ValueError("start must not be greater than end")

    kept = []
    for t in events:
        if not isinstance(t, int):
            raise TypeError("events must contain only integers")
        if start <= t <= end:
            kept.append(t - start)

    kept.sort()
    return kept

def normalize_chat_log(lines):
