def segment_run_lengths(s: str) -> list[tuple[str, int]]:
    if not isinstance(s, str):
        raise TypeError('s must be a str')

    def ws_category(ch: str) -> str:
        if ch == ' ':
            return 'space'
        if ch == '\t':
            return 'tab'
        if ch == '\n':
            return 'newline'
        return 'other_ws'

    if s == '':
        return []

    result = []
    prev_token = None
    count = 0

    for ch in s:
        if ch.isspace():
            token = ws_category(ch)
        else:
            token = ch

        if prev_token is None:
            prev_token = token
            count = 1
        elif token == prev_token:
            count += 1
        else:
            result.append((prev_token, count))
            prev_token = token
            count = 1

    result.append((prev_token, count))
    return result

def segment_label_runs(text: str) -> list[tuple[str, str, int]]:
    def label_of(ch: str) -> str:
        if 'a' <= ch <= 'z':
            return 'lower'
        if 'A' <= ch <= 'Z':
            return 'upper'
        if '0' <= ch <= '9':
            return 'digit'
        if ch in (' ', '\t', '\n', '\r'):
            return 'space'
        return 'other'

    if text == '':
        return []

    result = []
    current_char = text[0]
    run_len = 1

    for ch in text[1:]:
        if ch == current_char:
            run_len += 1
        else:
            result.append((label_of(current_char), current_char, run_len))
            current_char = ch
            run_len = 1

    result.append((label_of(current_char), current_char, run_len))
    return result

def compress_ranges(nums):
    if isinstance(nums, (str, bytes)):
        raise TypeError("nums must be a sequence of integers")
    try:
        iterator = iter(nums)
    except TypeError:
        raise TypeError("nums must be a sequence of integers")

    seen = set()
    unique = []
    for x in iterator:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("nums must be a sequence of integers")
        if x not in seen:
            seen.add(x)
            unique.append(x)

    if not unique:
        return ""

    parts = []
    start = prev = unique[0]
    for x in unique[1:]:
        if x == prev + 1:
            prev = x
        else:
            length = prev - start + 1
            if length >= 3:
                parts.append(f"{start}-{prev}")
            else:
                parts.extend(str(n) for n in range(start, prev + 1))
            start = prev = x
    length = prev - start + 1
    if length >= 3:
        parts.append(f"{start}-{prev}")
    else:
        parts.extend(str(n) for n in range(start, prev + 1))

    return ",".join(parts)

def canonicalize_quota_string(s):
    if not isinstance(s, str):
        raise TypeError('s must be a string')

    totals = {}
    saw_valid = False

    for raw_token in s.split(','):
        token = raw_token.strip()
        if token == '':
            continue
        saw_valid = True

        if token.count(':') > 1:
            raise ValueError('too many colons')

        if ':' in token:
            name_part, quota_part = token.split(':', 1)
            name = name_part.strip()
            quota_str = quota_part.strip()
            if name == '':
                raise ValueError('missing department name')
            if quota_str == '':
                raise ValueError('missing quota')
            if quota_str[0] == '+':
                raise ValueError('invalid quota')
            if quota_str[0] == '-':
                raise ValueError('negative quota')
            if not quota_str.isdigit():
                raise ValueError('invalid quota')
            quota = int(quota_str)
        else:
            name = token
            if name == '':
                raise ValueError('missing department name')
            quota = 1

        totals[name] = totals.get(name, 0) + quota

    if not saw_valid:
        return ''

    return ','.join(f'{name}:{totals[name]}' for name in sorted(totals))

def compress_spans(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list of integers")
    if any(not isinstance(v, int) for v in values):
        raise TypeError("all elements of values must be integers")

    if not values:
        return []

    result = []
    start = 0
    current = values[0]

    for i in range(1, len(values) + 1):
        if i == len(values) or values[i] != current:
            result.append((current, start, i - 1))
            if i < len(values):
                start = i
                current = values[i]
    return result

def parse_inventory_report(text):
    if text is None:
        raise ValueError('text must be a string')
    if text.strip() == '':
        return {}

    result = {}
    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if not line:
            continue
        if ':' not in line:
            raise ValueError('missing category separator')
        category_part, items_part = line.split(':', 1)
        category = category_part.strip()
        if category == '':
            raise ValueError('missing category name')
        if category not in result:
            result[category] = {}
        items_part = items_part.strip()
        if items_part == '':
            continue
        for entry in items_part.split(','):
            piece = entry.strip()
            if piece == '' or '=' not in piece:
                raise ValueError('malformed item entry')
            item_part, qty_part = piece.split('=', 1)
            item = item_part.strip()
            qty_str = qty_part.strip()
            if item == '' or qty_str == '':
                raise ValueError('malformed item entry')
            try:
                qty = int(qty_str)
            except Exception:
                raise ValueError('invalid quantity')
            result[category][item] = result[category].get(item, 0) + qty
    return result

def summarize_ragged_matrix(matrix):
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of rows")

    row_count = len(matrix)
    col_count = 0
    row_sums = []
    filled_cells = 0

    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        if len(row) > col_count:
            col_count = len(row)
        row_total = 0
        for value in row:
            if type(value) is not int:
                raise TypeError("all elements must be integers")
            row_total += value
            filled_cells += 1
        row_sums.append(row_total)

    col_sums = [0] * col_count
    for row in matrix:
        for i, value in enumerate(row):
            col_sums[i] += value

    missing_cells = row_count * col_count - filled_cells

    return {
        "row_count": row_count,
        "col_count": col_count,
        "filled_cells": filled_cells,
        "missing_cells": missing_cells,
        "row_sums": row_sums,
        "col_sums": col_sums,
    }

def compress_segments(values):
    result = []
    iterator = iter(values)
    try:
        first = next(iterator)
    except StopIteration:
        return result
    if type(first) is not int:
        raise TypeError("all elements must be integers")
    current = first
    count = 1
    for item in iterator:
        if type(item) is not int:
            raise TypeError("all elements must be integers")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_query_string(query):
    if not isinstance(query, str):
        raise TypeError('query must be a string')
    if query == '':
        return ''

    items = {}
    for segment in query.split('&'):
        if segment == '':
            continue
        if segment.count('=') != 1:
            raise ValueError('each segment must contain exactly one =')
        key, value = segment.split('=')
        key = key.strip().lower()
        value = value.strip().lower()
        items[key] = value

    return '&'.join(f'{k}={items[k]}' for k in sorted(items))

def normalize_inventory(records):
