    for rec in records:
        if not isinstance(rec, str):
            raise ValueError('each record must be a string')
        parts = rec.split(',')
        if len(parts) != 3:
            raise ValueError('each record must have exactly three fields')
        category, item, quantity = (p.strip() for p in parts)
        if item == '':
            raise ValueError('item name cannot be empty')
        if quantity == '':
            raise ValueError('quantity cannot be empty')
        try:
            qty = int(quantity, 10)
        except Exception as e:
            raise ValueError('invalid quantity') from e
        result.setdefault(item, set()).add(qty)
    return {item: sorted(qtys) for item, qtys in result.items()}

def normalize_inventory(records):
    """
    Normalize a list of inventory records into a dictionary mapping each item name to a sorted list of unique integer quantities seen for that item.

    Each record string must have exactly three comma-separated fields: 'category', 'item', and 'quantity'. Whitespace around fields should be ignored.
    The 'category' field is ignored for the result. The 'item' field must be a non-empty string after stripping whitespace. The 'quantity' field must be a valid base-10 integer with an optional leading sign; it may have surrounding whitespace. If any record is malformed, has the wrong number of fields, has an empty item name, or has a quantity that cannot be parsed as an integer, the function must raise ValueError.

    The result dictionary must contain one key per distinct item name. For each item, the value must be a list of distinct quantities for that item, sorted in ascending numeric order. Duplicate quantities for the same item must appear only once. If `records` is empty, return an empty dictionary.
    """
    from collections import defaultdict

    def parse_quantity(quantity_str):
        if not quantity_str:
            return 0
        try:
            return int(quantity_str.strip())
        except ValueError:
            raise ValueError(f"Invalid quantity: {quantity_str}")

    def normalize_record(record):
        category, item, quantity_str = record.split(',')
        category = category.strip()
        item = item.strip()
        quantity = parse_quantity(quantity_str)
        return (category, item, quantity)

    normalized_records = [normalize_record(record) for record in records]
    result = defaultdict(list)

    for category, item, quantity in normalized_records:
        result[category].append(quantity)

    return dict(result)

