def plan_museum_route(rooms, start, budget):
    if budget < 0:
        raise ValueError("budget must be non-negative")

    room_map = {}
    for name, cost, nxt in rooms:
        room_map[name] = (cost, nxt)

    if start not in room_map:
        raise KeyError(start)

    visited = []
    seen = set()
    total = 0
    current = start

    while current is not None:
        if current in seen:
            raise ValueError("cycle detected")
        if current not in room_map:
            raise KeyError(current)
        cost, nxt = room_map[current]
        if total + cost > budget:
            break
        seen.add(current)
        visited.append(current)
        total += cost
        current = nxt

    return visited, total

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    validated = []
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each event must be a 3-tuple")
        name, start, end = record
        if not isinstance(name, str) or not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("name must be str and times must be int")
        if start < 0 or end < 0 or start > end:
            raise ValueError("invalid time range")
        validated.append((name, start, end))

    by_name = {}
    for name, start, end in validated:
        by_name.setdefault(name, []).append((start, end))

    merged = []
    for name in sorted(by_name):
        ranges = sorted(by_name[name])
        cur_start, cur_end = ranges[0]
        for start, end in ranges[1:]:
            if start <= cur_end:
                if end > cur_end:
                    cur_end = end
            else:
                merged.append((name, cur_start, cur_end))
                cur_start, cur_end = start, end
        merged.append((name, cur_start, cur_end))

    return sorted(merged, key=lambda x: (x[0], x[1]))

def normalize_registry(records):
    result = {}

    if not isinstance(records, list):
        raise TypeError("records must be a list")

    for entry in records:
        if not (isinstance(entry, tuple) and len(entry) == 3):
            continue
        identifier, label, score = entry

        if not isinstance(identifier, str):
            continue
        ident = identifier.strip().lower()
        if not ident or any(ch not in "abcdefghijklmnopqrstuvwxyz0123456789_" for ch in ident):
            continue

        if not isinstance(label, str):
            continue
        lbl = " ".join(label.strip().split()).title()
        if lbl == "" and label.strip() == "":
            lbl = ""

        if type(score) is not int:
            continue
        if score < 0:
            continue

        current = result.get(ident)
        candidate = (ident, lbl, score)
        if current is None:
            result[ident] = candidate
        else:
            _, cur_lbl, cur_score = current
            if score > cur_score or (score == cur_score and lbl < cur_lbl):
                result[ident] = candidate

    return [result[k] for k in sorted(result)]

def scan_number_runs(text):
    runs = []
    n = len(text)
    i = 0
    while i < n:
        if '0' <= text[i] <= '9':
            start = i
            while i < n and '0' <= text[i] <= '9':
                i += 1
            end = i
            last_digit = text[end - 1]
            kind = 'even' if (ord(last_digit) - ord('0')) % 2 == 0 else 'odd'
            runs.append((start, end, kind))
        else:
            i += 1
    return runs

def canonicalize_query(query: str) -> str:
    if query.startswith('?'):
        query = query[1:]

    params = {}
    for segment in query.split('&'):
        if segment == '':
            continue
        if segment.count('=') != 1:
            raise ValueError('Each non-empty segment must contain exactly one =')
        key, value = segment.split('=', 1)
        if key == '':
            continue
        params[key] = value

    return '&'.join(f'{k}={params[k]}' for k in sorted(params))

