def normalize_inventory_counts(records):
    """
    Normalize inventory record counts by summing duplicates and removing prefixes.

    :param records: List of tuples or lists representing inventory records.
    :return: Dictionary mapping each item name to its normalized count.
    """
    normalized = {}
    for record in records:
        if isinstance(record, tuple) and len(record) == 2:
            name, count = record
            if isinstance(name, str) and isinstance(count, int):
                if name.startswith("tmp:"):
                    name = name[4:]
                if name in normalized:
                    normalized[name] += count
                else:
                    normalized[name] = count
        elif isinstance(record, list) and len(record) == 2:
            name, count = record
            if isinstance(name, str) and isinstance(count, int):
                if name.startswith("tmp:"):
                    name = name[4:]
                if name in normalized:
                    normalized[name] += count
                else:
                    normalized[name] = count
    return normalized

