                raise ValueError('Malformed fragment')
            a, b = parts
            typ = 'defeat'
        elif '?' in frag:
            parts = frag.split('?')
            if len(parts) != 2:
                raise ValueError('Malformed fragment')
            a, b = parts
            typ = 'heal'
        else:
            raise ValueError('Malformed fragment')
        if not (valid_ident(a) and valid_ident(b)):
            raise ValueError('Malformed fragment')
        items.append((a, typ, b))

    items.sort()
    return '\n'.join(f'{a}|{typ}|{b}' for a, typ, b in items)

def normalize_sensor_readings(data):
    valid = {}
    order = []
    for item in data:
        if not isinstance(item, tuple) or len(item) != 2:
            continue
        timestamp, value = item
        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            continue
        if timestamp < 0:
            continue
        if not (isinstance(value, (int, float)) and not isinstance(value, bool)):
            continue
        if timestamp in valid:
            continue
        valid[timestamp] = float(value)
        order.append(timestamp)

    if not valid:
        return []

    timestamps = sorted(valid)
    values = [valid[t] for t in timestamps]
    min_v = min(values)
    max_v = max(values)

    result = []
    if max_v == min_v:
        for t in timestamps:
            result.append((t, 0.0))
        return result

    denom = max_v - min_v
    for t in timestamps:
        norm = (valid[t] - min_v) / denom
        result.append((t, round(float(norm), 6)))
    return result

def normalize_instructions(instructions):
    if not isinstance(instructions, list):
        raise ValueError("instructions must be a list")

    result = []
    for item in instructions:
        if not isinstance(item, str):
            raise ValueError("each instruction must be a string")
        if item.count('=') != 1:
            raise ValueError("each instruction must contain exactly one '='")
        name, value = item.split('=', 1)
        name = name.strip()
        value = value.strip()
        if not name:
            raise ValueError("name must be non-empty")
        if not all(ch.isalnum() or ch == '_' for ch in name):
            raise ValueError("invalid name")
        result.append(name.lower() + '=' + value)
    return result

def compress_stamped_ranges(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    result = []
    if not events:
        return result

    def validate_item(item):
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each event must be a 2-element tuple")
        value, stamp = item
        if not isinstance(stamp, int):
            raise TypeError("stamp must be an integer")
        try:
            hash(value)
        except Exception:
            raise TypeError("value must be hashable")
        return value, stamp

    current_value, current_stamp = validate_item(events[0])
    run_start = current_stamp
    run_length = 1

    for item in events[1:]:
        value, stamp = validate_item(item)
        if value == current_value and stamp == current_stamp + 1:
            current_stamp = stamp
            run_length += 1
        else:
            if run_length >= 2:
                result.append((current_value, run_start, current_stamp))
            else:
                result.append((current_value, run_start))
            current_value = value
            current_stamp = stamp
            run_start = stamp
            run_length = 1

    if run_length >= 2:
        result.append((current_value, run_start, current_stamp))
    else:
        result.append((current_value, run_start))

    return result

def compress_stamped_ranges(events):
    """
    Compresses a list of (value, stamp) pairs into a compact, order-preserving description of consecutive runs.

    Parameters:
    events (list of tuples): A list of (value, stamp) pairs.

    Returns:
    list of tuples: A list of run descriptors.
    """
    if not isinstance(events, list):
        raise TypeError("Input must be a list.")
    if not all(isinstance(e, tuple) for e in events):
        raise TypeError("All elements in the list must be tuples of length 2.")
    if not all(isinstance(s, int) for s in events):
        raise TypeError("All stamps in the list must be integers.")

    def compress_run(value, start_stamp, end_stamp):
        if end_stamp - start_stamp >= 2:
            return (value, start_stamp, end_stamp)
        elif end_stamp - start_stamp == 1:
            return (value, start_stamp, end_stamp)
        else:
            return None

    compressed = []
    current_value = None
    current_stamp = None

    for value, stamp in events:
        if current_value is None or value != current_value:
            if current_value is not None:
                compressed.append(compress_run(current_value, current_stamp, stamp))
            current_value = value
            current_stamp = stamp

    if current_value is not None:
        compressed.append(compress_run(current_value, current_stamp, stamp))

    return compressed

