def decode_hybrid_sequence(s):
    if s == "":
        return []
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    out = []
    tokens = s.split(',')
    allowed_run_chars = {'A': 0, 'B': 1, 'C': -1, 'D': 2}

    for token in tokens:
        if token == "":
            raise ValueError("empty token")

        if ';' in token:
            # semicolons are allowed only in plain integers
            if any(ch in 'ABCD' for ch in token):
                raise ValueError("semicolon not allowed in run-length token")
            cleaned = token.replace(';', '')
            if cleaned in ('', '-', '+'):
                raise ValueError("malformed integer")
            if cleaned.count('-') > 1 or ('-' in cleaned and cleaned[0] != '-'):
                raise ValueError("malformed integer")
            if not all(ch.isdigit() for ch in cleaned.lstrip('-')):
                raise ValueError("malformed integer")
            out.append(int(cleaned))
            continue

        if token[-1] in allowed_run_chars:
            prefix = token[:-1]
            if prefix == "":
                raise ValueError("missing repetition count")
            if prefix[0] == '-':
                raise ValueError("negative repetition count")
            if not prefix.isdigit():
                raise ValueError("malformed repetition count")
            count = int(prefix)
            out.extend([allowed_run_chars[token[-1]]] * count)
            continue

        # plain integer token
        if token == '-' or token == '+':
            raise ValueError("malformed integer")
        if token.count('-') > 1 or ('-' in token and token[0] != '-'):
            raise ValueError("malformed integer")
        if not token.lstrip('-').isdigit():
            raise ValueError("malformed integer")
        out.append(int(token))

    return out

def normalize_inventory(records):
    if not isinstance(records, list):
        raise ValueError("records must be a list")
    out = []
    for rec in records:
        if not isinstance(rec, str):
            raise ValueError("each record must be a string")
        s = rec.strip()
        if '|' in s:
            parts = [p.strip() for p in s.split('|')]
            if len(parts) != 3 or any(p == '' for p in parts):
                raise ValueError("invalid pipe record")
            name, qty_s, price_s = parts
            try:
                qty = int(qty_s)
            except Exception:
                raise ValueError("invalid quantity")
            try:
                price = float(price_s)
            except Exception:
                raise ValueError("invalid price")
            if price < 0:
                raise ValueError("negative price")
            out.append((name, qty, price))
        elif ':' in s:
            parts = [p.strip() for p in s.split(':')]
            if len(parts) != 2 or any(p == '' for p in parts):
                raise ValueError("invalid colon record")
            name, qty_s = parts
            try:
                qty = int(qty_s)
            except Exception:
                raise ValueError("invalid quantity")
            out.append((name, qty, None))
        else:
            raise ValueError("unknown format")
    out.sort(key=lambda t: (t[0], t[1], -1 if t[2] is None else t[2]))
    return out

def format_interval_set(intervals):
    def validate_interval(it):
        if not isinstance(it, (list, tuple)) or len(it) != 2:
            raise ValueError("each interval must be a pair")
        a, b = it
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError("interval bounds must be integers")
        if a > b:
            raise ValueError("interval start must not exceed end")
        return a, b

    if intervals == []:
        return ""

    validated = [validate_interval(it) for it in intervals]
    validated.sort(key=lambda x: (x[0], x[1]))

    merged = []
    for start, end in validated:
        if not merged:
            merged.append([start, end])
            continue
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    parts = []
    for start, end in merged:
        if start == end:
            parts.append(str(start))
        else:
            parts.append(f"{start}-{end}")
    return ",".join(parts)

def parse_tone_commands(text: str) -> dict:
    if text.strip() == "":
        return {
            "starts": [],
            "ends": [],
            "segments": [],
            "unpaired_starts": [],
            "unpaired_ends": [],
            "duration_sum": 0,
        }

    starts = []
    ends = []

    parts = text.split(",")
    for raw in parts:
        token = raw.strip()
        if token == "":
            continue
        if len(token) < 2:
            raise ValueError("Malformed command")
        prefix = token[0]
        number_part = token[1:]
        if prefix not in ("S", "E"):
            raise ValueError("Malformed command")
        if number_part == "" or not number_part.isdigit():
            raise ValueError("Malformed command")
        value = int(number_part)
        if prefix == "S":
            starts.append(value)
        else:
            ends.append(value)

    pair_count = min(len(starts), len(ends))
    segments = [(starts[i], ends[i]) for i in range(pair_count)]
    unpaired_starts = starts[pair_count:]
    unpaired_ends = ends[pair_count:]
    duration_sum = sum(e - s for s, e in segments)

    return {
        "starts": starts,
        "ends": ends,
        "segments": segments,
        "unpaired_starts": unpaired_starts,
        "unpaired_ends": unpaired_ends,
        "duration_sum": duration_sum,
    }

def compress_consecutive(values):
    result = []
    if not values:
        return result
    current = values[0]
    count = 1
    for x in values[1:]:
        if x == current:
            count += 1
        else:
            result.extend([current, count])
            current = x
            count = 1
    result.extend([current, count])
    return result

def summarize_run_lengths(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return []
    runs = []
    current_char = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current_char:
            count += 1
        else:
            runs.append((current_char, count))
            current_char = ch
            count = 1
    runs.append((current_char, count))
    return runs

def normalize_sensor_readings(readings):
    if readings is None:
        raise TypeError('readings must not be None')
    result = []
    last = 0.0
    first = True
    for item in readings:
        if item is None:
            value = 0.0 if first else last
        else:
            value = float(item)
            last = value
        if item is None and not first:
            value = last
        if first and item is None:
            value = 0.0
            last = 0.0
        if value < -100.0:
            value = -100.0
        elif value > 100.0:
            value = 100.0
        result.append(float(value))
        first = False
    return result

def collapse_intervals(intervals):
    validated = []
    for item in intervals:
        try:
            start, end = item
        except Exception:
            raise ValueError('each interval must have exactly two items')
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('interval endpoints must be integers')
        if start > end:
            raise ValueError('interval start must be <= end')
        if start == end:
            continue
        validated.append((start, end))
    if not validated:
        return []
    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [list(validated[0])]
    for start, end in validated[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        elif start == last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def flatten_numeric_tree(data):
    def walk(obj):
        total = 0
        has_float = False

        if isinstance(obj, bool):
            return 0, False
        if isinstance(obj, int):
            return obj, False
        if isinstance(obj, float):
            return obj, True
        if isinstance(obj, dict):
            for v in obj.values():
                part, part_is_float = walk(v)
                total += part
                has_float = has_float or part_is_float
            return total, has_float
        if isinstance(obj, (list, tuple, set)):
            for item in obj:
                part, part_is_float = walk(item)
                total += part
                has_float = has_float or part_is_float
            return total, has_float
        return 0, False

    total, has_float = walk(data)
    return float(total) if has_float else total

def flatten_numeric_tree(data):
    """
    Flatten a nested structure containing lists, tuples, sets, and dicts,
    returning the sum of all numeric leaf values. Only integers and floats are considered.

    Args:
    data (Union[list, tuple, set, dict]): The input data structure.

    Returns:
    float: The sum of all numeric leaf values in the input structure.
    """
    def sum_numeric_leaf_values(node):
        if isinstance(node, list):
            return sum(sum_numeric_leaf_values(item) for item in node)
        elif isinstance(node, tuple):
            return sum(sum_numeric_leaf_values(item) for item in node)
        elif isinstance(node, set):
            return sum(sum_numeric_leaf_values(item) for item in node)
        elif isinstance(node, dict):
            return sum(sum_numeric_leaf_values(value) for value in node.values())
        else:
            return float(node)

    return sum_numeric_leaf_values(data)

