def normalize_inventory_changes(changes):
    if not isinstance(changes, list):
        raise TypeError('changes must be a list')

    totals = {}
    order = []

    for entry in changes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError('each change must be a 2-tuple')
        item, delta = entry
        if not isinstance(item, str) or not isinstance(delta, int):
            raise TypeError('item must be str and delta must be int')
        if delta == 0:
            continue
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += delta

    result = []
    for item in order:
        if totals[item] != 0:
            result.append((item, totals[item]))
    return result

def normalize_inventory_changes(changes):
    """
    Normalize inventory changes by summing the delta values for each item,
    ignoring items with delta zero. Returns a list of (item, delta) tuples.

    :param changes: List of 2-tuples (item, delta)
    :return: List of (item, delta) tuples after normalization
    """
    if not changes:
        return []

    normalized_changes = []
    for item, delta in changes:
        if isinstance(item, str) and isinstance(delta, int):
            normalized_changes.append((item, delta))
        elif delta == 0:
            continue

    # Combine tuples with the same item by summing their delta values
    combined_changes = []
    for item, delta in normalized_changes:
        if item in combined_changes:
            combined_changes[item] += delta
        else:
            combined_changes[item] = delta

    # Remove items with total delta zero
    for item, delta in combined_changes.items():
        if delta == 0:
            del combined_changes[item]

    return combined_changes

