def normalize_product_codes(text: str) -> str:
    totals = {}
    for raw_line in text.splitlines():
        stripped = raw_line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if raw_line.count('=') != 1:
            raise ValueError('invalid line')
        left, right = raw_line.split('=')
        code = left.strip().upper().replace(' ', '').replace('_', '')
        if not code:
            raise ValueError('empty code')
        qty_text = right.strip()
        if not qty_text:
            raise ValueError('invalid quantity')
        try:
            qty = int(qty_text, 10)
        except Exception as e:
            raise ValueError('invalid quantity') from e
        totals[code] = totals.get(code, 0) + qty
    if not totals:
        return ''
    return '\n'.join(f'{code}={totals[code]}' for code in sorted(totals))

def parse_duration_to_seconds(text):
    if not isinstance(text, str) or text == "":
        raise ValueError("invalid duration")

    i = 0
    n = len(text)
    sign = 1

    if text[i] in "+-":
        sign = -1 if text[i] == "-" else 1
        i += 1
        if i == n:
            raise ValueError("invalid duration")

    unit_multipliers = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen_units = set()
    total = 0
    parsed_any = False

    while i < n:
        start = i
        while i < n and text[i].isdigit():
            i += 1
        if start == i:
            raise ValueError("invalid duration")
        if i >= n:
            raise ValueError("invalid duration")
        unit = text[i]
        if unit not in unit_multipliers:
            raise ValueError("invalid duration")
        if unit in seen_units:
            raise ValueError("invalid duration")
        seen_units.add(unit)
        value = int(text[start:i])
        total += value * unit_multipliers[unit]
        parsed_any = True
        i += 1

    if not parsed_any:
        raise ValueError("invalid duration")

    return sign * total

def parse_duration_span(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if text == "":
        raise ValueError("empty input")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    i = 0
    n = len(text)

    while i < n:
        sign = 1
        if text[i] in '+-':
            sign = -1 if text[i] == '-' else 1
            i += 1
            if i >= n:
                raise ValueError("dangling sign")

        if i >= n or not text[i].isdigit():
            raise ValueError("expected digits")

        start = i
        while i < n and text[i].isdigit():
            i += 1
        number = int(text[start:i])

        if i >= n:
            raise ValueError("missing unit")

        unit = text[i]
        if unit not in units:
            raise ValueError("invalid unit")
        i += 1

        total += sign * number * units[unit]

    return total

def format_interval_set(intervals):
    try:
        iter(intervals)
    except TypeError:
        raise TypeError("intervals must be iterable")

    normalized = []
    for item in intervals:
        if not hasattr(item, '__iter__'):
            raise TypeError("each interval must be a 2-item sequence")
        try:
            a, b = item
        except Exception:
            raise TypeError("each interval must be a 2-item sequence")
        if type(a) is not int or type(b) is not int:
            raise TypeError("interval endpoints must be integers")
        if a > b:
            raise ValueError("interval start cannot exceed end")
        normalized.append((a, b))

    if not normalized:
        return ""

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [list(normalized[0])]
    for s, e in normalized[1:]:
        last_s, last_e = merged[-1]
        if s <= last_e + 1:
            if e > last_e:
                merged[-1][1] = e
        else:
            merged.append([s, e])

    parts = []
    for s, e in merged:
        parts.append(str(s) if s == e else f"{s}-{e}")
    return ", ".join(parts)

def format_interval_set(intervals):
    """
    Normalizes and serializes a collection of integer intervals.

    Parameters:
    intervals (list of lists): A list of 2-item sequences or tuples representing intervals.

    Returns:
    str: A string representation of the normalized intervals.
    """
    def normalize_interval(interval):
        if len(interval) != 2:
            raise TypeError("Each interval must be a 2-item sequence.")
        start, end = interval
        if start > end:
            raise ValueError("Interval has start > end.")
        return (min(start, end), max(start, end))

    # Normalize intervals
    normalized_intervals = sorted(normalize_interval(interval) for interval in intervals)

    # Merge overlapping intervals and intervals that touch
    merged_intervals = []
    current_start, current_end = normalized_intervals[0]

    for interval in normalized_intervals[1:]:
        if interval[0] <= current_end:
            current_end = max(current_end, interval[1])
        else:
            merged_intervals.append((current_start, current_end))
            current_start, current_end = interval

    # Remove duplicate intervals
    merged_intervals = list(set(merged_intervals))

    # Format the result
    result = []
    for start, end in merged_intervals:
        if start != end:
            result.append(f"{start}-{end}")
        elif start == end:
            result.append(f"{start}")

    return ",".join(result)

