def summarize_depth_signatures(code: str) -> list[tuple[str, int, int]]:
    lines = []
    for raw in code.splitlines():
        if raw.strip() == "":
            continue
        stripped_right = raw.rstrip()
        leading = len(stripped_right) - len(stripped_right.lstrip(" "))
        if leading % 2 != 0:
            raise ValueError("Indentation must be in multiples of two spaces")
        depth = leading // 2
        label = stripped_right.lstrip(" ").rstrip()
        lines.append((label, depth))
    if not lines:
        return []

    for i in range(1, len(lines)):
        prev_depth = lines[i - 1][1]
        cur_depth = lines[i][1]
        if cur_depth > prev_depth + 1:
            raise ValueError("Indentation jumps deeper than one level")

    n = len(lines)
    next_smaller_or_equal = [n] * n
    stack = []
    for i, (_, depth) in enumerate(lines):
        while stack and lines[stack[-1]][1] >= depth:
            next_smaller_or_equal[stack.pop()] = i
        stack.append(i)
    while stack:
        next_smaller_or_equal[stack.pop()] = n

    result = []
    for i, (label, depth) in enumerate(lines):
        end = next_smaller_or_equal[i]
        descendant_count = 0
        for j in range(i + 1, end):
            if lines[j][1] > depth:
                descendant_count += 1
        result.append((label, depth, descendant_count))
    return result

def summarize_depth_signatures(code: str) -> list[tuple[str, int, int]]:
    def parse_line(line):
        # Remove leading/trailing spaces
        line = line.strip()
        # Split into label and depth
        parts = line.split(' ')
        if len(parts) != 2:
            raise ValueError("Invalid line format")
        label = parts[0]
        depth = int(parts[1])
        return label, depth

    def compute_depth(node):
        if not node:
            return 0, 0
        left_depth, left_descendants = compute_depth(node.left)
        right_depth, right_descendants = compute_depth(node.right)
        return max(left_depth, right_depth) + 1, left_descendants + right_descendants

    def analyze_tree(root):
        if not root:
            return []
        depths = [compute_depth(root)]
        for node in root.children:
            depths.append(compute_depth(node))
        return depths

    try:
        depths = analyze_tree(code)
        return [(label, depth, descendant_count) for label, depth, descendant_count in depths]
    except ValueError as e:
        raise ValueError(f"Invalid input: {e}")

