def normalize_path_segments(path: str) -> str:
    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def segment_rule_encode(text):
    tokens = text.split()
    if not tokens:
        return ""

    out = []
    for token in tokens:
        digit_count = sum(ch.isdigit() for ch in token)
        transformed = token
        if digit_count > 0:
            if digit_count % 2 == 0:
                transformed = token[::-1]
            else:
                transformed = token[1:] + token[:1] if token else token
            if len(transformed) >= 4 and transformed[0] == transformed[-1]:
                transformed = transformed + transformed[-1]
        out.append(transformed)
    return " ".join(out)

def normalize_path_segments(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    absolute = path.startswith('/')
    trailing_slash = path.endswith('/')

    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts and parts[-1] != '..':
                parts.pop()
            else:
                if absolute:
                    continue
                parts.append('..')
        else:
            parts.append(segment)

    if absolute:
        result = '/' + '/'.join(parts)
        if result != '/' and trailing_slash and not parts:
            return '/'
        return result if parts else '/'

    if not parts:
        return '.'
    result = '/'.join(parts)
    return result

def normalize_path_segments(path):
    """
    Normalize a POSIX-style path string without resolving symbolic links or checking whether paths exist.

    Parameters:
    path (str): A string containing path segments separated by '/'.

    Returns:
    str: A normalized path string.
    """
    # Check if the input is a string
    if not isinstance(path, str):
        raise TypeError("Input must be a string.")

    # Normalize the path
    if path.startswith('/'):
        # Absolute path
        if path == '/':
            return '/'
        else:
            return path[1:]
    elif path.endswith('/'):
        # Relative path
        if path == '':
            return '.'
        else:
            return path[:-1]
    else:
        # Normalized path
        segments = path.split('/')
        normalized_segments = []

        for segment in segments:
            if segment == '.':
                continue
            elif segment == '..':
                if normalized_segments:
                    normalized_segments.pop()
                else:
                    raise ValueError("No preceding normal segment.")
            else:
                normalized_segments.append(segment)

        return '/' + '/'.join(normalized_segments)

