def encode_rle_runs(items):
    iterator = iter(items)
    try:
        first = next(iterator)
    except StopIteration:
        return []

    result = []
    current_value = first
    count = 1

    for item in iterator:
        if item == current_value:
            count += 1
        else:
            result.append((current_value, count))
            current_value = item
            count = 1

    result.append((current_value, count))
    return result

def compress_runs(values):
    items = list(values)
    if not items:
        return []

    result = []
    current = items[0]
    count = 1

    for item in items[1:]:
        if item == current:
            count += 1
        else:
            result.append([current, count])
            current = item
            count = 1

    result.append([current, count])
    return result

def merge_keyed_records(records):
    best = {}
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise TypeError("each record must be a 3-tuple")
        key, timestamp, payload = rec
        if not isinstance(key, str) or not isinstance(timestamp, int) or isinstance(timestamp, bool) or not isinstance(payload, str):
            raise TypeError("invalid record field types")
        current = best.get(key)
        if current is None:
            best[key] = rec
        else:
            _, best_ts, best_payload = current
            if timestamp > best_ts or (timestamp == best_ts and payload > best_payload):
                best[key] = rec
    return [best[k] for k in sorted(best)]

def split_delimited_quoted(text: str, delimiters: str, quote_char: str = '"') -> list[str]:
    """
    Splits the given text into fields using any character in delimiters as a separator,
    treating text enclosed in matching quote characters as a single field. Delimiters inside quoted sections do not split.
    The quote character itself is not kept in the output. Use backslash escaping inside quoted sections: a backslash immediately before a quote character or another backslash makes that next character literal.

    :param text: The input text to be split.
    :param delimiters: A string containing the delimiters to use for splitting.
    :param quote_char: The quote character to use for splitting. Defaults to '"'.
    :return: A list of strings representing the parsed fields.
    """
    if quote_char == '':
        raise ValueError("quote_char cannot be an empty string")
    if quote_char not in delimiters:
        raise ValueError("quote_char is not in delimiters")

    def split_quote_section(section):
        nonlocal quote_char
        start = 0
        while start < len(section):
            if section[start] == quote_char:
                end = start + 1
                while end < len(section) and section[end] != quote_char:
                    end += 1
                if end == len(section):
                    break
                yield section[start:end]
                start = end + 1
            else:
                start += 1
        yield section

    result = []
    current_field = ''
    for char in text:
        if char == quote_char:
            if current_field:
                result.append(current_field)
                current_field = ''
            start = char + 1
        elif char in delimiters:
            if current_field:
                result.append(current_field)
                current_field = ''
            current_field += char
        else:
            current_field += char

    if current_field:
        result.append(current_field)

    return result

