        iterator = iter(events)
    except TypeError:
        raise

    seen = set()
    normalized = []

    for record in iterator:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            continue
        label, start, end = record
        if not isinstance(label, str) or not isinstance(start, int) or not isinstance(end, int):
