def normalize_schedule(events):
    """
    Normalize a list of event records into a sorted list of normalized dictionaries.

    Parameters:
    events (iterable): A list of event records, each represented as a tuple or list.

    Returns:
    list: A sorted list of normalized event dictionaries.
    """
    def normalize_event(event):
        if len(event) != 3:
            raise ValueError("Each event must be a tuple or list of length 3.")
        if not isinstance(event[0], str):
            raise ValueError("Label must be a string.")
        if not isinstance(event[1], int):
            raise ValueError("Start must be an integer.")
        if not isinstance(event[2], int):
            raise ValueError("End must be an integer.")

        start, end = event
        if start >= end:
            return []

        return [
            {
                'label': event[0],
                'start': start,
                'end': end,
                'duration': end - start
            }
        ]

    # Normalize each event and sort them
    normalized_events = [normalize_event(event) for event in events]
    normalized_events.sort(key=lambda x: (x['start'], x['end'], x['label']))

    return normalized_events

