import re

def top_k_weighted_words(text, k):
    if not isinstance(k, int):
        raise ValueError("k must be an integer")
    if k < 0:
        raise ValueError("k must be non-negative")
    words = re.findall(r"[A-Za-z]+", text)
    if not words or k == 0:
        return []
    counts = {}
    for w in words:
        lw = w.lower()
        counts[lw] = counts.get(lw, 0) + 1
    items = [(w, c, c * len(w)) for w, c in counts.items()]
    items.sort(key=lambda x: (-x[1], -x[2], x[0]))
    return [(w, score) for w, _, score in items[:k]]

def decode_ledger(lines):
    income = 0
    expense = 0
    categories = {}

    for raw in lines:
        if not isinstance(raw, str):
            raise ValueError('each line must be a string')
        line = raw.strip()
        if line == '':
            continue

        if ' ' not in line:
            raise ValueError('malformed line')
        amount_part, category = line.split(None, 1)
        if not category or any(ch.isspace() for ch in category):
            raise ValueError('malformed category')
        if len(amount_part) < 2 or amount_part[0] not in '+-':
            raise ValueError('malformed amount')
        sign = amount_part[0]
        digits = amount_part[1:]
        if digits == '' or not digits.isdigit():
            raise ValueError('malformed amount')
        amount = int(digits)
        if sign == '+':
            income += amount
            categories[category] = categories.get(category, 0) + amount
        else:
            expense -= amount
            categories[category] = categories.get(category, 0) - amount

    return {'income': income, 'expense': expense, 'net': income + expense, 'categories': categories}

def normalize_task_weights(tasks):
    if not isinstance(tasks, list):
        raise TypeError("tasks must be a list")
    normalized = []
    for record in tasks:
        if not isinstance(record, dict):
            raise ValueError("each task must be a dict")
        required = {"id", "weight", "tags"}
        if set(record.keys()) != required:
            raise ValueError("each task must have exactly id, weight, tags")
        task_id = record["id"]
        weight = record["weight"]
        tags = record["tags"]
        if not isinstance(task_id, str):
            raise ValueError("id must be a string")
        task_id = task_id.strip()
        if task_id == "":
            raise ValueError("id cannot be empty after stripping")
        if not isinstance(weight, int):
            raise ValueError("weight must be an integer")
        weight = abs(weight)
        if weight < 0:
            raise ValueError("weight invalid")
        if not isinstance(tags, list):
            raise ValueError("tags must be a list")
        new_tags = []
        seen = set()
        for tag in tags:
            if not isinstance(tag, str):
                raise ValueError("tags must contain only strings")
            lower = tag.lower()
            if lower not in seen:
                seen.add(lower)
                new_tags.append(lower)
        normalized.append({"id": task_id, "weight": weight, "tags": new_tags})
    return normalized

def normalize_scored_choices(items, keep_ties=True, min_score=None, top_n=None):
    from math import isfinite

    best_by_label = {}

    for item in items:
        if isinstance(item, dict):
            if 'label' not in item or 'score' not in item:
                continue
            label = str(item['label'])
            score = item['score']
        elif isinstance(item, tuple) and len(item) == 2:
            label = str(item[0])
            score = item[1]
        else:
            continue

        if not isinstance(score, (int, float)):
            continue
        score = float(score)
        if score < 0 or not isfinite(score):
            continue

        current = best_by_label.get(label)
        if current is None or score > current:
            best_by_label[label] = score

    if min_score is not None:
        try:
            min_score_val = float(min_score)
        except (TypeError, ValueError):
            min_score_val = None
        if min_score_val is not None:
            best_by_label = {label: score for label, score in best_by_label.items() if score >= min_score_val}

    ranked = sorted(best_by_label.items(), key=lambda x: (-x[1], x[0]))

    if not isinstance(top_n, int) or top_n < 0:
        return ranked
    if top_n == 0:
        return []
    if not keep_ties:
        return ranked[:top_n]

    if top_n >= len(ranked):
        return ranked

    cutoff_score = ranked[top_n - 1][1]
    result = ranked[:top_n]
    i = top_n
    while i < len(ranked) and ranked[i][1] == cutoff_score:
        result.append(ranked[i])
        i += 1
    return result

def normalize_episode_index(index, total_episodes):
    if not isinstance(total_episodes, int) or total_episodes <= 0:
        raise ValueError("total_episodes must be a positive integer")

    if isinstance(index, int) and not isinstance(index, bool):
        pos = index - 1 if index > 0 else total_episodes + index
        if pos < 0 or pos >= total_episodes:
            raise IndexError("episode index out of range")
        return pos

    if isinstance(index, str):
        if not index.startswith("S") or "E" not in index[1:]:
            raise TypeError("malformed episode string")
        s_part, e_part = index[1:].split("E", 1)
        if not s_part.isdigit() or not e_part.isdigit() or not s_part or not e_part:
            raise TypeError("malformed episode string")
        season = int(s_part)
        episode = int(e_part)
        if season <= 0 or episode <= 0:
            raise TypeError("malformed episode string")
        pos = (season - 1) * 100 + (episode - 1)
        if pos < 0 or pos >= total_episodes:
            raise IndexError("episode index out of range")
        return pos

    raise TypeError("unsupported index type")

def compress_runs(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError('values must be iterable')

    result = []
    sentinel = object()
    prev = sentinel
    count = 0

    for item in iterator:
        if prev is sentinel:
            prev = item
            count = 1
        elif item == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = item
            count = 1

    if prev is not sentinel:
        result.append((prev, count))

    return result

def normalize_breadcrumb(path):
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    kept = []
    for raw_segment in path.split('/'):
        segment = raw_segment.strip()
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if kept:
                kept.pop()
            continue
        kept.append(segment)
    return '/'.join(kept)

def compact_interval_sums(items):
    if not isinstance(items, list):
        raise ValueError('items must be a list')
    result = []
    if not items:
        return result
    current_label = None
    current_total = 0
    first = True
    for pair in items:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError('each item must be a 2-tuple')
        label, value = pair
        if not isinstance(label, str):
            raise ValueError('label must be a string')
        if not isinstance(value, int):
            raise ValueError('value must be an integer')
        if first:
            current_label = label
            current_total = value
            first = False
        elif label == current_label:
            current_total += value
        else:
            result.append((current_label, current_total))
            current_label = label
            current_total = value
    result.append((current_label, current_total))
    return result

def normalize_event_schedule(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    normalized = []
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise TypeError("each event must be a 3-item tuple")
        day, start_minute, end_minute = record
        if not all(isinstance(x, int) for x in record):
            raise TypeError("each event field must be an int")
        if day < 0 or start_minute < 0 or end_minute > 1440 or start_minute >= end_minute:
            raise ValueError("invalid event time bounds")
        normalized.append((day, start_minute, end_minute))

    normalized.sort(key=lambda x: (x[0], x[1], x[2]))

    merged = []
    for day, start, end in normalized:
        if not merged or merged[-1][0] != day or start > merged[-1][2]:
            merged.append((day, start, end))
        else:
            prev_day, prev_start, prev_end = merged[-1]
            merged[-1] = (prev_day, prev_start, max(prev_end, end))
    return merged

def normalize_event_schedule(events):
    """
    Normalize a list of event records into a canonicalized schedule.

    Parameters:
    events (list of tuples): A list of 3-item tuples representing events.

    Returns:
    list of tuples: A list of normalized event records.
    """
    def merge_intervals(interval1, interval2):
        start = max(interval1[0], interval2[0])
        end = min(interval1[1], interval2[1])
        return (start, end)

    def sort_events(events):
        events.sort(key=lambda x: (x[0], x[1]))
        return events

    def validate_record(record):
        if len(record) != 3:
            raise TypeError("Each event record must be a tuple of exactly 3 integers.")
        if not all(isinstance(x, int) for x in record):
            raise ValueError("All event records must be integers.")
        if record[0] < 0 or record[1] > 1440:
            raise ValueError("Start and end minutes must be between 0 and 1440.")

    normalized_events = []
    for event in events:
        validate_record(event)
        day, start_minute, end_minute = event
        if day not in normalized_events:
            normalized_events.append((day, start_minute, end_minute))
        else:
            merged_interval = merge_intervals(normalized_events[-1], event)
            normalized_events[-1] = merged_interval

    sorted_events = sort_events(normalized_events)
    return sorted_events

