def normalize_inventory_changes(records):
    """
    Normalize a list of inventory adjustment records into a summary dictionary.

    Each record is a 3-tuple (item, delta, note), where:
    - item is a string item name.
    - delta is an integer adjustment that may be positive, negative, or zero.
    - note is either `None` or a string.

    Behavior:
    1. `item` names are case-sensitive. Do not strip whitespace or otherwise modify the item string.
    2. Ignore any record whose `item` is an empty string.
    3. For every valid record, accumulate `delta` into that item's total.
    4. For every valid record with a non-`None` note, store the note under that item in a list of notes, preserving encounter order.
    5. Return a dictionary with exactly two keys:
       - `'totals'`: a dict mapping each valid item to its total delta.
       - `'notes'`: a dict mapping each valid item to a list of its non-`None` notes in encounter order.
    6. Items that only appear in ignored records must not be present in either sub-dictionary.
    7. If `records` is empty, return `{'totals': {}, 'notes': {}}`.
    8. The function must raise `TypeError` if `records` is not an iterable of 3-tuples, or if any record is not a tuple of length 3, or if `delta` is not an integer, or if `note` is neither `None` nor a string.
    """
    totals = {}
    notes = {}

    for item, delta, note in records:
        if item == '':
            continue

        if item in totals:
            totals[item] += delta
        else:
            totals[item] = delta

        if note is not None:
            if item in notes:
                notes[item].append(note)
            else:
                notes[item] = [note]

    return {
        'totals': totals,
        'notes': notes
    }

