def parse_scoreboard(entries):
    standings = {}
    for raw in entries:
        if not isinstance(raw, str):
            raise ValueError("Each entry must be a string")
        entry = raw.strip()
        if entry.count(":") != 1:
            raise ValueError("Malformed entry")
        team_part, scores_part = entry.split(":", 1)
        team = team_part.strip()
        if team == "":
            raise ValueError("Empty team name")
        scores_part = scores_part.strip()
        if scores_part == "":
            raise ValueError("Empty score field")
        tokens = scores_part.split(",")
        if any(tok.strip() == "" for tok in tokens):
            raise ValueError("Empty score token")
        total = 0
        for tok in tokens:
            s = tok.strip()
            try:
                score = int(s)
            except Exception:
                raise ValueError("Invalid integer score")
            total += score
        standings[team] = standings.get(team, 0) + total
    return sorted(standings.items(), key=lambda item: (-item[1], item[0]))

def reconstruct_traces(events):
    # Validate and normalize events
    normalized = []
    for ev in events:
        if not isinstance(ev, tuple) or len(ev) != 3:
            raise TypeError("each event must be a 3-tuple")
        ts, action, name = ev
        if action not in ("start", "end"):
            raise ValueError("action must be 'start' or 'end'")
        normalized.append((ts, action, name))

    # Sort by timestamp; on ties, start before end
    normalized.sort(key=lambda x: (x[0], 0 if x[1] == "start" else 1))

    stacks = {}
    intervals = []

    for ts, action, name in normalized:
        if action == "start":
            stacks.setdefault(name, []).append(ts)
        else:
            stack = stacks.get(name)
            if stack:
                start_ts = stack.pop(0)
                if ts >= start_ts:
                    intervals.append((name, start_ts, ts, ts - start_ts))

    # Ignore unmatched starts remaining in stacks.
    intervals.sort(key=lambda x: (x[1], x[2], x[0]))
    return intervals

def normalize_inventory(transactions):
    if isinstance(transactions, (str, bytes)):
        raise ValueError('transactions must be an iterable of records')

    summary = {}

    for record in transactions:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError('each record must be a 3-item sequence')

        sku, delta, priority = record

        if not isinstance(sku, str) or sku == '':
            raise ValueError('sku must be a non-empty string')
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise ValueError('delta must be an integer')
        if not isinstance(priority, bool):
            raise ValueError('priority must be a boolean')

        if sku not in summary:
            summary[sku] = {'net': 0, 'count': 0, 'priority_net': 0}
        summary[sku]['net'] += delta
        summary[sku]['count'] += 1
        if priority:
            summary[sku]['priority_net'] += delta

    return {sku: summary[sku] for sku in sorted(summary)}

def normalize_quarter_notes(notes):
    if not isinstance(notes, list):
        raise ValueError('notes must be a list')

    result = []
    valid_pitches = {'C', 'D', 'E', 'F', 'G', 'A', 'B'}

    for token in notes:
        if not isinstance(token, str):
            raise ValueError('each note must be a string')
        if token == 'REST':
            result.append('REST')
            continue

        if ':' in token:
            base, dur_text = token.rsplit(':', 1)
            if not dur_text.isdigit():
                raise ValueError('invalid duration')
            duration = int(dur_text)
        else:
            base = token
            duration = 1

        if duration <= 0:
            raise ValueError('duration must be positive')
        if len(base) < 2:
            raise ValueError('invalid note')

        pitch = base[0]
        octave_text = base[1:]
        if pitch not in valid_pitches:
            raise ValueError('invalid pitch')
        if octave_text in {'', '+', '-'}:
            raise ValueError('invalid octave')
        if octave_text[0] == '-':
            if not octave_text[1:].isdigit() or len(octave_text) == 1:
                raise ValueError('invalid octave')
        else:
            if not octave_text.isdigit():
                raise ValueError('invalid octave')

        canonical = f'{pitch}{octave_text}'
        result.extend([canonical] * duration)

    return result

def decode_run_header(text: str) -> dict:
    if text is None:
        raise ValueError("text must be a string")
    if text.strip() == "":
        return {}

    allowed = {"name", "count", "unit", "flags", "note"}
    result = {}
    parts = text.split(";")
    for part in parts:
        if part == "":
            raise ValueError("empty pair")
        if part.count("=") != 1:
            raise ValueError("each pair must contain exactly one =")
        key, value = part.split("=", 1)
        key = key.strip()
        value = value.strip()
        if not key or key not in allowed:
            raise ValueError("invalid key")
        if key in result:
            raise ValueError("duplicate key")
        if key == "count":
            if value == "" or value[0] == "-" or not value.isdigit():
                raise ValueError("invalid count")
            result[key] = int(value)
        elif key == "flags":
            if value == "":
                raise ValueError("invalid flags")
            flags = [f.strip() for f in value.split(",")]
            if any(f == "" for f in flags):
                raise ValueError("invalid flags")
            result[key] = flags
        else:
            result[key] = value
    return result

