def decode_slug(slug: str) -> str:
    if not isinstance(slug, str):
        raise ValueError("slug must be a string")
    for ch in slug:
        if not ("a" <= ch <= "z" or "0" <= ch <= "9" or ch == "-"):
            raise ValueError("slug contains invalid characters")
    parts = [part for part in slug.split("-") if part != ""]
    out = []
    for part in parts:
        if part.isdigit():
            out.append(part)
        else:
            out.append(part[0].upper() + part[1:].lower())
    return " ".join(out)

