    counts = {}
    for x in values:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError('all elements must be ints')
        counts[x] = counts.get(x, 0) + 1
    parts = [f"{k}:{counts[k]}" for k in sorted(counts)]
    return "|".join(parts)

def normalize_breadcrumb(path: str) -> str:
    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' if not stack else '/' + '/'.join(stack)
    return '.' if not stack else '/'.join(stack)

def normalize_ragged_table(rows):
    if not isinstance(rows, list):
        raise TypeError('rows must be a list of lists')
    for row in rows:
        if not isinstance(row, list):
            raise TypeError('rows must be a list of lists')
    if not rows:
        return []
    max_len = max(len(row) for row in rows)
    result = []
    for row in rows:
        new_row = row[:] + [None] * (max_len - len(row))
        result.append(new_row)
    return result

def normalize_schedule(intervals):
    validated = []
    for interval in intervals:
        try:
            start, end = interval
        except Exception:
            raise TypeError("Each interval must contain exactly two values")
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("Interval endpoints must be integers")
        if start >= end:
            raise ValueError("Interval start must be less than end")
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: x[0])
    merged = [validated[0]]
    for start, end in validated[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

