def canonicalize_query(query: str) -> str:
    def decode(s: str) -> str:
        out = []
        i = 0
        while i < len(s):
            if s[i] == '%' and i + 2 < len(s):
                code = s[i + 1:i + 3].lower()
                if code == '20':
                    out.append(' ')
                    i += 3
                    continue
                if code == '2b':
                    out.append('+')
                    i += 3
                    continue
                if code == '26':
                    out.append('&')
                    i += 3
                    continue
                if code == '3d':
                    out.append('=')
                    i += 3
                    continue
            out.append(s[i])
            i += 1
        return ''.join(out)

    def encode(s: str) -> str:
        out = []
        for ch in s:
            if ch == ' ':
                out.append('%20')
            elif ch == '+':
                out.append('%2B')
            elif ch == '&':
                out.append('%26')
            elif ch == '=':
                out.append('%3D')
            else:
                out.append(ch)
        return ''.join(out)

    if query == '':
        return ''
    parts = query.split('&')
    if any(p == '' for p in parts):
        raise ValueError('empty pair')
    pairs = []
    for part in parts:
        if '=' in part:
            key, value = part.split('=', 1)
        else:
            key, value = part, ''
        dk = decode(key)
        dv = decode(value)
        pairs.append((dk, dv))
    pairs.sort(key=lambda kv: (kv[0], kv[1]))
    return '&'.join(f'{encode(k)}={encode(v)}' for k, v in pairs)

def normalize_access_list(spec: str) -> dict:
    if spec is None or spec.strip() == "":
        raise ValueError("empty specification")

    allowed_keys = {"users", "groups", "mode"}
    seen = {}

    parts = spec.split(";")
    for part in parts:
        if part.strip() == "":
            raise ValueError("malformed field")
        if "=" not in part:
            raise ValueError("malformed field")
        key, value = part.split("=", 1)
        key = key.strip()
        value = value.strip()
        if key == "":
            raise ValueError("malformed field")
        if key not in allowed_keys:
            raise ValueError("unknown key")
        if key in seen:
            raise ValueError("duplicate key")
        seen[key] = True

        if key in ("users", "groups"):
            if value == "":
                items = []
            else:
                raw_items = value.split(",")
                items = []
                for item in raw_items:
                    item = item.strip()
                    if item == "":
                        raise ValueError("empty identifier")
                    items.append(item)
            seen[key] = sorted(set(items))
        else:
            if value == "":
                raise ValueError("empty mode")
            if value not in {"read", "write", "admin"}:
                raise ValueError("invalid mode")
            seen[key] = value

    users = seen.get("users", [])
    groups = seen.get("groups", [])
    mode = seen.get("mode", "read")
    return {"users": users, "groups": groups, "mode": mode}

def normalize_schedule(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    normalized = []
    for event in events:
        if isinstance(event, dict):
            if set(event.keys()) != {'name', 'start', 'end'}:
                raise ValueError('invalid event dict')
            name = event['name']
            start = event['start']
            end = event['end']
        elif isinstance(event, (tuple, list)) and len(event) == 3:
            name, start, end = event
        else:
            raise ValueError('invalid event format')

        if not isinstance(name, str) or name == '':
            raise ValueError('invalid name')
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('invalid time values')
        if start < 0:
            raise ValueError('invalid start')
        if end < start:
            raise ValueError('invalid interval')

        normalized.append({'name': name, 'start': start, 'end': end})

    normalized.sort(key=lambda e: (e['start'], e['end'], e['name']))
    return normalized

def normalize_inventory(entries):
    if not isinstance(entries, list):
        raise ValueError("entries must be a list")
    aggregated = {}
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError("each entry must be a 3-item tuple")
        sku, quantity, tags = entry
        if not isinstance(sku, str) or sku == "":
            raise ValueError("sku must be a non-empty string")
        if not isinstance(quantity, int):
            raise ValueError("quantity must be an int")
        if not isinstance(tags, (list, tuple)):
            raise ValueError("tags must be a list or tuple")
        tag_set = aggregated.setdefault(sku, [0, set()])
        tag_values = []
        for tag in tags:
            if not isinstance(tag, str):
                raise ValueError("all tags must be strings")
            tag_values.append(tag)
        tag_set[0] += quantity
        tag_set[1].update(tag_values)
    result = []
    for sku in sorted(aggregated):
        total_quantity, tag_set = aggregated[sku]
        result.append((sku, total_quantity, sorted(tag_set)))
    return result

def decode_ledger(entries):
    if not entries:
        return []

    parsed = []
    max_index = -1
    for entry in entries:
        parts = entry.split(',')
        if len(parts) != 3:
            raise ValueError('each entry must have exactly three comma-separated fields')
        try:
            start = int(parts[0])
            end = int(parts[1])
            delta = int(parts[2])
        except Exception:
            raise ValueError('fields must be integers')
        if start < 0 or end < 0:
            raise ValueError('indices must be non-negative')
        if start > end:
            raise ValueError('start must not exceed end')
        parsed.append((start, end, delta))
        if end > max_index:
            max_index = end

    balances = [0] * (max_index + 1)
    for start, end, delta in parsed:
        for i in range(start, end + 1):
            balances[i] += delta
    return balances

def decode_ledger(entries):
    """
    Reconstructs a list of account balances from a compressed ledger specification.

    :param entries: List of strings, each representing an entry in the ledger.
    :return: List of integers representing the final balances for every index.
    """
    if not entries:
        return []

    # Parse each entry
    balances = []
    for entry in entries:
        try:
            start, end, delta = map(int, entry.split(','))
            if start < 0 or end < 0:
                raise ValueError("Start and end indices must be non-negative integers.")
            if start > end:
                raise ValueError("Start index cannot be greater than end index.")
            if start > len(balances):
                balances.extend([0] * (start - len(balances)))
            balances[start:end] += [delta]
        except ValueError as e:
            raise ValueError(f"Invalid entry: {e}")

    return balances

