def compact_intervals(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    normalized = []
    for interval in events:
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise TypeError("each interval must be a length-2 sequence")
        a, b = interval[0], interval[1]
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        if a <= b:
            normalized.append([a, b])
        else:
            normalized.append([b, a])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]

    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

def normalize_scored_items(records):
    from math import isfinite

    if isinstance(records, (str, bytes)):
        raise TypeError('records must be a sequence of 2-tuples')
    try:
        iterator = iter(records)
    except TypeError as e:
        raise TypeError('records must be a sequence of 2-tuples') from e

    out = []
    for item in iterator:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each record must be a 2-tuple')
        name, score = item
        if not isinstance(name, str):
            raise TypeError('name must be a string')
        if not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')

        normalized_name = '_'.join(name.strip().lower().split())
        if normalized_name == '':
            continue
        score_float = float(score)
        if not isfinite(score_float):
            continue
        out.append((normalized_name, score_float))

    out.sort(key=lambda x: (-x[1], x[0]))
    return out

def assign_frequency_levels(bands, max_gap):
    if max_gap < 0:
        raise ValueError("max_gap must be non-negative")
    if not bands:
        return []

    def parse(label):
        if not isinstance(label, str):
            raise ValueError("malformed band label")
        parts = label.split(":")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise ValueError("malformed band label")
        try:
            freq = int(parts[1])
        except Exception:
            raise ValueError("malformed band label")
        return label, freq

    parsed = [parse(bands[0])]
    for label in bands[1:]:
        parsed.append(parse(label))

    for i in range(1, len(parsed)):
        if parsed[i][1] < parsed[i - 1][1]:
            raise ValueError("frequencies must be in non-decreasing order")

    levels = [[parsed[0][0]]]
    prev_freq = parsed[0][1]
    for label, freq in parsed[1:]:
        if freq - prev_freq > max_gap:
            levels.append([label])
        else:
            levels[-1].append(label)
        prev_freq = freq
    return levels

def normalize_inventory(records):
    result = {}
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError("each record must be a tuple of length 3")
        sku, quantity, tags = rec
        if not isinstance(sku, str):
            raise TypeError("sku must be a string")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an integer")
        if tags is not None:
            if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
                raise TypeError("tags must be None or a list of strings")
        if sku not in result:
            result[sku] = {"quantity": 0, "tag_set": set(), "has_negative": False}
        result[sku]["quantity"] += quantity
        if quantity < 0:
            result[sku]["has_negative"] = True
        if tags is not None:
            result[sku]["tag_set"].update(tags)
    final = {}
    for sku, data in result.items():
        final[sku] = {
            "quantity": data["quantity"],
            "tag_count": len(data["tag_set"]),
            "has_negative": data["has_negative"],
        }
    return final

def normalize_keyed_records(records, required_keys):
    result = []
    keys = tuple(required_keys)
    for rec in records:
        if not isinstance(rec, dict):
            raise TypeError("each record must be a dictionary")
        out = {}
        for key in keys:
            out[key] = rec[key] if key in rec else None
        result.append(out)
    return result

def parse_contact_card(card: str) -> dict:
    if card.strip() == "":
        return {'name': None, 'email': None, 'phones': [], 'tags': set()}

    result = {'name': None, 'email': None, 'phones': [], 'tags': set()}
    fields = card.split(';')

    for raw_field in fields:
        field = raw_field.strip()
        if field == '':
            continue

        if '=' not in field:
            result['tags'].add(field)
            continue

        key, value = field.split('=', 1)
        key = key.strip()
        value = value.strip()

        if key == 'name':
            result['name'] = value
        elif key == 'email':
            result['email'] = value
        elif key == 'phone':
            result['phones'].append(value)
        elif key == 'tag':
            result['tags'].add(value)

    return result

def normalize_playlist(tracks):
    valid = []
    seen = set()
    for item in tracks:
        if not isinstance(item, dict):
            continue
        if 'artist' not in item or 'title' not in item:
            continue
        artist = item['artist']
        title = item['title']
        if not isinstance(artist, str) or not isinstance(title, str):
            continue
        artist_norm = artist.strip()
        title_norm = title.strip()
        if not artist_norm or not title_norm:
            continue
        key = (artist_norm.casefold(), title_norm.casefold())
        if key in seen:
            continue
        seen.add(key)
        out = {'artist': artist_norm, 'title': title_norm}
        if 'duration' in item and isinstance(item['duration'], int) and item['duration'] > 0:
            out['duration'] = item['duration']
        valid.append(out)
    valid.sort(key=lambda d: (d['artist'].casefold(), d['title'].casefold()))
    return valid

def parse_labeled_values(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    result = []
    positions = {}

    for segment in text.split('|'):
        seg = segment.strip()
        if seg == '':
            continue
        if seg.count(':') != 1:
            raise ValueError('each non-empty segment must contain exactly one colon')
        label, value = seg.split(':')
        label = label.strip()
        value = value.strip()
        if label == '':
            raise ValueError('label must not be empty')
        if label in positions:
            result[positions[label]] = (label, value)
        else:
            positions[label] = len(result)
            result.append((label, value))

    return result

def canonicalize_mailbox(address: str) -> str:
    if not isinstance(address, str):
        raise ValueError('address must be a string')
    s = address.strip()
    if s.count('@') != 1:
        raise ValueError('address must contain exactly one @')
    local, domain = s.split('@')
    if not local or not domain:
        raise ValueError('local and domain must be non-empty')
    plus_index = local.find('+')
    if plus_index != -1:
        local = local[:plus_index]
    local = local.replace('.', '')
    domain = domain.lower()
    if not local or not domain:
        raise ValueError('local and domain must be non-empty after normalization')
    return f'{local}@{domain}'

def normalize_slug(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    filtered = []
    for ch in text.lower():
        if ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch.isspace() or ch == '-':
            filtered.append(ch)
    s = ''.join(filtered)

    # Replace whitespace runs with hyphens
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            out.append('-')
            while i < n and s[i].isspace():
                i += 1
            continue
        out.append(ch)
        i += 1

    s = ''.join(out)

    # Collapse hyphen runs
    collapsed = []
    prev_hyphen = False
    for ch in s:
        if ch == '-':
            if not prev_hyphen:
                collapsed.append(ch)
            prev_hyphen = True
        else:
            collapsed.append(ch)
            prev_hyphen = False

    s = ''.join(collapsed).strip('-')
    return s if s else 'untitled'

def compress_ranges(values):
    ints = []
    for v in values:
        if type(v) is not int:
            raise TypeError("all elements must be integers")
        ints.append(v)

    if not ints:
        return ""

    nums = sorted(set(ints))
    parts = []
    start = prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            prev = n
            continue
        if start == prev:
            parts.append(str(start))
        else:
            parts.append(f"{start}-{prev}")
        start = prev = n

    if start == prev:
        parts.append(str(start))
    else:
        parts.append(f"{start}-{prev}")

    return ", ".join(parts)

def normalize_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')

    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                if not absolute:
                    stack.append('..')
            continue
        stack.append(part)

    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

def parse_ranked_pairs(text):
    if not isinstance(text, str):
