def run_length_encode_ranges(nums):
    items = list(nums)
    for x in items:
        if not isinstance(x, int):
            raise TypeError('all elements must be integers')
    if not items:
        return []
    runs = []
    start = prev = items[0]
    count = 1
    for x in items[1:]:
        if x == prev + 1:
            prev = x
            count += 1
        else:
            runs.append((start, prev, count))
            start = prev = x
            count = 1
    runs.append((start, prev, count))
    return runs

def normalize_command_schedule(commands):
    best = {}
    order = {}
    for idx, rec in enumerate(commands):
        if not isinstance(rec, tuple) or len(rec) != 3:
            raise ValueError("Each record must be a tuple of length 3")
        command, priority, active = rec
        if not isinstance(command, str) or command == "":
            raise ValueError("command must be a non-empty string")
        if not isinstance(priority, int):
            raise ValueError("priority must be an integer")
        if not isinstance(active, bool):
            raise ValueError("active must be a boolean")
        if command not in best:
            best[command] = rec
            order[command] = idx
        else:
            old_command, old_priority, old_active = best[command]
            if priority > old_priority:
                best[command] = rec
                order[command] = idx
            elif priority == old_priority:
                if active and not old_active:
                    best[command] = rec
                    order[command] = idx
                elif active == old_active:
                    pass
    result = list(best.values())
    result.sort(key=lambda r: (-r[1], r[0]))
    return result

def canonicalize_tags(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    grouped = {}
    order = []
    for record in records:
        if not isinstance(record, tuple) or len(record) != 2:
            raise TypeError('each record must be a 2-tuple')
        category, tags = record
        if not isinstance(category, str):
            raise TypeError('category must be a string')
        if category == '':
            raise ValueError('category must be non-empty')
        try:
            iterator = iter(tags)
        except TypeError:
            raise TypeError('tags must be iterable')
        key = category.lower()
        if key not in grouped:
            grouped[key] = [category, set()]
            order.append(key)
        for tag in iterator:
            if not isinstance(tag, str):
                raise TypeError('all tags must be strings')
            normalized = tag.strip().lower()
            if normalized:
                grouped[key][1].add(normalized)
    result = []
    for key in order:
        category, tagset = grouped[key]
        result.append((category, sorted(tagset)))
    return result

from typing import List, Tuple

def canonicalize_tags(records: List[Tuple[str, Iterable[str]]) -> List[Tuple[str, str]]:
    """
    Groups records by category, normalizes tags, and returns a list of tuples.

    Parameters:
    records (List[Tuple[str, Iterable[str]]): A list of tuples, each containing a category and a list of tags.

    Returns:
    List[Tuple[str, str]]: A list of tuples, each containing a category and a sorted list of unique tags.

    Raises:
    TypeError: If records is not a list, if any record is not a 2-tuple, if any category is not a string, or if any tags value is not iterable or contains a non-string item.
    ValueError: If a category is an empty string.
    """
    def normalize_tag(tag):
        return tag.strip().lower()

    def group_records(records):
        category_to_tags = {}
        for category, tags in records:
            if category in category_to_tags:
                category_to_tags[category].append(normalize_tag(tags))
            else:
                category_to_tags[category] = [normalize_tag(tags)]

        return [(category, sorted(set(tags))) for category, tags in category_to_tags.items()]

    return group_records(records)

