def normalize_workflow_events(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    seen = set()
    items = []

    for rec in events:
        if not isinstance(rec, tuple) or len(rec) != 4:
            raise ValueError("each event must be a tuple of exactly 4 items")

        timestamp, actor, action, payload = rec

        if not isinstance(timestamp, int):
            raise TypeError("timestamp must be int")
        if not isinstance(actor, str):
            raise TypeError("actor must be str")
        if not isinstance(action, str):
            raise TypeError("action must be str")
        if not isinstance(payload, str):
            raise TypeError("payload must be str")

        norm_actor = actor.strip().upper()
        norm_action = action.strip().lower()
        norm_payload = " ".join(payload.strip().split())
        canonical = f"{timestamp}|{norm_actor}|{norm_action}|{norm_payload}"

        if canonical not in seen:
            seen.add(canonical)
            items.append((timestamp, norm_actor, norm_action, norm_payload, canonical))

    items.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    return [x[4] for x in items]

def parse_duration_log(text):
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    lines = text.split('\n')
    count = 0
    total_ms = 0
    longest_label = None
    longest_value = None
    per_label = {}
    label_order = []
    factors = {'ms': 1, 's': 1000, 'm': 60000}
    for raw_line in lines:
        if raw_line.strip() == '':
            continue
        parts = raw_line.split(',')
        if len(parts) != 3:
            raise ValueError('malformed line')
        raw_label, raw_amount, raw_unit = parts
        label = raw_label.strip()
        if label == '':
            raise ValueError('empty label')
        amount_str = raw_amount.strip()
        unit = raw_unit.strip()
        if unit not in factors:
            raise ValueError('invalid unit')
        try:
            amount = int(amount_str)
        except Exception:
            raise ValueError('invalid amount')
        value_ms = amount * factors[unit]
        count += 1
        total_ms += value_ms
        if label not in per_label:
            per_label[label] = 0
            label_order.append(label)
        per_label[label] += value_ms
        if longest_value is None or value_ms > longest_value:
            longest_value = value_ms
            longest_label = label
    ordered_per_label = {label: per_label[label] for label in label_order}
    return {'count': count, 'total_ms': total_ms, 'longest_label': longest_label, 'per_label': ordered_per_label}

def summarize_runs(s):
    if not s or s.strip() == "":
        return {'count': 0, 'lengths': [], 'starts_with_digit': 0}

    tokens = s.split()
    lengths = []
    starts_with_digit = 0

    for tok in tokens:
        if not tok.isalnum():
            continue
        # Token must be exactly two contiguous blocks: one letters block and one digits block.
        i = 0
        n = len(tok)
        if n == 0:
            continue
        first_is_digit = tok[0].isdigit()
        if first_is_digit:
            while i < n and tok[i].isdigit():
                i += 1
            digit_len = i
            if digit_len == 0 or i == n:
                continue
            while i < n and tok[i].isalpha():
                i += 1
            if i != n:
                continue
        else:
            while i < n and tok[i].isalpha():
                i += 1
            if i == 0 or i == n:
                continue
            digit_start = i
            while i < n and tok[i].isdigit():
                i += 1
            if i != n or digit_start == n:
                continue
            digit_len = n - digit_start

        # Ensure exactly one block of each type and adjacency already enforced by parsing.
        # Reject tokens with mixed order beyond one switch.
        # For first_is_digit case: digits then letters. For else: letters then digits.
        lengths.append(digit_len)
        if first_is_digit:
            starts_with_digit += 1

    return {'count': len(lengths), 'lengths': lengths, 'starts_with_digit': starts_with_digit}

def encode_runs(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if text == '':
        return ''

    out = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        j = i + 1
        while j < n and text[j] == ch:
            j += 1
        count = j - i
        if ch == '#' or count > 1:
            out.append('#' + str(count) + ch)
        else:
            out.append(ch)
        i = j
    return ''.join(out)

def encode_runs(text: str) -> str:
    """
    Encode runs of identical characters in the given text using a custom escape rule.

    Parameters:
    text (str): The input string to be encoded.

    Returns:
    str: The encoded string.
    """
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")

    encoded_text = []
    current_char = text[0]
    count = 1

    for char in text[1:]:
        if char == current_char:
            count += 1
        else:
            if count > 1:
                encoded_text.append(f"{count}{current_char}")
            else:
                encoded_text.append(current_char)
            current_char = char
            count = 1

    # Handle the last run
    if count > 1:
        encoded_text.append(f"{count}{current_char}")
    else:
        encoded_text.append(current_char)

    return ''.join(encoded_text)

