def canonicalize_route(route: str) -> str:
    if route is None:
        raise ValueError('route must be a string')
    trimmed = route.strip()
    if trimmed == '':
        raise ValueError('empty route')
    if not trimmed.startswith('/'):
        raise ValueError('route must start with /')

    parts = trimmed.split('/')
    stack = []
    for part in parts[1:]:
        if part == '' or part == '.':
            continue
        if part == '..':
            if not stack:
                raise ValueError('cannot go above root')
            stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

def rewrite_slug(text):
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")
    filtered = []
    for ch in text:
        if ch.isspace() or ch in allowed:
            filtered.append(ch)
    s = ''.join(filtered).lower()
    s = s.replace('_', '-').replace('.', '-')
    out = []
    prev_hyphen = False
    for ch in s:
        if ch.isspace():
            ch = '-'
        if ch == '-':
            if not prev_hyphen:
                out.append(ch)
            prev_hyphen = True
        else:
            out.append(ch)
            prev_hyphen = False
    slug = ''.join(out).strip('-')
    return slug if slug else 'x'

def decode_run_length_pairs(encoded):
    if not isinstance(encoded, str):
        raise ValueError("encoded must be a string")
    if encoded == "":
        return ""

    result = []
    i = 0
    n = len(encoded)

    while i < n:
        if not encoded[i].isdigit():
            raise ValueError("expected digit at start of count")

        start = i
        while i < n and encoded[i].isdigit():
            i += 1

        if i >= n:
            raise ValueError("count missing following character")

        count = int(encoded[start:i])
        ch = encoded[i]
        i += 1

        if count:
            result.append(ch * count)

    return "".join(result)

def decode_run_length_pairs(encoded):
    """
    Decodes a compact run-length encoded string into a plain string.

    Parameters:
    encoded (str): A string containing zero or more segments.

    Returns:
    str: The decoded string formed by repeating each character the specified number of times, in order.
    """
    if not encoded:
        return ""

    decoded = []
    count = 0
    char = ""

    for char in encoded:
        if char.isdigit():
            count = count * 10 + int(char)
        elif char.isalpha():
            if count > 0:
                decoded.append(char * count)
            count = 0
        else:
            raise ValueError("Malformed input")

    if count > 0:
        decoded.append(char * count)

    return ''.join(decoded)

