def normalize_course_plan(plan):
    if not isinstance(plan, list):
        raise ValueError("plan must be a list")

    seen_codes = []
    code_set = set()

    for record in plan:
        if not isinstance(record, (list, tuple)) or len(record) != 3:
            raise ValueError("each record must be a 3-item tuple or list")
        course_code, prerequisites, credits = record
        if not isinstance(course_code, str):
            raise ValueError("course_code must be a string")
        if course_code in code_set:
            raise ValueError("duplicate course codes")
        code_set.add(course_code)
        seen_codes.append(course_code)
        if not isinstance(prerequisites, (list, tuple)):
            raise ValueError("prerequisites must be a list or tuple")
        if not isinstance(credits, int) or isinstance(credits, bool) or credits < 0:
            raise ValueError("credits must be a non-negative integer")
        for prereq in prerequisites:
            if not isinstance(prereq, str):
                raise ValueError("prerequisites must be strings")
            if prereq == course_code:
                raise ValueError("course cannot depend on itself")

    normalized = []
    for record in plan:
        course_code, prerequisites, credits = record
        unique_prereqs = sorted(set(prerequisites))
        normalized.append((course_code, unique_prereqs, credits))

    for course_code, prerequisites, _ in normalized:
        for prereq in prerequisites:
            if prereq not in code_set:
                raise ValueError("unknown prerequisite")

    normalized.sort(key=lambda x: x[0])
    return normalized

from decimal import Decimal

def summarize_transactions(log: str) -> dict:
    def norm_decimal(d: Decimal) -> str:
        s = format(d.normalize(), 'f')
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s if s else '0'

    accounts = {}
    account_order = []
    grand = Decimal('0')
    line_count = 0

    for raw_line in log.split('\n'):
        line = raw_line.strip()
        if not line:
            continue
        parts = [p.strip() for p in raw_line.split(',')]
        if len(parts) != 3:
            raise ValueError('Each non-empty line must have exactly three fields')
        account_id, amount_str, currency = parts
        if not account_id:
            raise ValueError('Empty account_id')
        if not currency:
            raise ValueError('Empty currency')
        try:
            amount = Decimal(amount_str)
        except Exception as e:
            raise ValueError('Invalid amount') from e

        line_count += 1
        grand += amount
        if account_id not in accounts:
            accounts[account_id] = {'count': 0, 'total': Decimal('0'), 'currencies': set()}
            account_order.append(account_id)
        acc = accounts[account_id]
        acc['count'] += 1
        acc['total'] += amount
        acc['currencies'].add(currency)

    ordered_accounts = {}
    for aid in account_order:
        acc = accounts[aid]
        ordered_accounts[aid] = {
            'count': acc['count'],
            'total': norm_decimal(acc['total']),
            'currencies': sorted(acc['currencies'])
        }

    return {
        'accounts': ordered_accounts,
        'grand_total': norm_decimal(grand),
        'line_count': line_count
    }

def compress_spans(nums):
    unique_sorted = sorted(set(nums))
    if not unique_sorted:
        return []
    spans = []
    start = prev = unique_sorted[0]
    for x in unique_sorted[1:]:
        if x == prev + 1:
            prev = x
        else:
            spans.append([start, prev])
            start = prev = x
    spans.append([start, prev])
    return spans

def normalize_relative_path(path: str) -> str:
    if path == "":
        return "."
    parts = path.split("/")
    stack = []
    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            else:
                stack.append("..")
        else:
            stack.append(part)
    return "/".join(stack) if stack else "."

def compress_ranges(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError('values must be iterable')

    result = []
    try:
        first = next(iterator)
    except StopIteration:
        return result

    if type(first) is not int:
        raise TypeError('all elements must be integers')

    start = 0
    end = 0
    current = first

    for idx, item in enumerate(iterator, start=1):
        if type(item) is not int:
            raise TypeError('all elements must be integers')
        if item == current:
            end = idx
        else:
            result.append((start, end, current))
            start = end = idx
            current = item
    result.append((start, end, current))
    return result

def normalize_event_scores(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    totals = {}
    for record in events:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError("each record must be a 3-tuple")

        name, score, weight = record

        if not isinstance(name, str) or name == "" or name != name.strip():
            raise ValueError("invalid name")
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError("invalid score")
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:
            raise ValueError("invalid weight")

        if name not in totals:
            totals[name] = [0.0, 0]
        totals[name][0] += float(score) * weight
        totals[name][1] += weight

    result = []
    for name in sorted(totals):
        weighted_sum, total_weight = totals[name]
        result.append((name, weighted_sum / total_weight, total_weight))
    return result

def fold_lines(text, width):
    if not isinstance(width, int) or width <= 0:
        raise ValueError("width must be a positive integer")
    if text is None:
        raise TypeError("text must be a string")
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    paragraphs = text.split('\n')
    out_paragraphs = []

    for para in paragraphs:
        words = para.split()
        if not words:
            out_paragraphs.append([])
            continue

        lines = []
        current = ""
        for word in words:
            if not current:
                current = word
            else:
                candidate_len = len(current) + 1 + len(word)
                if candidate_len <= width:
                    current += " " + word
                else:
                    lines.append(current)
                    current = word
        if current:
            lines.append(current)
        out_paragraphs.append(lines)

    rendered_paragraphs = []
    for lines in out_paragraphs:
        if not lines:
            rendered_paragraphs.append("")
        else:
            rendered_paragraphs.append("\n".join(lines))

    if all(p == "" for p in rendered_paragraphs):
        return ""

    return "\n".join(rendered_paragraphs)

def decode_rle_cells(text):
    if not isinstance(text, str) or text == "":
        raise ValueError("input must be a non-empty string")

    rows = text.split("\n")
    result = []
    expected_len = None

    for row in rows:
        if row == "":
            raise ValueError("empty row")
        if row.startswith(" ") or row.endswith(" ") or "  " in row:
            raise ValueError("invalid spacing")

        cells = []
        segments = row.split(" ")
        if len(segments) == 0:
            raise ValueError("empty row")

        for seg in segments:
            if seg == "" or ":" not in seg:
                raise ValueError("invalid segment")
            count_str, value = seg.split(":", 1)
            if count_str == "" or value == "":
                raise ValueError("invalid segment")
            if not count_str.isdigit():
                raise ValueError("invalid count")
            count = int(count_str)
            if count < 1:
                raise ValueError("invalid count")
            if len(value) != 1:
                raise ValueError("invalid value")
            cells.extend([value] * count)

        if expected_len is None:
            expected_len = len(cells)
        elif len(cells) != expected_len:
            raise ValueError("rows must have equal length")

        result.append(cells)

    return result

def normalize_csv_row(row, expected_fields):
    if expected_fields < 0:
        raise ValueError('expected_fields must be non-negative')
    if row == '':
        if expected_fields == 0:
            return []
        return [''] * expected_fields

    fields = []
    current = []
    i = 0
    n = len(row)
    in_quotes = False
    field_was_quoted = False

    while i < n:
        ch = row[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and row[i + 1] == '"':
                    current.append('"')
                    i += 2
                else:
                    in_quotes = False
                    field_was_quoted = True
                    i += 1
            else:
                current.append(ch)
                i += 1
        else:
            if ch == ',':
                field = ''.join(current)
                if not field_was_quoted:
                    field = field.strip()
                fields.append(field)
                current = []
                field_was_quoted = False
                i += 1
            elif ch == '"':
                if ''.join(current).strip() != '':
                    raise ValueError('unexpected quote')
                current = []
                in_quotes = True
                i += 1
            else:
                current.append(ch)
                i += 1

    if in_quotes:
        raise ValueError('unmatched quotes')

    field = ''.join(current)
    if not field_was_quoted:
        field = field.strip()
    fields.append(field)

    if len(fields) > expected_fields:
        raise ValueError('too many fields')
    while len(fields) < expected_fields:
        fields.append('')
    return fields

def normalize_grid_path(grid, path):
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError("grid must be a non-empty rectangular list of lists")
    if not all(isinstance(row, list) for row in grid):
        raise ValueError("grid must be a list of lists")
    width = len(grid[0])
    if width == 0:
        raise ValueError("grid rows must be non-empty")
    for row in grid:
        if len(row) != width:
            raise ValueError("grid must be rectangular")

    allowed = {"#", ".", "S", "E"}
    starts = []
    exits = 0
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell not in allowed:
                raise ValueError("invalid grid cell")
            if cell == "S":
                starts.append((i, j))
            elif cell == "E":
                exits += 1
    if len(starts) != 1:
        raise ValueError("grid must contain exactly one S")
    if exits < 1:
        raise ValueError("grid must contain at least one E")

    if not isinstance(path, list):
        raise ValueError("path must be a list")
    move_delta = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
    for move in path:
        if move not in move_delta:
            raise ValueError("invalid move")

    r, c = starts[0]
    traversed = [f"{r},{c}"]
    for move in path:
        dr, dc = move_delta[move]
        nr, nc = r + dr, c + dc
        if nr < 0 or nr >= len(grid) or nc < 0 or nc >= width:
            return "INVALID"
        if grid[nr][nc] == "#":
            return "INVALID"
        r, c = nr, nc
        traversed.append(f"{r},{c}")
    return "->".join(traversed)

def compress_signed_runs(nums):
    result = []
    iterator = iter(nums)
    try:
        current = next(iterator)
    except StopIteration:
        return result
    if not isinstance(current, int):
        raise TypeError("all elements must be integers")
    count = 1
    for item in iterator:
        if not isinstance(item, int):
            raise TypeError("all elements must be integers")
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_order_path(path: str) -> str:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    parts = []
    for segment in path.split('/'):
        if segment == '' or segment == '.':
            continue
        if segment == '..':
            if parts:
                parts.pop()
            continue
        if segment.startswith('~'):
            parts.append('~' + segment[1:].replace('~', ''))
            continue
        parts.append(segment)
    return '/'.join(parts)

def normalize_registry(records):
    result = {}
    for record in records:
        try:
            key, value = record
        except ValueError:
            raise ValueError('each record must be a 2-item sequence')
        except TypeError:
            raise ValueError('each record must be a 2-item sequence')
        if not isinstance(key, str):
            raise TypeError('key must be a string')
        normalized = '_'.join(key.strip().lower().split())
        if normalized:
            result[normalized] = value
    return result

def normalize_registry(records):
    """
    Normalize a sequence of registry entries into a canonical mapping.

    Parameters:
    records (list of tuples): A list of 2-item tuples, each representing a registry entry.

    Returns:
    dict: A dictionary where keys are normalized keys and values are the corresponding values from the last matching record.

    Raises:
    ValueError: If any record is not a 2-item sequence.
    TypeError: If any key is not a string.
    """
    def normalize_key(key):
        # Strip leading and trailing whitespace
        key = key.strip()
        # Convert to lowercase
        key = key.lower()
        # Replace internal run of one or more whitespace characters with a single underscore
        key = re.sub(r'\s+', '_', key)
        return key

    normalized_records = []
    for key, value in records:
        if not isinstance(key, str):
            raise TypeError("All keys must be strings.")
        if not isinstance(value, (int, float, str)):
            raise TypeError("All values must be integers, floats, or strings.")
        normalized_key = normalize_key(key)
        if normalized_key in normalized_records:
            normalized_records[normalized_key].append(value)
        else:
            normalized_records[normalized_key] = [value]

    return {key: values[-1] for key, values in normalized_records.items()}

