def sanitize_path_segments(parts):
    try:
        iterator = iter(parts)
    except TypeError:
        raise TypeError('parts must be iterable')

    cleaned = []
    prev = object()
    for part in iterator:
        if not isinstance(part, str):
            raise TypeError('all parts must be strings')
        s = part.strip().lower()
        i = 0
        out = []
        in_ws = False
        while i < len(s):
            ch = s[i]
            if ch.isspace():
                in_ws = True
            else:
                if in_ws and out:
                    out.append('_')
                in_ws = False
                if ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch in '_-':
                    out.append(ch)
            i += 1
        seg = ''.join(out)
        if seg == '':
            continue
        if seg == prev:
            continue
        cleaned.append(seg)
        prev = seg

    filtered = [seg for seg in cleaned if seg not in ('.', '..')]
    if filtered and filtered[0] == 'root':
        filtered = filtered[1:]
    return filtered

def summarize_plateau_runs(seq):
    runs = []
    it = iter(seq)
    try:
        current = next(it)
    except StopIteration:
        return {'run_count': 0, 'longest_run_value': None, 'longest_run_length': 0, 'runs': []}

    length = 1
    for x in it:
        if x == current:
            length += 1
        else:
            runs.append((current, length))
            current = x
            length = 1
    runs.append((current, length))

    longest_len = 0
    longest_val = None
    for value, run_len in runs:
        if run_len > longest_len:
            longest_len = run_len
            longest_val = value

    return {
        'run_count': len(runs),
        'longest_run_value': longest_val,
        'longest_run_length': longest_len,
        'runs': runs,
    }

def merge_time_blocks(blocks):
    try:
        iterator = iter(blocks)
    except TypeError as e:
        raise TypeError("blocks must be iterable") from e

    normalized = []
    for item in iterator:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a 2-item sequence")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("interval endpoints must be integers")
        if start < end:
            normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort(key=lambda x: x[0])
    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def parse_spaced_grid(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    grid = []
    width = 0
    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if line == '':
            continue
        tokens = line.split()
        row = []
        for tok in tokens:
            if tok == '-' or tok == '':
                raise ValueError('invalid integer token')
            if tok[0] == '-':
                if len(tok) == 1 or not tok[1:].isdigit():
                    raise ValueError('invalid integer token')
            elif not tok.isdigit():
                raise ValueError('invalid integer token')
            row.append(int(tok))
        grid.append(row)
        if len(row) > width:
            width = len(row)
    return grid, width

def summarize_reactions(events):
    if events == []:
        return {'unique_users': 0, 'net_score': 0, 'timeline': []}

    active = {}
    seen_users = set()
    timeline = []
    net_score = 0

    for event in events:
        if not (isinstance(event, tuple) and len(event) == 2):
            raise ValueError('each event must be a 2-tuple')
        user_id, action = event
        if not isinstance(user_id, str):
            raise ValueError('user_id must be a string')
        if action not in ('+', '-'):
            raise ValueError("action must be '+' or '-'")

        seen_users.add(user_id)
        previous = active.get(user_id)
        if previous is None:
            active[user_id] = action
            net_score += 1 if action == '+' else -1
        elif previous != action:
            active[user_id] = action
            net_score += 2 if action == '+' else -2
        timeline.append(net_score)

    return {
        'unique_users': len(seen_users),
        'net_score': net_score,
        'timeline': timeline,
    }

def normalize_shifted_letter_counts(text: str, shift: int) -> dict:
    counts = {chr(ord('a') + i): 0 for i in range(26)}
    total = 0
    shift %= 26

    for ch in text:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') + shift) % 26 + ord('a'))
            counts[shifted] += 1
            total += 1
        elif 'A' <= ch <= 'Z':
            shifted = chr((ord(ch) - ord('A') + shift) % 26 + ord('A'))
            counts[shifted.lower()] += 1
            total += 1

    if total == 0:
        return {k: 0.0 for k in counts}

    return {k: counts[k] / total for k in counts}

def normalize_inventory(records):
    grouped = {}
    order = []
    for rec in records:
        if not isinstance(rec, tuple) or len(rec) != 3:
            continue
        item_id, quantity, tag = rec
        if not isinstance(item_id, str) or item_id == "":
            continue
        if not isinstance(quantity, int):
            continue
        if not isinstance(tag, str):
            continue
        if item_id not in grouped:
            grouped[item_id] = [0, 0, []]
            order.append(item_id)
        grouped[item_id][0] += 1
        grouped[item_id][1] += quantity
        if tag not in grouped[item_id][2]:
            grouped[item_id][2].append(tag)
    result = []
    for item_id in sorted(grouped):
        count, net_quantity, tags = grouped[item_id]
        result.append((item_id, {"count": count, "net_quantity": net_quantity, "tags": tuple(tags)}))
    return result

def compress_runs(items):
