    iterator = iter(items)
    try:
        prev = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = item
            count = 1
    result.append((prev, count))
    return result

def normalize_section_headings(text):
