    out = []
    for line in lines:
        if line.startswith('#'):
            if line.endswith('\r\n'):
                body = line[:-2]
                ending = '\r\n'
            elif line.endswith('\n'):
                body = line[:-1]
                ending = '\n'
            elif line.endswith('\r'):
                body = line[:-1]
                ending = '\r'
            else:
                body = line
                ending = ''
            stripped = body.lstrip('#').strip()
            out.append('# ' + stripped + ending)
        else:
            out.append(line)
    return ''.join(out)

