def normalize_sql_identifiers(sql: str) -> str:
    out = []
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if ch == "'":
            start = i
            i += 1
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        i += 2
                    else:
                        i += 1
                        out.append(sql[start:i])
                        break
                else:
                    i += 1
            else:
                raise ValueError("unterminated single-quoted string")
            continue
        if ch == '"':
            start = i
            i += 1
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        i += 2
                    else:
                        i += 1
                        out.append(sql[start:i])
                        break
                else:
                    i += 1
            else:
                raise ValueError("unterminated double-quoted identifier")
            continue
        if ch.isalpha() or ch == '_':
            start = i
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                i += 1
            out.append(sql[start:i].lower())
            continue
        out.append(ch)
        i += 1
    return ''.join(out)

def normalize_inventory_transactions(records):
    result = {}
    if records is None:
        return {}
    for rec in records:
        if not isinstance(rec, dict):
            continue
        if 'item' not in rec or 'qty' not in rec:
            continue
        item = rec['item']
        qty = rec['qty']
        if not isinstance(item, str) or item == '':
            continue
        if not isinstance(qty, int):
            continue
        action = rec.get('action', None)
        if 'action' in rec and action not in ('add', 'remove'):
            continue
        tags = rec.get('tags', None)
        if 'tags' in rec:
            if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
                continue
        if action == 'remove':
            contrib = -abs(qty)
        else:
            contrib = qty
        result[item] = result.get(item, 0) + contrib
    return dict(sorted(result.items(), key=lambda kv: kv[0]))

def normalize_inventory_transactions(records):
    """
    Normalize a list of inventory transaction records and aggregate net quantity changes per item.

    :param records: An iterable of dictionaries.
    :return: A dictionary mapping each item to its net integer quantity, sorted by item name in ascending lexicographic order.
    """
    def normalize_quantity(record):
        if 'item' not in record or 'qty' not in record or 'action' not in record or 'tags' not in record:
            return {}

        item = record['item']
        qty = record['qty']
        action = record['action']
        tags = record.get('tags', [])

        if not item or not isinstance(qty, int) or not isinstance(action, str) or not isinstance(tags, list):
            return {}

        if action == 'remove':
            return -abs(qty)
        elif action == 'add':
            return qty
        else:
            return qty

    normalized_records = [normalize_quantity(record) for record in records]
    item_counts = {item: sum(normalized_records[item]) for item in set(normalized_records)}
    return dict(sorted(item_counts.items(), key=lambda x: x[0]))

