def summarize_nested_codes(data):
    from collections.abc import Sequence

    if isinstance(data, (str, bytes, bytearray)) or not isinstance(data, Sequence):
        raise TypeError("data must be a sequence")

    int_sum = 0
    int_count = 0
    strings = set()
    max_depth = 1
    shape = []

    def is_valid_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def walk(obj, depth):
        nonlocal int_sum, int_count, max_depth, shape
        if isinstance(obj, str):
            strings.add(obj)
            return
        if is_valid_int(obj):
            int_sum += obj
            int_count += 1
            return
        if isinstance(obj, (bytes, bytearray)) or not isinstance(obj, Sequence):
            raise TypeError("invalid element type")

        max_depth = max(max_depth, depth)
        if len(shape) < depth:
            shape.append(0)
        shape[depth - 1] = max(shape[depth - 1], len(obj))
        for item in obj:
            walk(item, depth + 1)

    walk(data, 1)
    return {
        "int_sum": int_sum,
        "int_count": int_count,
        "unique_strings": sorted(strings),
        "max_depth": max_depth,
        "shape": tuple(shape),
    }

def summarize_nested_codes(data):
    """
    Analyzes a nested collection of integers and strings, returning a dictionary with specific counts and shapes.

    Parameters:
    data (list or tuple): A sequence containing integers or sequences of integers/strings.

    Returns:
    dict: A dictionary with keys 'int_sum', 'int_count', 'unique_strings', 'max_depth', and 'shape'.
    """
    if not isinstance(data, (list, tuple)):
        raise TypeError("Input must be a sequence.")

    def sum_integers_and_strings(seq):
        total = 0
        unique_strings = set()
        for item in seq:
            if isinstance(item, int):
                total += item
            elif isinstance(item, list):
                total += sum_integers_and_strings(item)
            elif isinstance(item, str):
                unique_strings.add(item)
        return total, len(unique_strings)

    int_sum, int_count = sum_integers_and_strings(data)
    unique_strings = sorted(unique_strings)
    max_depth = max(len(seq) for seq in data if isinstance(seq, list))
    shape = tuple(max_depth + 1) * len(data)

    return {
        'int_sum': int_sum,
        'int_count': int_count,
        'unique_strings': unique_strings,
        'max_depth': max_depth,
        'shape': shape
    }

