def normalize_sections(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if text == '':
        return []

    lines = text.splitlines()
    paragraphs = []
    current = []

    def flush():
        if not current:
            return
        parts = []
        for line in current:
            stripped = line.strip()
            if stripped:
                parts.append(' '.join(stripped.split()))
        if parts:
            paragraph = ' '.join(parts).strip()
            if paragraph:
                paragraphs.append(paragraph)

    for line in lines:
        if line.strip() == '':
            flush()
            current.clear()
        else:
            current.append(line)
    flush()
    return paragraphs

def collapse_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")

    normalized = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each interval must be a two-item list or tuple")
        a, b = item
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")
        if a <= b:
            normalized.append([a, b])
        else:
            normalized.append([b, a])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def compress_intervals(intervals):
    if intervals is None:
        raise ValueError("intervals must be a sequence of pairs")

    normalized = []
    for item in intervals:
        try:
            a, b = item
        except Exception:
            raise ValueError("each interval must contain exactly two elements")

        # Reject booleans explicitly because bool is a subclass of int.
        if type(a) is not int or type(b) is not int:
            raise ValueError("interval endpoints must be integers")

        start, end = (a, b) if a <= b else (b, a)
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0]]

    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

def spiral_read(matrix):
    if not isinstance(matrix, list):
        raise ValueError("matrix must be a list of rows")
    if len(matrix) == 0:
        return []
    if any(not isinstance(row, list) for row in matrix):
        raise ValueError("each row must be a list")

    row_lengths = [len(row) for row in matrix]
    if len(set(row_lengths)) > 1:
        raise ValueError("all rows must have the same length")
    if row_lengths[0] == 0:
        return []

    top, bottom = 0, len(matrix) - 1
    left, right = 0, row_lengths[0] - 1
    result = []

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

def normalize_event_log(log):
    if log == "":
        return []

    records = []
    for raw_record in log.split(";"):
        record = raw_record.strip()
        if record == "":
            continue
        parts = record.split(",")
        if len(parts) != 3:
            raise ValueError("each non-empty record must have exactly three fields")
        ts_text = parts[0].strip()
        try:
            timestamp = int(ts_text)
        except Exception as e:
            raise ValueError("invalid timestamp") from e
        event_type = parts[1].strip()
        detail = parts[2].strip()
        records.append((timestamp, event_type, detail))

    records.sort(key=lambda item: item[0])
    return records

def decode_runlength_stream(encoded: str):
    if encoded == "":
        return []
    if encoded is None:
        raise ValueError("encoded must be a string")
    if not isinstance(encoded, str):
        raise ValueError("encoded must be a string")

    result = []
    segments = encoded.split(";")
    for segment in segments:
        if segment == "":
            raise ValueError("empty segment")
        if segment.count("*") != 1:
            raise ValueError("segment must contain exactly one *")
        count_str, token = segment.split("*", 1)
        if count_str == "" or not count_str.isdigit():
            raise ValueError("invalid count")
        if ";" in token or "*" in token:
            raise ValueError("invalid token")
        count = int(count_str, 10)
        if count < 0:
            raise ValueError("negative count")
        result.extend([token] * count)
    return result

def normalize_layered_scores(scores, *, reverse=False, decimals=3):
    if not isinstance(scores, list):
        raise TypeError("scores must be a list of lists")

    result = []
    for layer in scores:
        if not isinstance(layer, list):
            raise TypeError("scores must be a list of lists")
        if any(not isinstance(x, (int, float)) for x in layer):
            raise TypeError("all values must be numeric")

        if len(layer) == 0:
            result.append([])
            continue

        min_layer = min(layer)
        max_layer = max(layer)
        span = max_layer - min_layer

        normalized_layer = []
        for x in layer:
            if span == 0:
                v = 0.0
            else:
                v = (x - min_layer) / span
            if reverse:
                v = 1 - v
            normalized_layer.append(round(v, decimals))
        result.append(normalized_layer)

    return result

def parse_decimal_value(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    if text == "":
        raise ValueError("empty input")

    i = 0
    n = len(text)
    sign = 1
    if text[i] in "+-":
        sign = -1 if text[i] == "-" else 1
        i += 1
        if i == n:
            raise ValueError("sign only")

    if text[i:] != text[i:].strip():
        raise ValueError("whitespace not allowed")

    if text.count("+") + text.count("-") > (1 if text[0] in "+-" else 0):
        raise ValueError("multiple signs")
    if text.count(".") > 1:
        raise ValueError("multiple decimal points")

    body = text[i:]
    if body == "":
        raise ValueError("no digits")

    if any(ch not in "0123456789." for ch in body):
        raise ValueError("invalid character")

    if body == ".":
        raise ValueError("no digits")

    if body.count(".") == 1:
        left, right = body.split(".")
    else:
        left, right = body, ""

    if left == "" and right == "":
        raise ValueError("no digits")
    if left == "" and right == "":
        raise ValueError("no digits")
    if left == "" and right == "":
        raise ValueError("no digits")
    if left == "" and right == "" or (left == "" and right == ""):
        raise ValueError("no digits")
    if left == "" and right == "":
        raise ValueError("no digits")

    if left and not left.isdigit():
        raise ValueError("invalid integer part")
    if right and not right.isdigit():
        raise ValueError("invalid fractional part")
    if not left and not right:
        raise ValueError("no digits")

    if left == "" and right == "":
        raise ValueError("no digits")

    int_part = int(left) if left else 0
    frac_digits = right

    thousand_factor = 1000
    if len(frac_digits) >= 4:
        kept = int(frac_digits[:3]) if frac_digits[:3] else 0
        next_digit = int(frac_digits[3])
        rest = frac_digits[4:]
        result = int_part * thousand_factor + kept
        if next_digit > 5 or (next_digit == 5 and any(ch != "0" for ch in rest)):
            result += 1
        elif next_digit == 5:
            result += 1
    else:
        padded = (frac_digits + "000")[:3]
        result = int_part * thousand_factor + (int(padded) if padded else 0)
    return sign * result

def run_length_encode_segments(text: str) -> list[tuple[str, int, int]]:
    if not isinstance(text, str):
        raise TypeError('text must be a str')

    if text == '':
        return []

    result = []
    start = 0
    current = text[0]
    count = 1

    for i in range(1, len(text)):
        ch = text[i]
        if ch == current:
            count += 1
        else:
            result.append((current, count, start))
            current = ch
            start = i
            count = 1

    result.append((current, count, start))
    return result

def normalize_nested_unique(data):
    def walk(x, out, seen):
        if isinstance(x, bool) or not isinstance(x, int) and not isinstance(x, (list, tuple)):
            if x is None:
                return
            raise TypeError('all leaf values must be integers')
        if isinstance(x, int) and not isinstance(x, bool):
            if x not in seen:
                seen.add(x)
                out.append(x)
            return
        for item in x:
            walk(item, out, seen)

    result = []
    seen = set()
    if data is None:
        return result
    walk(data, result, seen)
    return result

def collapse_runs(items):
    it = iter(items)
    result = []
    try:
        current = next(it)
    except StopIteration:
        return result

    count = 1
    for x in it:
        if x == current:
            count += 1
        else:
            result.append((current, count))
            current = x
            count = 1
    result.append((current, count))
    return result

def canonicalize_route(route: str) -> str:
    if route == "":
        return ""

    retained = []
    for segment in route.split('/'):
        if segment == "" or segment == ".":
            continue
        if segment == "..":
            if retained:
                retained.pop()
            continue
        if not segment:
            continue
        first = segment[0]
        if not (first.isalpha() or first == '_'):
            raise ValueError(f"invalid segment: {segment!r}")
        for ch in segment:
            if not (ch.isalnum() or ch == '_'):
                raise ValueError(f"invalid segment: {segment!r}")
        retained.append(segment)
    return "/".join(retained)

def merge_step_segments(segments):
    if not isinstance(segments, list):
        raise TypeError("segments must be a list")

    rendered = []
    for item in segments:
        if isinstance(item, int):
            if item < 0:
                raise ValueError("integer segments must be non-negative")
            rendered.append(str(item))
        elif isinstance(item, tuple):
            if len(item) != 2:
                raise TypeError("tuple segments must have length 2")
            label, n = item
            if not isinstance(label, str):
                raise TypeError("segment label must be a string")
            if not isinstance(n, int):
                raise TypeError("segment length must be an integer")
            if n < 0:
                raise ValueError("segment length must be non-negative")
            rendered.append(f"{label}:{n}")
        else:
            raise TypeError("each segment must be an int or a 2-tuple")
    return "/".join(rendered)

def normalize_event_messages(events):
    result = []
    for event in events:
        if not isinstance(event, tuple) or len(event) != 2:
            result.append("INVALID")
            continue
        kind, payload = event
        if kind == "user":
            if isinstance(payload, str):
                result.append(f"USER: {payload}")
            else:
                result.append("MALFORMED")
        elif kind == "system":
            if isinstance(payload, tuple) and len(payload) == 2 and all(isinstance(x, str) for x in payload):
                component, message = payload
                result.append(f"SYSTEM[{component}]: {message}")
            else:
                result.append("MALFORMED")
        elif kind == "error":
            if isinstance(payload, int):
                result.append(f"ERROR#{payload}")
            else:
                result.append("MALFORMED")
        else:
            result.append("UNKNOWN")
    return result

def normalize_event_messages(events):
    """
    Normalize event messages according to the specified rules.

    Parameters:
    events (list of tuples): A list of event records, each containing a kind and a payload.

    Returns:
    list of str: A list of normalized message strings.
    """
    def normalize_message(record):
        if isinstance(record, tuple) and len(record) == 2:
            kind, payload = record
            if kind == "user":
                return f"USER: {payload}"
            elif kind == "system":
                component, message = payload
                return f"SYSTEM[{component}]: {message}"
            elif kind == "error":
                return f"ERROR#{payload}"
            else:
                return f"UNKNOWN"
        elif isinstance(record, int):
            return f"INVALID"
        elif isinstance(record, str):
            return record
        else:
            return "MALFORMED"

    return [normalize_message(event) for event in events]

