def simulate_stack_ops(ops):
    stack = []
    results = []
    for op in ops:
        if not isinstance(op, tuple):
            raise ValueError("Each operation must be a tuple")
        if not op:
            raise ValueError("Empty operation tuple")
        cmd = op[0]
        if cmd == 'push':
            if len(op) != 2:
                raise ValueError("push requires exactly one argument")
            stack.append(op[1])
            results.append(None)
        elif cmd == 'pop':
            if len(op) != 1:
                raise ValueError("pop takes no arguments")
            results.append(stack.pop() if stack else None)
        elif cmd == 'peek':
            if len(op) != 1:
                raise ValueError("peek takes no arguments")
            results.append(stack[-1] if stack else None)
        elif cmd == 'size':
            if len(op) != 1:
                raise ValueError("size takes no arguments")
            results.append(len(stack))
        else:
            raise ValueError("Unknown operation")
    return results

def simulate_stack_ops(ops):
    """
    Simulate a stack and return a list of results for each operation.

    :param ops: List of 2-tuples representing stack operations.
    :return: List of results for each operation in sequence.
    """
    stack = []
    results = []

    for op in ops:
        if op[0] == 'push':
            stack.append(op[1])
        elif op[0] == 'pop':
            if not stack:
                results.append(None)
            else:
                stack.pop()
        elif op[0] == 'peek':
            if not stack:
                results.append(None)
            else:
                results.append(stack[-1])
        elif op[0] == 'size':
            results.append(len(stack))
        else:
            raise ValueError(f"Unrecognized command: {op[0]}")

    return results

