def summarize_run_lengths(s):
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if s == '':
        return ''

    def encode_char(ch):
        if ch == '\\':
            return '\\\\'
        if ch.isdigit():
            return '\\' + ch
        if ch == ':':
            return '\\:'
        return ch

    parts = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        j = i + 1
        while j < n and s[j] == ch:
            j += 1
        count = j - i
        token = encode_char(ch)
        if count > 1:
            token += str(count)
        parts.append(token)
        i = j
    return '|'.join(parts)

def parse_compound_measurement(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return ""

    i = 0
    n = len(text)
    totals = {}
    order = []

    def parse_int(s, start):
        j = start
        if j < n and s[j] in '+-':
            j += 1
        if j >= n or not s[j].isdigit():
            raise ValueError("malformed integer")
        while j < n and s[j].isdigit():
            j += 1
        return int(s[start:j]), j

    while i < n:
        if text[i] in '+-':
            sign = text[i]
            i += 1
            if i < n and text[i] in '+-':
                raise ValueError("repeated sign")
            if i >= n or not text[i].isdigit():
                raise ValueError("missing digits")
            j = i
            while j < n and text[j].isdigit():
                j += 1
            amount = int(sign + text[i:j])
            i = j
        else:
            if not text[i].isdigit():
                raise ValueError("expected integer")
            j = i
            while j < n and text[j].isdigit():
                j += 1
            amount = int(text[i:j])
            i = j

        k = i
        if k >= n or not text[k].isalpha():
            raise ValueError("missing unit")
        while k < n and text[k].isalpha():
            k += 1
        unit = text[i:k]
        i = k

        if unit not in totals:
            totals[unit] = 0
            order.append(unit)
        totals[unit] += amount

        if i < n:
            if text[i] not in '+-':
                raise ValueError("stray characters")
    return ", ".join(f"{u}={totals[u]}" for u in order)

def summarize_hierarchical_tags(records):
    result = {}
    for item in records:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("Each record must be a 2-tuple")
        path, value = item
        if not isinstance(path, str):
            raise TypeError("Path must be a string")
        if not isinstance(value, int):
            raise TypeError("Value must be an integer")

        parts = [segment for segment in path.split('/') if segment != '']
        if not parts:
            continue

        for i in range(1, len(parts) + 1):
            key = '/'.join(parts[:i])
            result[key] = result.get(key, 0) + value
    return result

def parse_command_line(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')

    n = len(text)
    i = 0
    commands = []
    current = []

    def skip_ws(pos):
        while pos < n and text[pos].isspace():
            pos += 1
        return pos

    def read_quoted(pos):
        assert text[pos] == '"'
        pos += 1
        out = []
        while pos < n:
            ch = text[pos]
            if ch == '"':
                return ''.join(out), pos + 1
            if ch == '\\':
                if pos + 1 < n and text[pos + 1] in ('"', '\\'):
                    out.append(text[pos + 1])
                    pos += 2
                else:
                    out.append('\\')
                    pos += 1
            else:
                out.append(ch)
                pos += 1
        raise ValueError('unterminated quoted string')

    def read_bare(pos):
        start = pos
        while pos < n and (not text[pos].isspace()) and text[pos] not in ';"':
            pos += 1
        token = text[start:pos]
        if not token:
            raise ValueError('invalid token')
        return token, pos

    while True:
        i = skip_ws(i)
        if i >= n:
            break
        if text[i] == ';':
            if current:
                commands.append(current)
                current = []
            i += 1
            continue

        if text[i] == '"':
            tok, i = read_quoted(i)
            current.append(tok)
            continue

        tok, i = read_bare(i)
        if '=' in tok:
            name, value = tok.split('=', 1)
            if name == '' or any(c.isspace() or c in ';=' for c in name):
                raise ValueError('invalid assignment name')
            current.append(('assign', name, value))
        else:
            current.append(tok)

    if current:
        commands.append(current)
    return commands

def normalize_interval_list(intervals):
    if not isinstance(intervals, list):
        raise ValueError("intervals must be a list")

    validated = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each interval must be a 2-item list or tuple")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("interval endpoints must be integers")
        if start > end:
            raise ValueError("interval start must be <= end")
        validated.append((start, end))

    if not validated:
        return []

    validated.sort(key=lambda x: (x[0], x[1]))
    merged = [list(validated[0])]

    for start, end in validated[1:]:
        prev = merged[-1]
        if start <= prev[1] + 1:
            if end > prev[1]:
                prev[1] = end
        else:
            merged.append([start, end])

    return merged

def segment_runs(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if text == "":
        return []

    result = []
    current = text[0]
    count = 1

    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            result.append((current, count))
            current = ch
            count = 1

    result.append((current, count))
    return result

def compact_ranges(nums):
    if not nums:
        return []
    values = sorted(set(nums))
    ranges = []
    start = prev = values[0]
    for x in values[1:]:
        if x == prev + 1:
            prev = x
        else:
            ranges.append([start, prev])
            start = prev = x
    ranges.append([start, prev])
    return ranges

def normalize_sensor_readings(readings, minimum=0, maximum=100):
    if minimum > maximum:
        raise ValueError("minimum cannot be greater than maximum")
    result = []
    for item in readings:
        try:
            value = float(item)
        except (TypeError, ValueError):
            raise ValueError("invalid reading")
        rounded = int(round(value))
        if rounded < minimum:
            rounded = minimum
        elif rounded > maximum:
            rounded = maximum
        result.append(rounded)
    return result

def compress_runs(items):
    try:
        iterator = iter(items)
    except TypeError:
        raise

    result = []
    try:
        current = next(iterator)
    except StopIteration:
        return result

    count = 1
    for item in iterator:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def normalize_breadcrumbs(path: str) -> str:
    if path == "":
        return "."

    absolute = path.startswith("/")
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            else:
                if not absolute:
                    stack.append("..")
        else:
            stack.append(part)

    if absolute:
        return "/" + "/".join(stack) if stack else "/"
    return "/".join(stack) if stack else "."

def normalize_inventory_log(entries):
    result = {}
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            continue
        name, quantity = entry
        if not isinstance(name, str) or not isinstance(quantity, int):
            continue
        normalized = name.strip().lower()
        if normalized == '':
            continue
        if normalized in result:
            result[normalized] += quantity
        else:
            result[normalized] = quantity
    return result

def summarize_intervals(points):
    vals = list(points)
    for x in vals:
        if type(x) is not int:
            raise TypeError('all elements must be integers')
    if not vals:
        return {'count': 0, 'distinct': 0, 'runs': [], 'longest': None}
    vals.sort()
    runs = []
    current = vals[0]
    length = 1
    for x in vals[1:]:
        if x == current:
            length += 1
        else:
            runs.append((current, length))
            current = x
            length = 1
    runs.append((current, length))
    longest = runs[0]
    for r in runs[1:]:
        if r[1] > longest[1] or (r[1] == longest[1] and r[0] < longest[0]):
            longest = r
    return {'count': len(vals), 'distinct': len(runs), 'runs': runs, 'longest': longest}

from typing import List, Dict

def summarize_intervals(points: Iterable[int]) -> Dict[str, int]:
    """
    Summarizes contiguous runs of equal values in a sorted list of integers.

    Parameters:
    points (Iterable[int]): An iterable of integers.

    Returns:
    Dict[str, int]: A dictionary with keys 'count', 'distinct', 'runs', and 'longest'.
    """
    # Sort the points
    sorted_points = sorted(points)

    # Initialize variables
    count = len(sorted_points)
    distinct_values = set()
    runs = []
    longest = None

    # Iterate through the sorted points
    for i in range(1, len(sorted_points)):
        if sorted_points[i] == sorted_points[i - 1]:
            distinct_values.add(sorted_points[i])
        else:
            if distinct_values:
                runs.append((distinct_values.pop(), len(distinct_values)))
            distinct_values = {sorted_points[i]}
            count += 1

    # Add the last run
    if distinct_values:
        runs.append((distinct_values.pop(), len(distinct_values)))

    # Determine the longest run
    if longest is None or runs[-1][1] > longest[1]:
        longest = runs[-1]

    return {
        'count': count,
        'distinct': len(distinct_values),
        'runs': runs,
        'longest': longest
    }

