def merge_interval_labels(intervals):
    if not intervals:
        return []
    groups = {}
    for item in intervals:
        if not (isinstance(item, (tuple, list)) and len(item) == 3):
            raise ValueError('each interval must be a 3-item tuple or list')
        start, end, label = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('start and end must be integers')
        if not isinstance(label, str):
            raise ValueError('label must be a string')
        if start > end:
            raise ValueError('start must be <= end')
        groups.setdefault(label, []).append((start, end))
    merged_all = []
    for label in sorted(groups):
        segs = sorted(groups[label])
        cur_start, cur_end = segs[0]
        for start, end in segs[1:]:
            if start <= cur_end + 1:
                if end > cur_end:
                    cur_end = end
            else:
                merged_all.append((cur_start, cur_end, label))
                cur_start, cur_end = start, end
        merged_all.append((cur_start, cur_end, label))
    merged_all.sort(key=lambda x: (x[2], x[0]))
    return merged_all

def normalize_event_sequence(events):
    if not isinstance(events, list):
        raise TypeError('events must be a list')

    normalized = []
    for item in events:
        if not (isinstance(item, tuple) and len(item) == 3):
            raise ValueError('each event must be a 3-tuple')
        timestamp, action, payload = item
        if not isinstance(payload, dict):
            raise TypeError('payload must be a dictionary')
        new_payload = {}
        for key in sorted(payload.keys()):
            new_payload[key] = payload[key]
        new_payload['action_length'] = len(action)
        normalized.append((timestamp, action, new_payload))

    normalized.sort(key=lambda x: x[0])
    return normalized

def summarize_runs(values):
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be iterable")

    runs = []
    longest_run = 0
    changes = 0
    is_constant = True

    try:
        first = next(iterator)
    except StopIteration:
        return {
            'runs': [],
            'longest_run': 0,
            'changes': 0,
            'is_constant': True,
        }

    if not isinstance(first, int):
        raise TypeError("all elements must be integers")

    current_value = first
    current_length = 1

    for item in iterator:
        if not isinstance(item, int):
            raise TypeError("all elements must be integers")
        if item == current_value:
            current_length += 1
        else:
            runs.append((current_value, current_length))
            longest_run = max(longest_run, current_length)
            changes += 1
            is_constant = False
            current_value = item
            current_length = 1

    runs.append((current_value, current_length))
    longest_run = max(longest_run, current_length)

    return {
        'runs': runs,
        'longest_run': longest_run,
        'changes': changes,
        'is_constant': is_constant,
    }

def merge_intervals_weighted(intervals):
    if intervals is None:
        raise TypeError('intervals must be an iterable of 3-tuples')
    items = []
    for iv in intervals:
        if len(iv) != 3:
            raise ValueError('each interval must be a 3-tuple')
        start, end, weight = iv
        if start > end:
            raise ValueError('start must be <= end')
        items.append((start, end, weight))
    if not items:
        return []
    items.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end, cur_weight = items[0]
    for start, end, weight in items[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
            cur_weight += weight
        else:
            merged.append((cur_start, cur_end, cur_weight))
            cur_start, cur_end, cur_weight = start, end, weight
    merged.append((cur_start, cur_end, cur_weight))
    return merged

def summarize_runs(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list of integers")
    for x in values:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("values must be a list of integers")

    if not values:
        return {
            'run_count': 0,
            'longest_run_length': 0,
            'longest_run_value': None,
            'encoded': []
        }

    encoded = []
    current_value = values[0]
    current_length = 1
    for x in values[1:]:
        if x == current_value:
            current_length += 1
        else:
            encoded.append((current_value, current_length))
            current_value = x
            current_length = 1
    encoded.append((current_value, current_length))

    longest_run_value, longest_run_length = encoded[0]
    for value, length in encoded[1:]:
        if length > longest_run_length:
            longest_run_value = value
            longest_run_length = length

    return {
        'run_count': len(encoded),
        'longest_run_length': longest_run_length,
        'longest_run_value': longest_run_value,
        'encoded': encoded
    }

