def compress_ranges(values):
    try:
        items = list(values)
    except TypeError:
        raise TypeError("values must be iterable")

    unique = []
    seen = set()
    for x in items:
        if type(x) is not int:
            raise TypeError("all elements must be integers")
        if x not in seen:
            seen.add(x)
            unique.append(x)

    if not unique:
        return []

    unique.sort()
    result = []
    start = prev = unique[0]

    for x in unique[1:]:
        if x == prev + 1:
            prev = x
        else:
            result.append([start, prev])
            start = prev = x
    result.append([start, prev])
    return result

def compress_ranges(values):
    try:
        n = len(values)
    except Exception as e:
        raise TypeError("values must be a sequence") from e

    for x in values:
        if not isinstance(x, int) or isinstance(x, bool):
            raise TypeError("all elements must be integers")

    out = []
    i = 0
    while i < n:
        if i + 1 >= n:
            out.append((values[i],))
            break
        step = values[i + 1] - values[i]
        if step <= 0:
            out.append((values[i],))
            i += 1
            continue
        j = i + 2
        while j < n and values[j] - values[j - 1] == step:
            j += 1
        if j - i >= 2:
            if j - i == 2:
                out.append((values[i], values[i + 1], step))
            else:
                out.append((values[i], values[j - 1], step))
            i = j
        else:
            out.append((values[i],))
            i += 1
    return out

def schedule_landing(flights, gap, start_time):
    if gap < 0:
        gap = 0
    if not flights:
        return []
    schedule = []
    prev_time = None
    for item in flights:
        if len(item) != 3:
            raise ValueError("Each flight must be a tuple of (flight_id, earliest, latest)")
        flight_id, earliest, latest = item
        if earliest > latest:
            return None
        if prev_time is None:
            landing_time = max(start_time, earliest)
        else:
            landing_time = max(prev_time + gap, earliest)
        if landing_time > latest:
            return None
        schedule.append((flight_id, landing_time))
        prev_time = landing_time
    return schedule

def compress_intervals(intervals):
    if intervals is None:
        raise TypeError("intervals must be an iterable of 2-item iterables")

    normalized = []
    for interval in intervals:
        try:
            a, b = interval
        except Exception:
            raise ValueError("each interval must have exactly two items")

        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("interval endpoints must be integers")

        start, end = (a, b) if a <= b else (b, a)
        normalized.append([start, end])

    if not normalized:
        return []

    normalized.sort(key=lambda x: (x[0], x[1]))
    merged = [normalized[0][:]]
    for start, end in normalized[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

def plan_sensor_scan(sensors, budget):
    if not isinstance(sensors, list):
        raise TypeError("sensors must be a list")
    if not isinstance(budget, int):
        raise TypeError("budget must be an int")
    if budget < 0:
        raise ValueError("budget must be >= 0")

    items = []
    for sensor in sensors:
        if not isinstance(sensor, tuple) or len(sensor) != 3:
            raise TypeError("each sensor must be a 3-tuple")
        name, cost, priority = sensor
        if not isinstance(name, str):
            raise TypeError("sensor name must be a string")
        if not isinstance(cost, int):
            raise TypeError("sensor cost must be an int")
        if not isinstance(priority, int):
            raise TypeError("sensor priority must be an int")
        if cost <= 0:
            raise ValueError("sensor cost must be > 0")
        items.append((name, cost, priority))

    n = len(items)
    best = [(0, 0, ()) for _ in range(budget + 1)]

    def better(a, b):
        if a[1] != b[1]:
            return a[1] > b[1]
        if a[0] != b[0]:
            return a[0] < b[0]
        return a[2] < b[2]

    for name, cost, priority in items:
        for cap in range(budget, cost - 1, -1):
            prev = best[cap - cost]
            new_names = tuple(sorted(prev[2] + (name,)))
            candidate = (prev[0] + cost, prev[1] + priority, new_names)
            if better(candidate, best[cap]):
                best[cap] = candidate

    result = best[budget]
    if result[0] == 0:
        return (0, 0, ())
    return result

def parse_decimal_groups(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError('input must be a string')
    if s == '' or any(ch.isspace() for ch in s):
        raise ValueError('invalid format')

    i = 0
    sign = 1
    if s[0] in '+-':
        sign = -1 if s[0] == '-' else 1
        i = 1
        if i == len(s):
            raise ValueError('missing digits')

    if s[i] == '_':
        raise ValueError('underscore cannot start the number')

    digits = []
    prev_was_underscore = False
    saw_digit = False
    while i < len(s):
        ch = s[i]
        if ch.isdigit():
            digits.append(ch)
            saw_digit = True
            prev_was_underscore = False
        elif ch == '_':
            if not saw_digit or prev_was_underscore:
                raise ValueError('invalid underscore placement')
            prev_was_underscore = True
        else:
            raise ValueError('invalid character')
        i += 1

    if not saw_digit or prev_was_underscore:
        raise ValueError('invalid terminal state')

    return sign * int(''.join(digits))

def compress_intervals(values):
    items = []
    for v in values:
        if type(v) is not int:
            raise TypeError('all elements must be integers')
        items.append(v)

    if not items:
        return []

    uniq = sorted(set(items))
    result = []
    start = prev = uniq[0]

    for x in uniq[1:]:
        if x == prev + 1:
            prev = x
        else:
            result.append((start, prev))
            start = prev = x
    result.append((start, prev))
    return result

def normalize_intervals(intervals):
    if not isinstance(intervals, list):
        raise ValueError('intervals must be a list')

    normalized = []
    for idx, item in enumerate(intervals):
        if not isinstance(item, (list, tuple)):
            raise ValueError(f'interval at index {idx} must be a 2-item sequence')
        if len(item) != 2:
            raise ValueError(f'interval at index {idx} must have exactly two items')
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError(f'interval at index {idx} must contain integers')
        if start > end:
            raise ValueError(f'interval at index {idx} has start greater than end')
        normalized.append((start, end))

    if not normalized:
        return []

    normalized.sort()
    merged = []
    cur_start, cur_end = normalized[0]
    for start, end in normalized[1:]:
        if start <= cur_end + 1:
            if end > cur_end:
                cur_end = end
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

def decode_seating_code(code):
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    s = code.strip()
    if len(s) < 4:
        raise ValueError('invalid code format')
    if not s.startswith('R'):
        raise ValueError('invalid code format')
    c_pos = s.find('C', 1)
    if c_pos == -1:
        raise ValueError('invalid code format')
    row_part = s[1:c_pos]
    col_part = s[c_pos + 1:]
    if not row_part or not col_part:
        raise ValueError('invalid code format')
    if not row_part.isdigit() or not col_part.isdigit():
        raise ValueError('invalid code format')
    return (int(row_part), int(col_part))

def normalize_sections(text: str) -> str:
    if text == "":
        return ""

    sections = {}
    order = []
    current = None

    lines = text.split("\n")
    for line in lines:
        if line.startswith("##"):
            name = line[2:]
            if name.startswith(" "):
                name = name[1:]
            name = name.strip()
            if name not in sections:
                sections[name] = []
                order.append(name)
            current = name
        else:
            if current is not None:
                sections[current].append(line)

    output = []
    for name in order:
        output.append(f"## {name}")
        for item in reversed(sections[name]):
            output.append(item)
    return "\n".join(output)

def parse_kv_pairs(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    result = {}
    lines = text.split('\n')

    for raw_line in lines:
        line = raw_line.split('#', 1)[0].strip()
        if not line:
            continue

        eq_count = line.count('=')
        colon_count = line.count(':')

        if (eq_count and colon_count) or (eq_count + colon_count != 1):
            raise ValueError('malformed line')

        if eq_count == 1:
            sep = '='
        else:
            sep = ':'

        key, value = line.split(sep, 1)
        key = key.strip()
        value = value.strip()

        if not key:
            raise ValueError('empty key')

        result[key] = value

    return result

def parse_kv_pairs(text):
    """
    Parses a configuration-like string into a dictionary of string keys and values.

    :param text: A single string containing zero or more lines separated by \n.
    :return: A dictionary of string keys and values.
    """
    result = {}
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue

        parts = line.split('=')
        if len(parts) != 2:
            raise ValueError("Malformed line: expected exactly one '=' separator.")

        key, value = parts
        key = key.strip()
        value = value.strip()

        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]

    return result

