def compress_intervals(intervals):
    valid = []
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("Each interval must be a 2-item sequence")
        start, end = item
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("Interval bounds must be integers")
        if start <= end:
            valid.append((start, end))
    if not valid:
        return []
    valid.sort(key=lambda x: (x[0], x[1]))
    merged = [valid[0]]
    for start, end in valid[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def parse_config_lines(lines):
    if not isinstance(lines, list):
        raise TypeError("lines must be a list")
    result = {}
    for line in lines:
        if not isinstance(line, str):
            raise TypeError("all elements must be strings")
        if not line.strip():
            continue
        stripped = line.lstrip()
        if stripped.startswith('#'):
            continue
        key_chars = []
        val_chars = []
        in_key = True
        escaped = False
        found_sep = False
        for ch in line:
            if escaped:
                if in_key:
                    key_chars.append(ch)
                else:
                    val_chars.append(ch)
                escaped = False
                continue
            if ch == '\\':
                escaped = True
                continue
            if in_key and ch == '=':
                in_key = False
                found_sep = True
                continue
            if in_key:
                key_chars.append(ch)
            else:
                val_chars.append(ch)
        if escaped:
            if in_key:
                key_chars.append('\\')
            else:
                val_chars.append('\\')
        if not found_sep:
            raise ValueError("missing separator")
        key = ''.join(key_chars).lstrip()
        value = ''.join(val_chars).rstrip()
        if key == '':
            raise ValueError("empty key")
        result[key] = value
    return result

def normalize_sales_records(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')

    merged = {}
    order = []

    for record in records:
        if not isinstance(record, dict):
            continue
        if set(record.keys()) != {'item', 'quantity', 'price'}:
            continue

        item = record['item']
        qty = record['quantity']
        price = record['price']

        if not isinstance(item, str):
            continue
        item_norm = item.strip()
        if not item_norm:
            continue

        if isinstance(qty, int) and not isinstance(qty, bool):
            qty_norm = qty
        elif isinstance(qty, str):
            try:
                if qty.strip() == '':
                    continue
                qty_norm = int(qty.strip(), 10)
            except Exception:
                continue
        else:
            continue
        if qty_norm <= 0:
            continue

        if isinstance(price, bool):
            continue
        if isinstance(price, (int, float)):
            price_norm = float(price)
        elif isinstance(price, str):
            try:
                if price.strip() == '':
                    continue
                price_norm = float(price.strip())
            except Exception:
                continue
        else:
            continue
        if price_norm <= 0:
            continue

        if item_norm not in merged:
            merged[item_norm] = {'quantity': 0, 'price_sum': 0.0, 'count': 0}
            order.append(item_norm)
        merged[item_norm]['quantity'] += qty_norm
        merged[item_norm]['price_sum'] += price_norm
        merged[item_norm]['count'] += 1

    result = []
    for item_norm in order:
        data = merged[item_norm]
        result.append({'item': item_norm, 'quantity': data['quantity'], 'price': data['price_sum'] / data['count']})
    return result

def normalize_course_catalog(entries):
    def make_slug(title):
        out = []
        prev_hyphen = False
        for ch in title.lower():
            if ch.isalnum():
                out.append(ch)
                prev_hyphen = False
            else:
                if not prev_hyphen and out:
                    out.append('-')
                    prev_hyphen = True
        while out and out[-1] == '-':
            out.pop()
        return ''.join(out)

    courses = []
    total_credits = 0
    codes_seen = []
    seen_set = set()
    titles_by_credit = {}

    for record in entries:
        if not isinstance(record, tuple) or len(record) != 3:
            continue
        code, title, credits = record
        if not isinstance(code, str) or not isinstance(title, str) or not isinstance(credits, int):
            continue
        code_n = code.strip().upper()
        title_n = title.strip()
        if not code_n or not title_n or credits <= 0:
            continue
        slug = make_slug(title_n)
        course = {'code': code_n, 'title': title_n, 'credits': credits, 'slug': slug}
        courses.append(course)
        total_credits += credits
        if code_n not in seen_set:
            seen_set.add(code_n)
            codes_seen.append(code_n)
        titles_by_credit.setdefault(credits, []).append(title_n)

    return {
        'courses': courses,
        'total_credits': total_credits,
        'codes': tuple(codes_seen),
        'titles_by_credit': titles_by_credit,
    }

