def parse_span_spec(spec):
    if not isinstance(spec, str):
        raise ValueError('spec must be a string')
    if spec.strip() == '':
        return []

    result = []
    seen = set()

    parts = spec.split(',')
    for raw_item in parts:
        item = raw_item.strip()
        if item == '':
            raise ValueError('empty item')

        if '..' in item:
            if item.count('..') != 1:
                raise ValueError('malformed range')
            left, right = item.split('..')
            if left == '' or right == '':
                raise ValueError('malformed range')
            if left.strip() != left or right.strip() != right:
                raise ValueError('invalid whitespace inside number')
            try:
                start = int(left)
                end = int(right)
            except Exception as e:
                raise ValueError('invalid integer in range') from e
            step = 1 if start <= end else -1
            for n in range(start, end + step, step):
                if n not in seen:
                    seen.add(n)
                    result.append(n)
        else:
            if item.strip() != item:
                raise ValueError('invalid whitespace inside number')
            try:
                n = int(item)
            except Exception as e:
                raise ValueError('invalid integer') from e
            if n not in seen:
                seen.add(n)
                result.append(n)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    multipliers = {'w': 604800, 'd': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    i = 0
    n = len(s)

    while i < n:
        j = i
        if s[j] in '+-':
            raise ValueError("invalid number")
        if not s[j].isdigit():
            raise ValueError("expected digit")
        while j < n and s[j].isdigit():
            j += 1
        if j >= n:
            raise ValueError("missing unit")
        unit = s[j]
        if unit not in multipliers:
            raise ValueError("unknown unit")
        num = int(s[i:j])
        total += num * multipliers[unit]
        i = j + 1
    return total

def parse_inventory_lines(lines):
    result = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError('each line must be a string')
        parts = line.split('|')
        if len(parts) != 3:
            raise ValueError('malformed line')
        action, item, qty_text = parts
        if action not in ('IN', 'OUT'):
            raise ValueError('invalid action')
        if item == '' or '|' in item:
            raise ValueError('invalid item')
        if qty_text == '':
            raise ValueError('invalid quantity')
        if qty_text[0] in '+-':
            digits = qty_text[1:]
            if digits == '' or not digits.isdigit():
                raise ValueError('invalid quantity')
        else:
            if not qty_text.isdigit():
                raise ValueError('invalid quantity')
        qty = int(qty_text)
        delta = qty if action == 'IN' else -qty
        result[item] = result.get(item, 0) + delta
        if result[item] == 0:
            del result[item]
    return result

def normalize_inventory(events):
    try:
        iterator = iter(events)
    except TypeError:
        raise TypeError("events must be iterable")

    totals = {}
    order = []

    for event in iterator:
        if not isinstance(event, (tuple, list)) or len(event) != 2:
            raise TypeError("each event must be a 2-item tuple or list")
        item, delta = event
        if not isinstance(item, str):
            raise TypeError("item must be a string")
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise TypeError("delta must be an integer")
        if item not in totals:
            totals[item] = 0
            order.append(item)
        totals[item] += delta

    result = []
    for item in order:
        total = totals[item]
        if total > 0:
            status = "positive"
        elif total < 0:
            status = "negative"
        else:
            status = "zero"
        result.append({"item": item, "total": total, "status": status})
    return result

